INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SGHGH01YU002P0001', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0001', '김현감호', '金現感虎', '3인칭', '한문', '新羅俗, 每當仲春, 初八至十五日, 都人士女, 競遶興輪寺之殿塔爲福會.', '신라 풍속에 매년 2월이 되면 8일에서 15일까지 도읍의 남녀들이 서로 다투어 흥륜사(興輪寺)의 전탑(殿塔)을 돌며 복회(福會)를 열었다.', NULL, '신라', '현실계', '특정 불필요', '특정 불필요', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0002', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0002', '김현감호', '金現感虎', '3인칭', '한문', '元聖王代, 有郎君金現者, 夜深獨遶不息.', '원성왕(元聖王)대에 김현(金現)이라는 젊은이]가 밤이 깊도록 쉬지 않고 혼자 전탑을 돌고 있었다.', NULL, '신라', '현실계', '한국 경상북도_경주', '흥륜사', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0003', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0003', '김현감호', '金現感虎', '3인칭', '한문', '有一處女, 念佛隨遶, 相感而目送之.', '마침 한 처녀가 염불하면서 따라 돌았으니 서로 마음이 통해 눈짓을 보냈다.', NULL, '신라', '현실계', '한국 경상북도_경주', '흥륜사', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0004', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0004', '김현감호', '金現感虎', '3인칭', '한문', '遶畢, 引入屛處通焉.', '김현은 탑돌이를 마치고 처녀를 으슥한 곳으로 데리고 들어가서 정을 통했다.', NULL, '신라', '현실계', '한국 경상북도_경주', '흥륜사', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0005', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0005', '김현감호', '金現感虎', '3인칭', '한문', '女將還, 現從之,', '그녀가 집으로 돌아가려 하자 김현이 그녀를 따라갔으니', NULL, '신라', '현실계', '한국 경상북도_경주', '흥륜사', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0006', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0006', '김현감호', '金現感虎', '3인칭', '한문', '女辭拒而强隨之.', '처녀가 사양하고 거절했지만 억지로 따라갔다.', NULL, '신라', '현실계', '한국 경상북도_경주', '흥륜사', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0007', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0007', '김현감호', '金現感虎', '3인칭', '한문', '行至西山之麓, 入一茅店,', '가다가 서산(西山) 기슭에 이르러 한 초가집에 들어가니', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0008', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0008', '김현감호', '金現感虎', '3인칭', '한문', '有老嫗問女曰 :', '노구가 처녀에게 물었다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0009', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0009', '김현감호', '金現感虎', '3인칭', '한문', '“附率者, 何人?”', '“따라온 이는 누구냐?”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀, 노구', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0010', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0010', '김현감호', '金現感虎', '3인칭', '한문', '女陳其情,', '처녀가 그 사정을 이야기하자', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀, 노구', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0011', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0011', '김현감호', '金現感虎', '3인칭', '한문', '嫗曰 :', '노구가 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀, 노구', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0012', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0012', '김현감호', '金現感虎', '3인칭', '한문', '“雖好事, 不如無也. 然遂事不可諫也. 且藏於密. 恐汝弟兄之惡也.”', '“비록 좋은 일이긴 하지만 없느니만 못하다. 그러나 이미 벌어진 일이니 나무랄 수도 없다. 우선 은밀한 곳에 숨겨두거라. 네 형제가 나쁜 짓을 벌일까 두렵구나.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀, 노구', '논어_팔일', NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0013', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0013', '김현감호', '金現感虎', '3인칭', '한문', '把郎而匿之奧.', '처녀는 김현을 데려가 구석진 곳에 숨겼다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0014', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0014', '김현감호', '金現感虎', '3인칭', '한문', '小選, 有三虎, 咆哮而至, 作人語曰 :', '잠시 뒤 호랑이 3마리가 으르렁거리며 오더니 사람 목소리를 하며 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0015', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0015', '김현감호', '金現感虎', '3인칭', '한문', '“家有腥膻之氣. 療飢何幸.”', '“집안에서 비린내가 나는구나. 요깃거리가 있으니 어찌 다행이 아닌가.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0016', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0016', '김현감호', '金現感虎', '3인칭', '한문', '嫗與女叱曰 :', '노구가 처녀와 함께 꾸짖으며 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0017', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0017', '김현감호', '金現感虎', '3인칭', '한문', '“爾鼻之爽乎. 何言之狂也?”', '“네 코가 썩었구나. 어찌 미친 소리를 하는가?”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0018', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0018', '김현감호', '金現感虎', '3인칭', '한문', '時有天唱 :', '이때 하늘에서 소리가 들려왔다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0019', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0019', '김현감호', '金現感虎', '3인칭', '한문', '“爾輩, 嗜害物命尤多, 宜誅一以徵惡.”', '“너희들이 만물의 목숨을 즐겨 해치는 것이 몹시 잦으니 한 놈을 죽여서 악행을 징계할 것이다.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0020', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0020', '김현감호', '金現感虎', '3인칭', '한문', '三獸聞之, 皆有憂色.', '세 짐승이 그 말을 듣고 모두 근심하는 기색을 띠었다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0021', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0021', '김현감호', '金現感虎', '3인칭', '한문', '女謂曰 :', '처녀가 오빠들에게 일러 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0022', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0022', '김현감호', '金現感虎', '3인칭', '한문', '“三兄, 若能遠避而自懲, 我能代受其罰.”', '“세 오빠가 만약 멀리 달아나서 스스로 징계할 수 있다면 제가 그 벌을 대신 받겠습니다.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0023', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0023', '김현감호', '金現感虎', '3인칭', '한문', '皆喜, 俛首妥尾而遁去', '호랑이들이 모두 기뻐하여 머리를 숙이고 꼬리를 떨어뜨리고 달아났다', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '호녀, 노구, 호형', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0024', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0024', '김현감호', '金現感虎', '3인칭', '한문', '女入謂郎曰 :', '처녀가 들어와서 김현에게 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0025', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0025', '김현감호', '金現感虎', '3인칭', '한문', '“始吾恥君子之辱臨弊族, 故辭禁爾, 今旣無隱, 敢布腹心. 且賤妾之於郎君, 雖曰: ‘非類’, 得陪一夕之歡, 義重結褵之好. 三兄之惡, 天旣厭之, 一家之殃, 予欲當之. 與其死於等閑人之手, 曷若伏於郎君刃下, 以報之德乎? 妾以明日, 入市爲害劇, 則國人無如我何, 大王必募以重爵, 而捉我矣. 君其無㤼, 追我乎城北林中. 吾將待之.”', '“처음에 제가 낭군께서 하찮은 저희 족속을 욕스럽게 찾아 오는 것이 부끄러워 사양하며 거절했었는데, 이제는 숨길 것이 없으니 감히 속마음을 털어놓겠습니다. 천한 제가 낭군에게 있어 비록 같은 종류가 아니라고 하겠으나 하룻밤의 기쁨을 보낼 수 있었으니 의리가 혼례의 정분처럼 중요합니다. 세 오빠의 악행을 하늘이 미워하니 이 집안의 재앙을 제가 감당하고자 합니다. 다른 사람의 손에 죽게 되는 것이 어찌 낭군의 칼날 아래에 죽어 은덕을 갚는 것과 같겠습니까? 제가 내일 시장에 들어가 지나치게 사람들을 해치면 나라 사람들이 저를 어찌 할 수 없어 대왕은 반드시 높은 벼슬을 걸고 사람을 모집하여 저를 잡을 것입니다. 낭군께선 겁내지 말고 도성 북쪽의 숲속으로 저를 찾아오십시오. 제가 기다리고 있겠습니다.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', '시경_빈풍', NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0026', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0026', '김현감호', '金現感虎', '3인칭', '한문', '現曰 :', '김현이 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0027', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0027', '김현감호', '金現感虎', '3인칭', '한문', '“人交人, 彝倫之道, 異類而交, 蓋非常也. 旣得從容, 固多天幸, 何可忍賣於伉儷之死, 僥倖一世之爵祿乎?”', '“사람이 다른 사람과 사귀는 것은 인륜의 도리지만 이류(異類)와 사귀는 것은 일반적인 일이 아니다. 이미 차분한 여인을 얻었으니 참으로 다행인데 어찌 차마 배필의 죽음을 팔아 일세의 작록을 요행으로 삼겠는가?”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0028', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0028', '김현감호', '金現感虎', '3인칭', '한문', '女曰 :', '처녀가 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0029', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0029', '김현감호', '金現感虎', '3인칭', '한문', '“郎君無有此言. 今妾之壽夭, 蓋天命也, 亦吾願也, 郎君之慶也, 予族之福也, 國人之喜也. 一死而五利備, 其可違乎? 但爲妾創寺. 講眞詮, 資勝報, 則郎君之惠, 莫大焉.”', '“낭군께서는 그런 말씀 마십시오. 지금 저의 목숨은 천명이요 또 저의 소원이요 낭군께는 경사고 제 족속의 복록이며 나라 사람들의 기쁨입니다. 한 번 죽어 다섯 가지 이로움이 갖춰지니 어찌 어길 수 있겠습니까? 다만 저를 위해 절을 창건하고 불경을 강론하여 좋은 과보(果報)를 얻도록 해주신다면 낭군의 은혜는 이보다 큰 것이 없을 것입니다.”', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0030', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0030', '김현감호', '金現感虎', '3인칭', '한문', '遂相泣而別.', '마침내 그들은 서로 울면서 작별하였다.', NULL, '신라', '현실계', '한국 경상북도_경주_선도산', '초가집(호녀의 집)', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0031', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0031', '김현감호', '金現感虎', '3인칭', '한문', '次日, 果有猛虎入城中, 剽甚無敢當.', '다음 날 과연 사나운 호랑이가 도성 안으로 들어왔는데 사나움이 심하여 감당할 수가 없었다.', NULL, '신라', '현실계', '한국 경상북도_경주', '도성', '호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0032', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0032', '김현감호', '金現感虎', '3인칭', '한문', '元聖王聞之, 申令曰 :', '원성왕이 이를 듣고 명령을 내렸다.', NULL, '신라', '현실계', '한국 경상북도_경주', '대궐', '원성왕', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0033', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0033', '김현감호', '金現感虎', '3인칭', '한문', '‘戡虎者, 爵二級.’', '‘호랑이를 잡는 사람에게 2급의 벼슬을 주겠다.’', NULL, '신라', '현실계', '한국 경상북도_경주', '대궐', '원성왕', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0034', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0034', '김현감호', '金現感虎', '3인칭', '한문', '現詣闕奏曰 :', '그러자 김현이 대궐로 나아가 아뢰었다.', NULL, '신라', '현실계', '한국 경상북도_경주', '대궐', '김현, 원성왕', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0035', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0035', '김현감호', '金現感虎', '3인칭', '한문', '“小臣能之.”', '“소신이 할 수 있습니다.”', NULL, '신라', '현실계', '한국 경상북도_경주', '대궐', '김현, 원성왕', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0036', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0036', '김현감호', '金現感虎', '3인칭', '한문', '乃先賜爵以激之.', '왕이 곧 먼저 벼슬을 내려 그를 격려했다.', NULL, '신라', '현실계', '한국 경상북도_경주', '대궐', '김현, 원성왕', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0037', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0037', '김현감호', '金現感虎', '3인칭', '한문', '現持短兵, 入林中, 虎變爲娘子, 熙怡而笑曰 :', '김현이 짧은 무기를 쥐고 숲속으로 들어가자', NULL, '신라', '현실계', '한국 경상북도_경주', '논호림', '김현,', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0038', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0038', '김현감호', '金現感虎', '3인칭', '한문', '虎變爲娘子, 熙怡而笑曰 :', '호랑이가 여인으로 변하고는 기뻐하는 얼굴로 웃으며 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주', '논호림', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0039', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0039', '김현감호', '金現感虎', '3인칭', '한문', '“昨夜, 共郎君繾綣之事, 惟君無忽. 今日被爪傷者, 皆塗興輪寺醬, 聆其寺之螺鉢聲, 則可治.”', '“어젯밤 낭군과 함께했던 깊은 일을 그대께서는 소홀히 여기지 마십시오. 오늘 제 발톱에 상처를 입은 사람들은 모두 흥륜사(興輪寺)의 간장을 바르고 그 절의 나팔(螺鉢)소리를 들으면 나을 수 있습니다.”', '頸 : 剄로 추정', '신라', '현실계', '한국 경상북도_경주', '논호림', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0040', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0040', '김현감호', '金現感虎', '3인칭', '한문', '乃取現所佩刀, 自頸而仆, 乃虎也.', '처녀는 김현이 차고 있던 칼을 뽑아 스스로 목을 찌르고 엎어졌으니 곧 호랑이가 되었다.', NULL, '신라', '현실계', '한국 경상북도_경주', '논호림', '김현, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0041', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0041', '김현감호', '金現感虎', '3인칭', '한문', '現出林而託曰 :', '김현이 숲속에서 나와 거짓으로 말했다.', NULL, '신라', '현실계', '한국 경상북도_경주', '도성', '김현', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0042', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0042', '김현감호', '金現感虎', '3인칭', '한문', '“今玆虎易摶矣.”', '“지금 이 호랑이를 손쉽게 잡았다.”', NULL, '신라', '현실계', '한국 경상북도_경주', '도성', '김현', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0043', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0043', '김현감호', '金現感虎', '3인칭', '한문', '匿其由不洩, 但依諭而治之, 其瘡皆效.', '그러고는 그 연고를 누설하지 않고 그저 그녀의 당부대로 다친 사람들을 치료하니 그 상처가 모두 나았다.', NULL, '신라', '현실계', '한국 경상북도_경주', '도성', '김현', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0044', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0044', '김현감호', '金現感虎', '3인칭', '한문', '今俗亦用其方.', '지금도 민간에서는 그 방법을 쓴다.', NULL, '신라', '현실계', '한국 경상북도_경주', '특정 불필요', '특정 불필요', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0045', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0045', '김현감호', '金現感虎', '3인칭', '한문', '現旣登庸, 創寺於西川邊, 號虎願寺, 常講『梵網經』, 以導虎之冥遊, 亦報其殺身成己之恩.', '김현은 등용된 후 서천(西川) 주변에 절을 창건하고 호원사(虎願寺)라 이름 붙이고 늘 『범망경(梵網經)』을 강설하여 호랑이의 저승길을 인도했으며, 스스로 희생해 자기를 출세시킨 은혜에 보답했다.', NULL, '신라', '현실계', '한국 경상북도_경주_황성동', '호원사', '김현', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0046', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0046', '김현감호', '金現感虎', '3인칭', '한문', '現臨卒, 深感前事之異, 乃筆成傳, 俗始聞知.', '김현이 죽음을 앞두고 지난 일의 기이함에 깊이 감동하여 곧장 기록해 전(傳)을 지었으니 민간에서 비로소 알려지게 되었다.', NULL, '신라', '현실계', '한국 경상북도_경주_황성동', '호원사', '김현', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0047', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0047', '김현감호', '金現感虎', '3인칭', '한문', '因名論虎林, 稱于今.', '그리하여 그 숲을 ‘논호림(論虎林)’으로 이름하고 지금도 그렇게 불린다.', '論 : 輪으로 추정', '신라', '현실계', '한국 경상북도_경주', '특정 불필요', '특정 불필요', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0048', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0048', '김현감호', '金現感虎', '3인칭', '한문', '貞元九年.', '정원(貞元) 9년(793) 때의 일이다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_십방현(什邡縣)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0049', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0049', '김현감호', '金現感虎', '3인칭', '한문', '申屠澄自黃冠, 調補漢州什邡縣之尉.', '신도징(申屠澄)이 벼슬하지 않고 지내다가 한주(漢州) 십방현(什邡縣)의 현위(縣尉)로 임명되었다.', NULL, '신라', '현실계', '중국_사천성(四川省)', NULL, '신도징', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0050', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0050', '김현감호', '金現感虎', '3인칭', '한문', '至眞符縣之東十里許,', '진부현(眞符縣) 동쪽 10리쯤 되는 곳에 이르렀는데', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌', '신도징', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0051', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0051', '김현감호', '金現感虎', '3인칭', '한문', '遇風雪大寒. 馬不能前.', '눈보라와 큰 추위를 만나 말이 나아가지 못했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌', '신도징', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0052', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0052', '김현감호', '金現感虎', '3인칭', '한문', '路傍有茅舍, 中有煙火甚溫.', '그런데 길옆에 초가집이 있었으니 그곳은 불이 지펴져 있어 매우 따뜻했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0053', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0053', '김현감호', '金現感虎', '3인칭', '한문', '照燈下就之, 有老父嫗及處子, 環火而坐.', '등불을 비춰 아래로 가보니 늙은 부부와 여인이 불을 둘러싸고 앉아 있었다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0054', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0054', '김현감호', '金現感虎', '3인칭', '한문', '其女年, 方十四五, 雖蓬髮垢衣, 雪膚花臉, 擧止姸媚.', '여인의 나이는 막 14·5살쯤 되어보였으며 비록 머리가 헝클어지고 옷이 때묻었으나 흰 눈 같은 살결과 꽃 같은 얼굴에 몸가짐이 곱고 아름다웠다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0055', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0055', '김현감호', '金現感虎', '3인칭', '한문', '父嫗見澄來, 遽起曰 :', '늙은 부부는 신도징이 온 것을 보고는 황급히 일어나 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0056', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0056', '김현감호', '金現感虎', '3인칭', '한문', '“客甚衝寒雪, 請前就火.”', '“손님께서 추위와 눈을 힘들게 맞으셨으니 불 쪽으로 가까이 오십시오.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0057', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0057', '김현감호', '金現感虎', '3인칭', '한문', '澄坐良久, 天色已暝, 風雪不止.', '신도징이 한참 동안 앉아 있었는데 날이 이미 저물고 눈도 그치지 않았다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0058', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0058', '김현감호', '金現感虎', '3인칭', '한문', '澄曰 :', '신도징이 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0059', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0059', '김현감호', '金現感虎', '3인칭', '한문', '“西去縣尙遠, 請宿丁此.”', '“서쪽으로 현과 떨어진 거리가 아직 머니 이곳에서 묵었으면 합니다.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0060', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0060', '김현감호', '金現感虎', '3인칭', '한문', '父嫗曰 :', '부부가 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0061', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0061', '김현감호', '金現感虎', '3인칭', '한문', '“苟不以蓬蓽爲陋, 敢承命.”', '“진실로 이 빈천한 집을 누추하게 여기지 않으시다면 감히 말씀을 받들겠습니다.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', '진서_갈홍전', NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0062', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0062', '김현감호', '金現感虎', '3인칭', '한문', '澄遂解鞍施衾幃.', '신도징이 마침내 말안장을 풀고 이부자리를 폈다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0063', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0063', '김현감호', '金現感虎', '3인칭', '한문', '其女見客方止, 修容靘粧, 自帷箔間出, 有閑雅之態, 猶過初時.', '여인은 손님이 막 묵는 것을 보고는 용모를 다듬고 곱게 단장하여 휘장 사이에서 나왔으니 얌전한 자태가 처음 보았을 때보다 더 괜찮았다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0064', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0064', '김현감호', '金現感虎', '3인칭', '한문', '澄曰 :', '신도징이 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0065', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0065', '김현감호', '金現感虎', '3인칭', '한문', '“小娘子明惠, 過人甚. 幸未婚, 敢請自媒如何?”', '“어린 낭자의 총명함이 다른 사람들보다 훨씬 뛰어납니다. 행여 아직 혼인하지 않았다면 감히 직접 중매를 청하고 싶은데 어떠합니까?”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0066', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0066', '김현감호', '金現感虎', '3인칭', '한문', '翁曰 :', '여인의 부친이 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0067', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0067', '김현감호', '金現感虎', '3인칭', '한문', '“不期貴客, 欲採拾. 豈定分也?”', '“뜻밖에 귀한 손님께서 거두어 주신다고 하시니 어찌 정해진 연분이 아니겠습니까?”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0068', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0068', '김현감호', '金現感虎', '3인칭', '한문', '澄遂修子婿之禮.', '신도징이 드디어 사위로서의 예를 치루었다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0069', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0069', '김현감호', '金現感虎', '3인칭', '한문', '澄乃以所乘馬, 載之而行.', '그리고 자신이 타고 온 말에 여인을 태우고 떠났다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '동촌_초가집', '신도징, 호녀의 모친, 호녀의 부친, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0070', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0070', '김현감호', '金現感虎', '3인칭', '한문', '旣至官, 俸祿甚薄,', '이미 임지에 이르렀는데 봉록이 무척 적었으나', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0071', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0071', '김현감호', '金現感虎', '3인칭', '한문', '妻力以成家, 無不歡心.', '아내가 힘써 살림을 꾸렸으니 마음에 즐겁지 않음이 없었다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0072', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0072', '김현감호', '金現感虎', '3인칭', '한문', '後秩滿將歸, 已生一男一女, 亦甚明惠.', '그 후 임기가 끝나 돌아갈 무렵 이미 1남 1녀를 두고 있었는데 자녀들이 몹시 총명했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0073', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0073', '김현감호', '金現感虎', '3인칭', '한문', '澄尤加敬愛. 嘗作贈內詩云:', '신도징은 아내를 더욱 존경하고 사랑하여 한번은 증내시(贈內詩)를 지었다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0074', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0074', '김현감호', '金現感虎', '3인칭', '한문', '“一宦慚梅福, 三年愧孟光. 此情何所喩? 川上有鴛鴦.”', '“한번 벼슬하니 매복(梅福)에게 부끄럽고, 3년을 지내니 맹광(孟光)에게 부끄럽네. 이 마음을 무엇에 비유하겠는가? 냇물 위에는 원앙새 있구나.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', '『한서(漢書)』「매복전(梅福傳)」 / 『후한서(後漢書)』「양홍전(梁鴻傳)」', NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0075', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0075', '김현감호', '金現感虎', '3인칭', '한문', '其妻終日吟諷, 似黙有和者, 未嘗出口.', '그 아내는 종일토록 그 시를 읊조리며 잠잠히 화답할 내용이 있는 듯했으나 입 밖으로 말하지 않았다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0076', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0076', '김현감호', '金現感虎', '3인칭', '한문', '澄罷官, 罄室歸本家.', '신도징이 벼슬을 그만두고 집을 비운 뒤 본가로 돌아오니', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0077', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0077', '김현감호', '金現感虎', '3인칭', '한문', '妻忽悵然謂澄曰 :', '아내가 갑자기 슬퍼하며 신도징에게 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0078', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0078', '김현감호', '金現感虎', '3인칭', '한문', '“見贈一篇, 尋卽有和.”', '“전에 주셨던 시 한 편을 보고 얼마 뒤 화답한 것이 있습니다.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0079', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0079', '김현감호', '金現感虎', '3인칭', '한문', '乃吟曰 :', '곧 시를 읊었다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0080', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0080', '김현감호', '金現感虎', '3인칭', '한문', '“琴瑟情雖重, 山林志自深. 常憂時節變, 辜負百年心.”', '“부부의 정이 비록 중요하지만, 산림을 향한 뜻이 저절로 깊구나. 매번 근심하는 것은 시절이 변하여, 헛되이 백년가약 저버리는 것이라네.”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0081', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0081', '김현감호', '金現感虎', '3인칭', '한문', '遂與訪其家, 不復有人矣.', '드디어 함께 여인의 집을 찾아갔으나 더이상 사람이 보이지 않았다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0082', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0082', '김현감호', '金現感虎', '3인칭', '한문', '妻思慕之甚, 盡日涕泣,', '아내는 몹시 그리워하며 종일토록 눈물을 흘리다가', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0083', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0083', '김현감호', '金現感虎', '3인칭', '한문', '忽壁角見一虎皮, 妻大笑曰 :', '문득 벽 모퉁이의 호랑이 가죽을 보더니 크게 웃으며 말했다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0084', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0084', '김현감호', '金現感虎', '3인칭', '한문', '“不知此物尙在耶.”', '“이 물건이 아직도 있을 줄은 몰랐구나”', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0085', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0085', '김현감호', '金現感虎', '3인칭', '한문', '遂取披之, 卽變爲虎, 哮吼拏攫, 突門而出.', '곧 가죽을 꺼내서 입으니 즉시 호랑이로 변하여 포효하고 움퀴고 할퀴다가 문으로 돌진하고 나가 버렸다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0086', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0086', '김현감호', '金現感虎', '3인칭', '한문', '澄驚避之, 攜二子, 尋其路,', '신도징은 놀라서 피했다가 두 아이를 데리고 아내가 간 길을 찾다가', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '임지(任地)_신도징의 집', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0087', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0087', '김현감호', '金現感虎', '3인칭', '한문', '望山林, 大哭數日,', '산림을 바라보고 며칠을 통곡했으니', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', '산림', '신도징, 호녀', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0088', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0088', '김현감호', '金現感虎', '3인칭', '한문', '竟不知所之.', '그 뒤로 끝내 간 곳을 알지 못한다.', NULL, '신라', '현실계', '중국_사천성(四川省)_성도부(成都府)_진부현(眞符縣)', NULL, '신도징', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0089', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0089', '김현감호', '金現感虎', '3인칭', '한문', '噫! 澄現二公之接異物也, 變爲人妾, 則同矣, 而贈背人詩, 然後哮吼拏攫而走, 與現之虎異矣. 現之虎, 不得已而傷人, 然善誘良方, 以救人. 獸有爲仁如彼者, 今有人而不如獸者. 何哉? 詳觀事之終始, 感人於旋遶佛寺中, 天唱徵惡. 以自代之, 傳神方以救人, 置精廬講佛戒. 非徒獸之性仁者也, 蓋大聖應物之多方, 感現公之能致精於旋遶, 欲報冥益耳. 宜其當時能受禧佑乎', '슬프구나! 신도징과 김현 두 사람이 이물을 접했을 때 호랑이가 변해 사람의 아내가 된 것은 똑같으나 인간 세상을 저버리는 시를 준 다음 포효하고 움퀴고 할퀴다가 달아났으니 김현의 호랑이와는 다르다. 김현의 호랑이는 어쩔 수 없이 사람을 다치게 했으나 좋은 처방을 알려주어 사람을 도왔다. 짐승인데도 인(仁)을 행함이 저와 같은 자가 있는데 지금은 사람인데도 짐승보다 못한 자가 있는 것은 무엇 때문인가? 이 사적의 전말을 자세히 살펴보면 김현의 호랑이는 사찰에서 탑돌이를 하던 중에 사람과 교감하였고, 하늘이 악행을 징계한다고 소리치자 자신으로써 이를 대신했으며 신효한 처방을 전하여 사람을 구했고 절을 세워 불계(佛戒)를 강설하게 했다. 이는 단지 짐승의 본성이 어진 자일 뿐만 아니라 대개 대성(大聖:관음보살)이 만물에 여러 방면으로 감응한 것이니, 김현이 지성으로 탑돌이를 할 수 있었던 것에 감동하여 명익(冥益)을 갚고자 한 것이다. 당시 복을 받을 수 있었던 것이 마땅하도다.', NULL, '종결평', '종결평', '종결평', '종결평', '종결평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SGHGH01YU002P0090', '장면_김현감호_목판본_한국 규장각한국학연구원_001_S#0090', '김현감호', '金現感虎', '3인칭', '한문', '讚曰 : “山家不耐三兄惡, 蘭吐那堪一諾芳. 義重數條輕萬死, 許身林下落花忙.”', '다음과 같이 찬한다. “산가(山家)는 세 오빠의 죄악을 견딜 수 없는데, 어찌 난초가 내뿜는 꽃다운 승낙을 견디겠는가. 의리의 소중함 몇 가지에 만 번 죽음은 가벼워, 수풀 아래 스스로 희생했으니 낙화처럼 졌구나.”', NULL, '최종평', '최종평', '최종평', '최종평', '최종평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0001', '장면_낙우애우기_필사본_한국 고려대학교_S#0001', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '湖南泰仁懸, 有郭生者, 逸其名. 家貧奉母, 年二十而未娶. 資性豪邁, 以詩才鳴於一鄉云.', '호남(湖南) 태인현(泰仁縣)에 곽생(郭生)이라는 자가 있었으니 그 이름은 전해지지 않는다. 그는 가난한 살림에 모친을 봉양하고 살았으며 스물이 되도록 아직 장가들지 못했는데, 성품이 호매하고 시재(詩才)가 고을에 알려질 정도였다고 한다.', '懸 : 원본에는 懸', '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0002', '장면_낙우애우기_필사본_한국 고려대학교_S#0002', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '丙辰秋八月, 國設典試, 生欲觀光, 告老母.', '병진(丙辰)년 가을 8월 나라에서 전시(典試)를 시행했으니 곽생이 서울을 구경하고자 하여 모친께 아뢰었다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0003', '장면_낙우애우기_필사본_한국 고려대학교_S#0003', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '母難之曰:', '그러자 모친은 이를 꺼리며 말했다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0004', '장면_낙우애우기_필사본_한국 고려대학교_S#0004', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“觀國之賓, 雖是士子本色, 遠離膝下, 亦關老母貽憂.”', '“나라의 빛을 관광하는 빈객이 비록 선비의 본분이나 슬하에서 멀리 떠나는 것은 또한 늙은 어미에게 걱정을 끼치는 일이다”', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', '『주역(周易)』·「관괘(觀卦)」', NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0005', '장면_낙우애우기_필사본_한국 고려대학교_S#0005', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0006', '장면_낙우애우기_필사본_한국 고려대학교_S#0006', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“親髮漸衰, 子年已盛. 顧念世變, 榮養無幾. 願望母親矜察哀情.”', '“모친의 머리카락이 점점 줄어들고 자식의 나이도 이미 장성했는데 세태의 변화를 돌이켜 생각해보니 영예롭게 봉양할 날이 얼마 남지 않았습니다. 바라건대 모친께서는 슬픈 사정을 불쌍히 여겨주십시오.”', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0007', '장면_낙우애우기_필사본_한국 고려대학교_S#0007', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '母壯其志, 黽勉許之, 盡賣釵釧, 備給盤纏.', '모친이 곽생의 뜻을 장하게 여겨 마지못해 허락하고는 비녀와 팔찌를 모두 팔아 경비를 마련했다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 곽생의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0008', '장면_낙우애우기_필사본_한국 고려대학교_S#0008', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生輕治行裝, 向去京城.', '이에 곽생이 행장을 간단히 꾸리고 경성으로 떠났다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0009', '장면_낙우애우기_필사본_한국 고려대학교_S#0009', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '至濟原驛, 山川風物, 一倍明麗, 村前澄江一帶, 委曲滙潭, 江堤綠柳密繁.', '곽생이 제원역(濟原驛)에 도착하자 산천과 경치가 한껏 또렷하고 아름다웠으니 마을 앞의 강물 한 줄기는 깊은 못을 굽이쳐 흐르고 강둑의 푸른 버들은 빽빽하게 우거져있었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0010', '장면_낙우애우기_필사본_한국 고려대학교_S#0010', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遙聞洴澼聲, 自柳間隱隱出.', '이때 빨래하는 소리가 멀리서 들려왔으니 버들 사이에서 은은히 흘러나왔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0011', '장면_낙우애우기_필사본_한국 고려대학교_S#0011', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生怡然心蕩, 緩步堤頭, 尋聲下去.', '곽생이 기뻐한 채 마음이 들떠 천천히 강둑을 걸으며 소리를 따라 내려갔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0012', '장면_낙우애우기_필사본_한국 고려대학교_S#0012', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '有小娥, 年可十八九, 以淡粧素服, 雙垂玉脚, 嬌柔嫩態, 眞是絕色.', '그곳에는 나이가 18-19살 정도 되는 젊은 아가씨가 옅은 화장에 흰옷을 입고서 옥 같은 다리를 물에 담그고 있었으니 가녀린 자태가 참으로 절색이었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0013', '장면_낙우애우기_필사본_한국 고려대학교_S#0013', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生坐憩傍磯, 凝情熟視,', '곽생이 근처 바위에 앉아 쉬면서 정신을 쏟아 골똘히 바라보았으니', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0014', '장면_낙우애우기_필사본_한국 고려대학교_S#0014', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '着潮滿頰, 低頭浣衣', '그녀는 뺨 가득 홍조를 띤 채 머리를 숙이고 빨래를 했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0015', '장면_낙우애우기_필사본_한국 고려대학교_S#0015', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '既已, 日已夕矣, 小娥撤洗而歸, 頻頻湊目, 去了村裡.', '날이 이미 저물자 젊은 아가씨가 빨래를 마치고 돌아가는데 누차 눈길을 보내며 마을 안으로 사라졌다', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0016', '장면_낙우애우기_필사본_한국 고려대학교_S#0016', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生悵然消魂, 不能定情.', '곽생이 서글픈 심정으로 혼이 나가 마음을 진정시킬 수가 없었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '강둑(江堤)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0017', '장면_낙우애우기_필사본_한국 고려대학교_S#0017', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '隨娥而到其室, 卽依山大廈也.', '곽생이 젊은 아가씨를 따라 그녀의 집에 도착했는데 그 집은 곧 산을 의지하고 있는 큰 집이었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0018', '장면_낙우애우기_필사본_한국 고려대학교_S#0018', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '立于門前, 呼主人.', '문 앞에서서 주인을 부르자', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0019', '장면_낙우애우기_필사본_한국 고려대학교_S#0019', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小頃, 一叉鬟出邀曰:', '잠시 뒤 젊은 여종이 나와 맞이하며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0020', '장면_낙우애우기_필사본_한국 고려대학교_S#0020', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“吾家, 本無外居主人, 但有老媼及小姐而已. 客從何處, 而有所告也?”', '“우리 집에는 원래 외거하는 주인은 없고 다만 늙은 할미와 소저만 지내고 있을 뿐입니다. 손님께서는 어디에서 오셨으며 전하실 말씀이 있으십니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0021', '장면_낙우애우기_필사본_한국 고려대학교_S#0021', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0022', '장면_낙우애우기_필사본_한국 고려대학교_S#0022', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“遠程過客, 日昏失路. 借得一宵間許接否? ”', '“저는 먼길을 떠나는 과객인데 날이 저물어 길을 잃었습니다. 혹시 하룻밤 정도만 묵어도 괜찮겠습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0023', '장면_낙우애우기_필사본_한국 고려대학교_S#0023', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '叉指廊宇曰:', '여종이 행랑채를 가리키며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_행랑채', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0024', '장면_낙우애우기_필사본_한국 고려대학교_S#0024', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“憩此, 則夕飯備來矣.”', '“여기에서 쉬시면 저녁밥을 준비해 오겠습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_행랑채', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0025', '장면_낙우애우기_필사본_한국 고려대학교_S#0025', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '須臾, 叉鬟擎黑漆盤, 指碧琉瓶來進, 勉食之. 又張華燭, 設綺席而入, 主人待客之禮, 草草悉備矣.', '잠시 뒤 차환이 흑칠이 된 쟁반을 들고 푸른 유리병을 들고 와서 식사를 권했다. 또 화촉을 밝히고 비단 자리를 펴고 들어갔으니 주인이 손님을 대하는 예를 간단하게나마 모두 갖추었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_행랑채', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0026', '장면_낙우애우기_필사본_한국 고려대학교_S#0026', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '是夜三更, 皓月滿堂.', '이날 밤 삼경 무렵 밝은 달빛이 집을 가득 비추었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_행랑채', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0027', '장면_낙우애우기_필사본_한국 고려대학교_S#0027', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生無心傾壺, 醉興方酣, 獨出窓外, 徘徊庭中.', '곽생이 무심히 술병을 기울이다가 취흥이 막 무르익어 홀로 창밖으로 나와 뜰 안을 서성거렸다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_뜰', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0028', '장면_낙우애우기_필사본_한국 고려대학교_S#0028', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '回顧內堂, 四垣皆丈餘, 高不能踰.', '내당(內堂)을 돌아보니 사방의 담장이 모두 한 장 남짓 되어 높아서 뛰어넘을 수가 없었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_뜰', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0029', '장면_낙우애우기_필사본_한국 고려대학교_S#0029', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '乍見墻下有穴, 即鷄犬出入處也.', '잠시 담장 아래에 있는 구멍을 보니 곧 닭과 개가 드나드는 곳이었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_뜰', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0030', '장면_낙우애우기_필사본_한국 고려대학교_S#0030', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遂附腹鑽入. 河影入簷, 桐葉拂墻.', '마침내 곽생이 배를 땅에 붙여 비집고 들어갔는데 은하수 그림자가 처마에 들고 오동잎이 담장에 부딪혔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변 담장', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0031', '장면_낙우애우기_필사본_한국 고려대학교_S#0031', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遙見紗窓, 燭影明滅, 但有刀尺聲微微出.', '멀리 사창(紗窓)을 바라보니 촛불 그림자가 아늘거렸으며 그저 바느질 도구를 다루는 소리만 미미하게 들려왔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변 담장', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0032', '장면_낙우애우기_필사본_한국 고려대학교_S#0032', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生屏息跬足, 狙伏窓下, 透隙覘之,', '곽생이 숨을 죽이고 반걸음씩 내딛어 창 아래에 숨어 엎드리고는 창호지에 틈을 내어 안을 엿보았으니', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0033', '장면_낙우애우기_필사본_한국 고려대학교_S#0033', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '西壁下有老媼, 年可六十, 憑衾而坐, 東壁下小娥, 面燈刺繡, 卽江邊洴澼女也.', '서쪽 벽 아래에는 나이가 60살쯤 되어 보이는 늙은 할미가 이불을 덮고 앉아있었으며, 동쪽 벽 아래에는 젊은 아가씨가 등불을 마주하고 자수를 놓고 있었는데 그녀는 바로 강가에서 빨래하던 여인이었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변', '곽생, 김씨, 노파A', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0034', '장면_낙우애우기_필사본_한국 고려대학교_S#0034', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '老媼從容謂小娥日: “夜深退宿也.”', '늙은 할미가 조용히 젊은 아가씨에게 말했다. “밤이 깊었으니 물러가 쉬거라.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변', '곽생, 김씨, 노파A', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0035', '장면_낙우애우기_필사본_한국 고려대학교_S#0035', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生心自幸喜曰:', '곽생이 마음 속으로 몹시 기뻐하며 생각했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변', '곽생, 김씨, 노파A', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0036', '장면_낙우애우기_필사본_한국 고려대학교_S#0036', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“此間, 必有小娥之粧閣而獨宿者也.”', '“이 집에는 분명 젊은 아가씨가 단장하는 방이 있어 홀로 머물고 있을 것이다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내당(內堂) 주변', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0037', '장면_낙우애우기_필사본_한국 고려대학교_S#0037', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '彷徨之際, 顧眄左右, 階上屼然有小閣, 幽篁深草, 半藏前面. 生', '곽생이 방황하는 와중 좌우를 둘러보았는데 계단 위에 조그만 집이 우뚝 솟아 있었으니 대나무가 우거지고 풀이 무성하여 앞부분이 반쯤 가려져 있었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0038', '장면_낙우애우기_필사본_한국 고려대학교_S#0038', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '先預小閣, 軒上有竹篋, 大可以容身, 遂蒙篋潛身而坐矣.', '곽생이 미리 그 조그만 집으로 갔는데 헌상(軒上)에 대나무 상자가 있었으니 크기가 몸을 들일만 하여 마침내 상자를 덮고 몸을 숨긴 채 앉아있었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0039', '장면_낙우애우기_필사본_한국 고려대학교_S#0039', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '有頃, 小娥秉燭緩步而來, 徘徊軒上, 足蹴竹篋者再三,', '이윽고 젊은 아가씨가 촛불을 들고 천천히 걸어오더니 헌상을 돌아다니다가 발로 대나무 상자를 두세 번 찼다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0040', '장면_낙우애우기_필사본_한국 고려대학교_S#0040', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '仍開戶入房, 挑燈長嘯, 悄然誦長恨詞一闋.', '그리고 문을 열고 방으로 들어가 등불을 돋고 길게 한숨을 쉬더니 슬프게 장한사(長恨詞) 한 곡조를 읊조렸다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0041', '장면_낙우애우기_필사본_한국 고려대학교_S#0041', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生脫篋而入, 恭敬跪坐,', '곽생이 상자에서 나와 방으로 들어가 공손히 꿇어 앉았는데', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0042', '장면_낙우애우기_필사본_한국 고려대학교_S#0042', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥別無驚恐之色, 徐問曰:', '젊은 아가씨는 그다지 놀라거나 당황하는 기색이 없이 천천히 물었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0043', '장면_낙우애우기_필사본_한국 고려대학교_S#0043', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“秀才, 人耶神耶?”', '“그대께서는 사람입니까? 귀신입니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0044', '장면_낙우애우기_필사본_한국 고려대학교_S#0044', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '곽생이 말했다', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0045', '장면_낙우애우기_필사본_한국 고려대학교_S#0045', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“神何至此? 卽是人也.”', '“귀신이 어찌 여기에 이르겠습니까? 저는 사람입니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0046', '장면_낙우애우기_필사본_한국 고려대학교_S#0046', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '젊은 아가씨가 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0047', '장면_낙우애우기_필사본_한국 고려대학교_S#0047', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“誠是人也? 踰墻鑽穴, 胡爲乎深夜耶?”', '“정말 사람입니까? 담장을 넘고 구멍을 뚫고 오셨으니 깊은 밤에 어쩐 일이십니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0048', '장면_낙우애우기_필사본_한국 고려대학교_S#0048', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0049', '장면_낙우애우기_필사본_한국 고려대학교_S#0049', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“匵玉藏光, 善賈沽之, 盒香掩臭, 好情者袖之. 今美娘以芝蘭之色, 氷雪之姿, 雖欲斂彩鞱光於深閨匵盒之中, 其幽光暗臭, 自不可盡掩者矣. 願娘子聽我情悃. 學生本泰仁人, 家貧親老, 未得娶室. 赴擧京城, 偶入此鄉, 一看花顏, 三魂欲消. 非不知栢舟之難犯, 丘麻之可戒 而秦簫有緣, 蜀琴挑情, 蝶戀蜂貪, 忍注不得. 古人所謂‘情慾所蔽, 禮不暇立焉’者, 豈非格論耶?”', '“궤 속의 옥이 빛을 숨기고 있더라도 뛰어난 장사꾼들을 그것을 사고, 합 속의 향이 냄새를 덮더라도 정이 깊은 자는 이를 소매 속에 넣어둡니다. 지금 아름다운 낭자께서는 지초와 난초의 낯빛과 얼음과 눈같은 자태를 지니고 계십니다. 비록 깊은 규방의 궤와 함 속에 광채를 가리고자 하나 그 그윽한 빛과 은은한 향은 본디 다 감출 수 없는 법입니다. 바라건대 낭자께서는 저의 간곡한 정을 들어 보십시오. 저는 본래 태인(泰仁) 사람으로 집안이 가난하고 모친께서 연로하신데 아직 장가를 들지 못했습니다. 경성에 과거를 보러 가다가 우연히 이 마을에 들렀는데 그대의 꽃다운 얼굴을 한번 보고 나니 삼혼이 사라지는 줄 알았습니다. 백주(栢舟)를 범하기 어렵고 구마(丘麻)가 경계해야 함을 모르지는 않으나 진(秦)나라의 퉁소에 연분이 있었고 촉(蜀)나라의 거문고는 정을 돋우었으니 나비가 그리워하고 벌이 탐내는 것을 차마 멈출 수 없습니다. 옛사람이 ‘정욕에 가리워지면 예를 세울 겨를이 없다.’라고 말한 것이 어찌 합당한 의론이 아니겠습니까?”', '丘 : 원본에는 立', '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', '구마', NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0050', '장면_낙우애우기_필사본_한국 고려대학교_S#0050', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥微笑曰:', '작은 아가씨가 미소를 띠며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0051', '장면_낙우애우기_필사본_한국 고려대학교_S#0051', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“吾家扄鐍甚固, 秀才何以得入也?”', '“우리 집은 자물쇠로 매우 굳게 잠겨 있는데 그대께서는 어떻게 들어오셨습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0052', '장면_낙우애우기_필사본_한국 고려대학교_S#0052', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生備傳入來事,', '곽생이 들어오게 된 경위를 갖추어 말하자', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0053', '장면_낙우애우기_필사본_한국 고려대학교_S#0053', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥斂顔曰:', '젊은 아가씨가 얼굴빛을 고치며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0054', '장면_낙우애우기_필사본_한국 고려대학교_S#0054', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“郎君軒裳華胄, 金玉奇標, 斯實淑媛之賢夫也. 不陋蓬菲, 許摧肝腸, 雖迷蠢, 豈無感心? 然而郎君一去之後, 攀雲弄桂, 富貴爀耀, 則非但郎君之不復念也, 妾亦不敢望郎君也. 守紅深閨, 堪作望門之婦而已, 豈不哀哉?”', '“낭군의 높은 신분과 훌륭한 가문, 그리고 금옥과 같은 의용은 참으로 숙녀의 훌륭한 남편감이십니다. 봉비(蓬菲)를 누추하게 여기지 않으시고 기꺼이 고통을 받아들이시니 첩이 비록 못나고 어리석으나 어찌 마음에 감동됨이 없겠습니까? 그러나 낭군께서 이곳을 떠나신 뒤에 구름 속에 올라 계수나무를 희롱하여 부귀가 찬란하게 빛난다면, 낭군께서만 저를 다시 생각하지 않으실 뿐만 아니라 저 역시 감히 낭군을 바라볼 수 없게 될 것입니다. 깊은 규방에서 붉은 얼굴 지키면서 문만 바라보는 부인이 되는 것을 견뎌야 할 따름이니 어찌 슬프지 않겠습니까? ”', '葑 : 원본에는 蓬', '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0055', '장면_낙우애우기_필사본_한국 고려대학교_S#0055', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '仍泣下涓涓.', '그러고는 눈물을 뚝뚝 흘렸다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0056', '장면_낙우애우기_필사본_한국 고려대학교_S#0056', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生以手拭其涙曰:', '곽생이 손으로 그 눈물을 닦아주며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0057', '장면_낙우애우기_필사본_한국 고려대학교_S#0057', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“黃河不斷, 白首爲誓.”', '“황하가 끊어지지 않듯 백발이 되도록 맹세할 것입니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_소각(小閣)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0058', '장면_낙우애우기_필사본_한국 고려대학교_S#0058', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '携手同枕.', '이에 손을 잡고 가 베개를 함께했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내실(內室)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0059', '장면_낙우애우기_필사본_한국 고려대학교_S#0059', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥於枕上謂生:', '작은 아가씨가 베개 위에서 곽생에게 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내실(內室)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0060', '장면_낙우애우기_필사본_한국 고려대학교_S#0060', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“妾本錦山富商之女也. 妾父貪於班婚, 嫁妾此家. 未及數月, 小郎夭逝, 紅顏薄命, 撫躬自悼, 但願死後生前, 獲奉佳郎矣. 去夜, 夢有人爭傳云: “龍戰于野. 出見之, 果於雲霧中, 瑞色亘天.” 有頃, 紅珠落於江岸, 黃龍見妾逐來. 妾恐惧奔入, 閉戶堅鎖. 黃龍以玉髯朱舌, 舉頭回入於墻下小穴, 盤于軒上竹篋之中. 妾終夜恐刼, 夢事甚異, 故翌朝出江邊, 就見落珠處, 則有小冊子遺之. 妾拾而藏之, 郎君來坐其處, 又聞郎君入來之路, 則與夢龍少無差爽. 以是知郎君之登科, 而妾之奉郎君巾櫛, 實是天緣也. 願郎君俯察至願, 永矢不貳.”', '“첩은 본래 금산(錦山) 부상(富商)의 딸입니다. 저의 부친께서는 양반 집안과 혼인하는 것을 탐내어 저를 이 집에 시집보내셨습니다. 아직 몇 달이 채 안 되었는데 젊은 신랑이 요절하여 홍안박명(紅顏薄命)한 저는 몸을 쓰다듬으며 스스로 슬퍼했으니 그저 사후든 생전이든 훌륭한 낭군을 모시기만을 원했습니다. 그런데 지난밤 꿈에 어떤 사람이 바삐 와서 “용들이 들판에서 싸우고 있다.”라고 전하길래 첩이 나가 보니 과연 구름과 안개 속에서 상서로운 빛깔이 하늘에 닿아있었습니다. 잠시 뒤 붉은 구슬이 강 언덕에 떨어졌고 황룡이 저를 보고 쫓아왔습니다. 저는 몹시 두려워 달려 들어와 문을 닫고 굳게 잠갔습니다. 황룡은 옥 수염과 붉은 혀를 하고서 머리를 들어 담 아래 작은 구멍으로 들어와 마루 위 대나무 상자 속에 똬리를 틀고 있었습니다. 저는 밤새도록 두려워하다가 꿈속 일이 몹시 기이해 다음 날 강가로 나가 구슬을 떨어뜨린 곳을 보니 작은 책자가 거기에 남겨져 있었습니다. 첩이 이를 주워서 간직해 두었는데 오늘 낭군께서 그곳에 와서 앉으셨으며 또 낭군께서 들어오신 길을 들어보니 꿈속의 용과 조금도 차이가 없었습니다. 이를 통해 낭군께서 급제하실 줄 알았으며 제가 낭군의 건즐(巾櫛)을 받드는 것도 참으로 하늘이 내리신 인연입니다. 바라건대 낭군께서는 첩의 간절한 소원을 굽어 살피시고 두 마음을 먹지 마시옵소서.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내실(內室)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0061', '장면_낙우애우기_필사본_한국 고려대학교_S#0061', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '仍出冊子贈之.', '그러고는 책자를 꺼내 곽생에게 주었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내실(內室)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0062', '장면_낙우애우기_필사본_한국 고려대학교_S#0062', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生忙受, 寓目外面, 以龍珠二字題目, 次次按閱, 則盡是當今第一科製句, 上以靑黃黑圈點, 箇箇如琅玕之美也.', '곽생이 다급히 받고서 표지를 살펴보니 용주(龍珠) 2글자로 표제를 하고 있었으며 차근차근 읽어보니 모두 당시에 가장 뛰어난 제구(製句)인데다 위에는 청색‧황색‧흑색 권점이 찍혀있었으니 하나하나 옥돌같은 아름다움을 띠고 있었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집_내실(內室)', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0063', '장면_낙우애우기_필사본_한국 고려대학교_S#0063', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生納于袖中, 摻手泣別, 悤悤登程.', '곽생은 책자를 소매 속에 넣어 두고 여인의 손을 잡고 울면서 이별하고는 서둘러 길을 떠났다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '김씨의 대갓집', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0064', '장면_낙우애우기_필사본_한국 고려대학교_S#0064', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '到京邸待科日, 及見掛題, 乃是龍珠篇第三章題也.', '경저(京邸)에 머무르며 과거 시험 날을 기다리다가 과제로 걸린 것을 보니 용주(龍珠)편 제3장의 문제이었다.', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '과장(科場)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0065', '장면_낙우애우기_필사본_한국 고려대학교_S#0065', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生一筆揮之, 投券而出.', '곽생이 단숨에 답안을 써 내리고는 답안을 제출하고 나왔다.', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '과장(科場)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0066', '장면_낙우애우기_필사본_한국 고려대학교_S#0066', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '日暮時, 自春院門, 呼‘壯元郎, 郭某者’.', '해가 질 무렵 춘원문(春院門)에서 ‘장원 급제자 곽아무개’라고 호명했다.', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '춘원문(春院門)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0067', '장면_낙우애우기_필사본_한국 고려대학교_S#0067', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生戴桂花, 擁仙樂, 光彩聾一世矣. 三日游街, 鹿鳴還鄉.', '곽생은 계수화를 꽂고 선악(仙樂)을 둘렀으며 광채가 온 세상에 퍼졌으니 삼일유가를 끝내고 녹명연(鹿鳴宴)을 마친 다음 고향으로 돌아갔다.', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '-', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0068', '장면_낙우애우기_필사본_한국 고려대학교_S#0068', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '路上有一老僕, 俯哭于馬前,', '그런데 가는 길에 한 노복이 말 앞으로 와서 엎드려 통곡하자', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '-', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0069', '장면_낙우애우기_필사본_한국 고려대학교_S#0069', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '急問, 卽是生老母訃音也.', '곽생이 다급히 물어보니 곧 곽생의 노모가 세상을 떠났다는 소식이었다.', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '-', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0070', '장면_낙우애우기_필사본_한국 고려대학교_S#0070', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生墮馬躃踊,', '곽생이 말에서 내려 가슴을 두드리며 통곡했으니', NULL, '조선', '현실계', '한국(韓國)_서울_한양(漢陽)', '-', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0071', '장면_낙우애우기_필사본_한국 고려대학교_S#0071', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '從者扶護, 轉至鎭岑邑底.', '따르던 사람들이 그를 부축해 진잠읍(鎭岑邑) 아래로 데려갔다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '-', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0072', '장면_낙우애우기_필사본_한국 고려대학교_S#0072', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '時秋風葉落, 寒月照窓, 蓼莪之懷滿腔, 風樹之痛挾骨.', '때는 가을바람에 낙엽이 떨어지고 찬 달빛이 창을 비추고 있었으니 부모를 제대로 봉양하지 못한 회포가 속에 가득하고 부모를 잃은 애통함이 뼈를 파고들었다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0073', '장면_낙우애우기_필사본_한국 고려대학교_S#0073', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '推窓跳出, 散步旅庭, 或仰天而呼泣, 或仆地而搗胸, 垂髮掩面, 失性哀呌.', '곽생은 창을 열고 밖으로 뛰쳐나가 여관의 뜰을 이리저리 거닐었는데 하늘을 올려다보며 통곡하는가 하면 땅에 엎드려 가슴을 두드렸으니 헝크러진 머리가 얼굴을 가린 채 정신을 잃고 슬피 울었다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0074', '장면_낙우애우기_필사본_한국 고려대학교_S#0074', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '忽聞飈風, 動地, 健夫三十餘人, 排門直入.', '그런데 홀연 회오리바람 소리가 들리고 땅이 흔들리더니 건장한 장부 30여 인이 문을 밀치고 곧바로 들어왔다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0075', '장면_낙우애우기_필사본_한국 고려대학교_S#0075', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '執生結縛, 瞥然肩負, 前擁後扶, 如電如雷, 馳去甚駛.', '그리고 곽생을 붙잡아 결박하고 삽시간에 어깨로 짊어지고는 앞뒤로 둘러싸 번개와 우레 같은 속도로 말을 몰아 급히 질주했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0076', '장면_낙우애우기_필사본_한국 고려대학교_S#0076', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '而其旅館主人, 與從者, 茫然不知也.', '그러나 여관의 주인과 곽생을 따르던 자들은 까마득히 알지 못했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0077', '장면_낙우애우기_필사본_한국 고려대학교_S#0077', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '行可六七里, 而驅入於大村庄高門巨廈之中, 直至內庭,', '장부들이 6-7리 쯤 가다가 큰 촌장(村庄) 중 높은 문이 있는 커다란 저택 안으로 재빨리 들어가 곧장 내정(內庭)에 이르렀으니', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내정(內庭)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0078', '장면_낙우애우기_필사본_한국 고려대학교_S#0078', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '始解縛, 納于小房中, 自外鎖鑰.', '그제서야 곽생을 풀고 방 안으로 들인 다음 밖에서 문을 자물쇠로 잠갔다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0079', '장면_낙우애우기_필사본_한국 고려대학교_S#0079', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生收拾精神, 舉目回視, 錦屏重重, 華燭煌煌. 繡衾角枕, 玉頮鈆黛, 蘭麝瓊貝之屬, 左右羅列, 粲粲郁郁, 如坐波斯市中.', '곽생이 정신을 가다듬고 눈을 떠 주위를 둘러보니 비단 병풍이 겹겹이 있고 화촉이 밝게 빛나고 있었다. 또 수놓은 이불과 뿔 모양 베개, 옥 세숫대야와 화장품, 난초와 사향, 구슬과 패물 등이 이리저리 늘어져 있고 반짝반짝 찬란한 것이 페르시아 시장 한가운데에 앉아있는 듯했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0080', '장면_낙우애우기_필사본_한국 고려대학교_S#0080', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '而門外, 繞匝喧聒, 往來奔走, 儼然縉紳家也.', '문밖에는 사람들이 주위에서 떠들썩하고 분주하게 오갔으니 엄연한 사대부의 집안이었다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0081', '장면_낙우애우기_필사본_한국 고려대학교_S#0081', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '少頃, 有珊珊之聲, 自遠至近, 侍女四五人, 扶衛一美女, 開戶納房, 鎖鑰如初.', '잠시 뒤 옥구슬 구르는 소리가 멀리서부터 가까이 다가왔으니 4-5명의 시녀가 한 미인을 에워싸고 와서 문을 열고 방 안으로 들여보내고는 아까처럼 자물쇠로 문을 잠갔다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0082', '장면_낙우애우기_필사본_한국 고려대학교_S#0082', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生疑怪莫測, 對呼侍女曰:', '곽생이 의아하고 망측해하며 시녀들을 불러 말했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0083', '장면_낙우애우기_필사본_한국 고려대학교_S#0083', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“是何事? 是何事? 願見主人一言卞之.”', '“이게 무슨 일인가? 이게 무슨 일인가? 바라건대 주인을 뵙고 한마디 말로 상황을 알았으면 합니다.”', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0084', '장면_낙우애우기_필사본_한국 고려대학교_S#0084', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '其美女進執生臂曰:', '이에 미인이 앞으로 와서 곽생의 팔을 붙잡으며 말했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0085', '장면_낙우애우기_필사본_한국 고려대학교_S#0085', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“郎君旣入吾房, 更欲何之? 東床合歡, 禮備珍重. 今夕何夕, 背妾欲去? 妾雖柔腸, 不畏一死.”', '“낭군께서 이미 제 방에 들어오셨는데 또 어디를 가신답니까? 동상(東床)에서 기쁨을 함께하고 진중히 예를 갖추십시오. 오늘 저녁이 어떤 저녁인데 저를 떠나려 하십니까? 첩이 비록 마음은 연약하지나 죽는 것은 두렵지가 않습니다.”', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0086', '장면_낙우애우기_필사본_한국 고려대학교_S#0086', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '涕泣涓涓, 若浥露之海棠.', '이렇게 눈물을 줄줄 흘리니 마치 이슬을 머금은 해당화 같았다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0087', '장면_낙우애우기_필사본_한국 고려대학교_S#0087', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生收髮斂容, 長跪而對曰:', '곽생이 머리와 의관을 단정히 하고 꿇어앉아 대답했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0088', '장면_낙우애우기_필사본_한국 고려대학교_S#0088', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“吾本湖南人, 離違赴舉, 歸遭親喪, 獨步寒庭, 對月悲傷. 何來趕卒, 縶之維之, 飛也似驅, 入於此房. 是家何家? 處子何人?”', '“저는 본래 호남 사람으로 고향을 떠나 과거를 보고 돌아오는 길에 모친의 부음 소식을 듣게 되어 홀로 쓸쓸한 뜰을 거닐고 달을 마주하며 비통해하고 있었습니다. 그런데 어디서 온 장부들이 저를 결박해 말을 몰 듯 재빨리 데리고 와 이 방에 들여놨습니다. 이 집은 어떤 집이고 처자는 누구십니까?”', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0089', '장면_낙우애우기_필사본_한국 고려대학교_S#0089', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '美女低首良久, 又言曰:', '미인은 고개를 숙이고 한참 동안 있다가 다시 말했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0090', '장면_낙우애우기_필사본_한국 고려대학교_S#0090', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“命道奇薄, 事到此境, 皇天后土, 此羞難洗. 然入吾房者, 即吾夫也, 焉有一女而事二夫也?:', '“운명이 기박하여 일이 이 지경이 되었으니 천황과 후토신이라도 이 수치를 씻어내기가 어렵습니다. 그러나 제 방에 들어온 사람은 곧 제 남편이니 어찌 한 여자가 두 남편을 섬기겠습니까?”', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0091', '장면_낙우애우기_필사본_한국 고려대학교_S#0091', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '翻身入內房焉.', '이렇게 말하고는 몸을 돌려 안방으로 들어갔다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0092', '장면_낙우애우기_필사본_한국 고려대학교_S#0092', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '元來此家, 盧進士家也. 進士已死, 妻朱氏, 但有一女, 結婚於連山蔡姓家. 蔡家郎子, 素有狂癎之疾, 每於稠人中, 則本症輒發, 失性奔逃矣. 是日行禮後, 猝然狂奔, 兩家奴僕, 四散趨覓. 夜深後, 見旅舘庭內, 獨有散髮叫唬者, 以爲蔡郎, 誤納洞房也.', '사실 이 집은 노진사(盧進士)의 집이다. 노 진사는 이미 죽고 그 아내 주씨(朱氏)는 딸 하나만을 두었으니 그녀는 연산(連山)의 채씨(蔡氏) 집안과 혼약을 맺었다. 채씨 집안의 신랑은 평소에 간질병을 앓고 있어서 늘 많은 사람들 속에 있으면 본래 지니던 증세가 발작해 실성하고서 달아나곤 했었다. 이날 혼례를 행한 뒤에도 갑자기 광분해버리는 바람에 두 집안의 노복들이 사방으로 흩어져 급히 찾아보았다. 밤이 깊은 뒤에 여관의 뜰 안을 보니 홀로 머리를 풀어헤치고 울부짖는 사람이 있어 노복들이 채랑으로 착각하고 규방에 잘못 들여 넣고 말았다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집_내실(內室)', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0093', '장면_낙우애우기_필사본_한국 고려대학교_S#0093', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '於是會其宗族, 語其始末.', '그리하여 그 친척들을 불러모아 자조치종을 설명하니', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨, 친척', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0094', '장면_낙우애우기_필사본_한국 고려대학교_S#0094', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '宗族皆曰:', '친척들이 모두 이렇게 말했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨, 친척', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0095', '장면_낙우애우기_필사본_한국 고려대학교_S#0095', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“先來而不入房者, 人緣也, 後來而入其房者, 天緣也. 世焉有人勝天之理乎?”', '“먼저 와서 방에 들어가지 않은 것은 사람의 인연이고, 뒤에 와서 그 방에 들어 간 것은 하늘의 인연이다. 세상에 어찌 사람이 하늘을 능가할 리가 있겠는가?”', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨, 친척', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0096', '장면_낙우애우기_필사본_한국 고려대학교_S#0096', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '仍向生議婚,', '곧 곽생에게 혼인에 대해 의논하니', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨, 친척', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0097', '장면_낙우애우기_필사본_한국 고려대학교_S#0097', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生不得已, 許之.', '곽생이 하는 수 없이 받아들였다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨, 친척', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0098', '장면_낙우애우기_필사본_한국 고려대학교_S#0098', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '凌晨歸旅舘, 率其從者, 明日發行.', '곽생이 이른 새벽 여관으로 돌아와 따르는 사람들을 데리고 다음날 길을 떠났다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '여관', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0099', '장면_낙우애우기_필사본_한국 고려대학교_S#0099', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '還家, 初終喪事, 以禮過行.', '집으로 돌아와 초종상례(初終喪禮)를 예로써 행했다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0100', '장면_낙우애우기_필사본_한국 고려대학교_S#0100', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '日月流邁, 遽經三年, 涓吉行禮于盧家.', '세월이 순식간에 흘러 어느덧 3년이 지나 노씨 집안에서 좋은 날을 가려 혼례를 행했다.', NULL, '조선', '현실계', '한국(韓國)_대전(大田)_유성구(儒城區)_진잠동(鎭岑洞)', '노씨(盧氏)의 대갓집', '곽생, 노씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0101', '장면_낙우애우기_필사본_한국 고려대학교_S#0101', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '歸路入濟原驛, 問街頭老嫗曰:', '곽생이 돌아가는 길에 제원역에 들러 길가의 늙은 할멈에게 물었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0102', '장면_낙우애우기_필사본_한국 고려대학교_S#0102', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“彼家小姐, 尙無恙否?”', '“저 집의 소저는 아직 안녕하십니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0103', '장면_낙우애우기_필사본_한국 고려대학교_S#0103', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '老嫗答曰:', '늙은 할멈이 대답했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0104', '장면_낙우애우기_필사본_한국 고려대학교_S#0104', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“相公在何處? 而問何所據也?”', '“상공께서는 어느 곳에 계신 분입니까? 또 무슨 이유로 물어보십니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0105', '장면_낙우애우기_필사본_한국 고려대학교_S#0105', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0106', '장면_낙우애우기_필사본_한국 고려대학교_S#0106', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“其家少姐, 即吾表妹也, 過去路, 將欲尋見也.”', '“그 집의 젊은 아가씨는 곧 저의 외종 사촌인데 지나가는 길에 들려 보려고 합니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0107', '장면_낙우애우기_필사본_한국 고려대학교_S#0107', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '老嫗曰:', '늙은 할멈이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0108', '장면_낙우애우기_필사본_한국 고려대학교_S#0108', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“其家老媼, 去秋病死, 其小姐獨居無依. 盡賣家産, 搬移于錦山邑底. 今春吾子以事適沃川, 路由珍山縣洛陽村杏花店, 見其小姐賣酒資生云矣. 相公欲見之, 往見其處可也.”', '“그 집의 늙은 어미는 작년 가을에 병으로 세상을 떠나고 그 젊은 여인은 의탁할 곳 없이 홀로 지내고 있는데 집안의 재산을 전부 팔아 금산의 읍내로 이사를 갔습니다. 올해 봄에 제 아들이 옥천(沃川)에 용무가 있었는데 가던 길에 진산현(珍山縣) 낙양촌(洛陽村) 행화점(杏花店)을 경유하게 되어 그 소저가 술을 팔아 생계를 잇는 것을 보았다고 합니다. 상공께서 그녀를 만나고자 한다면 그곳으로 가보시면 될 것입니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_제원면(濟原面)', '길거리(街頭)', '곽생, 노파B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0109', '장면_낙우애우기_필사본_한국 고려대학교_S#0109', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生馳馬向珍山, 訪洛陽村路傍店楣上, 扁題杏花店三字.', '곽생이 진산을 향해 말을 몰아 낙양촌 길가의 주점의 문미에 ‘행화점’ 3글자로 현판이 달린 곳을 찾아갔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0110', '장면_낙우애우기_필사본_한국 고려대학교_S#0110', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生繫馬門柱, 從容上樓.', '곽생이 말을 문 기둥에 묶고 조용히 누각으로 올라갔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생', NULL, '『剪燈新話』‧「聯芳樓記', NULL, NULL, NULL, NULL);
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SNUAUG01NU001P0111', '장면_낙우애우기_필사본_한국 고려대학교_S#0111', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '有小娥, 年可十六七, 左右豪流蕩子, 亂坐傾盃.', '거기에는 16-17세쯤 되어 보이는 젊은 아가씨가 있었으니 주위에 호기롭고 방탕한 자제들이 어지러이 앉아 술잔을 기울이고 있었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0112', '장면_낙우애우기_필사본_한국 고려대학교_S#0112', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥見生改容, 頗有款色.', '젊은 여인이 곽생을 보고는 표정을 바꾸며 사못 정중한 낯빛을 띠었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0113', '장면_낙우애우기_필사본_한국 고려대학교_S#0113', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0114', '장면_낙우애우기_필사본_한국 고려대학교_S#0114', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“此店有上品酒乎?”', '“이 주점에서 가장 좋은 술이 있는가?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0115', '장면_낙우애우기_필사본_한국 고려대학교_S#0115', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小娥曰:', '젊은 여인이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0116', '장면_낙우애우기_필사본_한국 고려대학교_S#0116', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“相公如求上品酒, 請小待之.”', '“상공께서 만일 가장 좋은 술을 원하신다면 잠깐 기다려 주십시오.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0117', '장면_낙우애우기_필사본_한국 고려대학교_S#0117', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遂邀生就席而坐, 飲酒.', '드디어 곽생을 맞이해 자리를 마련해 앉히고 술을 마시게 했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0118', '장면_낙우애우기_필사본_한국 고려대학교_S#0118', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '人次次散去, 小娥問生曰:', '사람들이 하나둘씩 자리를 떠나자 젊은 여인이 곽생에게 물었다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0119', '장면_낙우애우기_필사본_한국 고려대학교_S#0119', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“相公, 自齋原驛來否?”', '“상공께서는 제원역에서 오셨습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0120', '장면_낙우애우기_필사본_한국 고려대학교_S#0120', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0121', '장면_낙우애우기_필사본_한국 고려대학교_S#0121', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“然.”', '“그렇습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0122', '장면_낙우애우기_필사본_한국 고려대학교_S#0122', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '젊은 여인이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0123', '장면_낙우애우기_필사본_한국 고려대학교_S#0123', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“相公三年前, 果無赴舉之事, 而路由其處乎?”', '“상공께서는 3년 전 과연 과거를 보는 일로 가던 중에 그 길을 지나치지 않았는지요?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0124', '장면_낙우애우기_필사본_한국 고려대학교_S#0124', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0125', '장면_낙우애우기_필사본_한국 고려대학교_S#0125', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“有之.”', '“그런 적이 있었습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0126', '장면_낙우애우기_필사본_한국 고려대학교_S#0126', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '여인이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0127', '장면_낙우애우기_필사본_한국 고려대학교_S#0127', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“那時相公, 不爲經宿於依山廣廈之內軒乎?”', '“그때 상공께서는 산을 의지하고 있는 큰 집의 안 마루에서 묵게 되지 않으셨습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0128', '장면_낙우애우기_필사본_한국 고려대학교_S#0128', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0129', '장면_낙우애우기_필사본_한국 고려대학교_S#0129', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“宿矣.”', '“묵었습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0130', '장면_낙우애우기_필사본_한국 고려대학교_S#0130', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '曰:', '여인이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0131', '장면_낙우애우기_필사본_한국 고려대학교_S#0131', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“然則, 不記妾顏乎? 吾家小姐, 一自相公去後, 念久成病, 伏枕潛潛, 三載于玆矣. 此家前路, 卽去京大路也, 南來之人, 莫不落鞭, 或冀相公之過此, 豈料今日之相逢?”', '“그렇다면 저의 얼굴을 기억하지 못하십니까? 우리 집 아가씨는 한번 상공께서 떠나신 뒤로 오랫동안 그리워하다가 병을 앓아 침실에 엎드려 움직이지도 못한지가 올해로 3년째입니다. 이 집의 길은 곧 서울로 떠나는 큰길로 남쪽에서 올라오는 사람들이 채찍을 쉬지 않는 사람이 없으니 혹시라도 상공께서 여기를 지나치시길 기대했으나 오늘 서로 만날 줄을 어찌 생각했겠습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0132', '장면_낙우애우기_필사본_한국 고려대학교_S#0132', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '仍雀躍入內曰:', '곧 폴짝 뛰어 안방에 들어가서 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0133', '장면_낙우애우기_필사본_한국 고려대학교_S#0133', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“小姐! 小姐! 郎君來矣.”', '“아가씨! 아가씨! 낭군께서 오셨습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 여종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0134', '장면_낙우애우기_필사본_한국 고려대학교_S#0134', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小姐精神怳惚, 起坐床褥, 進執生手, 舊悵新戀, 悲喜交切.', '소저가 정신이 황홀하여 침상에서 일어났다가 앉았다 하다가 나아가 곽생의 손을 잡고서 과거의 슬픔과 지금의 간절함을 이야기했으니 희비가 교차했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 여종, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0135', '장면_낙우애우기_필사본_한국 고려대학교_S#0135', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '乃飲泣曰:', '이내 소저가 눈물을 머금으며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0136', '장면_낙우애우기_필사본_한국 고려대학교_S#0136', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“郎君生乎? 何其失信若是, 斷盡兒女子肝腸乎? 槐黃八月, 題名鴈塔耶?”', '“낭군께서는 살아계셨습니까? 어찌 이토록 신의를 잃고 아녀자의 간장을 다 태우신답니까? 회나무가 노랗게 물드는 8월에 대안탑(大雁塔)에 이름은 적으셨습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0137', '장면_낙우애우기_필사본_한국 고려대학교_S#0137', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0138', '장면_낙우애우기_필사본_한국 고려대학교_S#0138', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“登科如意, 而失信非情.”', '“과거급제는 뜻대로 이루었으나 신의를 잃은 것은 제 뜻이 아니었습니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0139', '장면_낙우애우기_필사본_한국 고려대학교_S#0139', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遂一遍顛末.', '드디어 자초지종을 다 이야기했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0140', '장면_낙우애우기_필사본_한국 고려대학교_S#0140', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小姐曰:', '소저가 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0141', '장면_낙우애우기_필사본_한국 고려대학교_S#0141', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“然則其間, 胡無一字音信也?”', '“그렇다면 그동안 어찌하여 한 자의 소식도 없었던 것입니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0142', '장면_낙우애우기_필사본_한국 고려대학교_S#0142', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生曰:', '곽생이 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0143', '장면_낙우애우기_필사본_한국 고려대학교_S#0143', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“荒迷餘喘, 何暇致此.”', '“당황하고 어지럽고 겨우 목숨만 부지했으니 어느 겨를에 여기까지 살필 수 있었겠습니까?”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0144', '장면_낙우애우기_필사본_한국 고려대학교_S#0144', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小姐亦具述始末曰:', '소저 역시 그간의 자초지종을 갖추어 설명하며 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0145', '장면_낙우애우기_필사본_한국 고려대학교_S#0145', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“奉別倏爾, 情緒糾結, 塊處孤房, 祝手苦竢. 使人往探郎君之消息, 京來新恩, 絡繹不絕, 終不見近似於郎君儀貌者. 故妾妄慮郎君之落在山外. 然三年不來, 尤增疑慮, 今春與侍兒來住此地. 若過今春, 則使相逢於鬼門關外, 殆矣, 殆矣.”', '“급하게 낭군과 이별하고 복잡한 마음으로 빈 방에 홀로 지내면서 손을 모아 고대했습니다. 사람을 보내 낭군의 소식을 가서 탐문하도록 했는데 서울에서 오는 급제자들은 끊이지 않고 연이어 졌으나 끝내 낭군의 모습과 비슷한 사람은 보이지 않았습니다. 그러므로 첩은 망령되게도 낭군께서 낙방하고 외진 곳에 있다고 생각했습니다. 그러나 3년 동안 오지 않자 더욱 의심스러운 생각이 들어 올 봄에 여종과 함께 여기에 머물렀습니다. 만약 이번 봄이 지났으면 혹 귀문관(鬼門關) 밖에서 상봉했을 것이니 참으로 위태로울 뻔했습니다.”', '妄 : 원본에는 忘', '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0146', '장면_낙우애우기_필사본_한국 고려대학교_S#0146', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '生又說盧家成婚事,', '곽생 역시 노진사 댁과 혼사를 치른 일을 이야기하니', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0147', '장면_낙우애우기_필사본_한국 고려대학교_S#0147', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '小姐謝曰:', '소저가 말했다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0148', '장면_낙우애우기_필사본_한국 고려대학교_S#0148', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '“郎君慶福如此, 宜有天神指媒矣.”', '“낭군의 경사스러운 복이 이와 같으니 분명히 천신께서 중매를 지시함이 있는 것입니다.”', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面)', '행화점(杏花店)_내방', '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0149', '장면_낙우애우기_필사본_한국 고려대학교_S#0149', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '遂與治裝同歸.', '마침내 행장을 꾸려 함께 고향으로 돌아왔다.', NULL, '조선', '현실계', '한국(韓國)_충청남도(忠淸南道)_금산군(錦山郡)_진산면(珍山面) / 한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', NULL, '곽생, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0150', '장면_낙우애우기_필사본_한국 고려대학교_S#0150', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '翌年春, 率盧家女, 爲上室, 以金女爲副室, 生九男.', '이듬해 봄 노씨 집안의 딸을 데리고 와서 상실(上室)로 삼고 김씨 여인은 부실(副室)로 삼은 뒤 아홉 아들을 낳았다.', NULL, '조선', '현실계', '한국(韓國)_전라북도(全羅北道)_정읍시(井邑市)_태인면(泰仁面)', '곽생(郭生)의 집', '곽생, 노씨, 김씨', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0151', '장면_낙우애우기_필사본_한국 고려대학교_S#0151', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '憂樂之間, 摠是奇遇矣.', '근심과 기쁨 사이에 모두 기이한 만남이다.', NULL, '종결평', '종결평', '종결평', '종결평', '종결평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SNUAUG01NU001P0152', '장면_낙우애우기_필사본_한국 고려대학교_S#0152', '낙우애우기', '樂遇哀遇記', '3인칭', '한문', '外史氏曰: “詩云: ‘娶妻如之何? 非媒不得.’ 以此觀之, 何嘗有媒而後娶妻乎? 非徒娶妻, 新榜槐名, 由此占得, 庸非天意而誰也? 雖然, 以若榮華, 終未得一日養於玆庭, 是爲郭子之大恨也.”', '외사씨가 말한다. “『시경(詩經)』에 ‘아내를 얻으려면 어떻게 해야 하는가? 중매가 아니면 얻을 수 없다.’라고 했으니 이를 통해 본다면 어찌 중매를 둔 다음에야만 아내를 얻을 수 있겠는가? 아내를 얻었을 뿐만 아니라 신방(新榜)에 합격자로 이름을 걸은 것도 이를 통해 차지한 것이니 하늘의 뜻이 아니고 무엇이겠는가? 비록 그렇지만 이러한 영화로움으로 끝내 하루도 모친을 봉양하지 못했으니 이것이 곽생의 큰 한이다.”', NULL, '최종평', '최종평', '최종평', '최종평', '최종평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0001', '장면_만복사저포기_목판본_일본 내각문고_001_S#0001', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '南原有梁生者, 早喪父母, 未有妻室, 獨居萬福寺之東.', '남원(南原)에 양생(梁生)이라는 자가 있었는데 일찍 부모를 여의고 아직 아내가 없이 만복사(萬福寺)의 동쪽에 홀로 지냈다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0002', '장면_만복사저포기_목판본_일본 내각문고_001_S#0002', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '房外有梨花一株, 方春盛開, 如瓊樹銀堆.', '방 밖에 배나무 한 그루가 있었는데 막 봄이 되어 꽃이 만개하니 옥으로 된 나무에 은이 쌓여있는 것 같았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0003', '장면_만복사저포기_목판본_일본 내각문고_001_S#0003', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生每月夜, 逡巡朗吟其下.', '양생은 달 밝은 밤마다 그 나무 아래에서 머뭇거리며 낭랑히 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0004', '장면_만복사저포기_목판본_일본 내각문고_001_S#0004', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '詩曰:', '시는 이러하다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0005', '장면_만복사저포기_목판본_일본 내각문고_001_S#0005', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“一樹梨花伴寂寥, 可憐辜負月明宵. 靑年獨臥孤窓畔, 何處玉人吹鳳簫?”', '“배꽃 한 그루 적막함을 짝하는데, 가련히도 달 밝은 밤을 그냥 저버리는구나. 청년이 홀로 외로운 창가에 누웠는데, 어디서 미인이 봉황 피리를 부는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0006', '장면_만복사저포기_목판본_일본 내각문고_001_S#0006', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“翡翠孤飛不作雙, 鴛鴦失侶浴晴江. 誰家有約敲碁子, 夜卜燈花愁倚窓.”', '“비취새는 외로이 날며 짝을 짓지 못하고, 원앙새는 짝을 잃고 맑은 강에서 목욕하네. 누구 집에 약속이 있는지 바둑돌을 두드리며, 밤에 등불로 점치다가 시름스레 창에 기대네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0007', '장면_만복사저포기_목판본_일본 내각문고_001_S#0007', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '吟罷, 忽空中有聲曰:', '시 읊기를 마치자 홀연히 공중에서 소리가 났다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0008', '장면_만복사저포기_목판본_일본 내각문고_001_S#0008', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“君欲得好逑, 何憂不遂?”', '“그대가 좋은 짝을 얻고자 하는데, 어찌 이루지 못할 것을 근심하는가?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0009', '장면_만복사저포기_목판본_일본 내각문고_001_S#0009', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生心喜之.', '양생은 마음속으로 기뻐했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0010', '장면_만복사저포기_목판본_일본 내각문고_001_S#0010', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '明日, 卽三月二十四日也, 州俗, 燃燈於萬福寺祈福, 士女騈集, 各呈其志.', '다음 날은 곧 3월 24일로 고을 풍속에 만복사에 연등을 달고 복을 비는 모임이 있었으니 남녀가 빽빽이 모여들어 각기 그 소망을 바치곤 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0011', '장면_만복사저포기_목판본_일본 내각문고_001_S#0011', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '日晩梵罷人稀, 生袖摴蒲, 擲於佛前曰:', '날이 저물어 범패 소리가 멈추고 인적이 드물자 양생이 저포(摴蒲)를 소매에 넣어두었다가 부처 앞에 던지며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0012', '장면_만복사저포기_목판본_일본 내각문고_001_S#0012', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“吾今日與佛, 欲鬪蒲戱. 若我負, 則設法筵以賽, 若佛負, 則得美女, 以遂我願耳.”', '“저는 오늘 부처님과 저포 놀이를 겨루고자 합니다. 만약 제가 지면 법연(法筵)을 열어서 갚을 것이고, 만약 부처님께서 지신다면 미녀를 얻도록 해 주셔서 제 소원을 이뤄주십시오.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0013', '장면_만복사저포기_목판본_일본 내각문고_001_S#0013', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '祝訖, 遂擲之, 生果勝.', '축원을 마치고 마침내 윷을 던지니 양생이 과연 이겼다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0014', '장면_만복사저포기_목판본_일본 내각문고_001_S#0014', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '卽跪於佛前曰:', '양생이 곧바로 부처 앞에 무릎을 꿇고 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0015', '장면_만복사저포기_목판본_일본 내각문고_001_S#0015', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“業已定矣, 不可誑也.”', '“결과가 이미 정해졌으니 속이시면 안됩니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0016', '장면_만복사저포기_목판본_일본 내각문고_001_S#0016', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '遂隱於几下, 以候其約.', '마침내 탁자 아래에 숨어 약속을 기다렸다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0017', '장면_만복사저포기_목판본_일본 내각문고_001_S#0017', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '俄而, 有一美姬, 年可十五六. 丫鬟淡飾, 儀容婥妁, 如仙姝天妃, 望之儼然.', '조금 뒤 열대여섯 살쯤 되어 보이는 아름다운 여인이 나타났다. 그녀는 쪽진 머리를 하고 엷게 화장을 했으며 거동과 용모가 곱고 아리따워 마치 선녀나 천비(天妃)와 같아 의젓하게 보였다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0018', '장면_만복사저포기_목판본_일본 내각문고_001_S#0018', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '手携油甁, 添燈揷香, 三拜而跪, 噫而歎曰:', '그녀는 손에 기름병을 들고서 등불에 기름을 더하고 향을 꽂은 뒤 부처 앞에 세 번 절하고 무릎을 꿇고는 탄식하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0019', '장면_만복사저포기_목판본_일본 내각문고_001_S#0019', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“人生薄命, 乃如此邪?”', '“인생의 박명함이 어찌 이러합니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0020', '장면_만복사저포기_목판본_일본 내각문고_001_S#0020', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '遂出懷中狀詞, 獻於卓前.', '마침내 품속에서 축원문을 꺼내 탁자 앞에 바쳤다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0021', '장면_만복사저포기_목판본_일본 내각문고_001_S#0021', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '其詞曰:', '그 내용은 이러하다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0022', '장면_만복사저포기_목판본_일본 내각문고_001_S#0022', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“某州某地居住何氏某, 竊以曩者邊方失禦, 倭寇來侵, 干戈滿目, 烽燧連年. 焚蕩室廬, 虜掠生民, 東西奔竄, 左右逋逃, 親戚僮僕, 各相亂離. 妾以蒲柳弱質, 不能遠逝, 自入深閨, 終守幽貞, 不爲行露之沾, 以避橫逆之禍. 父母以女子守節不爽, 避地僻處, 僑居草野, 已三年矣. 然而秋月春花, 傷心虛度, 野雲流水, 無聊送日, 幽居在空谷, 歎平生之薄命, 獨宿度良宵, 傷彩鸞之獨舞, 日居月諸, 魂銷魄喪, 夏夕冬宵, 膽裂腸摧, 惟願覺皇, 曲垂憐愍. 生涯前定, 業不可避, 賦命有緣, 早得歡娛, 無任懇禱之至.”', '“아무 고을 아무 곳에 거주하는 하씨(何氏) 아무개는 삼가 아뢰니 지난번에 변방의 방어가 무너져 왜구가 침략해 와 창고 방패가 눈에 가득하고 봉화가 해마다 이어졌습니다. 집들을 불태워 쓸어버리고 백성들을 노략질하니 동서로 달아나 숨고 좌우로 도망쳐 친척과 노복들이 각기 뿔뿔이 흩어졌습니다. 저는 물가의 버들 같은 연약한 자질이라 멀리 도망갈 수 없어 스스로 깊은 규방에 들어가 끝내 절개를 지켜 길가 이슬에 젖는 모욕을 당하지 않고 뜻밖의 화를 피했습니다. 부모님께서는 여자가 절개를 지켜 어긋남이 없다 하여 궁벽한 곳으로 피신해 초야에 임시로 머무르게 하신 지가 이미 3년이 되었습니다. 그러나 가을에 달이 뜨고 봄에 꽃이 필 때면 마음만 상한 채 헛되이 보내고, 들판의 구름과 흐르는 물처럼 무료하게 세월을 보냈습니다. 빈 골짜기에 숨어 지내며 평생의 박명함을 한탄하고 홀로 지새며 좋은 밤을 보내니 아름다운 난새가 홀로 춤추는 것을 슬퍼했습니다. 세월이 흘러 혼백이 사라지고 여름과 겨울밤마다 간담이 찢어지며 애간장이 뒤틀립니다. 오직 바라건대 부처님께서는 굽어 연민을 베풀어 주십시오. 저의 생애가 전생에 정해져 그 업을 피할 수 없으나 타고난 운명에 인연이 있다면 일찍 기쁨과 즐거움을 얻게 해 주시기를 간절히 빕니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0023', '장면_만복사저포기_목판본_일본 내각문고_001_S#0023', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女旣投狀, 嗚咽數聲.', '여인이 글을 바치고 나서 여러 번 오열했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0024', '장면_만복사저포기_목판본_일본 내각문고_001_S#0024', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生於隙中, 見其姿容, 不能定情, 突出而言曰:', '양생은 틈 사이로 그 자태와 용모를 보고 정을 가라앉히지 못해 불쑥 나와 말하였다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0025', '장면_만복사저포기_목판본_일본 내각문고_001_S#0025', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“向者投狀, 爲何事也?”', '“조금 전에 글을 바치신 것은 무슨 일 때문입니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0026', '장면_만복사저포기_목판본_일본 내각문고_001_S#0026', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '見女狀辭, 喜溢於面, 謂女子曰:', '양생은 여인의 글을 보고는 기쁨이 얼굴에 가득한 채 여인에게 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0027', '장면_만복사저포기_목판본_일본 내각문고_001_S#0027', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“子何如人也, 獨來于此?”', '“그대는 어떤 사람이길래 홀로 이곳에 오셨습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0028', '장면_만복사저포기_목판본_일본 내각문고_001_S#0028', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0029', '장면_만복사저포기_목판본_일본 내각문고_001_S#0029', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“妾亦人也. 夫何疑訝之有? 君但得佳匹, 不必問名姓. 若是其顚倒也?”', '“첩 또한 사람입니다. 의아하게 여길 게 무엇이 있겠습니까? 그대께서는 그저 좋은 배필을 얻었으면 되었지 성명을 물을 필요는 없습니다. 어찌 이다지도 사리에 어긋나십니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0030', '장면_만복사저포기_목판본_일본 내각문고_001_S#0030', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '時, 寺已頹落, 居僧住於一隅, 殿前只有廊廡, 蕭然獨存, 廊盡處, 有板房甚窄.', '그때에 만복사는 이미 퇴락해 머물던 승려들은 절 한쪽 구석에서 지냈고 불전 앞에는 오직 행랑만이 쓸쓸히 홀로 남아 있었으며, 복도 끝에는 매우 좁은 나무 판자 방이 있었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0031', '장면_만복사저포기_목판본_일본 내각문고_001_S#0031', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生挑女而入,', '양생이 여인을 유혹해 들어가자', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0032', '장면_만복사저포기_목판본_일본 내각문고_001_S#0032', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女不之難, 相與講歡, 一如人間.', '여인은 이를 거절하지 않았으니 서로 교분을 나누었는데 한결같이 인간 세상과 같았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0033', '장면_만복사저포기_목판본_일본 내각문고_001_S#0033', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '將及夜半, 月上東山, 影入窓柯, 忽有跫音.', '밤이 장차 깊어 달이 동산에 떠오르고 그림자가 창가의 나뭇가지에 비칠 무렵 갑자기 발자국 소리가 났다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0034', '장면_만복사저포기_목판본_일본 내각문고_001_S#0034', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0035', '장면_만복사저포기_목판본_일본 내각문고_001_S#0035', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“誰耶? 將非侍兒來耶?”', '“누구냐? 혹 시녀가 온 것이 아니냐?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0036', '장면_만복사저포기_목판본_일본 내각문고_001_S#0036', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '兒曰:', '여종이 대답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0037', '장면_만복사저포기_목판본_일본 내각문고_001_S#0037', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“唯. 向日娘子, 行不過中門, 履不容數步, 昨暮偶然而出, 一何至於此極也?”', '“예. 예전에 낭자께서는 거동하실 때 중문을 넘지 않으시고 발걸음은 몇 걸음을 넘지 않으셨는데, 어제 저녁에 우연히 나가시더니 어찌 이 지경에 이르셨습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0038', '장면_만복사저포기_목판본_일본 내각문고_001_S#0038', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0039', '장면_만복사저포기_목판본_일본 내각문고_001_S#0039', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“今日之事, 蓋非偶然, 天之所助, 佛之所佑, 逢一粲者, 以爲偕老也. 不告而娶, 雖明敎之法曲, 式燕以遨, 亦平生之奇遇也. 可於茅舍, 取裀席酒果來.”', '“오늘의 일은 우연이 아니니 하늘의 도움과 부처님의 보우로 아름다운 이를 만나 백년해로 하려는 것입니다. 부모에게 고하지 않고 혼인하는 것이 비록 명교(明敎)의 법도에는 어긋난다고 하나 잔치에 참석하여 즐기는 것 또한 평생의 기이한 만남이니 초가집에 가서 요와 방석, 술과 과일을 가져오는 게 좋겠다.“', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0040', '장면_만복사저포기_목판본_일본 내각문고_001_S#0040', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '侍兒一如其命而往, 設筵於庭.', '여종이 온전히 그 명대로 다녀와 뜰에 자리를 깔았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0041', '장면_만복사저포기_목판본_일본 내각문고_001_S#0041', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '時將四更也. 鋪陳几案, 素淡無文, 而醪醴馨香, 定非人間滋味.', '때는 4경(四更) 무렵으로 진설한 술상은 소박하고 무늬가 없었으나 술의 향기가 결코 인간 세상의 맛이 아니었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0042', '장면_만복사저포기_목판본_일본 내각문고_001_S#0042', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生雖疑怪, 談笑淸婉, 儀貌舒遲, 意必貴家處子, 踰墻而出, 亦不之疑也.', '양생은 비록 괴이하게 여겼으나 여인이 담소가 맑고 아름다우며 거동이 차분한 것을 보고, ‘분명 귀한 집안의 처자가 담장을 넘어 나온 것이라.’라고 생각하고는 그것을 의심하지 않았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0043', '장면_만복사저포기_목판본_일본 내각문고_001_S#0043', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '觴進, 命侍兒, 歌以侑之, 謂生曰:', '술잔을 올리고는 여인이 시녀에게 명해 노래로 흥을 돕게 하고는 양생에게 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0044', '장면_만복사저포기_목판본_일본 내각문고_001_S#0044', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“兒定仍舊曲, 請自製一章, 以侑, 如何?”', '“아이가 옛 곡조를 부를 것이니 청컨대 직접 한 장(章)을 지어서 흥을 돋구워 주심이 어떻습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0045', '장면_만복사저포기_목판본_일본 내각문고_001_S#0045', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生欣然應之, 曰:', '생이 흔쾌히 응하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0046', '장면_만복사저포기_목판본_일본 내각문고_001_S#0046', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“諾.”', '“그러겠습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0047', '장면_만복사저포기_목판본_일본 내각문고_001_S#0047', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '乃製滿江紅一闋, 命侍兒歌之曰:', '마침내 「만강홍(滿江紅)」 한 곡조를 지어 시녀에게 그것을 부르게 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0048', '장면_만복사저포기_목판본_일본 내각문고_001_S#0048', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“惻惻春寒羅衫薄, 幾回腸斷金鴨冷. 晩山凝黛, 暮雲張繖. 錦帳鴛衾無與伴, 寶釵半倒吹龍管.可惜許光陰易跳丸. 中情懣. 燈無焰銀屛短, 徒收淚誰從款. 喜今宵. 鄒律一吹回暖. 破我佳城千古恨, 細歌金縷傾銀椀. 悔昔時, 抱恨蹙眉, 兒眠孤館.”', '“싸늘한 봄추위에 얇은 비단 적삼. 몇 번이나 애가 끊어지고 금향로가 식었던가? 저녁 산은 눈썹 먹처럼 어둑하고, 저무는 구름은 일산처럼 퍼져있네. 비단 장막과 원앙금침은 함께할 짝이 없고, 보배로운 비녀 반쯤 기운 채 피리를 부네. 애석하게도 세월은 튀는 탄환처럼 빠르니, 마음속엔 번민만 가득하구나. 등불엔 불빛이 없고 은병풍은 짧은데, 한갓 눈물만 거둘뿐 누구를 따라 사랑할까? 기쁘구나 이 밤이여. 추연의 피리 한 번 불어 따스함 돌아와서. 나의 무덤 속 천고의 한을 깨뜨리니, 가만히 금루곡 부르며 은 술잔 기울이네. 옛날을 후회하네. 한을 머금고 눈썹 찌푸리며, 외로운 객사에서 내 잠들었던 것을.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0049', '장면_만복사저포기_목판본_일본 내각문고_001_S#0049', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '歌竟, 女愀然曰:', '노래를 마치자 여인이 서글픈 기색으로 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0050', '장면_만복사저포기_목판본_일본 내각문고_001_S#0050', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“曩者蓬島, 失當時之約, 今日瀟湘, 有故人之逢, 得非天幸耶? 郞若不我遐棄, 終奉巾櫛, 如失我願, 永隔雲泥.”', '“지난날 봉래산에서는 당시의 기약을 잃었으나 오늘 소상강(瀟湘)에서는 옛 벗을 만났으니 천행이 아니겠습니까? 낭군께서 만약 저를 멀리해 버리지 않으신다면 평생토록 건즐을 받들 것이지만 만약 제 소원을 저버리신다면 영원히 구름길과 진흙길처럼 멀어질 것입니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0051', '장면_만복사저포기_목판본_일본 내각문고_001_S#0051', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生聞此言, 一感一驚曰:', '양생이 이 말을 듣고 한편으로 감동하고 한편으로 놀라며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0052', '장면_만복사저포기_목판본_일본 내각문고_001_S#0052', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“敢不從命?”', '“감히 말씀을 따르지 않겠습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0053', '장면_만복사저포기_목판본_일본 내각문고_001_S#0053', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '然其態度不凡, 生熟視所爲.', '그러나 여인의 태도가 평범하지 않아 양생은 그녀가 하는 바를 유심히 살폈다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0054', '장면_만복사저포기_목판본_일본 내각문고_001_S#0054', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '時, 月掛西峰, 鷄鳴荒村, 寺鐘初擊, 曙色將暝.', '이때 달이 서쪽 봉우리에 걸리고 닭이 황촌(荒村)에서 울었으며 사찰의 종소리가 처음 울리고 새벽빛이 어슴푸레했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0055', '장면_만복사저포기_목판본_일본 내각문고_001_S#0055', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0056', '장면_만복사저포기_목판본_일본 내각문고_001_S#0056', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“兒可撤席而歸.”', '“얘야. 자리를 거두고 돌아가거라.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0057', '장면_만복사저포기_목판본_일본 내각문고_001_S#0057', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '隨應隨滅, 不知所之.', '시녀가 대답하자마자 이내 사라졌는데 어디로 갔는지 알 수가 없었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0058', '장면_만복사저포기_목판본_일본 내각문고_001_S#0058', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0059', '장면_만복사저포기_목판본_일본 내각문고_001_S#0059', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“因緣已定, 可同携手.”', '“인연이 이미 정해졌으니 함께 손을 잡고 가시지요.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0060', '장면_만복사저포기_목판본_일본 내각문고_001_S#0060', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生執女手, 經過閭閻, 犬吠於籬, 人行於路.', '양생이 여인의 손을 잡고 여염집을 지나갔는데 울타리에서 개가 짖고 길에 사람들이 지나갔다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0061', '장면_만복사저포기_목판본_일본 내각문고_001_S#0061', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '而行人, 不知與女同歸, 但曰:', '그러나 행인들은 양생이 여인과 함께 가는 줄을 모르고 다만 이렇게 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0062', '장면_만복사저포기_목판본_일본 내각문고_001_S#0062', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“生早歸何處?”', '“생께서는 어디서 일찍이 가시오?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0063', '장면_만복사저포기_목판본_일본 내각문고_001_S#0063', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生答曰:', '양생이 답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0064', '장면_만복사저포기_목판본_일본 내각문고_001_S#0064', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“適醉臥萬福寺, 投故友之村墟也.”', '“마침 만복사에서 취해 누웠다가 친구의 마을로 가는 중입니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0065', '장면_만복사저포기_목판본_일본 내각문고_001_S#0065', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '至詰朝, 女引至草莽間, 零露瀼瀼, 無逕路可遵.', '이른 아침이 되자 여인이 양생을 풀숲 사이로 이끌었는데 떨어지는 이슬로 흠뻑 젖어 따를 만한 길이 없었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0066', '장면_만복사저포기_목판본_일본 내각문고_001_S#0066', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生曰:', '양생이 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0067', '장면_만복사저포기_목판본_일본 내각문고_001_S#0067', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“何居處之若此也?”', '“어찌 거처하는 곳이 이와 같습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0068', '장면_만복사저포기_목판본_일본 내각문고_001_S#0068', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0069', '장면_만복사저포기_목판본_일본 내각문고_001_S#0069', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“孀婦之居, 固如此耳.”', '“과부의 거처란 본디 이러할 뿐입니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0070', '장면_만복사저포기_목판본_일본 내각문고_001_S#0070', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女又謔曰:', '여인이 또 농담으로 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0071', '장면_만복사저포기_목판본_일본 내각문고_001_S#0071', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“於邑行路, 豈不夙夜, 謂行多露.”', '“이슬이 흠뻑 내린 길을, 아침저녁으로 다니지 않겠냐마는, 길에 이슬이 많을까 두려워하네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0072', '장면_만복사저포기_목판본_일본 내각문고_001_S#0072', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生乃謔之曰:', '양생이 곧 농담으로 답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0073', '장면_만복사저포기_목판본_일본 내각문고_001_S#0073', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“有狐綏綏, 在彼淇梁. 魯道有蕩, 齊子翶翔.”', '“여우가 살금살금 짝을 찾아다니니 저 기수(淇水)의 다리에 있네. 노(魯)나라 길은 평탄하니 문강(文姜)이 편히 오가는누나.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0074', '장면_만복사저포기_목판본_일본 내각문고_001_S#0074', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '吟而笑傲.', '이렇게 시를 읊고는 웃고 즐거워했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0075', '장면_만복사저포기_목판본_일본 내각문고_001_S#0075', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '遂同去開寧洞, 蓬蒿蔽野, 荊棘參天, 有一屋, 小而極麗', '마침내 함께 개녕동(開寧洞)으로 가자 쑥이 들판을 덮고 가시나무가 하늘로 솟아있는데 집 한 채가 있었으니 작으면서도 몹시 아름다웠다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0076', '장면_만복사저포기_목판본_일본 내각문고_001_S#0076', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '邀生俱入, 裀褥帳幃極整, 如昨夜所陳.', '여인이 양생을 맞이해 함께 들어가니 침구와 휘장이 아주 잘 정돈되어 있어 어젯밤에 펼쳐놓은 것과 같았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0077', '장면_만복사저포기_목판본_일본 내각문고_001_S#0077', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '留三日, 歡若平生然.', '양생은 사흘 동안 평생을 지내온 사이[부부]처럼 기쁨을 누렸다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0078', '장면_만복사저포기_목판본_일본 내각문고_001_S#0078', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '其侍兒美而不黠, 器皿潔而不文, 意非人世, 而繾綣意篤, 不復思慮,', '그녀의 여종은 아름다면서도 영악하지 않았으며 그릇은 깨끗하면서도 화려하지 않아 속으로 인간 세상이 아니라고 여겼는데 지극한 정이 두터워 더는 생각하지 않았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0079', '장면_만복사저포기_목판본_일본 내각문고_001_S#0079', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '已而, 女謂生曰:', '이윽고 여인이 양생에게 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0080', '장면_만복사저포기_목판본_일본 내각문고_001_S#0080', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“此地三日, 不下三年, 君當還家, 以顧生業也.”', '“이곳에서의 사흘은 3년과 다름이 없으니 당신은 집으로 돌아가 생업을 돌보셔야 합니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0081', '장면_만복사저포기_목판본_일본 내각문고_001_S#0081', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '遂設離宴, 以別.', '그러고는 마침내 송별하는 자리를 베풀어 이별하고자 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0082', '장면_만복사저포기_목판본_일본 내각문고_001_S#0082', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生悵然曰:', '양생이 슬퍼하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0083', '장면_만복사저포기_목판본_일본 내각문고_001_S#0083', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“何遽別之速也?”', '“어찌 이리 대번에 서둘러 이별한답니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0084', '장면_만복사저포기_목판본_일본 내각문고_001_S#0084', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0085', '장면_만복사저포기_목판본_일본 내각문고_001_S#0085', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“當再會, 以盡平生之願爾. 今日到此弊居, 必有夙緣, 宜見鄰里族親, 如何?”', '“다시 만나 평생의 소원을 다할 것입니다. 오늘 이 누추한 거처에 이른 것은 분명 전생의 인연이 있는 것이니 마땅히 이웃에 지내는 친척들에게 인사를 드리는 것이 어떻겠습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0086', '장면_만복사저포기_목판본_일본 내각문고_001_S#0086', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生曰:', '양생이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0087', '장면_만복사저포기_목판본_일본 내각문고_001_S#0087', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“諾.”', '“좋습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0088', '장면_만복사저포기_목판본_일본 내각문고_001_S#0088', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '卽命侍兒, 報四鄰以會.', '즉시 시녀에게 명하여 사방 이웃에 알려 모이게 하였다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0089', '장면_만복사저포기_목판본_일본 내각문고_001_S#0089', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '其一曰鄭氏. 其二曰吳氏. 其三曰金氏. 其四曰柳氏. 皆貴家巨族, 而與女子同閭閈, 親戚而處子者也. 性俱溫和, 風韻不常, 而又聰明識字, 能爲詩賦.', '첫째는 정씨(鄭氏), 둘째는 오씨(吳氏), 셋째는 김씨(金氏), 넷째는 유씨(柳氏)였다. 모두 귀족 명문가의 딸들로 여인과 같은 마을에 사는 친척인 처녀들이었다. 성품이 모두 온화하고 풍채와 운치가 예사롭지 않았으며 총명해 글자를 알아 시부(詩賦)를 지을 줄 알았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0090', '장면_만복사저포기_목판본_일본 내각문고_001_S#0090', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '皆作七言短篇四首以贐.', '모두 7언단편 4수를 지어 전별시로 삼았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0091', '장면_만복사저포기_목판본_일본 내각문고_001_S#0091', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '鄭氏態度風流, 雲鬟掩鬢, 乃噫而吟曰:', '정씨는 태도가 풍류스럽고 구름 같은 머리가 귀밑을 가렸는데 이에 탄식하며 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0092', '장면_만복사저포기_목판본_일본 내각문고_001_S#0092', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“春宵花月兩嬋娟, 長把春愁不記年. 自恨不能如比翼, 雙雙相戱舞靑天."', '“봄밤의 꽃과 달은 모두 아름다우나, 길게 봄 시름을 안고 세월 가는 것도 잊었네, 스스로 한탄하는 것은 비익조(比翼鳥)처럼, 함께 푸른 하늘에서 춤추지 못하는 것이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0093', '장면_만복사저포기_목판본_일본 내각문고_001_S#0093', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"漆燈無焰夜如何, 星斗初橫月半斜. 惆悵幽宮人不到, 翠衫撩亂鬢鬖髿."', '검은 등잔에 불꽃 없으니 이 밤을 어찌할까, 북두칠성이 막 비끼고 달은 반쯤 기울었네. 쓸쓸하고 그윽한 무덤에는 사람 오지 않고, 푸른 적삼 어지럽게 흔들리니 귀밑머리 흐트러지네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0094', '장면_만복사저포기_목판본_일본 내각문고_001_S#0094', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"標梅情約竟蹉跎, 辜負春風事已過. 枕上淚痕幾圓點, 滿庭山雨打梨花."', '정다운 혼인의 약속은 끝내 어긋나니, 봄바람 저버린 채 일은 이미 지나버렸네. 베갯머리 눈물 자국 몇 번을 찍었는가, 뜰에 가득한 산 비는 배꽃을 두드리네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0095', '장면_만복사저포기_목판본_일본 내각문고_001_S#0095', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"一春心事已無聊, 寂寞空山幾度宵. 不見藍橋經過客, 何年裴航遇雲翹."', '봄날의 심사가 이미 무료해졌으니, 적막한 빈 산에서 몇 밤이나 보냈던가. 남교를 지나는 길손을 보지 못했으니, 어느 해에 배항이 운교를 만날까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0096', '장면_만복사저포기_목판본_일본 내각문고_001_S#0096', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '吳氏, 丫鬟妖弱, 不勝情態, 繼吟曰:', '오씨는 쪽진 머리가 예쁘고 가녀린데 정태(情態)를 이기지 못해 이어서 이렇게 읊었다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0097', '장면_만복사저포기_목판본_일본 내각문고_001_S#0097', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“寺裏燒香歸去來, 金錢暗擲竟誰媒. 春花秋月無窮恨,  銷却樽前酒一盃."', '“절에서 향을 사르고 돌아왔으니, 금전을 몰래 던졌으니 끝내 누가 중매설까. 봄꽃과 가을 달에 다함이 없는 한을, 술동이 앞에서 술 한 잔으로 달래네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0098', '장면_만복사저포기_목판본_일본 내각문고_001_S#0098', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"漙漙曉露浥桃腮, 幽谷春深蝶不來. 却喜隣家銅鏡合, 更歌新曲酌金罍."', '"흠뻑 맺힌 새벽이슬이 복사꽃 같은 뺨 적시는데, 깊은 골짜기엔 봄 깊어도 나비는 오지 않네. 도리어 이웃집에 거울이 합쳐짐을 기뻐해, 다시 새 곡조를 노래하며 금술잔에 술 따르네."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0099', '장면_만복사저포기_목판본_일본 내각문고_001_S#0099', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"年年燕子舞東風, 腸斷春心事已空. 羨却芙蕖猶竝蔕, 夜深同浴一池中."', '"해마다 제비는 봄바람에 춤추는데, 애끊는 춘정은 일이 이미 헛되었네. 오히려 연꽃이 나란히 꽂대를 나란히하고서, 한밤중에 같은 연못 속에서 함께 목욕하는 것을 부러워하네."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0100', '장면_만복사저포기_목판본_일본 내각문고_001_S#0100', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"一層樓在碧山中, 連理枝頭花正紅. 却恨人生不如樹, 靑年薄命淚凝瞳.”', '"한 층 되는 누각이 푸른 산속에 있는데, 연리지  가지 끝에는 꽃이 정말 붉구나. 도리어 인생이 나무만 못함을 한스럽게 여겨, 박명한 청춘은 눈물이 눈동자에  맺히네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0101', '장면_만복사저포기_목판본_일본 내각문고_001_S#0101', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '金氏, 整其容儀, 儼然染翰, 責其前詩, 淫佚太甚, 而言曰:', '김씨는 용모와 자세를 가다듬고 의젓하게 붓을 흠뻑 적시더니 앞선 시들이 너무 음탕하다고 꾸짖고는 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0102', '장면_만복사저포기_목판본_일본 내각문고_001_S#0102', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“今日之事, 不必多言, 但叙光景, 胡乃陳懷以失其節, 傳鄙懷於人間?”', '“오늘의 일은 말을 많이 할 필요가 없고 그저 광경만 묘사할 것이지 어찌 마음 속 생각을 늘어놓아 그 절개를 잃고 인간 세상에 비루한 뜻을 전하는가.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0103', '장면_만복사저포기_목판본_일본 내각문고_001_S#0103', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '遂郞然賦曰:', '마침내 낭랑하게 시를 지었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0104', '장면_만복사저포기_목판본_일본 내각문고_001_S#0104', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"杜鵑鳴了五更風, 寥落星河已轉東. 莫把玉簫重再弄, 風情恐與俗人通."', '“두견새 울어대는 오경 무렵의 바람에, 희미한 은하수는 이미 동쪽으로 돌아섰네. 옥퉁소를 다시는 불지 마시오, 풍정이 속인에게 알려질까 두렵구나."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0105', '장면_만복사저포기_목판본_일본 내각문고_001_S#0105', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"滿酌烏程金叵羅, 會須取醉莫辭多. 明朝捲地東風惡, 一段春光奈夢何."', '"금 술잔에 오정주(烏程酒) 가득 부었으니, 모름지기 취해야지 많다고 사양하지 마소서. 내일 아침엔 땅을 휩쓰는 사나운 동풍 불 텐데, 한 조각 봄빛은 꿈같으니 어찌하겠는가?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0106', '장면_만복사저포기_목판본_일본 내각문고_001_S#0106', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"綠紗衣袂懶來垂, 絃管聲中酒百巵. 淸興未闌歸未可, 更將新語製新詞."', '"푸른 비단 옷소매를 게을리 늘어뜨리고, 현악기와 관악기 소리 속에 술 백 잔을 돌리네. 맑은 흥취 다하지 않아 아직 돌아갈 수 없으니, 다시 새로운 말로 새로운 노래를 짓노라."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0107', '장면_만복사저포기_목판본_일본 내각문고_001_S#0107', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"幾年塵土惹雲鬟, 今日逢人一解顔. 莫把高唐神境事, 風流話柄落人間.”', '"몇 년 동안 땅속에서 구름머리 묻혔었나, 오늘 님을 만나 한 번 얼굴을 펴보네. 그러니 고당의 선경에서 있었던 일을 가져다가, 풍류의 이야깃거리로 인간 세상에 퍼뜨리지 마소서.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0108', '장면_만복사저포기_목판본_일본 내각문고_001_S#0108', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '柳氏, 淡粧素服, 不甚華麗, 而法度有常. 沈黙不言, 微笑而題曰:', '유씨는 담박한 화장에 소복을 입어 매우 화려하지는 않았으나 법도가 늘 갖추어져있었다. 묵묵히 말이 없다가 미소를 지으며 시를 썼다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0109', '장면_만복사저포기_목판본_일본 내각문고_001_S#0109', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"確守幽貞經幾年, 香魂玉骨掩重泉. 春宵每與姮娥伴, 叢桂花邊愛獨眠."', '“그윽한 정절 굳게 지키며 몇 년이나 지냈던가 , 향기로운 혼과 옥 같은 뼈는 황천에 묻혀서. 봄밤마다 늘 항아와 함께하면서, 육계나무 꽃가에서 홀로 자기를 즐기네."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0110', '장면_만복사저포기_목판본_일본 내각문고_001_S#0110', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"却笑春風桃李花, 飄飄萬點落人家. 平生莫把靑蠅點, 誤作崑山玉上瑕."', '"문득 봄바람의 복사꽃이 오얏꽃이, 흩날리며 만 점 꽃이 남의 집에 떨어지네. 평소 푸른 파리가 싸놓은 똥을, 곤륜산 옥의 흠으로 잘못 여기지 않았네."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0111', '장면_만복사저포기_목판본_일본 내각문고_001_S#0111', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '"脂粉慵拈首似蓬, 塵埋香匣綠生銅. 今朝幸預鄰家宴, 羞看冠花別樣紅."', '"연지와 분 바르길 게을리해 머리는 쑥대 같고 , 향갑엔 먼지가 쌓이고 구리거울엔 푸른 녹이 슬었네. 오늘 아침 다행히 이웃집 잔치에 참여해
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SBMPSJPG01YU001P0159', '장면_만복사저포기_목판본_일본 내각문고_001_S#0160', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '翌日, 設牲牢朋酒, 以尋前迹, 果一殯葬處也.', '다음날 양생은 희생 제물과 술을 마련해 이전에 여인과 지냈던 장소를 찾아가 보니 과연 임시로 만든 무덤이 하나 있었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0160', '장면_만복사저포기_목판본_일본 내각문고_001_S#0161', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生設奠哀慟, 焚楮鏹于前, 遂葬焉.', '양생이 제전을 베풀고 애통해하며 영전 앞에서 지전을 불사르고 드디어 장사를 지냈다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0161', '장면_만복사저포기_목판본_일본 내각문고_001_S#0162', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '作文, 以弔之曰:', '그러고는 제문을 지어 다음과 같이 조문했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0162', '장면_만복사저포기_목판본_일본 내각문고_001_S#0163', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“惟靈生而溫麗, 長而淸渟. 儀容侔於西施, 詩賦高於淑眞. 不出香閨之內, 常聽鯉庭之箴, 逢亂離而璧完, 遇寇賊而珠沈. 托蓬蒿而獨處, 對花月而傷心. 腸斷春風, 哀杜鵑之啼血, 膽裂秋霜, 歎紈扇之無緣. 嚮者, 一夜邂逅, 心緖纏綿. 雖識幽明之相隔, 實盡魚水之同歡. 將謂百年以偕老, 豈期一夕而悲酸? 月窟驂鸞之姝, 巫山行雨之娘, 地黯黯而莫歸, 天漠漠而難望. 入不言兮恍惚, 出不逝兮蒼茫. 對靈幃而掩泣, 酌瓊漿而增傷. 感音容之窈窈, 想言語之琅琅. 嗚虖哀哉! 爾性聰慧, 爾氣精詳. 三魂縱散, 一靈何亡? 應降臨而陟庭, 或薰蒿而在傍. 雖死生之有異, 庶有感於些章!”', '“그대의 영령은 태어남에 온화하고 고왔으며 자라서는 맑고 깨끗했습니다. 용모는 서시(西施)에 견줄 만하고 시부(詩賦)는 주숙진(朱淑眞)보다 뛰어났습니다. 규방 안을 벗어나지 않고 늘 부모의 가르침을을 듣다가 난리를 만났을 때 절개를 옥처럼 온전히 했는데, 도적을 만나 진주가 물에 잠기듯 안타깝게 죽었습니다. 쑥대밭에 의탁해 홀로 지내다가 꽃과 달을 대하며 상심했네. 봄바람에 애간장 끊어지니 두견새가 피눈물 흘리는 것을 슬퍼했고 가을 서리에 간담이 쪼개지니 버림받은 비단 부채가 인연을 만나지 못한 신세를 탄식했습니다. 지난번 하룻밤 만남에 마음이 서로 얽히고 말았으니 비록 이승과 저승이 막혀있음을 알고서도 참으로 물고기가 물을 만난 것처럼 기쁨을 다했습니다. 장차 백년해로를 하고자 했으나 어찌 하룻밤만에 헤어져 슬프고 쓰라릴 줄을 기약했겠습니까? 달 속 궁궐에서 난새를 타던 여인이었으며, 무산에서 비를 뿌리는 낭자였구나. 땅은 어둑어둑해 돌아갈 수 없고 하늘은 아득해 바라보기가 어렵습니다. 들어와서는 멍하니 말이 없고 나가서는 아득히 갈 길이 없습니다. 영위(靈幃)를 대하고 눈물 훔치며 맑은 술을 따르니 상심만 더해지지만, 그윽한 음성과 용모를 떠올리며 낭랑했던 목소리를 그리워합니다. 아아! 슬프도다! 그대의 성품은 총명했으며 그대의 기운은 빼어났으니 삼혼(三魂)이 비록 흩어졌더라도 그대의 혼령이 어찌 사라졌겠습니까? 응당 강림해 뜰에 오르시거나 아니면 아지랑이처럼 옆에 있을 것입니다. 비록 삶과 죽음에는 차이가 있겠으나 바라건대 이 제문에 감응하소서.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0163', '장면_만복사저포기_목판본_일본 내각문고_001_S#0164', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '後, 極其情哀, 盡賣田舍, 追薦再三夕,', '이후 양생은 슬픈 마음이 극에 달하고는 전답과 집을 모두 팔아 여인에게 천도재를 두세 밤 동안 올렸더니', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0164', '장면_만복사저포기_목판본_일본 내각문고_001_S#0165', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '女於空中, 唱曰:', '여인이 공중에서 노래를 불렀다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0165', '장면_만복사저포기_목판본_일본 내각문고_001_S#0166', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '“蒙君薦拔, 已於他國, 爲男子矣. 雖隔幽明, 寔深感佩. 君當復修淨業, 同脫輪回.”', '“그대가 천도해 준 덕분에 저는 이미 다른 나라에서 남자로 태어나게 되었습니다. 비록 이승과 저승이 가로막혀 있으나 실로 깊이 감격하고 있습니다. 그대께서도 응당 다시 정업(淨業)을 닦아서 같이 윤회에서 벗어납시다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SBMPSJPG01YU001P0166', '장면_만복사저포기_목판본_일본 내각문고_001_S#0167', '만복사저포기', '萬福寺樗蒲記', '3인칭', '한문', '生後不復婚嫁, 入智異山採藥, 不知所終.', '양생은 이후 다시 장가들지 않고 지리산(智異山)에 약초를 캐러 들어갔는데 그 마지막은 알 수 없다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0001', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0001', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '崇禎三年春正月, 余遊京師, 不成進士, 困而歸.', '숭정(崇禎) 3년(1630년) 봄 정월, 내가 서울에 갔다가 진사(進士)가 되지 못하고 지친 채 돌아왔다.', NULL, '조선', '현실계', '한국(韓國)_서울_전체;한국 경상북도_영천', '정호의의 집', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0002', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0002', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '丈夫雖不以得失介于懷, 而光陰倏忽, 三十之年已過, 恐未免爲鄉人,', '대장부가 비록 득실을 마음에 두지 않아야 하지만 세월은 순식간에 흘러 서른 살이 이미 넘었으니 향인(鄉人)이 되는 것을 면치 못할까 걱정이 들었다.', NULL, '조선', '현실계', '한국(韓國)_서울_전체;한국 경상북도_영천', '정호의의 집', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0003', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0003', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '遂盡棄科舉之文, 淨掃書室, 歛容端坐, 敬讀魯論. 沉潛翫味, 聖師所言, 髣髴乎親承面命矣.', '마침내 나는 과거 시험을 위한 글을 모두 버리고 서실(書室)을 깨끗이 청소하고 몸가짐을 바로 하고 단정히 앉아, 『논어(論語)』를 공경하는 마음으로 읽었다. 깊이 빠져들어 완미하니, 마치 공자님께 말씀하시는 것이 직접 대면하여 가르침을 받는 듯하였다.', NULL, '조선', '현실계', '한국(韓國)_서울_전체;한국 경상북도_영천', '정호의의 집_서실(書室)', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0004', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0004', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '然余受氣昏惰, 立志不固, 讀書之暇, 精怠神疲,', '그러나 나는 타고난 기질이 어리석고 게을러 뜻을 견고히 세우지 못하고 독서하는 겨를에 기운이 나태해지고 정신이 피곤해졌다.', NULL, '조선', '현실계', '한국(韓國)_서울_전체;한국 경상북도_영천', '정호의의 집_서실(書室)', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0005', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0005', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '宰予晝寢, 莊周化蝶, 栩栩然行盡江千, 飄飄然踏徧天上之九萬.', '재여(宰予)처럼 낮잠이 들었는데, 장주(莊周)처럼 나비가 되어 훨훨 수천 리 강가를 다 돌아다니고, 나풀나풀 하늘의 아득히 높은 곳을 밟으며 돌아다녔다.', NULL, '조선', '비현실계', '꿈', '강가', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0006', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0006', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '有二客從余, 其不知矣.', '그러다 두 객이 나를 뒤따랐는데 그들이 누군지는 알지 못했다.', NULL, '조선', '비현실계', '꿈', '강가', '정호의, 객A, 객B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0007', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0007', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余與客携手偕行, 至一處, 有高樓傑閣, 阧起中天.', '내가 두 객과 함께 손을 잡고 같이 걸어 한 곳에 이르니 높고 큰 누각이 하늘로 우뚝 솟아 있었다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0008', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0008', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '由其門而入, 玉題相輝, 金碧掩映, 雲牕繡戶, 或鎻或開,', '그 문으로 들어가니 옥으로 된 현판이 빛나고 금빛과 푸른빛이 은은히 비치며, 구름 창과 수놓은 창문이 혹 잠겨 있고 혹 열려 있었다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0009', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0009', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '而有美娥綠衣靑裳者數十輩, 搗藥而入于內. 又有呻吟之聲出於外, 余凜乎其不可留也.', '그리고 녹색 저고리에 푸른 치마를 입은 아름다운 아가씨 수십 명이 약을 찧어 안으로 들어가고 있었다. 또 신음하는 소리가 밖에서 새어 나와 나는 섬뜩하여 그곳에 머무를 수가 없었다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0010', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0010', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '返而出門, 行十里許, 若有追之者,', '되돌아 문을 나서 십여 리쯤 걸어가니 뒤쫓아 오는 자가 있는 듯했다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0011', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0011', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '顧而視之, 有兩少娥, 携壺榼而來, 曰：', '돌아보니 두 어린 아가씨가 술병과 도시락을 들고 와서 말했다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0012', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0012', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '地倅送我, 以慰君也.', '“수령께서 저희를 보내어 그대를 위로하게 하셨습니다.”', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0013', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0013', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '遂與之俱行.', '마침내 그들과 함께 걸었다.', NULL, '조선', '비현실계', '꿈', '누각A', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0014', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0014', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '至五里, 見萬頃蒼波, 一望無涯. 而蒼崖千尺兀然高起, 飛甍峻宇森列於其巔.', '다섯 리쯤 가니 만 이랑의 푸른 파도가 있었는데 한번 바라보니 끝이 없었다. 또 푸른 절벽 천 길이 우뚝 솟아 있었는데 나는 듯한 용마루와 웅장한 집들이 그 위에 늘어서 있었다.', NULL, '조선', '비현실계', '꿈_동해', '웅장한집[峻宇]', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0015', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0015', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余乃攝衣而上, 開戶而入,', '나는 옷을 걷어 올린 다음 위로 올라가 문을 열고 안으로 들어가자,', NULL, '조선', '비현실계', '꿈_동해', '웅장한집[峻宇]', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0016', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0016', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '則有數人坐于廳事, 而不爲之禮, 余亦不與之語.', '몇 사람이 청사(廳事)에 앉아 있었는데 예를 갖추지 않아 나 역시 그들과 말을 섞지 않았다.', NULL, '조선', '비현실계', '꿈_동해', '웅장한집[峻宇]_청사(廳事)', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0017', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0017', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '周覧旣畢, 履巉嚴而行.', '두루 살펴본 뒤, 험하고 가파른 곳을 밟으며 걸었다.', NULL, '조선', '비현실계', '꿈_동해', '가파른 길', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0018', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0018', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '又登一樓, 二客亦隨至矣.', '또 어떤 누각에 오르자 두 객 역시 따라왔다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 객A, 객B, 아가씨 A, 아가씨B', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0019', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0019', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '有主人振衣出迎, 引入上座.', '주인이 옷깃을 털고 나와 맞이하며 나를 상좌(上座)로 안내했다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0020', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0020', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余呼娥酌酒, 蓋地倅所送也.', '나는 아가씨들을 불러 술을 따르게 했으니 이는 수령이 보낸 것이었다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0021', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0021', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '乃擧而屬客, 客又酬, 極懽而罷.', '곧 잔을 들어 객에게 권하자 객 역시 화답했으니 크게 즐기고서야 파했다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0022', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0022', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余問于主人曰：', '내가 주인에게 물었다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0023', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0023', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '“此地名云何? 異景勝槩, 非吾東方之所有也.”', '“이곳의 이름이 무엇입니까? 이렇게 기이하고 빼어난 경치는 우리 동방에 있는 곳이 아닙니다.”', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0024', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0024', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '主人笑曰：', '주인이 웃으며 말했다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0025', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0025', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '“此東海也.”', '“이곳은 동해(東海)입니다.”', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0026', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0026', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余曰：', '내가 말했다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0027', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0027', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '“若東海, 則此去觀魚臺, 幾許里?”', '“만약 동해라면 이곳에서 관어대(觀魚臺)까지는 거리가 얼마쯤 됩니까?”', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0028', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0028', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '曰：', '주인이 말했다.', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0029', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0029', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '“一舍之程也.”', '“30리 쯤 됩니다.”', NULL, '조선', '비현실계', '꿈_동해', '누각B', '정호의, 수령', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0030', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0030', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '余大然而覺, 但曲肱書牕而已.', '내가 크게 놀라 깨어났는데 그저 서창에 팔을 궤고 있을 뿐이었다.', NULL, '조선', '현실계', '한국(韓國)_서울_전체;한국 경상북도_영천', '정호의의 집_서실(書室)', '정호의', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SMYDHR01NU001P0031', '장면_몽유동해록_목판본_한국 국립중앙도서관_001_S#0031', '몽유동해록', '夢遊東海錄', '1인칭', '한문', '嗚呼, 世間得失皆如此夢, 雖有一名之成, 與夢麗者, 何異哉. 況窮達有數, 富貴在天, 余何慽慽於心乎. 都將得失歸之於夢, 而孜孜矻矻, 篤志力學, 以待其時可矣. 夫豈若小丈夫然而悻悻爲哉.', '아아! 세상의 득실은 모두 이 꿈과 같으니 비록 명예를 이룬다고 한들 꿈속의 화려함과 무엇이 다르겠는가? 더구나 궁핍하고 영달하는 것은 운수에 달려 있고 부귀는 하늘에 달려 있는데 내 어찌 마음 속으로 근심한단 말인가? 모두 득실을 꿈으로 돌려버리고 부지런히 매진해 뜻을 독실히 다지고 학문에 힘써 때를 기다리는 것이 좋을 것이다. 어찌 소인배들과 같이 안달복달하겠는가?', NULL, '평결부', '평결부', '평결부', '평결부', '평결부', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0001', '장면_산중열녀전_필사본_한국 경북대학교_S#0001', '산중열녀전', '山中列女傳', '1인칭', '한문', '戊戌春, 予堊居病伏, 隣朋至者, 以古談慰我罪縶涔寂, 須錄之如左.', '무술년 봄 내가 상을 당해 악실(堊室)에 병들어 누워있을 때 이웃의 벗이 찾아와 옛날이야기로 상중이라 적막한 나를 위로해 주었다. 이에 그 내용을 기록하니 다음과 같다.', NULL, '도입평', '도입평', '도입평', '도입평', '도입평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0002', '장면_산중열녀전_필사본_한국 경북대학교_S#0002', '산중열녀전', '山中列女傳', '3인칭', '한문', '古有嶠南李氏子, 自少以讀書爲業.', '옛날 영남의 이씨(李氏) 집안 자제가 있었으니 어려서부터 독서를 업으로 삼았다.', NULL, '조선', '현실계', '한국 영남', '이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0003', '장면_산중열녀전_필사본_한국 경북대학교_S#0003', '산중열녀전', '山中列女傳', '3인칭', '한문', '業已精時, 有廷試令.', '학업이 이미 단련되었을 무렵 마침 정시(廷試)를 실시한다는 명령이 내려왔다.', NULL, '조선', '현실계', '한국 영남', '이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0004', '장면_산중열녀전_필사본_한국 경북대학교_S#0004', '산중열녀전', '山中列女傳', '3인칭', '한문', '此人自挾其能, 謂:‘梯富貴別利器之秋也’ 乃勇赴焉.', '이 사람은 스스로 자신의 재능을 믿고 ‘부귀에 오르고 재능을 시험할 때’라고 여기고는 용기를 내어 과거 길을 나섰다.', NULL, '조선', '현실계', '한국 영남', '이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0005', '장면_산중열녀전_필사본_한국 경북대학교_S#0005', '산중열녀전', '山中列女傳', '3인칭', '한문', '克日啓行, 望京城進發.', '기일을 정하고 출발해 서울을 향해 나아아갔다.', NULL, '조선', '현실계', '한국 영남', '이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0006', '장면_산중열녀전_필사본_한국 경북대학교_S#0006', '산중열녀전', '山中列女傳', '3인칭', '한문', '日行三舍而宿, 每借店寄宿, 凡若此者數日.', '하루에 90리를 가서 묵었는데 매번 여관을 빌려 머물렀으니 이렇게 하기를 며칠을 했다.', NULL, '조선', '현실계', '한국 미상', '여관', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0007', '장면_산중열녀전_필사본_한국 경북대학교_S#0007', '산중열녀전', '山中列女傳', '3인칭', '한문', '一日曉起, 携杖而行, 行數里, 入肆, 喫飯取飽.', '하루는 새벽에 일어나 지팡이를 들고 길을 가는데 몇 리를 가서는 주막에 들어가 실컷 밥을 먹고 배를 채웠다.', NULL, '조선', '현실계', '한국 미상', '주막', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0008', '장면_산중열녀전_필사본_한국 경북대학교_S#0008', '산중열녀전', '山中列女傳', '3인칭', '한문', '已訖, 又登程, 峻嶺在前, 勢若摩天.', '식사를 마치고 다시 길을 나서자 앞에는 험준한 산마루가 있었으니 기세가 하늘에 닿을 듯했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0009', '장면_산중열녀전_필사본_한국 경북대학교_S#0009', '산중열녀전', '山中列女傳', '3인칭', '한문', '且路分二條, 一條卽向嶺, 那路一條, 轉入山谷, 差坦焉.', '또 길이 두 갈래로 갈라졌는데 한 갈래는 곧장 산마루쪽으로 나 있었고, 다른 한 갈래는 산골짜기를 돌아 들어가는 길이었는데 자못 평탄했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0010', '장면_산중열녀전_필사본_한국 경북대학교_S#0010', '산중열녀전', '山中列女傳', '3인칭', '한문', '不敢依嶺而進, 遂向山谷去了.', '그는 감히 산마루쪽으로 넘어가지 못하고 산골짜기로 돌아 들어가는 길을 향해 갔다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0011', '장면_산중열녀전_필사본_한국 경북대학교_S#0011', '산중열녀전', '山中列女傳', '3인칭', '한문', '路且崎嶇, 正行之間, 日當午矣.', '길이 또한 험준했는데 바로 가던 와중 어느덧 정오 무렵이 되었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0012', '장면_산중열녀전_필사본_한국 경북대학교_S#0012', '산중열녀전', '山中列女傳', '3인칭', '한문', '無酒肆可療處, 四顧幷無村落, 只得倚岩安歇, 自咄不已,', '그러나 요기할 만한 주막도 없고 사방을 둘러보아도 촌락 하나 없었으니 다만 바위에 기대어 쉬면서 스스로 탄식하기를 마지 않았다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0013', '장면_산중열녀전_필사본_한국 경북대학교_S#0013', '산중열녀전', '山中列女傳', '3인칭', '한문', '復强行十餘里, 日已西, 宿泊不知在何焉', '다시 억지로 10여 리를 걸었으니 해는 이미 서쪽으로 기울었고 묵을만한 곳이 어디에 있는지 알 수 없었으며', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0014', '장면_산중열녀전_필사본_한국 경북대학교_S#0014', '산중열녀전', '山中列女傳', '3인칭', '한문', '險谷行路之餘, 飢且切, 乃憑高四望, 山之北岩穴間, 人烟炊夕,', '험한 계곡에서 길을 걸어온 나머지 배고픔이 또한 심해졌는데 곧 높은 곳에 의지해 사방을 둘러보니 산 북쪽 바위틈 사이로 저녁밥 짓는 연기가 보였다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0015', '장면_산중열녀전_필사본_한국 경북대학교_S#0015', '산중열녀전', '山中列女傳', '3인칭', '한문', '中心, 以爲渴者得水, 蒼黃捨命而去,', '그는 속으로 목마른 사람이 물을 얻었다고 여기고는 황급히 온 힘을 다해 그곳으로 향했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0016', '장면_산중열녀전_필사본_한국 경북대학교_S#0016', '산중열녀전', '山中列女傳', '3인칭', '한문', '比到天色依微,', '도착하고 보니 날이 이미 어둑어둑해졌다', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0017', '장면_산중열녀전_필사본_한국 경북대학교_S#0017', '산중열녀전', '山中列女傳', '3인칭', '한문', '有一美人, 素服澹粧而出, 背而立曰:', '한 미인이 소복 차림으로 옅게 화장하고 나와서는 등을 돌린 채 서서 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0018', '장면_산중열녀전_필사본_한국 경북대학교_S#0018', '산중열녀전', '山中列女傳', '3인칭', '한문', '“何許君子, 得至此耶?”', '“어디 사시는 군자이길래 이곳에 이르셨습니까?”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0019', '장면_산중열녀전_필사본_한국 경북대학교_S#0019', '산중열녀전', '山中列女傳', '3인칭', '한문', '少年具道入谷迷路, 艱行見飢之由.', '젊은이는 골짜기로 들어와 길을 잃고 힘들게 길을 걷다 배고픔을 겪은 연유를 모두 이야기했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0020', '장면_산중열녀전_필사본_한국 경북대학교_S#0020', '산중열녀전', '山中列女傳', '3인칭', '한문', '他婦憐而答曰:', '그 아낙이 가련히 여겨 대답하여 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0021', '장면_산중열녀전_필사본_한국 경북대학교_S#0021', '산중열녀전', '山中列女傳', '3인칭', '한문', '“夫婦有別, 客應知之. 雖然烏可見人飢而不之救乎? 且日已盡, 此山豹虎極多, 不可向佗處去了.”', '“부부가 유별함을 손님도 분명 알 것입니다. 비록 그러나 어찌 사람의 배고픔을 보고도 구하지 않을 수 있겠습니까. 또 날이 이미 저물었고 이 산에는 표범과 호랑이가 몹시 많으니 다른 곳으로 갈 수도 없습니다.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집', '이생, 산중 부인', '『孟子』「滕文公上', NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0022', '장면_산중열녀전_필사본_한국 경북대학교_S#0022', '산중열녀전', '山中列女傳', '3인칭', '한문', '遂請入房, 房止一間.', '마침내 방으로 들기를 청하니 방은 단 한 칸뿐이었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0023', '장면_산중열녀전_필사본_한국 경북대학교_S#0023', '산중열녀전', '山中列女傳', '3인칭', '한문', '客飢渴人, 冒廉入房坐定,', '소년은 배가 고프고 목이 말랐기에 부끄러움을 무릅쓰고 방으로 들어가 자리를 잡았다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0024', '장면_산중열녀전_필사본_한국 경북대학교_S#0024', '산중열녀전', '山中列女傳', '3인칭', '한문', '進糲飯菜羹, 曰:', '여인이 밥과 나물국을 내오며 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0025', '장면_산중열녀전_필사본_한국 경북대학교_S#0025', '산중열녀전', '山中列女傳', '3인칭', '한문', '“山中, 無別味”', '“산속이라 별미가 없습니다.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0026', '장면_산중열녀전_필사본_한국 경북대학교_S#0026', '산중열녀전', '山中列女傳', '3인칭', '한문', '此時, 少年飢腔, 其味果如何哉? 雖太牢之供, 莫以加此.', '이때 소년은 배가 몹시 고팠으니 그 맛이 과연 어떠했겠는가? 비록 태뢰(太牢)와 같은 음식이라도 이보다 나을 수는 없었을 것이다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', '『莊子』‧「至樂」', NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0027', '장면_산중열녀전_필사본_한국 경북대학교_S#0027', '산중열녀전', '山中列女傳', '3인칭', '한문', '至夜深, 婦人在厨, 不入房, 少年那無不安之心?', '밤이 깊었는데도 부인은 부엌에 머물고는 방에 들어오지 않았으니 소년이 어찌 불안한 마음이 없었겠는가?', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0028', '장면_산중열녀전_필사본_한국 경북대학교_S#0028', '산중열녀전', '山中列女傳', '3인칭', '한문', '因開門, 向婦而語曰:', '이에 문을 열고 부인에게 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0029', '장면_산중열녀전_필사본_한국 경북대학교_S#0029', '산중열녀전', '山中列女傳', '3인칭', '한문', '“豈聞客居溫突, 而主處冷厨者乎? 且云山多豹虎, 奈何爲此?”', '“어찌 손님이 온돌에서 지내는데 주인은 찬 부엌에 있다는 말을 듣겠습니까? 게다가 산에 표범과 호랑이도 많다고 하셔 놓고는 어찌 이러십니까?”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0030', '장면_산중열녀전_필사본_한국 경북대학교_S#0030', '산중열녀전', '山中列女傳', '3인칭', '한문', '若是者, 數三,', '소년이 이렇게 서너 번 하였으나', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0031', '장면_산중열녀전_필사본_한국 경북대학교_S#0031', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦尙不諾,', '그 아낙은 여전히 허락하지 않았다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0032', '장면_산중열녀전_필사본_한국 경북대학교_S#0032', '산중열녀전', '山中列女傳', '3인칭', '한문', '少年遂請自居于厨.', '소년은 마침내 자신이 부엌에 머물겠다고 청했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0033', '장면_산중열녀전_필사본_한국 경북대학교_S#0033', '산중열녀전', '山中列女傳', '3인칭', '한문', '然後, 那婦强入房, 分左右而坐.', '그제서야 그 아낙이 억지로 방에 들어와 좌우로 나누어 앉았다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0034', '장면_산중열녀전_필사본_한국 경북대학교_S#0034', '산중열녀전', '山中列女傳', '3인칭', '한문', '明燭刺針, 爲少年困憊, 因勸之寢,', '부인은 촛불을 밝히고 바느질을 하다가 소년이 피곤해하므로 잠자리에 들기를 권하니', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0035', '장면_산중열녀전_필사본_한국 경북대학교_S#0035', '산중열녀전', '山中列女傳', '3인칭', '한문', '少年從之就寢.', '소년이 그 말을 따라 잠자리에 들었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0036', '장면_산중열녀전_필사본_한국 경북대학교_S#0036', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦人儀容, 有羞月沈魚之態, 少年之心, 烏得睡着?', '부인은 모습이 달과 물고기가 부끄러워 숨을 정도의 자태를 지니고 있으니 소년의 마음이 어찌 잠들 수 있겠는가?', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', '『莊子』‧「齊物論」', NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0037', '장면_산중열녀전_필사본_한국 경북대학교_S#0037', '산중열녀전', '山中列女傳', '3인칭', '한문', '自思: ‘銅雀春風, 庶不爲周郞所笑.’', '스스로 ‘동작대(銅雀臺)의 봄바람이 주랑(周郞)의 비웃음거리가 되어서는 안되겠구나.’라고 생각했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', '『三國志演義』', NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0038', '장면_산중열녀전_필사본_한국 경북대학교_S#0038', '산중열녀전', '山中列女傳', '3인칭', '한문', '乃託睡困, 而陽以足加婦膝上, 微開睫, 觀動靜如何.', '그러고는 잠든 것을 핑계로 일부러 부인의 무릎 위에 발을 올려놓고는 눈을 가늘게 뜨고서 그 반응이 어떤지를 살폈다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0039', '장면_산중열녀전_필사본_한국 경북대학교_S#0039', '산중열녀전', '山中列女傳', '3인칭', '한문', '則婦以針尺在傍者, 推足置席, 不以手.', '부인이 주변에 있는 침척(針尺)으로 그 발을 밀어서 자리에 놓고 손을 대지 않았다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0040', '장면_산중열녀전_필사본_한국 경북대학교_S#0040', '산중열녀전', '山中列女傳', '3인칭', '한문', '色忽變曰:', '그리고는 안색을 바꾸며 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0041', '장면_산중열녀전_필사본_한국 경북대학교_S#0041', '산중열녀전', '山中列女傳', '3인칭', '한문', '“客子必困甚.”', '“손님께서 무척 피곤하신가 보다.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0042', '장면_산중열녀전_필사본_한국 경북대학교_S#0042', '산중열녀전', '山中列女傳', '3인칭', '한문', '少年, 復如此者再,', '소년이 다시 이와 같이 몇 번 반복하니', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0043', '장면_산중열녀전_필사본_한국 경북대학교_S#0043', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦人亦如前, 旣畢, 乃厲聲向客曰:', '부인 역시 이전과 같이 대처하고는 바느질을 마치고 나서 곧 엄한 목소리로 손님에게 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0044', '장면_산중열녀전_필사본_한국 경북대학교_S#0044', '산중열녀전', '山中列女傳', '3인칭', '한문', '“起起.”', '“일어나십시오!”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0045', '장면_산중열녀전_필사본_한국 경북대학교_S#0045', '산중열녀전', '山中列女傳', '3인칭', '한문', '客驚得十分, 慚然而起, 陽作睡覺之狀,', '손님은 깜짝 놀라 부끄러운 기색으로 일어나 마치 자다가 깬 듯한 모습을 했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0046', '장면_산중열녀전_필사본_한국 경북대학교_S#0046', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦端坐罵客曰:', '부인은 단정히 앉아 손님을 꾸짖으며 말하였다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0047', '장면_산중열녀전_필사본_한국 경북대학교_S#0047', '산중열녀전', '山中列女傳', '3인칭', '한문', '“男女間大節, 只是別一字. 我聞客之行止, 云 :‘赴廷試.’ 乃儒者, 而何爲無禮此甚?”', '“남녀 사이의 가장 큰 절개는 오직 ‘별(別)’이라는 한 글자입니다. 제가 손님의 거동을 들어보니 과거를 보러 가는 길이라고 하니 곧 유자(儒者)이실텐데 어찌하여 무례하기가 이렇게 심합니까?”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0048', '장면_산중열녀전_필사본_한국 경북대학교_S#0048', '산중열녀전', '山中列女傳', '3인칭', '한문', '客詐爲愕然而應曰:', '손님은 일부러 놀란 듯한 표정을 지으며 답했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0049', '장면_산중열녀전_필사본_한국 경북대학교_S#0049', '산중열녀전', '山中列女傳', '3인칭', '한문', '“我何失禮? 責我至此? 或因睡中魂迷, 有此過失耶?”', '“제가 무슨 실례를 저질렀길래 나를 이토록 책망하십니까? 혹 제가 잠결에 정신이 혼미하여 이러한 실수를 저질렀습니까?”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0050', '장면_산중열녀전_필사본_한국 경북대학교_S#0050', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦良久, 以加足之事, 及之.', '부인이 한참 있다가 다리를 올린 일에 대해 언급하자', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0051', '장면_산중열녀전_필사본_한국 경북대학교_S#0051', '산중열녀전', '山中列女傳', '3인칭', '한문', '客悟悔不已, 稱罪求恕.', '손님이 뉘우치기를 마지 않고 죄를 지었다고 말하며 용서를 구했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0052', '장면_산중열녀전_필사본_한국 경북대학교_S#0052', '산중열녀전', '山中列女傳', '3인칭', '한문', '婦人强婉其顔色而言曰:', '부인이 애써 낯빛을 풀고는 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0053', '장면_산중열녀전_필사본_한국 경북대학교_S#0053', '산중열녀전', '山中列女傳', '3인칭', '한문', '“妾本此山下居人, 不幸家夫蚤歿, 因葬于此岩穴之右. 小妾因掃夫塚, 以死爲期, 而命縷頑不絶, 保至今日. 且上無舅姑, 下無子女, 妾命之薄如此, 年方十九.”', '“첩은 본래 이 산 아래에 살던 사람인데 불행하게도 남편이 일찍 죽어서 이 암혈의 오른 쪽에 장사를 지냈습니다. 소첩은 남편의 무덤을 쓸면서 죽음으로써 기약했는데 실오라기 같은 목숨이 끊어지지 않아 지금까지 지내고 있습니다. 또 위로는 시부모도 없고 아래로는 자식도 없으니 첩의 운명이 이토록 기박하며 나이는 열아홉입니다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0054', '장면_산중열녀전_필사본_한국 경북대학교_S#0054', '산중열녀전', '山中列女傳', '3인칭', '한문', '言訖, 淚如泉湧而已. 捫淚曰:', '부인이 말을 마치자 눈물이 샘솟듯 흘러냀다. 곧 눈물을 훔치며 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0055', '장면_산중열녀전_필사본_한국 경북대학교_S#0055', '산중열녀전', '山中列女傳', '3인칭', '한문', '“客懷不義之心, 故我賦得一句, 請客聽之.”', '“손님께서 불의한 마음을 품었기에 제가 시 한 구절을 지었으니 손님께서는 들어보십시오.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0056', '장면_산중열녀전_필사본_한국 경북대학교_S#0056', '산중열녀전', '山中列女傳', '3인칭', '한문', '遂嗚咽, 而誦其賦曰:', '마침내 오열하며 지은 시를 읊었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0057', '장면_산중열녀전_필사본_한국 경북대학교_S#0057', '산중열녀전', '山中列女傳', '3인칭', '한문', '“新人對於黑夜, 舊夫泣於黃泉.”', '“새 사람을 캄캄한 밤에 마주하니, 옛 남편은 황천에서 울고 있구나.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, '소작품(6언시)', NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0058', '장면_산중열녀전_필사본_한국 경북대학교_S#0058', '산중열녀전', '山中列女傳', '3인칭', '한문', '誦過, 復珠淚滿裳.', '읊기를 마치자 다시 구슬 같은 눈물이 치마를 가득 적셨다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0059', '장면_산중열녀전_필사본_한국 경북대학교_S#0059', '산중열녀전', '山中列女傳', '3인칭', '한문', '客聽之, 不覺毛骨竦然, 有凜乎不可犯貞德烈氣, 只得依枕擁朣而睡.', '손님이 이를 듣고는 자기도 모르게 모골(毛骨)이 오싹해졌으니 그 정숙한 덕성과 열녀의 기상이 범할 수 없음에 서늘한 기운을 느끼고는 그저 베개를 끌어안은 채 잠이 들었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생, 산중 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0060', '장면_산중열녀전_필사본_한국 경북대학교_S#0060', '산중열녀전', '山中列女傳', '3인칭', '한문', '少焉, 夢覺, 窓已曙, 山禽報曉.', '잠시 뒤 잠에서 깨니 창밖이 이미 밝아있었고 산새가 새벽을 알리고 있었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_단칸방(單房)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0061', '장면_산중열녀전_필사본_한국 경북대학교_S#0061', '산중열녀전', '山中列女傳', '3인칭', '한문', '束裝, 出門視之, 果有一路, 通于墓側, 乃孀媍省掃之路也.', '행장을 꾸리고 나서 문을 나서 보니 과연 길 하나가 무덤 옆으로 나 있었는데 바로 아낙이 남편의 무덤을 돌보며 청소하던 길이었다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_부인 남편의 무덤[墓]', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0062', '장면_산중열녀전_필사본_한국 경북대학교_S#0062', '산중열녀전', '山中列女傳', '3인칭', '한문', '少年自思曰:', '소년이 스스로 생각하며 말했다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_부인 남편의 무덤[墓]', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0063', '장면_산중열녀전_필사본_한국 경북대학교_S#0063', '산중열녀전', '山中列女傳', '3인칭', '한문', '“如此烈婦, 我幾乎浼”', '“이와 같은 열부를 내가 욕되게 할 뻔했구나.”', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)_여인의 집_부인 남편의 무덤[墓]', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0064', '장면_산중열녀전_필사본_한국 경북대학교_S#0064', '산중열녀전', '山中列女傳', '3인칭', '한문', '遂下山, 抄路而行.', '이윽고 산을 내려와 길을 찾아 떠났다.', NULL, '조선', '현실계', '한국 미상', '산골짜기(山谷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0065', '장면_산중열녀전_필사본_한국 경북대학교_S#0065', '산중열녀전', '山中列女傳', '3인칭', '한문', '又明日, 到京邸, 刺得于議政金氏家, 因留宿焉.', '또 다음날 서울에 이르러 의정(議政) 김씨(金氏) 가문에 명첩을 올리고 그곳에 머물렀다.', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집', '이생, 김의정(金議政)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0066', '장면_산중열녀전_필사본_한국 경북대학교_S#0066', '산중열녀전', '山中列女傳', '3인칭', '한문', '時, 議政女新寡,', '마침 김의정의 딸이 최근에 과부가 되었는데,', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집', '김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0067', '장면_산중열녀전_필사본_한국 경북대학교_S#0067', '산중열녀전', '山中列女傳', '3인칭', '한문', '寡懷不貞之心, 夜潛到李生寢房,', '과부가 부정한 마음을 품고 밤에 몰래 이생의 침실로 들어왔다.', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_이생의 침실[寢房]', '이생, 김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0068', '장면_산중열녀전_필사본_한국 경북대학교_S#0068', '산중열녀전', '山中列女傳', '3인칭', '한문', '生以義曉之, 且以前日烈婦所著詩誦之,', '그러자 이생이 의(義)로써 그녀를 깨우치고 전날 열부가 지은 시를 읊어주자', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_이생의 침실[寢房]', '이생, 김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0069', '장면_산중열녀전_필사본_한국 경북대학교_S#0069', '산중열녀전', '山中列女傳', '3인칭', '한문', '寡卽抆淚, 致悔曰:', '과부가 눈물을 훔치고 후회하며 말했다.', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_이생의 침실[寢房]', '이생, 김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0070', '장면_산중열녀전_필사본_한국 경북대학교_S#0070', '산중열녀전', '山中列女傳', '3인칭', '한문', '“君子數語, 使妾有守貞之道.”', '“군자의 몇 마디가 첩으로 하여금 정절을 지키는 도리를 지니게 했습니다.”', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_이생의 침실[寢房]', '이생, 김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0071', '장면_산중열녀전_필사본_한국 경북대학교_S#0071', '산중열녀전', '山中列女傳', '3인칭', '한문', '拜謝不已.', '그리고는 절하고 사례하기를 그치지 않았다.', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_이생의 침실[寢房]', '이생, 김씨녀(金氏女)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0072', '장면_산중열녀전_필사본_한국 경북대학교_S#0072', '산중열녀전', '山中列女傳', '3인칭', '한문', '時夜, 議政巡庄, 窃聽而心德之.', '이날 밤 김 의정이 장원을 돌다가 몰래 듣고는 덕이 있다고 여겼다.', NULL, '조선', '현실계', '한국 한양', '김의정(金議政)의 집_장원[庄]', '국왕, 김의정(金議政)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0073', '장면_산중열녀전_필사본_한국 경북대학교_S#0073', '산중열녀전', '山中列女傳', '3인칭', '한문', '遂昇聞于王庭, 蓋薦其才德也.', '마침내 조정에 아뢰었으니 이는 그의 재덕을 천거한 것이다.', NULL, '조선', '현실계', '한국 한양', '조정[王庭]', '국왕, 김의정(金議政), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0074', '장면_산중열녀전_필사본_한국 경북대학교_S#0074', '산중열녀전', '山中列女傳', '3인칭', '한문', '遂擢用爲弘文館學生云.', '마침내 그를 발탁해 홍문관(弘文館) 학생(學生)으로 임명했다고 한다.', NULL, '조선', '현실계', '한국 한양', '조정[王庭]', '국왕, 김의정(金議政), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJYNJ01NU001P0075', '장면_산중열녀전_필사본_한국 경북대학교_S#0075', '산중열녀전', '山中列女傳', '3인칭', '한문', '余聽之曰: “若非烈女之一句, 焉得及此? 噫! 山中岩兮! 有婦廬焉. 朝夕省掃, 其夫泣于泉! 一語貞節, 少年有則. 矧乎其終, 淫婦爲烈, 信其自守, 德加諸人.', '내가 이 이야기를 듣고는 말했다. “열녀의 시 한 구절이 아니었다면 어찌 이럴 수 있었겠는가? 아! 산속의 바위여! 그곳에 부인이 집을 지었구나.아침저녁으로 살피고 청소하니, 그 남편이 황천에서 감격해 우는구나. 한마디 정절의 말이, 소년이 모범으로 삼았도다. 더구나 마침내, 음탕한 아낙이 열녀가 되었으니 진실로 자신을 지키다가 그 덕이 남들에게 더해졌구나.”', NULL, '종결평', '종결평', '종결평', '종결평', '종결평', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P001', '장면_심진사전_한국 대전시립박물관_S#0001', '심진사전', '沈進士傳', '3인칭', '한문', '洛下有沈進士者, 忘其名. 性本迂僻, 而自謂高潔, 人皆目笑之.', '서울에 심진사(沈進士)라는 자가 있었으니 그 이름은 잊어버렸다. 그의 성품은 본래 고지식하고 편벽되었으나 스스로는 고결하다고 여겼으니 사람들이 모두 그를 보고 비웃었다.', NULL, '조선', '현실계', '한국 한양', '-', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P002', '장면_심진사전_한국 대전시립박물관_S#0002', '심진사전', '沈進士傳', '3인칭', '한문', '以事抵湖南,', '심 진사가 어떤 일이 있어 호남(湖南)으로 갔으니', NULL, '조선', '현실계', '한국 호남', '-', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P003', '장면_심진사전_한국 대전시립박물관_S#0003', '심진사전', '沈進士傳', '3인칭', '한문', '夕到一村舍, 而望見其東.', '저녁에 한 마을의 집[촌가]에 이르렀다가 동쪽을 멀리 바라보았다.', NULL, '조선', '현실계', '한국 호남', '모촌', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P004', '장면_심진사전_한국 대전시립박물관_S#0004', '심진사전', '沈進士傳', '3인칭', '한문', '有一巨室, 而高門臨水, 槐柳掩暎.', '거기에는 대갓집이 하나 있었는데 높은 대문이 물가에 있어 회화나무와 버드나무가 언뜻 비치고 있었다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P005', '장면_심진사전_한국 대전시립박물관_S#0005', '심진사전', '沈進士傳', '3인칭', '한문', '問之, 則曰:', '그 집에 대해 누군가에게 물어보자 그 사람이 말했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P006', '장면_심진사전_한국 대전시립박물관_S#0006', '심진사전', '沈進士傳', '3인칭', '한문', '“主人翁, 富甲南土.” 云.', '“저 집의 주인옹은 남쪽 지방에서 최고 부자입니다.”', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P007', '장면_심진사전_한국 대전시립박물관_S#0007', '심진사전', '沈進士傳', '3인칭', '한문', '俄有蒼頭來, 傳其主命曰:', '잠시 뒤 하인이 와서 그 주인의 말을 전했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P008', '장면_심진사전_한국 대전시립박물관_S#0008', '심진사전', '沈進士傳', '3인칭', '한문', '“奴家僻陋, 不堪止宿, 願枉高駕, 以光蓬蓽.”', '“저의 집은 외지고 누추해 머물러 묵을 곳이 못되지만 귀한 걸음을 해주셔서 누추한 집을 빛내주십시오.”', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P009', '장면_심진사전_한국 대전시립박물관_S#0009', '심진사전', '沈進士傳', '3인칭', '한문', '沈生即投其家, 入門, 數重無非壯麗.', '심생(沈生)이 곧 그 집에 투숙해 문 안으로 들어가니 겹겹으로 된 공간이 장엄하고 화려하지 않음이 없었다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P010', '장면_심진사전_한국 대전시립박물관_S#0010', '심진사전', '沈進士傳', '3인칭', '한문', '抵一高軒, 朱欄曲檻, 縹緲於萬竿脩竹之間, 而眼底淸朗, 怳若仙境也.', '어떤 고헌(高軒)에 이르자 붉은 난간과 구부러진 난간이 울창한 대나무 숲 사이에서 어렴풋이 솟아 눈앞에 환하게 펼쳐지니 흡사 선경(仙境)과 같았다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P011', '장면_심진사전_한국 대전시립박물관_S#0011', '심진사전', '沈進士傳', '3인칭', '한문', '主人翁, 欣然迎接曰:', '주인옹이 기쁘게 맞이하며 말했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P012', '장면_심진사전_한국 대전시립박물관_S#0012', '심진사전', '沈進士傳', '3인칭', '한문', '“古人云, ‘四海之內, 皆兄弟.’, ‘傾蓋如舊’, 何必舊相識也?”', '“옛사람들 말에 ‘사해 안이 모두 형제다.’라고 했고, ‘수레 덮개를 기울이고 잠깐 이야기해도 오랜 친구를 대하는 것 같다.’고 했는데 어찌 꼭 예전부터 아는 사이여야만 하겠습니까?”', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, '『논어(論語)』「안연(顔淵)」/ 『사기(史記)』「추양열전(鄒陽列傳)」', NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P013', '장면_심진사전_한국 대전시립박물관_S#0013', '심진사전', '沈進士傳', '3인칭', '한문', '因略問姓名居址門戶宗族後, 顧命左右, 進酒饌.', '그리고는 성명과 거주지와 문호와 종족을 대략 물은 후 옆 사람에게 명하여 술과 음식을 내오게 했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P014', '장면_심진사전_한국 대전시립박물관_S#0014', '심진사전', '沈進士傳', '3인칭', '한문', '明粧麗服者數人, 擧案而進水陸珍味, 食前方丈.', '그러자 몹시 화려한 의복을 입은 사람 여려 명이 상을 들고서 산해진미를 내어왔는데 밥상이 사방 1길이나 되었다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, '『맹자(孟子)』 「진심 하(盡心下)」', NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P015', '장면_심진사전_한국 대전시립박물관_S#0015', '심진사전', '沈進士傳', '3인칭', '한문', '以碧玉盃, 酌紫霞酒, 而相勸.', '벽옥으로 만든 잔에 자하주(紫霞酒)를 부어 서로 권했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P016', '장면_심진사전_한국 대전시립박물관_S#0016', '심진사전', '沈進士傳', '3인칭', '한문', '又有粉兒戴綠髮, 曳錦裙, 抱琵琶者十餘雙, 箇箇明艶, 淸歌管絃, 嬌姸竝奏.', '또 머리에 가체(加髢)를 쓰고 비단 치마를 끌며 비파를 안은 화장한 아이들 십여 쌍이 있었으니 하나하나가 눈부시게 요염했으며, 청아한 노래와 관현악 연주로 교태와 아름다움을 함께 드러냈다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P017', '장면_심진사전_한국 대전시립박물관_S#0017', '심진사전', '沈進士傳', '3인칭', '한문', '主翁把盃, 曰:', '주인옹이 술잔을 잡고 말했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P018', '장면_심진사전_한국 대전시립박물관_S#0018', '심진사전', '沈進士傳', '3인칭', '한문', '“吾與尊君, 素非親厚, 而所以奉邀者, 我有切急情事, 誠欲奉托於君, 君能聽之否?”', '“나와 존군(尊君)은 평소 친분이 있는 건 아닙니다만 이렇게 받들어 맞이한 까닭은 내게 몹시 절박한 사정이 있어 성심으로 존군께 부탁을 하고 싶어서이니 그대께서 들어줄 수 있겠습니까?”', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P019', '장면_심진사전_한국 대전시립박물관_S#0019', '심진사전', '沈進士傳', '3인칭', '한문', '沈生謝曰:', '심생이 사례하며 말했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P020', '장면_심진사전_한국 대전시립박물관_S#0020', '심진사전', '沈進士傳', '3인칭', '한문', '“吾與公, 曾無雅分, 而邂逅相遇, 款曲至此, 未知令公欲托者, 何事? 力所及處, 豈敢不奉周旋?”', '“내가 공과는 평소 친분을 둔 적이 없지만 서로 만나 이렇게 곡진히 대하시니 모르겠습니다만 영공께서 부탁하려는 일은 어떤 일입니까? 힘이 닿는 한 어찌 감히 받들어 돕지 않겠습니까?”', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P021', '장면_심진사전_한국 대전시립박물관_S#0021', '심진사전', '沈進士傳', '3인칭', '한문', '主翁曰:', '주인옹이 말했다.', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SSJSJNU001P022', '장면_심진사전_한국 대전시립박물관_S#0022', '심진사전', '沈進士傳', '3인칭', '한문', '“老人家財, 雖足五福, 難分妻妾, 俱無子女, 晩得賤妾, 始生一女, 今至破瓜之年. 老人鍾愛甚篤, 而其母即京城士人某之婢也. 吾請以千金, 贖出其女, 而其主執拗不許. 今聞欲以吾女, 爲其侍婢, 使令於前而其差奴方至. 吾切憤惋, 誠無辭可拒. 而保此息女, 只有一道, 若士夫卜妾, 則其主雖甚怪妄, 亦安敢下手乎? 玆者事機已迫, 而吾女雖賤, 才容果非凡庸, 吾誠不忍以窈窕之女, 委與鄕曲之茸闒者. 今見君, 京城華族, 少年才子, 若以賤息, 奉事巾櫛, 吾死無恨. 未知君可肯許否?”', '“이 늙은이가 집안의 재산이 비록 오복(五福)에 들긴 하지만 처첩을 가릴 것 없이 모두 자식이 없다가 늘그막에 천첩을 두어 비로소 딸 하나를 얻었으니 지금 나이가 열여섯이 되었습니다. 이 늙은이가 몹시 사랑을 쏟았으나 그 어미는 서울의 사인(士人) 아무개의 비녀(婢女)입니다. 내가 천금으로 그녀를 속량(贖良)시키고자 했으나 그 주인이 고집을 부리며 허락하지 않았습니다. 지금 듣기로 내 딸을 그의 시비로 삼아서 앞에서 부리겠다고 하여 그 명령을 받은 노비가 막 여기 왔습니다. 내 참으로 분하지만 참으로 거절할 구실이 없습니다. 그런데 이 딸아이를 지키는 데에는 다만 한가지 방도가 있으니 만약 사대부가 첩으로 들인다면 그 주인이 비록 심히 괴망(怪妄)한 사람이라도 어찌 감히 아래에서 손을 쓸 수가 있겠습니까? 지금 일의 기미가 이미 급박한데 내 딸은 비록 천하지만 재주와 용모가 범상치 않으니 내가 진실로 차마 아리따운 딸을 시골의 우둔한 자에게 맡기지는 못하겠소. 그런데 지금 그대를 보니 서울의 지체 높은 사족으로 젊은 나이에 재주가 있어 보이니 만약 미천한 딸을 그대에게 시집 보내 모실 수게 한다면 내 죽어도 여한이 없습니다. 모르겠습니다만 그대께서는 허락해 주실 수 있겠습니까?', NULL, '조선', '현실계', '한국 호남', '모촌_대갓집', NULL, '『서경(書經)』 「홍범(洪範)」/ 
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SAS01NU001P0017', '장면_안생_필사본_한국 규장각한국학연구원_S#0017', '안생', '安生', '3인칭', '한문', '乘夜, 踰垣相從, 爲買小店於宮側. 以爲往來之所.', '그리고 밤을 틈타 담을 넘어 서로 만났으며 재상 집 근처에 작은 가게를 사서 왕래하는 장소로 삼았다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0018', '장면_안생_필사본_한국 규장각한국학연구원_S#0018', '안생', '安生', '3인칭', '한문', '一日, 女家送赤鞋一雙.', '하루는 여인의 집에서 붉은 신 한 켤레를 보내왔다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0019', '장면_안생_필사본_한국 규장각한국학연구원_S#0019', '안생', '安生', '3인칭', '한문', '女探弄不已,', '여인이 이를 만지작거리며 좋아함을 마지않으니', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0020', '장면_안생_필사본_한국 규장각한국학연구원_S#0020', '안생', '安生', '3인칭', '한문', '生戱曰:', '안생이 농담하며 말했다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0021', '장면_안생_필사본_한국 규장각한국학연구원_S#0021', '안생', '安生', '3인칭', '한문', '“着此好物, 將樂他人乎?”', '“이 좋은 신을 신고 장차 다른 사람을 즐겁게 해주려는가?”', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0022', '장면_안생_필사본_한국 규장각한국학연구원_S#0022', '안생', '安生', '3인칭', '한문', '女變色曰:', '여인이 정색하고 말했다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0023', '장면_안생_필사본_한국 규장각한국학연구원_S#0023', '안생', '安生', '3인칭', '한문', '“成說之言, 皎在目前, 君何發言如是?”', '“맹세한 말이 눈앞에 선한데 그대는 어찌 그런 말씀을 하십니까?”', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0024', '장면_안생_필사본_한국 규장각한국학연구원_S#0024', '안생', '安生', '3인칭', '한문', '卽解所佩刀, 割盡一隻.', '그러고는 곧장 차고 있던 칼을 풀어 신발 한 짝을 다 찢어버렸다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0025', '장면_안생_필사본_한국 규장각한국학연구원_S#0025', '안생', '安生', '3인칭', '한문', '又一日, 針縫白衫,', '또 하루는 여인이 흰 적삼을 바느질하고 있었는데', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0026', '장면_안생_필사본_한국 규장각한국학연구원_S#0026', '안생', '安生', '3인칭', '한문', '生戲亦如之.', '안생이 지난 번과 같이 또 농담을 했다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0027', '장면_안생_필사본_한국 규장각한국학연구원_S#0027', '안생', '安生', '3인칭', '한문', '女卽掩泣曰:', '여인이 즉시 얼굴을 가리고 울며 말했다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0028', '장면_안생_필사본_한국 규장각한국학연구원_S#0028', '안생', '安生', '3인칭', '한문', '“予非背君, 君實背我.”', '“제가 그대를 배반한 것이 아니라 그대가 실로 저를 배반하는 것입니다.”', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0029', '장면_안생_필사본_한국 규장각한국학연구원_S#0029', '안생', '安生', '3인칭', '한문', '以衫投於汚瀆.', '그러고는 적삼을 더러운 도랑에 던져버렸다.', NULL, '조선', '현실계', '한국 한양', '도랑', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0030', '장면_안생_필사본_한국 규장각한국학연구원_S#0030', '안생', '安生', '3인칭', '한문', '生心服其操. 眷戀愈甚.', '안생이 마음으로 그 지조에 감복해 그리워하는 마음이 더욱 깊어졌다.', NULL, '조선', '현실계', '한국 한양', '도랑', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0031', '장면_안생_필사본_한국 규장각한국학연구원_S#0031', '안생', '安生', '3인칭', '한문', '自此, 暮去曉還, 如是者累月.', '이로부터 안생은 저녁에 갔다가 새벽에 돌아왔으니 이렇게 한 것이 여러 달이었다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0032', '장면_안생_필사본_한국 규장각한국학연구원_S#0032', '안생', '安生', '3인칭', '한문', '大相聞之大怒, 嫁與伴人之無妻者.', '재상이 이 소문을 듣고 크게 노해 종놈 중 아내가 없는 자에게 시집보내게 했다.', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집', '재상', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0033', '장면_안생_필사본_한국 규장각한국학연구원_S#0033', '안생', '安生', '3인칭', '한문', '女卽欣然曰.', '여인이 즉시 기뻐하며 말했다.', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집', '재상, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0034', '장면_안생_필사본_한국 규장각한국학연구원_S#0034', '안생', '安生', '3인칭', '한문', '“事已至此. 吾豈守節之人?”', '“일이 이미 이 지경이 되었으니 제가 어찌 절개를 지킬 사람이겠습니까?”', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집', '재상, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0035', '장면_안생_필사본_한국 규장각한국학연구원_S#0035', '안생', '安生', '3인칭', '한문', '嫁娵之具, 親自爲備, 盡招宮人. 作盛饌饋之.', '여인은 혼수품을 직접 챙기고 집안 종들을 전부 불러 성찬을 지어 대접했다.', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집', '재상, 여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0036', '장면_안생_필사본_한국 규장각한국학연구원_S#0036', '안생', '安生', '3인칭', '한문', '人人皆意改嫁, 而或疾其反覆無信.', '사람들은 모두 그녀가 개가할 것이라고 여겼으니 혹자는 그가 신의 없이 마음을 바꿨다고 미워하기도 했다.', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집', '여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0037', '장면_안생_필사본_한국 규장각한국학연구원_S#0037', '안생', '安生', '3인칭', '한문', '女於是夕, 潛入他房, 自縊而死.', '여인은 이날 저녁에 몰래 다른 방에 들어가 스스로 목매어 죽었다.', NULL, '조선', '현실계', '한국 한양', '동성(東城) 재상의 집_빈 방[他房]', '여인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0038', '장면_안생_필사본_한국 규장각한국학연구원_S#0038', '안생', '安生', '3인칭', '한문', '生未之知也.', '그러나 안생은 아직 이 사실을 알지 못했다.', NULL, '조선', '현실계', '한국 한양', '미상', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0039', '장면_안생_필사본_한국 규장각한국학연구원_S#0039', '안생', '安生', '3인칭', '한문', '翌日, 生在本家,', '다음 날 안생이 본가에 있는데,', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0040', '장면_안생_필사본_한국 규장각한국학연구원_S#0040', '안생', '安生', '3인칭', '한문', '有小艾入云.', '어린 여종이 들어와 일렀다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0041', '장면_안생_필사본_한국 규장각한국학연구원_S#0041', '안생', '安生', '3인칭', '한문', '“娘子來矣.”', '“낭자께서 오셨습니다.”', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0042', '장면_안생_필사본_한국 규장각한국학연구원_S#0042', '안생', '安生', '3인칭', '한문', '生倒屣出門,', '안생이 신발을 거꾸로 신고 문을 나섰는데', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0043', '장면_안생_필사본_한국 규장각한국학연구원_S#0043', '안생', '安生', '3인칭', '한문', '艾遽曰:', '여종이 다급히 말했다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0044', '장면_안생_필사본_한국 규장각한국학연구원_S#0044', '안생', '安生', '3인칭', '한문', '“娘子, 死於昨夜.”', '“낭자께서는 지난밤에 죽었습니다.”', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0045', '장면_안생_필사본_한국 규장각한국학연구원_S#0045', '안생', '安生', '3인칭', '한문', '生笑而未知信. 不問其故.', '안생이 웃으며 아직 믿지 않았으며 그 이유를 묻지 않았다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생의 여종[小艾]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0046', '장면_안생_필사본_한국 규장각한국학연구원_S#0046', '안생', '安生', '3인칭', '한문', '至其店, 則堂中置床, 表衾覆尸.', '밀회 장소였던 가게에 이르니 대청 가운데 평상이 놓였고 겉 이불이 시신을 덮고 있었다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0047', '장면_안생_필사본_한국 규장각한국학연구원_S#0047', '안생', '安生', '3인칭', '한문', '生失聲痛哭, 枕股擣胷, 四隣聞之, 無不嗚咽.', '안생이 목 놓아 통곡하며 주저 앉아 가슴을 치니 사방 이웃이 이를 듣고 오열하지 않는 이가 없었다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0048', '장면_안생_필사본_한국 규장각한국학연구원_S#0048', '안생', '安生', '3인칭', '한문', '是時, 大雨水漲, 人不通于城東家.', '이때 큰 비가 내려 물이 불어는 바람에 사람들이 성 동쪽 집과 왕래하지 못했다.', NULL, '조선', '현실계', '한국 한양', '여인의 집', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0049', '장면_안생_필사본_한국 규장각한국학연구원_S#0049', '안생', '安生', '3인칭', '한문', '生自備喪具殯之, 朝夕設奠, 夜則目不交睫.', '안생은 직접 상례 도구를 마련해 빈소를 차리고 아침저녁으로 제사 음식을 올리며 밤에는 눈을 붙이지 못했다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0050', '장면_안생_필사본_한국 규장각한국학연구원_S#0050', '안생', '安生', '3인칭', '한문', '夜久假寐, 女自外而入, 彷彿平生之貌.', '밤이 깊어 선잠이 들었는데 여인이 밖으로부터 들어오니 살아생전의 모습과 흡사했다.', NULL, '조선', '비현실계', '꿈', '작은 가게', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0051', '장면_안생_필사본_한국 규장각한국학연구원_S#0051', '안생', '安生', '3인칭', '한문', '生進欲與話, 遽已睡覺.', '안생이 나아가 함께 이야기하고자 하였으나 급작스레 이미 잠을 깼다.', NULL, '조선', '비현실계/현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0052', '장면_안생_필사본_한국 규장각한국학연구원_S#0052', '안생', '安生', '3인칭', '한문', '回望室中, 窓牖寂然. 風褰紙帳, 孤燈明滅而已.', '방 안을 돌아보니 창문은 고요하고 바람은 종이 장막을 걷어 올렸으니 외로운 등불만 깜빡일 뿐이었다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0053', '장면_안생_필사본_한국 규장각한국학연구원_S#0053', '안생', '安生', '3인칭', '한문', '生呼痛, 將絶復蘇.', '안생이 울부짖고 비통해하며 기절했다가 다시 깨어났다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0054', '장면_안생_필사본_한국 규장각한국학연구원_S#0054', '안생', '安生', '3인칭', '한문', '越三日, 雲散雨霽.', '사흘이 지나니 구름이 흩어지고 비가 개었다.', NULL, '조선', '현실계', '한국 한양', '작은 가게', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0055', '장면_안생_필사본_한국 규장각한국학연구원_S#0055', '안생', '安生', '3인칭', '한문', '生乘月向本家, 獨行信步.', '안생이 달을 타고 본가를 향했으니 홀로 발길이 닿는 대로 걸었다.', NULL, '조선', '현실계', '한국 한양', '미상', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0056', '장면_안생_필사본_한국 규장각한국학연구원_S#0056', '안생', '安生', '3인칭', '한문', '至壽康宮東門. 夜已二鼓.', '그러다 수강궁(壽康宮) 동문에 이르니 밤은 이미 이경(二更)쯤 되었다.', NULL, '조선', '현실계', '한국 한양', '창경궁(昌慶宮) 동문', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0057', '장면_안생_필사본_한국 규장각한국학연구원_S#0057', '안생', '安生', '3인칭', '한문', '有女靚粉高髻, 或後或先.', '여인이 분을 곱게 바르고 높은 쪽머리를 하고 있었으니 앞서거니 뒤서거니 했다.', NULL, '조선', '현실계', '한국 한양', '창경궁(昌慶宮) 동문', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0058', '장면_안생_필사본_한국 규장각한국학연구원_S#0058', '안생', '安生', '3인칭', '한문', '生追而視之, 罄欬歎息, 一似前聞.', '안생이 쫓아가 보니 기침 소리와 한숨 소리가 이전에 들었던 소리와 똑같았다.', NULL, '조선', '현실계', '한국 한양', '창경궁(昌慶宮) 동문', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0059', '장면_안생_필사본_한국 규장각한국학연구원_S#0059', '안생', '安生', '3인칭', '한문', '生大呼而走.', '안생이 크게 소리 지르며 달아났다.', NULL, '조선', '현실계', '한국 한양', '창경궁(昌慶宮) 동문', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0060', '장면_안생_필사본_한국 규장각한국학연구원_S#0060', '안생', '安生', '3인칭', '한문', '至一溝曲, 女又坐其傍.', '한 도랑 굽이에 이르니 여인이 또 그 근처에 앉아 있었다.', NULL, '조선', '현실계', '한국 한양', '창경궁(昌慶宮) 동문_도랑[一溝曲]', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0061', '장면_안생_필사본_한국 규장각한국학연구원_S#0061', '안생', '安生', '3인칭', '한문', '生不顧而去, 至其家. 女又坐門外.', '안생이 돌아보지 않고 떠나가 자신의 집에 이르렀는데 여인이 또 대문 밖에 앉아 있었다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생, 여인(귀신)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0062', '장면_안생_필사본_한국 규장각한국학연구원_S#0062', '안생', '安生', '3인칭', '한문', '生大聲喚僕.', '안생이 큰 소리로 종을 부르자', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0063', '장면_안생_필사본_한국 규장각한국학연구원_S#0063', '안생', '安生', '3인칭', '한문', '女沒身于砧竇, 寂無所見.', '여인은 다듬이 돌에 몸을 감춰 고요하여 보이는 바가 없었다.', NULL, '조선', '현실계', '한국 한양', '안생의 집_다듬이 돌[砧竇]', '안생, 여인(귀신)', '재상, 제서(諸婿), 여인', NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0064', '장면_안생_필사본_한국 규장각한국학연구원_S#0064', '안생', '安生', '3인칭', '한문', '生心神昏懞, 若癡若狂.', '안생은 심신이 어지러워 바보 같기도 하고 미친 사람 같기도 했다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SAS01NU001P0065', '장면_안생_필사본_한국 규장각한국학연구원_S#0065', '안생', '安生', '3인칭', '한문', '月餘以禮葬之, 未幾生亦死.', '한 달 남짓 뒤에 예법대로 여인의 장례를 치러주었으나 얼마 안 있어 안생 또한 세상을 떠났다.', NULL, '조선', '현실계', '한국 한양', '안생의 집', '안생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0001', '장면_오후강전_필사본_한국 이채하_S#0001', '오후강전', '吳後姜傳', '3인칭', '한문', '有宋高宗皇帝建炎二年戊申, 同平章事金萬鍊, 以老退歸里鄕.', '송(宋)나라 고종황제(高宗皇帝) 건염(建炎) 2년 무신년(戊申年)에 동평장사(同平章事) 김만련(金萬鍊)이 나이가 들어 관직에서 물러나 고향으로 돌아갔다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0002', '장면_오후강전_필사본_한국 이채하_S#0002', '오후강전', '吳後姜傳', '3인칭', '한문', '鄕錢塘也, 天下之名娼·佳妓之所來會也, 美羞珍錯之所産出也. 左有太湖, 右有大江, 南通蠶叢, 北連皇城. 商艦貿艎, 泛泛來往, 眞三吳之一都會也.', '고향 전당(錢塘)은 천하의 이름난 창기(娼妓)와 아름다운 기녀들이 모이는 곳이자 진귀한 산해진미가 나오는 곳이다. 왼쪽에는 태호(太湖)가 있고 오른쪽에는 대강(大江)이 흐르며, 남쪽으로는 잠총(蠶叢)과 통하고 북쪽으로는 황성(皇城)과 접해있어 상선(商船)과 무역선이 자주 오갔으니 참으로 삼오(三吳) 도회지 중 하나였다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0003', '장면_오후강전_필사본_한국 이채하_S#0003', '오후강전', '吳後姜傳', '3인칭', '한문', '萬鍊乃築室於天皇山下, 扁之曰: “昊廣”, 積六經九典諸史百家之書, 又有樂器·琴瑟·鼓缶·管笛之屬.', '김만련이 천황산(天皇山) 아래에 집을 지어 “호광(昊廣)”으로 편액하고서 육경(六經)‧구전(九典)‧각종 역사서‧제자백가 서적을 모아두고 또 악기‧금슬(琴瑟)‧북과 질장구‧피리 따위를 갖추었다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0004', '장면_오후강전_필사본_한국 이채하_S#0004', '오후강전', '吳後姜傳', '3인칭', '한문', '每於春花爛熳, 秋月明朗之, 則以瓦器盛水, 援琴自彈. 族其高下, 又與二三故老, 投壺圍碁, 消遣世慮, 頓忘天下之憂.', '매번 봄꽃이 만발하거나 가을 달이 밝게 비출 때면 질그릇에 물을 채워놓고 비파를 가지고 와서 스스로 연주하곤 했다. 나이가 많고 적은 사람을 한데 모아 또 노인 두세 명과 함께 투호와 바둑을 즐기며 세상의 걱정을 흘려보내 문득 천하의 근심을 잊었다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0005', '장면_오후강전_필사본_한국 이채하_S#0005', '오후강전', '吳後姜傳', '3인칭', '한문', '有一子, 名曰: ‘海甲’, 字曰: ‘漢仲’, 神彩淸越, 襟期卓然.', '그에게는 아들 하나가 있으니 이름은 ‘해갑(海甲)’이고 자(字)는 ‘한중(漢仲)’으로 정신과 풍채가 맑고 뛰어났으며 지취가 남달랐다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련, 김해갑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0006', '장면_오후강전_필사본_한국 이채하_S#0006', '오후강전', '吳後姜傳', '3인칭', '한문', '於後園, 別構一堂, 使生處以讀書.', '김만련이 후원(後園)에 별도로 당(堂)을 지어 김생이 독서하며 지내도록 해주었다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련, 김해갑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0007', '장면_오후강전_필사본_한국 이채하_S#0007', '오후강전', '吳後姜傳', '3인칭', '한문', '生才藝過人, 於書無不慣通, 工於六律, 善於詞藻. 時人號曰: ‘金李杜’.', '김생은 재주와 문예가 남보다 뛰어나 글에 익숙히 통달하지 않음이 없고 육률(六律)도 전공하고 시문에도 능숙해 당시 사람들이 ‘김이두(金李杜)’라고 불렀다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련, 김해갑', '『창려선생집(昌黎先生集)』‧「조장적(調張籍)」', NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0008', '장면_오후강전_필사본_한국 이채하_S#0008', '오후강전', '吳後姜傳', '3인칭', '한문', '蓋指詩如李白, 形如杜牧也.', '이는 시가 이백(李白)과 같고 모습이 두목(杜牧)과 같다는 말이다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련, 김해갑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0009', '장면_오후강전_필사본_한국 이채하_S#0009', '오후강전', '吳後姜傳', '3인칭', '한문', '年至十七, 結婚於皇城法部尙書王裕之女, 及期成禮.', '김생의 나이가 17살이 되자 황제 도성의 법부상서(法部尙書) 왕유(王裕)의 딸과 혼약을 맺고 기일이 되자 예식을 치렀다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련, 김해갑, 왕유, 왕유의 딸[왕씨(王氏)]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0010', '장면_오후강전_필사본_한국 이채하_S#0010', '오후강전', '吳後姜傳', '3인칭', '한문', '王氏亦淑女也, 工於詩詞, 日誦內則女儀等書, 爲捆內法度, 人賀其得內助.', '왕씨(王氏) 또한 현숙한 여인으로 시사(詩詞)를 전공하여 날마다 󰡔내칙(內則)󰡕과 󰡔여의(女儀)󰡕 등의 책을 암송해 집안의 법도로 삼았으니, 사람들이 그녀가 내조를 잘하는 것을 가상히 여겼다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '왕유의 딸[왕씨(王氏)]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0011', '장면_오후강전_필사본_한국 이채하_S#0011', '오후강전', '吳後姜傳', '3인칭', '한문', '越六年癸丑, 父萬鍊卒, 是年, 母邢氏又卒, 明年, 妻王氏亦卒.', '6년이 지난 계축(癸丑)년에 부친 만련이 세상을 떠나고 이듬해 모친 형씨(邢氏)도 세상을 떠났으며 다음 해에 아내 왕씨도 세상을 떠났다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김만련,형씨(邢氏), 왕유의 딸[왕씨(王氏)]', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0012', '장면_오후강전_필사본_한국 이채하_S#0012', '오후강전', '吳後姜傳', '3인칭', '한문', '生悲酸悼苦, 不能自抑, 且思其淑儀禮度, 頓無再取室之意.', '김생은 슬픔에 쓰라리고 괴로워하여 스스로 가눌 수 없었으니 그 현숙하고 의젓한 몸가짐을 생각할 때면 더는 다시 아내를 맞이할 마음이 없었다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김해갑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0013', '장면_오후강전_필사본_한국 이채하_S#0013', '오후강전', '吳後姜傳', '3인칭', '한문', '欲周遊六合, 博覽宇內, 以寓形骸於浮埃之外, 乃放賣家産, 使弟河甲及季母留氏, 僑寓河北.', '이에 천지를 두루 돌아다니고 세상을 널리 유람하여 몸을 속세 밖에 맡기고자 하여 곧 가산(家産)을 처분한 다음 아우 하갑(河甲)과 숙모 유씨(留氏)를 하북(河北)에 얹혀살도록 하였다.', NULL, '중국', '현실계', '중국(中國)_절강성(浙江省)_항주시(杭州市)_천황산(天皇山)', '김만련(金萬鍊)의 저택', '김해갑, 하갑(河甲), 숙모 유씨(留氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0014', '장면_오후강전_필사본_한국 이채하_S#0014', '오후강전', '吳後姜傳', '3인칭', '한문', '卽端蒙單閼夏之仲也, 乃束匹馬之裝, 携焦尾之琴, 作淮南之遊.', '그해 을묘년(乙卯年) 음력 5월로 김생은 곧 혼자 떠날 행장을 꾸린 다음 초미금(焦尾琴)을 메어 회남(淮南) 지역으로 떠났다.', NULL, '중국', '현실계', '중국(中國)_안휘성(安徽省)_회남(淮南)', '김만련(金萬鍊)의 저택', '김해갑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SOHGJ01NU001P0015', '장면_오후강전_필사본_한국 이채하_S#0015', '오후강전', '吳後姜傳', '3인칭', '한문', '自金陵鏡浦, 歷汝州三江七島九灣六洲諸處, 至海昌月浦, 時則仲秋望間.', '금릉(金陵)의 경포(鏡浦)에서 출발하여 여주(汝州)의 세 강‧일곱 섬‧아홉 만과‧여섯 모래톱 등 여러 곳을 지나 해창(海昌)의 월포(月浦)에 이르렀으니 때는 음력 8월 보름 무렵이었다.', NULL, '중국', '현실계', '중국_강소성(江蘇省)_남경시(南京市)
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SWRPHJ01NU002P0051', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0051', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '王與夫人, 歡喜時,', '월지국 왕과 부인(왕후)이 기뻐할 즈음', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0052', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0052', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '公主生身, 具陳上事,', '공주로 태어난 몸이 염라대왕의 일을 갖추어 진술하니', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0053', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0053', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '王嘆之, 詔王郞曰:', '월지국 왕이 감탄하여 왕랑에게 조서를 내려 말했다', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0054', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0054', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '“朕曾不見此事, 所謂夢中之瑞.”', '“짐이 이런 일을 본 적이 없으니 이른바 꿈 중의 상서로다.”', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0055', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0055', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '王郞卽奏言:', '왕랑이 즉시 아뢰었다.', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0056', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0056', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '“宋氏, 十一年間, 不思餘親, 唯守前信, 乃遇重親,”', '“송씨가 11년 동안 다른 친족을 생각하지 않고 오직 전날의 신의를 지켜 이에 새 부모님을 만났습니다.”', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨), 월지국 왕, 월지국 왕후', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0057', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0057', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '歡喜而退, 延壽一百四十七歲,', '기뻐하여 돌아가 수명을 147세까지 연장했으니', NULL, '고려', '비현실계', '월지국', '월지국 왕국', '왕랑, 월지국 공주(송씨)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0058', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0058', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '後同生極樂也.', '훗날 부부는 함께 극락세계에서 태어났다.', NULL, '고려', '비현실계', '서방정토(西方淨土)', '서방정토(西方淨土)', '왕랑, 월지국 공주(송씨)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SWRPHJ01NU002P0059', '장면_왕랑반혼전_목판본_한국 동국대학교_001_S#0059', '왕랑반혼전', '王郞返魂傳', '3인칭', '한문', '彼王郞於此念佛, 雖不信輕笑, 以其見聞故, 終成往生之益, 況見聞而不輕笑, 見聞而隨喜者乎? 故附此傳, 助現念佛利澤之廣.', '저 왕랑이 이 염불에 대해 비록 믿지 않고 경시하며 비웃었으나 그 보고 들은 까닭으로 마침내 왕생의 이익을 이루게 되었다. 더구나 보고 들으면서 경시하거나 비웃지 않고, 보고 들으면서 수희(隨喜)하는 자들은 어떠하겠는가? 그러므로 이 전(傳)을 덧붙여 염불의 이익과 은택이 넓음을 드러내는 것을 돕는다.', NULL, '논평부', '논평부', '논평부', '논평부', '논평부', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0001', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0076', '유생전', '劉生傳', '3인칭', '한문', '以禮葬之, 結幕山谷, 盡心至誠, 三年侍墓而歸,', '유생이 예를 갖추어 장례를 치르고 산골짜기에 여막(廬幕)을 지어 마음을 다해 지극정성으로 3년 동안 시묘살이를 하고 집에 돌아왔다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0002', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0077', '유생전', '劉生傳', '3인칭', '한문', '家禍連綿, 奴僕分散, 田盡莊耗. 內無擬門之童, 外無投己之戚, 孑孑孤蹤, 零丁獨立, 勢不已, 奔走道路, 行乞東西.', '그런데 집안의 재앙이 끊이지 않아 노복들은 이리저리 흩어지고 가산도 모두 소모되었다. 안으로는 대문에서 응대하는 동자가 없었으며 밖으로는 자기를 받아줄 친척이 없었으니 혈혈단신(孑孑單身)으로 의지할 데 없이 혼자 남아 상황이 어쩔 수가 없어 길거리를 돌아다니며 여기저기로 구걸하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0003', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0078', '유생전', '劉生傳', '3인칭', '한문', '衣結懸鶉, 面浮餓色, 人皆哀嗟, 莫不流涕.', '의복은 헤어져 너덜너덜하고 얼굴에는 굶주린 기색이 드러나니 사람들이 모두 서글퍼하며 눈물을 흘리지 않는 이가 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0004', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0079', '유생전', '劉生傳', '3인칭', '한문', '生一邊思, 則欲自絕殘命, 暫忘身勢. 故未所能者, 使劉氏綿綿殘孫, 永絕先祀, 亦失父母之遺言.', '유생은 한편으로 남은 목숨을 스스로 끊어 자신의 신세를 잠깐 잊으려는 생각도 했다. 그러나 짐짓 그렇게 할 수 없었던 것은 만일 유씨 가문의 대대로 이어지는 후손이 선조의 제사를 영영 끊게 되면 또한 부모의 유언을 저버리게 되는 것이기 때문이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0005', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0080', '유생전', '劉生傳', '3인칭', '한문', '是以, 僅保弱質, 流離度日.', '그래서 유생은 겨우 쇠약한 몸을 보존하여 떠돌아다니며 날을 보냈다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0006', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0081', '유생전', '劉生傳', '3인칭', '한문', '一日, 方尙書見之道中, 不勝哀嗟, 握手落淚曰:', '하루는 방 상서가 길 가운데서 유생을 만나 애통함을 이기지 못하여 손을 잡고 눈물을 흘리며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '방 상서 / 유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0007', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0082', '유생전', '劉生傳', '3인칭', '한문', '“嗟呼! 天道無知, 使劉氏子孫, 豈至此極! 循環世變, 實難知之矣.”', '“아아! 하늘도 무심하시다. 유씨의 자손을 어찌 이 지경에 이르게 하였는가! 돌고 도는 세상의 변화는 정말로 알기가 어렵구나.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '방 상서 / 유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0008', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0083', '유생전', '劉生傳', '3인칭', '한문', '因與生俱歸處於外堂, 又改衣一襲, 遺養食肉, 容貌風彩, 一如其舊, 眞可謂華麗玉郎. 尙書愈奇之.', '방 상서가 그리하여 유생과 함께 돌아와 외당(外堂)에 살게 하고 또 옷 한 벌을 새로 입히며 머물러 있게 하고 고기를 먹이자 용모와 풍채가 모두 예전과 같아졌으니 참으로 화려한 옥랑(玉郎)이라 할 만하였다. 그래서 방 상서가 유생을 더욱 기이하게 여겼다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 외당(外堂)', '방 상서 / 유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0009', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0084', '유생전', '劉生傳', '3인칭', '한문', '生念於心中曰: ‘尙書不忘前日吾先君之言約, 處我客室, 衣食款待, 此實感格. 然年未二十, 俱喪父母, 流離道路, 幸托此家, 遷延歲月, 豈有喜事?’', '유생은 마음속으로 ‘상서께서 전날 돌아가신 아버님과의 언약을 잊지 않으시고 나를 객실에서 거처하게 하며 의복과 음식으로 정성껏 대접해주시니 이는 정말 감격스러운 일이다. 그러나 내 나이가 아직 스물이 안 되었는데 부모를 모두 여의고 길거리에서 유리걸식하다 운 좋게 이 집에 의탁하여 세월만 보내고 있으니 어찌 기쁜 일이 있겠는가?’ 라고 생각했으니', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 외당(外堂)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0010', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0085', '유생전', '劉生傳', '3인칭', '한문', '時時思念身勢, 長嘆不已.', '때때로 자신의 신세를 생각하며 긴 탄식을 그치지 않았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 외당(外堂)', '유홍', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0011', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0086', '유생전', '劉生傳', '3인칭', '한문', '一日, 夫人窺見生, 謂尙書曰:', '하루는 방 상서의 부인이 유생을 엿보고 방 상서에게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서 /방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0012', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0087', '유생전', '劉生傳', '3인칭', '한문', '“尙書不忘前日劉相公之所約, 收生處室, 以待至極, 可謂有信. 然妾暫視劉生之容貌, 多有汚闊之氣像. 他日立身後, 必有矯人之態, 夫養虎遺患, 尙書奈何? 且劉生早年喪親, 隻身無依, 尙書全守微約, 完心不回. 若以蘭蕙之弱質, 配玆駔儈之下村, 則孤鸞, 不勝木鷄之伴, 丹鳳, 何忍烏鵲之隨? 願尙書, 以鳳以凰, 以鴦以鴌, 以永遂奔奔, 同此于飛, 妾雖今死, 何恨之有?”', '“상서께서 전날에 유상공과 약속하신 것을 잊지 않으셔서 유생을 거두어들여 객실에 거처하도록 하고 지극히 대접하고 계시니 신의가 있다고 이를만합니다. 그러나 제가 유생의 용모를 얼핏 보았는데 아주 우활한 기상을 지녔습니다. 훗날 출세하고 난 뒤에 반드시 남을 속일 상이니 무릇 ‘호랑이를 길러 근심을 남긴다.’고 하는 것을 상서께서는 어떻게 생각하십니까? 또 유생은 이른 나이에 부모를 여의고 홀몸으로 의탁할 곳이 없는데 상서께서는 사소한 약속을 온전히 지키려고 마음을 굳게 하여 바꾸지 않으십니다. 만일 난초와 혜초의 연약한 기질을 지닌 사람더러 낮고 천한 거간꾼과 짝이 되게 한다면, 외로운 난새가 나무로 된 닭의 짝이 되는 것을 감당하지 못하니 붉은 봉황이 어찌 차마 까마귀와 까치를 따르겠습니까? 바라건대 상서께서 봉황에는 봉황으로 원앙에는 원앙으로 길이 한 쌍을 이뤄주어 함께 이에 짝지어 날게 해준다면, 제가 비록 지금 죽더라도 무슨 한이 있겠습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서 /방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0013', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0088', '유생전', '劉生傳', '3인칭', '한문', '尙書曰:', '그러자 상서가 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서 /방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0014', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0089', '유생전', '劉生傳', '3인칭', '한문', '“夫人何以出此言? 劉生氣骨有非凡, 必有大人之形容, 夫人安有知人之鑑乎? 且況誠約已定, 吾豈食言者乎? 自此, 夫人更無此言.”', '“부인은 어찌하여 이런 말을 내뱉으십니까? 유생의 기개와 골격은 범상치 않은 점이 있어 분명 대인(大人)의 모습을 지녔으니 부인께서 무슨 사람을 보는 안목이 있답니까?? 더구나 진실한 약속은 이미 정해졌는데 제가 어찌 식언(食言)하는 사람이겠습니까? 이제부터는 다시는 이런 말 마십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서 /방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0015', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0090', '유생전', '劉生傳', '3인칭', '한문', '此時, 右承相達睦, 本以奸行, 得寵於皇帝, 權據朝庭, 威振四海, 臣僚百官, 莫不盡恐.', '한편 이때 우승상(右丞相) 달목(達睦)이라는 자가 본래 간사한 행동으로 황제의 총애를 받고 있었으니 권세가 조정을 차지하고 위엄이 사해에 떨쳐 신하들과 관리들 중에 두려워하지 않는 이가 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_북경(北京)', '황궁(皇宮)_조정(朝廷)', '달목', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0016', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0091', '유생전', '劉生傳', '3인칭', '한문', '聞方娘有閒幽直靜德, 故欲求婚於方尙書, 知尙書終不可聽, 假托皇命, 欲爲求婚.', '달목이 방 낭자가 조용하고 정직하며 얌전한 덕이 있다는 소문을 듣고는 방 상서에게 구혼을 하고자 했으나 방 상서가 결코 들어주지 않을 것을 알고 황제의 명령에 가탁하여 구혼을 하려 했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_북경(北京)', '황궁(皇宮)_조정(朝廷)', '순종 황제 / 달목', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0017', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0092', '유생전', '劉生傳', '3인칭', '한문', '緣由, 告訴皇帝, 皇帝然之, 乃傳敎方尙書曰:', '이러한 사연을 황제에게 아뢰자 황제가 이를 옳다 여기고 방 상서에게 다음과 같이 하교했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_북경(北京)', '황궁(皇宮)_조정(朝廷)', '순종 황제', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0018', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0093', '유생전', '劉生傳', '3인칭', '한문', '“前日, 卿之女子, 先帝欲封後宮, 未遂意而崩, 此先帝之所論女子, 不可不擇功勳之臣子, 以爲婚姻也. 故朕親切擇焉, 今右承相達睦子, 捐吉行禮. 若一毫辭讓不從, 則斬.”', '“지난번에 경의 딸은 선제(先帝)께서 후궁으로 봉하려고 하셨으나 뜻을 이루지 못하시고 세상을 떠나셨다. 방 낭자는 선제께서 언급하신 여자로 공훈이 있는 신하를 선택하여 혼인을 시키지 않을 수가 없다. 그러므로 짐이 친절히 배우자를 간택하였으니 지금 우승상 달목의 아들과 길일을 택하여 혼례를 치르라. 만일 조금이라도 사양하고 따르지 않는다면 참형을 내릴 것이다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_북경(北京) / 중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0019', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0094', '유생전', '劉生傳', '3인칭', '한문', '尙書落膽, 未知所謂, 夫人謂尙書曰:', '방 상서가 낙담하여 아뢸 바를 알리지 못하고 있었는데 부인이 상서에게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0020', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0095', '유생전', '劉生傳', '3인칭', '한문', '“尙書前日, 以家兒事, 久係皇獄, 雖免罪冤, 前萌未盡. 皇詔今亦如此, 威㥘求婚, 此猝難謀避. 雖欲全守前約, 何可得乎?”', '“상서께서는 저번에 집안 아이의 일로 오랫동안 황제의 옥사에 연루되어 있어서 비록 원죄(冤罪)를 면하였으나 이전에 싹튼 것이 아직 사라지지 않았습니다. 황제의 조서가 또한 이와 같아 구혼하라고 겁을 주고 있으니 이는 단숨에 모면하기 어렵습니다. 비록 전날의 약속을 온전히 지키고자 하지만 어찌 그럴 수 있겠습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0021', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0096', '유생전', '劉生傳', '3인칭', '한문', '尙書, 亦默默無言, 諸族亦皆曰:', '이에 방 상서가 또한 묵묵부답하니 여러 친족들 또한 이렇게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0022', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0097', '유생전', '劉生傳', '3인칭', '한문', '“劉約雖篤, 皇命奈何? 且劉生, 丐乞無依, 達生少年登第, 職至翰林學士, 富貴赫然, 門外華麗, 人皆健羨, 願皇敎以許達婚.”', '“유 승상과의 약속이 비록 돈독하더라도 황명을 어찌하겠습니까? 또한 유생은 구걸하고 다니며 의탁할 곳이 없으나, 달생(達生)은 젊은 나이에 과거에 급제해 직책이 한림학사(翰林學士)까지 이르렀으니 부귀가 성대하고 집안 주변 사람들도 화려하니 사람들이 모두 부러워하고 있습니다. 바라건대 황제의 전교에 따라 달씨 집안과의 혼인을 받아들이십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인', NULL, NULL, '내실 혹은 정청이라 규정하기 애매함', NULL, NULL, NULL),
    ('SYSJ02NU001P0023', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0098', '유생전', '劉生傳', '3인칭', '한문', '尙書尤爲憤憫, 莫知所爲.', '상서가 더욱 분통해하고 근심하면서 어찌할 바를 몰랐다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0024', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0099', '유생전', '劉生傳', '3인칭', '한문', '時皇帝又下敎曰:', '이때 황제가 또 하교하였다.', NULL, '원_순종(가상)', NULL, '중국(中國)_북경(北京)', '황궁(皇宮)_조정(朝廷)', '순종황제', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0025', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0100', '유생전', '劉生傳', '3인칭', '한문', '“聞劉生, 尙在卿家, 躊躇達婚云, 是何故也? 若不從國命, 則先斬正玉, 夷滅方族.”', '“듣자 하니 유생이 아직도 경의 집에 있어 달씨 집안과의 혼사를 망설이고 있다고 하니 무슨 연고로 그런 것인가? 만약 국명을 따르지 않는다면 먼저 유정옥을 참형에 내리고 너희 씨족을 멸할 것이다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0026', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0101', '유생전', '劉生傳', '3인칭', '한문', '皇命如此急迫, 更有何策? 尙書不得已, 斷定達婚, 夫人與諸族, 一邊大喜, 然尙書, 獨不勝憤痛.', '황제의 명이 이와 같이 급박하니 또 무슨 대책이 있겠는가? 방 상서가 어쩔 수 없이 달씨 집안과의 혼인을 결정하니 부인과 여러 친족들이 모두 크게 기뻐했으나 상서는 혼자 분통한 마음을 견디지 못하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0027', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0102', '유생전', '劉生傳', '3인칭', '한문', '且行禮之日, 不過一朔矣, 時娘子聞此言, 驚駭狂測, 入奏於父母曰:', '한편 유생과 혼례를 치를 날이 한 달밖에 남지 않았는데 이때 낭자가 그 말을 듣고 몹시 놀라고 어쩔 줄 몰라 하며 부모님에게 찾아가 말씀을 올렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0028', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0103', '유생전', '劉生傳', '3인칭', '한문', '“一女二夫, 古禮有之乎?”', '“한 여자에 두 남편인 경우가 과거의 예법에 있었습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0029', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0104', '유생전', '劉生傳', '3인칭', '한문', '尙書默默無語, 夫人責曰:', '방 상서가 묵묵부답하자 부인이 낭자를 꾸짖으며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0030', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0105', '유생전', '劉生傳', '3인칭', '한문', '“汝以閨中女子, 以待父母之處分, 如訴等事, 非汝之所關, 汝何雜談於此也?”', '“너는 규방의 여자로 부모의 처분을 기다려야 하니 하소연하는 일들은 네가 상관할 바가 아닌데 너는 어찌 여기에 쓸데없는 말을 하느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0031', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0106', '유생전', '劉生傳', '3인칭', '한문', '娘子離席再拜, 泣而對曰:', '낭자가 자리에서 일어나 재배하고 울면서 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0032', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0107', '유생전', '劉生傳', '3인칭', '한문', '“父親前與劉生公, 金石定婚, 且使少女, 行禮於前. 而劉相公, 亦賜玉指環曰: ‘以此, 終入劉氏之門.’ 少女自其以後, 知入劉氏之門, 更無他慮矣. 今聞與達家, 定婚云, 是誠是哉?”', '“부친께서는 전날 유 승상과 금석과 같은 혼약을 맺으시고 저에게 앞에서 축수의 예를 행하게 했습니다. 그러자 유 승상께서 또한 옥지환을 주시면서 ‘이것으로 마침내 유씨네 가문에 들어왔도다.’라고 말씀하셨으니 저는 그날 이후로 유씨네 집안에 들어가는 줄 알고 더 이상 다른 생각을 하지 않았습니다. 그런데 지금 달씨 집안과 정혼한다고 들었으니 이것이 정말로 사실입니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0033', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0108', '유생전', '劉生傳', '3인칭', '한문', '夫人曰:', '부인이 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0034', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0109', '유생전', '劉生傳', '3인칭', '한문', '“無他. 皇帝下敎若此若此, 勢不得已. 雖父母, 奈何奈何?”', '“다른 이유는 없다. 황제께서 이러저러하게 하교하셨으니 상황 상 어쩔 수가 없다. 비록 부모라도 정녕 어찌하겠느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0035', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0110', '유생전', '劉生傳', '3인칭', '한문', '娘子下淚伏奏曰:', '낭자가 눈물을 흘리고 엎드려 말씀을 올렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0036', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0111', '유생전', '劉生傳', '3인칭', '한문', '“若初無劉氏之定禮, 小女以閨中身, 豈可取舍於彼此哉? 所以來奏唐突者, 或恐失禮於私心, 受笑於衆人也, 今黃河, 尙未如帶, 泰山亦未如礪, 願父母勿食舊約, 更可深思焉. 小女久處閨闈, 粗通經史, 非不知忠臣不事二君, 烈女不更二夫. 小女既行禮於劉, 又婚姻於達, 則此何異於二夫乎? 夫生若爲無禮之人, 死何免無義之魂乎? 生不作恧, 死當無冤. 是以, 忠臣守義而不難其死, 烈女守節而不畏沒身, 願父母以保千金之貴體, 不求小女之殘命, 以免皇家之罪焉.”', '“만약 애초에 유씨 집안과의 혼약이 없었다면 제가 규중에 있는 몸으로서 어찌 이 사람 저 사람을 가릴 수 있겠습니까? 제가 당돌하게 와서 아뢰는 이유는 혹여 사사로운 마음에 예를 잃어 뭇사람들에게 비웃음을 받을까 두려워서입니다. 지금 황하가 아직 허리띠처럼 마르지 않고 태산이 아직 숫돌처럼 갈아 없어지지 않았으니 바라건대 부모님께서는 옛 약속을 저버리지 마시고 더욱 깊이 생각해 주십시오. 저는 오랫동안 규중에 있으면서 경서와 역사서를 대강 살펴보았는데 충신(忠臣)은 두 임금을 섬기지 않고 열녀(烈女)는 두 남편을 섬기지 않는 것을 모르지 않습니다. 제가 이미 유 승상에게 예를 행하였는데, 또 달씨 집안과 혼인을 한다면 즉 이는 두 남편을 섬기는 것과 뭐가 다르겠습니까? 대저 살아서 예가 없는 사람이 된다면, 죽어서 어찌 의리 없는 귀신이 되는 것을 면하겠습니까? 살아서 부끄러운 짓을 하지 않아야 죽어서 원통함이 없을 것입니다. 이 때문에 충신은 의를 지키고서 죽는 것을 어려워하지 않았고, 열녀는 절개를 지키고 목숨을 잃는 것을 두려워하지 않았으니 바라건대 부모께서는 천금과 같은 귀한 몸을 보존하시고 저의 하찮은 목숨을 구하지 마셔서 황실의 형벌에서 벗어나십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0037', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0112', '유생전', '劉生傳', '3인칭', '한문', '自是, 全廢食飲, 裹頭不起.', '이로부터 방 낭자는 아무것도 입에 대지 않으며 머리를 싸매고 일어나지 않았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0038', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0113', '유생전', '劉生傳', '3인칭', '한문', '父母私憫罔極, 百端開誘曰:', '방 상서 부부가 속으로 걱정하고 슬퍼하며 갖가지 방법으로 달래며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0039', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0114', '유생전', '劉生傳', '3인칭', '한문', '“汝之所言, 誠是可也, 其爲父母, 亦無此心乎? 然皇命如此, 不能任意. 汝不思父母. 固執貞禮, 稱病不起, 篤心決死, 貞禮雖大, 父母其小乎? 且夫妻本無他子, 只有汝也, 而汝若絕命, 則吾等何所望也? 汝未死前, 吾等先爲自絕, 欲不見如許事, 且爲汝不能. 汝以思父母秋毫之恩, 如何?”', '“네 말이 진실로 옳다. 부모된 입장에서 또한 그런 마음이 없겠느냐? 그렇지만 황명이 이와 같으니 마음대로 할 수가 없다. 네가 부모를 생각하지 않고 정절을 고집하느라 병을 핑계로 잃어나지 않으며 마음을 굳게 먹고 죽기를 결심하니, 정절이 아무리 크더라도 부모는 사소한 것이냐? 또 우리 부부는 본래 다른 자식이 없고 단지 너만 두었는데 네가 만약 목숨을 끊어버린다면 우리는 무엇을 바라보며 살겠느냐? 네가 죽기 전에 우리들이 먼저 목숨을 끊어서 이런 꼴을 보지 않았으면 하지만 너 때문에 그럴 수가 없다. 너는 부모의 자그마한 은혜를 생각해 보는 것이 어떻겠느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0040', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0115', '유생전', '劉生傳', '3인칭', '한문', '娘子聞此言, 掩淚更奏曰:', '방 낭자가 이 말을 듣고 눈물을 닦고 다시 말씀을 올렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0041', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0116', '유생전', '劉生傳', '3인칭', '한문', '“昔者, 楚王有一女子, 而年纔五歲, 未免孩提. 王憐愛, 坐膝上, 撫顏戲之曰: “汝若成長, 則以嫁城門外百姓之家.” 女子果成長, 則王擇駙馬, 女進曰: “女子五歲前, 坐小女於膝上, 以語小女之言, 大王忘之乎?” 王驚笑曰: “果戲耳, 豈有眞耶?” 女復進曰: “昔者, 周成王, 與叔虞, 戲曰: “以此桐圭, 封若.” 史佚請擇日, 王曰: “戲耳.” 佚曰: “天子無戲言.” 今大王, 豈與小女, 戲之也? 不可使聞於憐國也, 小女爲國家, 不取他門也.” 楚王, 不已從之云. 夫楚女五歲, 能行其言, 小女豈惜生死, 永欲失十五歲之事乎?”', '“옛날에 초왕(楚王)에게 딸이 하나 있었는데 나이가 겨우 다섯 살로 어린아이에 지나지 않았습니다. 왕이 그녀를 귀여워하고 아끼며 무릎 위에 앉히고는 얼굴을 쓰다듬으며 장난으로 이렇게 말씀하셨습니다. “네가 만약 장성한다면 성문 밖에 있는 백성의 집안에 시집보낼 것이다.” 딸이 과연 성장하여 왕이 사윗감을 선택하려는데 딸이 말했습니다. “제가 다섯 살이 되기 전에 저를 무릎 위에 앉히고서 제게 하셨던 말씀을 대왕께서는 잊으셨습니까?” 왕이 놀라고 웃으며 말했습니다. “과연 농담으로 했던 말인데 어찌 진심이 담겼겠는가?” 그러자 딸이 다시 말했습니다. “옛날에 주(周)나라 성왕(成王)은 숙우(叔虞)와 더불어 농담으로 “이 오동나무 잎으로 만든 규(珪)로 너를 봉하노라.”라고 말했습니다. 이에 사일(史佚)이 제후로 세울 날을 정하기를 청하자 성왕이 “농담일 뿐이다.”라고 말했습니다. 그러나 사일은 “천자에게는 농담하는 법이 없습니다.”라고 했습니다. 그런데 지금 대왕께서는 어찌 소녀와 농담을 한단 말입니까? 이러한 일로 이웃 나라에 알려져서는 안 되니 저는 나라를 위해서라도 감히 다른 집안에 시집가지 않겠습니다.” 초왕은 만류하지 못하고 딸의 말을 따랐습니다. 대저 초왕의 딸은 다섯 살인데도 그 말을 실천할 수 있었는데, 제가 어찌 살고 죽는 것을 아까워하여 열다섯 살의 일을 영영 저버리려 하겠습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0042', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0117', '유생전', '劉生傳', '3인칭', '한문', '尙書持敎書, 入娘子寢室曰:', '방 상서가 황제의 교서를 가지고 낭자의 침실로 들어가 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0043', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0118', '유생전', '劉生傳', '3인칭', '한문', '“皇命若此若此, 雖父母奈何奈何? 私憫罔極, 憤痛不已.”', '“황제의 명령이 이러저러하니, 비록 부모여도 정녕 어찌하겠는가? 나는 속으로 걱정하고 슬퍼하며 분통함을 그치지 못하겠다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0044', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0119', '유생전', '劉生傳', '3인칭', '한문', '娘子心中, 自決其死, 始謂父母曰:', '그러자 방 낭자는 마음속으로 죽을 것을 결심하고 부모에게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0045', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0120', '유생전', '劉生傳', '3인칭', '한문', '“父母若是其憫然, 小女貞禮, 雖不如楚女, 暫委一身, 以從父母願焉.”', '“부모님께서 이처럼 근심하시니 저의 정절은 비록 초왕의 딸과 같진 않으나, 잠시 이 한 몸 미뤄두고 부모님께서 원하시는 바를 따르도록 하겠습니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0046', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0121', '유생전', '劉生傳', '3인칭', '한문', '父母聞此言, 一邊喜樂, 一邊悲感.', '방 낭자의 부모가 이 말을 듣고 한편으로는 다행으로 여기고 한편으로는 슬퍼했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0047', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0122', '유생전', '劉生傳', '3인칭', '한문', '然娘子心中, 則決其死, 欲見劉生, 以敘生前冤懷. 以處子之身, 誠爲事禮不可, 欲爲一書, 以告達.', '그러나 낭자는 마음속으로 죽을 것을 결심하고 유생을 보고 생전의 원통한 마음을 풀고자 하였다. 하지만 처자의 몸으로 직접 찾아가는 예절은 불가했기에 한 통의 편지를 써서 그 마음을 전달하고자 하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0048', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0123', '유생전', '劉生傳', '3인칭', '한문', '謂蘭蕙曰:', '이에 방 낭자가 난혜에게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방 영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0049', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0124', '유생전', '劉生傳', '3인칭', '한문', '“汝暗去外堂, 先窺劉郎君氣色而來.”', '“너는 몰래 외당에 가서 우선 유 낭군의 기색을 살펴보고 오거라.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방 영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0050', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0125', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙既承命而出, 秘跡, 暗窺生之所爲.', '난혜가 방 낭자의 명을 받들고 나와 자취를 숨기고 유생의 행동을 몰래 엿보았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0051', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0126', '유생전', '劉生傳', '3인칭', '한문', '此時, 三更將深, 萬籟俱寂, 且金風乍起, 月色如晝.', '이때는 밤 깊은 삼경(三更)으로 주위가 온통 고요하였으며 가을바람이 문득 일어나고 달빛이 낮과 같이 환할 때였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0052', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0127', '유생전', '劉生傳', '3인칭', '한문', '生獨處空堂, 挑半殘燈, 惟詠經史, 忽東窓半開, 喟然長嘆曰:', '유생이 홀로 빈 외당에 있으면서 절반 넘게 타든 등불의 심지를 돋우며 경사를 읊조리다가 문득 동창(東窓)을 반쯤 열고 한숨을 쉬며 길게 탄식했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0053', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0128', '유생전', '劉生傳', '3인칭', '한문', '“嗟呼! 前生何等罪惡, 今世早失父母, 孑孑孤蹤, 轉寄人門? 連命度日, 所幹何事? 未知主人相公, 豈忘婚姻耶?”', '“아아! 내가 전생에 무슨 나쁜 짓들을 저질렀길래 지금 세상에서 일찍 부모님을 여의고 혈혈단신으로 남의 집에 빌붙게 되었는가? 연명하며 세월만 보내고 있으니 내가 맡아야 할 일이 무슨 일인가? 모르겠다만 또 주인 상서께서는 어찌 혼약을 잊으셨단 말인가?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0054', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0129', '유생전', '劉生傳', '3인칭', '한문', '哀嘆數聲, 方欲就枕, 蘭聽聞此言, 不勝哀嗟, 掩淚而歸以告娘子.', '이렇게 몇 마디 슬프게 탄식하고 막 침실로 가려고 할 무렵, 난혜가 이 말을 듣고는 비탄함을 가누지 못한 채 눈물을 닦고 돌아와 방 낭자에게 이러한 사정을 전달했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂) / 방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '난혜, 유생, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0055', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0130', '유생전', '劉生傳', '3인칭', '한문', '娘子聞此言, 尤爲悲感, 謂蘭蕙曰:', '방 낭자가 이 말을 듣고 더욱 비통해하며 난혜에게 일러 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0056', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0131', '유생전', '劉生傳', '3인칭', '한문', '“劉郎君不知吾家之事, 惟望婚姻之期, 如是嗟嘆. 吾心非木石, 豈無痛恨?”', '“유 낭군께서 우리 집안의 사정을 알지 못하시고 오직 혼인하는 날만 바라보면서 이처럼 탄식하고 계시는구나. 내 마음이 목석(木石)이 아닌데 어찌 애통해하지 않겠느냐”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0057', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0132', '유생전', '劉生傳', '3인칭', '한문', '卽開玉函, 出吳綾絈紅羅衫, 以噬指出血, 以書萬端懷抱, 又謂蘭蕙曰:', '그리고 곧장 옥함(玉函)을 열어 오(吳)나라 비단으로 만든 두건과 붉은 적삼을 꺼내고 손가락을 깨물어 피를 낸 다음 온갖 회포들을 쓰고 다시 난혜에게 일러 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0058', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0133', '유생전', '劉生傳', '3인칭', '한문', '“汝持此書, 卽傳劉郎君, 又受答狀而來.”', '“너는 이 편지를 가지고 유 낭군에게 곧장 전달한 다음 답장을 받아서 오거라.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0059', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0134', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙承命而去, 剝啄叩門.', '난혜가 명을 받들고 외당으로 가서 똑똑하고 문을 두드렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0060', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0135', '유생전', '劉生傳', '3인칭', '한문', '生獨坐窓前, 尙未遂眠, 聞扣門之聲, 驚而問曰:', '유생은 홀로 창 앞에 앉아 아직 잠을 이루지 못하고 있다가 문을 두드리는 소리를 듣고 놀라 물었다.', '問 : 원본에는 門', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0061', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0136', '유생전', '劉生傳', '3인칭', '한문', '“汝何爲人, 如此深夜, 奚爲來驚也?”', '“너는 누구이길래 이렇게 늦은 밤에 어찌 찾아와서 놀래키는가?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0062', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0137', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙伏奏曰:', '난혜가 엎드려 아뢰었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0063', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0138', '유생전', '劉生傳', '3인칭', '한문', '“小婢, 主人宅小娘子之侍婢, 今承娘子之命而來.”', '“저는 주인댁 낭자를 모시는 몸종으로 지금 아가씨의 명을 받들고 왔습니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0064', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0139', '유생전', '劉生傳', '3인칭', '한문', '卽出封書一張, 以跪奏進,', '그리고 곧장 봉해 놓은 편지 한 통을 꺼내어 무릎을 꿇고 공손히 전달하니,', '張 : 원본에는 改', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0065', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0140', '유생전', '劉生傳', '3인칭', '한문', '生驚該狂測, 忙手披閱.', '유생은 놀라서 어쩔 줄 몰라 하며 허겁지겁 편지를 펼쳐보았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0066', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0141', '유생전', '劉生傳', '3인칭', '한문', '其書曰:', '그 편지의 내용은 이러하다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0067', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0142', '유생전', '劉生傳', '3인칭', '한문', '“方氏榮愛, 謹再拜奉書于劉郎君案下. 妾本與郎君, 雖無奠鴈親迎之道, 亦有玉環先聘之禮. 是以, 妾唐突私書, 敢瀆請覽. 誠知閨中處子之道理不可, 此勢不得已者, 何事? 妾薄命無雙, 在世之日不遠, 故暫忘恥廉, 以記情懷, 令人敢達. 願郎君勿責無禮, 深察情勢, 使篋扇懷恩, 綈布戀德, 則雖死之日, 猶生之年. 且前日郎君之大人, 與妾之先君, 以金石定約, 以玉環先禮曰: ‘泰山若礪, 黃河如帶, 永勿失期, 更無追懷.’ 妾自是後, 思入劉門, 而願捧箕箒. 造物爲猜, 好事多魔, 不意兩家先君, 久係皇獄, 痛恨不已. 幸被神明, 無事得釋, 相歡無比. 噫! 皇天無常, 時運不幸, 郎君連遭患喪, 失所無依, 流離道路, 妾之大人, 見之救之. 不忘前期, 與處客室, 令姑度日, 妾之私幸. 惟望婚禮, 百年偕老矣, 今右丞相達睦, 假托皇命, 威㤼求婚, 妾若不從國命, 先罪郎君, 禍及父母. 又若從國命, 則以背郎君, 爲永失前期, 以此一身, 進退難得, 無數哀痛. 百以思之, 則幸得一體慮, 死外則無策. 是以, 如是敘情, 鑑察焉. 妾之一身, 若死則皇詔無奈? 郎君免禍, 妾之父母免策也. 妾亦無愧於心, 此妾一得之計料. 然妾之父母, 本無他子, 只有小妾一身, 今既死後, 誰憐妾父之母之年老, 誰收父母之白骨乎? 願郎君勿以妾沒後故, 自同外人, 憐恤妾之父母, 雖黃泉之下, 庶幾暝目也. 且妾死後, 勿謂鄙累, 郎君親自斂襲, 乞埋骨於郎君先塋, 無依孤魂, 庶有依托, 免於地下之冤魂也.”', '“방영애는 삼가 재배하고 유 낭군께 편지 올립니다. 저는 본래 낭군과 비록 전안(奠雁)하고 친영(親迎)하는 예를 행하지 못했으나 또한 옥지환으로 먼저 납폐(納幣)의 예를 갖추었습니다. 이 때문에 제가 당돌하게 사사로이 편지를 올리니 감히 외람되이 읽어봐 주시길 청합니다. 진실로 규중 처자의 도리로 안된다는 것을 알지만 지금 상황이 어쩔 수가 없으니 무슨 일이겠습니까? 첩은 운명이 기구하기가 견줄 데 없어 세상에 있을 날이 얼마 남지 않았기에 우선 염치불고하고 정회를 적고 사람을 시켜 감히 전달했습니다. 바라건대 낭군께서는 저의 무례함을 꾸짖지 마시고 깊이 사정을 살피셔서 상자 속 부채 신세로 은혜를 품게 하고 명주 솜옷 신세로 덕을 그리워하게 해주신다면 비록 죽는 날이 오히려 사는 해일 것입니다. 또 전날에 낭군의 어르신께서 저의 아버님과 금석과 같은 다짐으로 혼사를 정하시고, 옥지환로 먼저 예를 행하시며 ‘태산이 숫돌처럼 갈아 없어지고 황하가 허리띠처럼 마르게 될 때 까지 길이 약속을 잃지 않아 다시 후회하는 일이 없도록 합시다.’라고 말씀하셨습니다. 저는 이날로부터 유씨 집안에 들어가서 부녀의 도리를 받들고자 생각했습니다. 그러나 조물주께서 시기하시고 좋은 일에는 방해가 많은지라 뜻밖에 두 집안의 어르신께서 오랫동안 황제의 옥사에 연루되어 통한을 금치 못했습니다. 다행히 신명(神明)을 입어 무사히 풀려났으니 서로 기뻐하심이 비할 데가 없었습니다. 아! 그러나 하늘이 무심하시고 운수가 불행하여 낭군께서 연이어 불상사를 당해 의지할 곳을 잃은 채 길에서 떠돌아다니게 되셨는데, 저의 아버님께서 발견하시고 도와주셨습니다. 그리고 전날의 약속을 잊지 않으셔서 객실에 머물게 하여 우선 날을 보내도록 해주셨으니 제게 있어 무척 다행입니다. 오직 혼례를 치르고 백년해로하기를 바라고 있었는데 지금 우승상 달목이 황명을 가탁하여 위협하고 겁을 주며 혼인을 요구하니, 만일 제가 국명을 따르지 않는다면 먼저 낭군에게 죄를 물을 것이고 재앙이 부모에게 미칠 것입니다. 또 국명을 따른다면 낭군을 배신하고 영영 전날의 약속을 어기는 것이 되니 이 한 몸이 이러지도 저러지도 못하여 수없이 애통해했습니다. 온갖 방법으로 고민하다가 마침 한 가지 대안을 냈으니 죽는 것 말고는 방법이 없습니다. 이 때문에 이와 같이 사정을 말씀드리는 것이니 살펴봐주십시오. 저 한 몸이 만약 죽게 된다면 황제의 조서가 내려와도 어찌할 수 없고 낭군께서도 화를 면하고 저의 부모님도 황제의 책명(策命)에서 벗어나며 저 역시 마음에 부끄러움이 없을 것이니 이것이 제가 생각해 낸 한 방법입니다. 그러나 첩의 부모님께서는 본래 다른 자식이 없고 단지 저 하나만 있으니 지금 죽은 후에 누가 저의 부모님의 연로함을 불쌍하게 생각해 주겠으며 누가 부모님의 백골을 거두어주겠습니까? 바라건대 낭군께서는 제가 이미 죽은 뒤라고 해서 남들과 똑같이 여기지 않아 첩의 부모님을 불쌍히 여겨주신다면 비록 황천의 아래에서라도 눈 감을 수 있을 것입니다. 또 제가 죽은 뒤에 저를 비루하다고 여기지 마시고 낭군께서 직접 저를 염습(斂襲)하셔서 부디 낭군의 선영에 유골을 묻어준다면, 의지할 곳 없는 고혼이 의탁할 수 있어 지하의 원혼이 되는 것을 면할 것입니다.”', '斂襲 : 원본에는 斂濕', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0068', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0143', '유생전', '劉生傳', '3인칭', '한문', '生見畢, 驚慘愧閔, 不勝痛恨. 落淚長嘆, 僅答其書, 使付持去,', '유생이 편지를 다 보고는 놀라고 참담해하며 부끄러워하고 근심하며 애통함을 가누지 못했다. 눈물을 흘리고 길게 탄식하며 겨우 편지에 답장하고서는 난혜에게 부쳐서 가지고 가게 하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0069', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0144', '유생전', '劉生傳', '3인칭', '한문', '其書曰:', '그 편지의 내용은 이러하다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0070', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0145', '유생전', '劉生傳', '3인칭', '한문', '“薄命劉生正玉, 謹再拜奉答于玉娘子座下. 僕蓋前某月某日, 過窺玉娘子於後苑, 弄競秋千之狀, 歸來以後, 自然心神蕩亂, 伎癢不禁. 因遂疾病, 轉輾枕席, 遲離不起. 父母私憫, 深察情私, 果與娘子大人, 相約定婚, 欣喜無極, 感謝何勝? 其自以後, 結願少解, 窹寢思服, 苦待袵席之日矣. 噫! 皇天無助, 世道不振, 先君捐館, 老母亦辭堂. 孑孑單身, 零丁獨立, 三載風霜, 盡禮侍墓而歸, 家禍連綿, 婢僕分散, 財用空竭, 百事零替. 一身無依, 流離漂泊, 東西奔走, 娘子大人, 見而哀之, 收處客室, 衣食款待, 此不忘前日吾先君之言約. 是以, 日夜所念, 幸遇娘子, 若遂于飛, 庶報娘子之父母, 亦遂僕父母願. 故不能玉碎, 姑爲瓦全, 寄跡人門, 遷延歲月, 所望婚期. 今姑度日, 意外今夕, 伏承來使, 忙受尺素, 一喜一驚, 如對娘子. 然而看來未半, 心寒骨冷, 令人感傷. 僕三載所幹, 一朝冷落, 誰謂有志者, 事竟成也? 宿緣旣薄, 魔妖有戲, 失侶孤鴈, 飛落於何渚, 求友暮鶯, 驚散於秋風. 浮萍身勢, 落葉行色, 更歸何處? 娘子書中, 亦有絕雲, 何其過言也? 此非娘子之愆尤也. 乃是賤僕之薄福. 勿慮忘事. 保以貴體, 永奉父母, 以登達門, 萬端子孫, 百年同樂也. 且孝子, 百行之源也. 娘子知一未知二. 欲傷孝儀, 以取禮節, 誰謂娘子可也? 且娘子之父母, 更無他子, 只有娘子, 娘子不從親命, 若爲身死, 則白骨父母, 何所依託, 何處歸焉? 僕之八字奇薄, 夙遭憫凶, 俱喪父母, 辛苦歲月, 若此一身, 在世無益. 誠欲自絕, 則綿綿劉氏殘孫, 自絕無後, 不祀先塋, 此倫禮, 莫大罪焉, 必永失父母之遺言也. 此死亦未能, 生亦不敢, 可憐身勢, 罔極無托. 然而何面目, 更留此家, 以對相公? 噫! 夜色將曙, 則僕之行色, 重人所恥, 令欲乘昏退去, 不勝悲感, 躊躇難堪. 願娘子莫惜一盃酒, 使人受送, 則僕醉中暫忘憤感, 以察去向. 臨楮鳴咽, 小記萬一, 伏乞鑑之.”', '“박명한 유정옥은 삼가 재배하고 옥낭자(玉娘子)에게 답장 올립니다. 저는 이전 모월 모일에 뒤 정원에서 낭자께서 그네를 타고 노는 모습을 지나가다 엿보고, 집에 돌아온 다음 자연히 마음이 혼란스러워 간질거리는 마음을 견딜 수 없었습니다. 이에 병을 앓아 잠자리에서 엎치락뒤치락하며 마음에서 떠나지 않아 일어나지 못했습니다. 부모님께서 속으로 걱정하시고 제 심경을 깊이 살피셔서 과연 낭자의 부모님과 서로 정혼을 맺었다고 하니, 저의 기쁨이 그지없었는데 감사함을 어찌 다하겠습니까? 그 뒤로부터 결심했던 소원이 조금 풀려 자나 깨나 그리워하며 같이 지낼 날만 몹시 기다렸습니다. 아! 그러나 하늘께서 돕지 않으시고 세상의 도가 떨쳐지지 않아 아버지께서 돌아가시고 어머니께서도 세상을 떠났습니다. 혈혈단신으로 의지할 데 없이 홀로 3년 동안 풍상(風霜)을 겪으며 예를 다해 시묘살이를 마치고 돌아왔는데, 집안의 재앙이 끊이지 않아 노복들이 이리저리 흩어지고 가산이 전부 소모되어 모든 일이 허사가 되었습니다. 이 한 몸 의지할 곳 없는 채 정처 없이 헤매며 여기저기 떠돌아다니고 있었는데 낭자의 부친께서 저를 보고 불쌍히 안타까워하고는 데려다 객실에 거처하게 하고 의복과 음식으로 정성껏 대접해주셨으니, 이는 전날 제 부친과의 약속을 잊지 않으신 것입니다. 그리하여 ‘다행히 낭자를 만나서 만약 혼례를 치른다면 아마 낭자의 부모님에게 보답하고 나의 부모님의 바람도 이뤄지게 될텐데.’하고 밤낮으로 생각했습니다. 그래서 깨끗하게 죽지 못하고 겨우 심신만 보전하여 남의 집에 자취를 맡겨 세월만 보내며 혼인날만 바라보았습니다. 지금 이렇게 그냥저냥 날만 보내는데 뜻밖에 오늘 저녁 엎드려 삼가 심부름 온 시비에게서 바삐 편지를 받으니 한편으로 기쁘고 한편으로 놀라 마치 낭자를 마주하는 듯 했습니다. 그러나 반도 채 읽지 않았는데 마음이 서늘하고 뼈가 오싹하여 사람을 상심하게 합니다. 제가 3년 동안 도모하던 일이 하루아침에 무너졌으니 누가 “뜻이 있는 자는 일이 마침내 이루어진다.”라고 했습니까? 묵은 인연이 기박해졌고 마귀와 요괴가 희롱을 하고 있으니 짝 잃은 외로운 기러기는 어느 물가에 날아가 앉겠으며, 짝 찾는 저녁의 꾀꼬리는 가을바람에 놀라 흩어지게 되었습니다. 부평초 같은 신세와 낙엽과 같은 행색으로 다시 어디로 돌아가겠습니까? 낭자께서는 편지 내용에 또한 목숨을 끊겠다고 하시니 어찌하여 지나친 말씀을 하십니까? 이는 낭자의 잘못이 아니고 곧 미천한 제가 박복한 탓입니다. 혼약을 저버리는 것을 염려하지 마시고 귀한 몸을 보존하시어 길이 부모님을 모시고 달씨 가문에 시집가서 수많은 자손들과 백년해로하십시오. 또 효성스러운 자식은 모든 행동의 근원입니다. 그런데 낭자는 하나는 알고 둘은 모릅니다. 효의(孝儀)를 상하게 하여 예절을 취하려 하니 누가 낭자더러 옳다고 하겠습니까? 또 낭자의 부모님께서는 더욱이 다른 자식이 없으시고 다만 낭자만 있으니, 낭자께서 부모님의 명을 따르지 않고 만약 죽어버린다면 백골이 된 부모님께서는 어디에 의탁하며 어디로 가겠습니까? 저의 팔자가 기구하여 일찍이 우환과 변고를 만나 부모님을 모두 여의고 힘들게 세월을 보내고 있으니 이 한 몸 같은 경우는 세상에 있어봤자 도움이 안 됩니다. 그러나 진실로 스스로 목숨을 끊고자 한다면 겨우겨우 이어진 유씨가문이 저절로 끊겨 후손이 없어져 선영에 제사를 지내지 못하게 되니, 이는 인륜(人倫)에 있어 이보다 큰 죄가 없고 필시 부모님의 유언을 영원히 저버리는 것입니다. 이렇게 죽는 것 또한 할 수 없고 사는 것 또한 감당하지 못하고 있으니 가련한 제 신세가 망극하여 어쩔 줄 모르겠습니다. 그러하니 무슨 면목으로 다시 이 집에 머물며 상공을 대하겠습니까? 아 밤빛이 장차 밝아지면 저의 행색이 더욱 남에게 부끄러우니 어두울 때를 틈타 물러나고 싶지만 슬픔을 견디지 못해 주저하여 어쩌지 못하고 있습니다. 바라건대 낭자께서는 한 잔의 술을 아끼지 마시고 사람을 시켜 보내주신다면 제가 취중에 잠시라도 괴로움을 잊고서 어디로 떠날지 생각해 보겠습니다. 편지를 대하고 오열하며 수많은 저의 생각 중 일부를 조금 적었으니 바라건대 살펴봐주십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0071', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0146', '유생전', '劉生傳', '3인칭', '한문', '娘子見畢, 吞聲而泣, 玉淚成行, 雙雙流頰, 不勝哽咽, 初不能言, 須臾, 謂蘭蕙曰:', '낭자가 편지를 다 보자마자 소리 죽여 우니 옥 같은 눈물이 줄줄 흘러 두 뺨을 타고 내려갔으며, 목이 메는 것을 견디지 못해 처음에는 말을 할 수 없다가 잠시 후 난혜에게 일러 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0072', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0147', '유생전', '劉生傳', '3인칭', '한문', '“劉郎君之情勢, 若此. 人非木石, 豈無想感?”', '“유 낭군의 사정이 이와 같구나. 사람이 목석이 아닌데 어찌 생각하고 느끼는 바가 없겠느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0073', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0148', '유생전', '劉生傳', '3인칭', '한문', '卽具酒肴, 以盛壺榼, 亦解玉環一隻, 以封羅袖, 使蘭蕙傳語曰:', '곧장 술과 안주를 마련하여 병을 채우고 또한 옥지환을 한 짝을 빼내어 비단 소매에 싸서 난혜를 시켜 말을 전하게 했으니 다음과 같다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0074', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0149', '유생전', '劉生傳', '3인칭', '한문', '“酒肴雖薄, 出於情表, 指環無雙, 出於情勢. 然察於私情, 勿以重咎, 姑留外堂, 以看始末. 以憐秦涉之玉碎, 可迷金穀之花飛, 恤之哀之. 薄緣弱質, 雖未酬父母養育之恩, 亦知夫婦三從之禮, 且取義捨生, 古聖所戒. 妾以奉天霍女之心, 豈忍息國不言之婦? 噫! 郎君若不棄此情, 當合鏡於後世, 訪倩娘於來生也.”', '“술과 안주가 비록 보잘 것 없지만 정표(情表)에서 나온 것이고, 옥지환이 한 쌍이 없는 것은 부득이한 처지에서 나온 것입니다. 그러나 제 개인적인 사정을 살피셔서 너무 허물하지 마시고 우선 외당에 계셔서 일의 전말을 살펴보십시오. 진(秦)나라 진섭(陳涉)의 죽음을 불쌍히 여기는 마음이라면 금곡(金穀)의 흩날리는 꽃잎을 심취하실 수 있으실 테니 불쌍하고 애처롭게 여겨 주십시오. 운수가 사납고 체질이 연약해 비록 부모님께서 길러주신 은혜를 아직 갚을 수는 없으나, 또한 부부의 삼종(三從)의 예법을 알고 있고 또 의를 취해 목숨을 저버리는 것은 과거 성인께서 경계하신 바 입니다. 제가 천명을 받든 곽녀(霍女)의 마음을 가지고 어찌 식국(息國)의 말하지 않은 부인의 행동을 차마 하겠습니까? 아! 낭군께서 만일 이러한 정을 버리지 않으신다면 제가 응당 후세에 거울을 합하고, 내세에서 천랑(倩娘)을 찾을 것입니다.”', '秦 : 원본에는 奉, 穀 : 원본에는 谷', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_외당(外堂)', '난혜, 유정옥', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0075', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0150', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙至草堂, 以娘子之言, 一一傳奏, 以奉酒肴隻環.', '난혜가 초당(草堂)에 이르러 낭자의 말을 일일이 전해 올리고 술과 안주와 옥지환 하나를 바쳤다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0076', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0151', '유생전', '劉生傳', '3인칭', '한문', '劉生須臾長嘆曰:', '유생이 잠깐 있다가 길게 한숨 쉬며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0077', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0152', '유생전', '劉生傳', '3인칭', '한문', '“噫哉! 娘子之心也, 何其固也? 由薄福一人, 言至此極, 反爲慙愧, 更兼厚顏.”', '“아아! 낭자의 마음이 어찌 이리도 고집스러운가? 박복한 한 사람 때문에 말이 이 지경에 이르렀으니 도리어 부끄러워지고 더욱 면목이 없구나.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0078', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0153', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙酌酒進三盃, 生飲畢, 又使答謝曰:', '난혜가 술을 따라 세 잔을 올리니 유생이 다 마시자마자 또 답사(答謝)하게 하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0079', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0154', '유생전', '劉生傳', '3인칭', '한문', '“所送酒肴, 雖表三盃, 似重千金. 然娘子之言, 何其薄倖也? 娘子棄父母而先死, 三千之罪, 莫大焉, 娘子胡爲小節, 欲絕大義, 於心安乎? 更勿心慮, 善自珍重. 多罪正玉, 今爲退去, 然而彼百歲後, 如此情意, 庶敘地下爲望. 伏願娘子, 勿謂心慮, 百年無疆. 僕從此永決, 後期來生, 言止此矣. 伏乞察焉.”', '“보내주신 술과 안주는 비록 석 잔으로 표했지만 마치 천금처럼 귀중합니다. 그러나 낭자의 말은 어찌 이리도 매정하답니까? 낭자께서 부모를 버리고 먼저 죽는다면 삼천 가지 죄 중에 이보다 큰 것이 없으니 낭자께선 어찌 작은 절개를 위해 대의(大義)를 저버리려고 해야만 마음에 편하시겠습니까? 다시는 걱정하지 마시고 스스로 몸을 잘 보존하십시오. 죄 많은 저 정옥은 지금 물러가지만 저 100년 후에 이와 같은 마음을 지하에서 펴지기를 기대합니다. 삼가 바라건대 낭자께서는 염려스럽다는 말 마시고 만수무강하십시오. 저는 이로부터 영영 이별하고 이후 다음 생을 기약할 것이니 말을 이만 마치겠습니다. 삼가 살펴주십시오”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0080', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0155', '유생전', '劉生傳', '3인칭', '한문', '又書一札, 以給蘭蕙曰:', '편지 한 장을 써서 난혜에게 주며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0081', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0156', '유생전', '劉生傳', '3인칭', '한문', '“此書以奉相公.”', '“이 편지는 상공께 바치도록 해라.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_ 초당(草堂)', '난혜, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0082', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0157', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙聞此言, 不勝悲痛, 掩淚以歸, 以劉生之言, 仔細告達.', '난혜가 이 말을 듣고 비통함을 가누지 못하고 눈물을 닦으며 돌아가 유생의 말을 낭자에게 자세히 전달했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '난혜, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0083', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0158', '유생전', '劉生傳', '3인칭', '한문', '娘子聞此言, 默無言, 血淚流行, 沾濕羅衫.', '낭자가 이 말을 듣고 묵묵히 말이 없다가 피눈물을 흘려 나삼(羅衫)을 적셨다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '난혜, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0084', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0159', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙以劉生之言, 獻奉尙書, 尙書亦深恨.', '난혜가 유생의 말대로 방 상서에게 편지를 전하니 방 상서 또한 매우 한스럽게 여겼다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '난혜, 방상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0085', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0160', '유생전', '劉生傳', '3인칭', '한문', '其書曰:', '그 편지의 내용은 이러하다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '난혜, 방상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0086', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0161', '유생전', '劉生傳', '3인칭', '한문', '“門下罪人劉正玉, 謹再拜奉書于座下, 生夙遭憫凶, 早喪父母, 東西丏乞, 流離行道. 尙書大人, 見而收之, 使困鳥, 托一枝之安, 俾枯魚, 籍斗水之活, 僅得保身, 安過餘日. 淺慮, 尙書以無依一人, 如是厚待, 此非他. 尙書應當不忘於先君之定約也, 此實感激. 生前未報之恩, 死後當爲含珠, 庶報其萬一矣, 意外今夕, 暫聞風便, 相公以達婚事, 心慮過度, 遺辱貴體, 此皆由小生之過也. 如是之後, 生更留此家, 於心誠爲否便, 於事體亦可殊常. 是以今夕姑爲退去, 後期雖爲極無常. 然今對相公尊儀, 以敘萬端之恩澤, 可以退去, 於事理當然, 反以思之, 則無面目對相公故, 姑未能下直, 私自出家. 其不美罪狀許赦!”', '“문하의 죄인 유정옥이 삼가 재배하고 상서의 좌하에 편지를 올립니다. 저는 젊은 나이에 우환과 변고를 만나 일찌감치 부모님을 여의고 이리저리 걸식하며 길거리를 떠돌아 다녔습니다. 그런데 상서 대인께서 저를 보고 거두셨으니 지친 새를 한 나뭇가지의 편안함에 깃들게 하고 다 죽어가는 물고기를 동이 물에 살도록 머물게 하는 격이라 겨우 몸을 보존할 수 있어 남은 날을 편안히 보내었습니다. 얕은 제 생각으로는 상서께서 의지할 데 없는 저를 이처럼 후하게 대접해주셨으니 이는 다른 뜻이 아닙니다. 상서께서는 분명 제 아버님과 정한 약속을 잊지 않으신 것이니 이는 정말 감격스러운 일입니다. 제가 살아서 아직 갚지 못한 은혜는 죽은 뒤에라도 마땅히 갚아야 하니 바라건대 만분의 일이라도 보답하고자 하였습니다. 그런데 뜻밖에도 오늘 저녁 소식을 잠깐 듣기로는 상공께서 달씨 가문과의 혼사 때문에 걱정이 많으셔서 귀하신 몸에 누를 끼친다고 하니 이는 모두 저의 잘못에서 비롯된 것입니다. 만일 이런 상황을 겪고도 제가 또 이 집에 머무른다면 마음에 진실로 불편하게 되며 도리상으로도 일반적이지 않습니다. 그러므로 오늘 저녁에 일단 물러나고자 하니 이후의 만남은 비록 지극히 무상합니다. 그러나 지금 상공의 모습을 직접 대하여 만단의 은택을 펼치고 물러나는 것이 일의 이치상 당연하지만. 돌이켜 생각해보니 상공을 뵐 면목이 없으므로 일단 작별인사를 드리지 않고 사사로이 집에서 떠나겠습니다. 이 불미스러운 죄상을 용서해 주십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '난혜, 방상서', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0087', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0162', '유생전', '劉生傳', '3인칭', '한문', '尙書見之, 嘆之不已.', '상서가 편지를 읽고 탄식을 그치지 못하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '난혜, 방상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0088', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0163', '유생전', '劉生傳', '3인칭', '한문', '此時, 娘子聞劉生出去, 日夜涕泣, 爲之瘦瘠. 欲爲自絕, 蘭蕙以想其隙故, 姑爲保命矣, 其間哀痛, 何以勝記?', '이때 낭자가 유생이 집을 떠난다는 소식을 듣고 밤낮으로 눈물을 흘려 수척하게 되었다. 낭자가 스스로 목숨을 끊고자 했으나 난혜가 그 틈을 염두에 두고 있었기 때문에 일단 목숨을 유지하였으니 그동안의 애통함을 어찌 이루 기록하겠는가?', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방영애의 내실(內室)', '방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0089', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0164', '유생전', '劉生傳', '3인칭', '한문', '此時, 正當行禮之日矣. 達翰林盛備威儀, 而到其所, 奴僕如雲, 風彩揚揚, 眞可謂:‘闊達大丈夫矣.’ 人皆健羨, 莫不稱贊.', '이제 바로 혼례를 치를 날이 되었다. 달 한림이 예복을 성대하게 갖추고 방씨네 집에 이르자 노복들이 구름과 같이 몰려들었으니 그 의기양양한 풍채가 참으로 활달한 대장부라 할 만했다. 사람들도 모두 부러워하면서 칭찬하지 않은 자가 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '달 한림, 방영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0090', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0165', '유생전', '劉生傳', '3인칭', '한문', '方尙書卽座於中堂, 使翰林, 先行幣帛之禮, 又使娘子亦行奠鴈之禮, 娘子裏頭全臥, 固心不起.', '방 상서가 바로 중당으로 다가가 앉아서 달 한림에게 먼저 폐백의 예를 행하게 하고 또 낭자에게 전안례를 행하게 하니, 낭자가 머리를 싸매고 완전히 드러누워 마음을 굳게 먹고 일어나지 않았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '달 한림, 방영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0091', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0166', '유생전', '劉生傳', '3인칭', '한문', '尙書夫婦, 百端開誘曰:', '그러자 상서 부부가 온갖 방법으로 낭자를 타이르며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0092', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0167', '유생전', '劉生傳', '3인칭', '한문', '“汝終不回. 則吾家生死, 皆係汝矣, 汝何爲人子, 使其父母, 至於狼狽也?”', '“네가 끝까지 마음을 고치지 않는 구나. 우리 집의 생사가 모두 너에게 달렸으니 너는 어찌 자식으로서 부모를 낭패한 상황에 이르게 하느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0093', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0168', '유생전', '劉生傳', '3인칭', '한문', '娘子不得已, 而掩淚而起, 使侍婢若干粧飾, 又侍婢十餘輩, 僅出中堂, 行臨禮席.', '낭자가 어쩔 수 없이 눈물을 닦고 일어나 시비를 시켜 조금 단장하여 꾸민 다음 또 다른 시비 십여 명과 함께 겨우 중당으로 나와서 예석(禮席)에 이르렀다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0094', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0169', '유생전', '劉生傳', '3인칭', '한문', '其娘子哀痛形容, 仿佛秋月嚬光於雨雲之間, 恰似冬栢掩色於雪裏之老松.', '낭자의 애통해하는 모습은 가을 달이 비구름 사이에서 모습을 찌푸리는 듯하고, 동백나무가 눈 덮인 늙은 소나무 사이에서 빛깔을 감추는 듯했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0095', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0170', '유생전', '劉生傳', '3인칭', '한문', '娘子始禮畢, 夫人戒曰:', '낭자가 예를 마치자마자 부인이 훈계하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0096', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0171', '유생전', '劉生傳', '3인칭', '한문', '“汝勿悲既往之事, 當入彼門, 奉長上以道, 事翰林以禮, 待婢僕以恩. 擇言發, 非禮勿行, 以盡夫婦之樂, 於吾夫妻之心, 此一大慶事, 此言信勿頃忘.”', '“너는 지나간 일을 슬퍼하지 말고 응당 저 달씨 가문에 들어가서 웃어른을 도로써 모시고 남편을 예로써 섬기며 노복들을 은혜로써 대하거라. 말을 가려서 내뱉고 예가 맞지 않는 행동은 하지 말아서 부부의 즐거움을 다한다면 우리 부부의 바람에 있어 이는 일대의 경사이니 이 말을 명심해서 잠시도 잊어서는 아니된다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0097', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0172', '유생전', '劉生傳', '3인칭', '한문', '娘子嗚呼不能言, 以喉間殘聲, 僅奏曰:', '낭자는 탄복하느라 말을 제대로 하지 못하고 목구멍 사이의 자그마한 소리로 겨우 아뢰었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0098', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0173', '유생전', '劉生傳', '3인칭', '한문', '“父母萬世珍重.”', '“부모님께서는 만수무강하십시오.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0099', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0174', '유생전', '劉生傳', '3인칭', '한문', '如是一言而已, 嘿嘿無他言.', '이처럼 한 마디 말을 남길 뿐 묵묵히 다른 말은 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '방 영애, 방상서, 방상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0100', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0175', '유생전', '劉生傳', '3인칭', '한문', '尙書令娘子, 催促入轎, 娘子勢不得已, 纔入轎中, 達翰林欲閉轎門之際, 娘子使蘭蕙, 命閉之, 翰林無聊而退, 顏色赧然.', '방 상서가 낭자에게 가마를 타라고 재촉하자 낭자가 하는 수 없이 가마 안에 들어갔는데 달 한림이 가마 문을 닫으려고 할 때 낭자가 난혜를 시켜 닫으라고 명하니 한림이 당황해하며 물러나 얼굴빛이 붉어졌다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '달 한림, 방영애, 방상서, 방상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0101', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0176', '유생전', '劉生傳', '3인칭', '한문', '尙書把翰林之手曰:', '방 상서가 한림의 손을 잡으며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '달 한림, 방영애, 방상서, 방상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0102', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0177', '유생전', '劉生傳', '3인칭', '한문', '“迷劣女兒, 未達事禮, 如是輕操不泯, 重過許赦焉.”', '“못난 내 딸아이가 섬기는 예에 밝지 못하여 이처럼 경솔한 행동을 씻어내지 못했으니 중대한 과오를 용서해 주게나.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_중당(中堂)', '달 한림, 방영애, 방상서, 방상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0103', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0178', '유생전', '劉生傳', '3인칭', '한문', '翰林使娘子玉轎前行, 而翰林則遂後倍去, 各色風流, 左右侍衛, 令人健羨. 行路見者, 莫不稱贊.', '한림이 낭자가 탄 옥가마를 앞에 가게 하고 자신은 즉시 그 뒤로 잇달아 갔으니 가지각색 풍류와 좌우에서 시위하는 모습이 사람들을 몹시 부러워하게 만들었다. 길에서 그 광경을 보는 자들 중에 칭찬하지 않은 이가 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '달 한림, 방영애, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0104', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0179', '유생전', '劉生傳', '3인칭', '한문', '是時, 達承相聞方娘子來, 大會一家諸族, 設宴於中堂, 凡鋪陳之物, 飲饌之味, 不可勝言.', '이때 달 승상이 방 낭자가 온다는 소식을 듣고 일가친척들을 전부 불러모아 중당에서 잔치를 베풀었으니, 무릇 진열된 물건과 맛난 술과 안주는 이루 다 말할 수 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_중당', '달 승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0105', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0180', '유생전', '劉生傳', '3인칭', '한문', '娘子乘所玉轎, 直至堂下,', '낭자가 탄 옥가마가 바로 당하(堂下)에 도착하니', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0106', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0181', '유생전', '劉生傳', '3인칭', '한문', '承相夫人, 與諸親戚大喜而出, 爭先聚觀.', '달 승상 부인이 여러 친척들과 몹시 기뻐하며 나와 앞다투어 모여 그 모습을 보았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0107', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0182', '유생전', '劉生傳', '3인칭', '한문', '侍婢以開轎門, 娘子忽以羅巾, 擁其項而自縊.', '그런데 시비가 가마 문을 열자 낭자가 비단 수건으로 목을 맨 채 죽어있었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0108', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0183', '유생전', '劉生傳', '3인칭', '한문', '左右驚駭叵測, 承相夫人, 亦罔極罔極曰:', '주위 사람들이 모두 놀라 어쩔 줄 몰라 하고 달 승상 부인 또한 몹시 망극해하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0109', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0184', '유생전', '劉生傳', '3인칭', '한문', '“噫! 是何事也?”', '“아! 이게 어찌된 일인가?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0110', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0185', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙亦抱屍痛哭, 絕而復甦, 呼天叩地而哭曰:', '난혜 또한 낭자의 시신을 안고 통곡하며 기절했다가 다시 정신을 차리고는 하늘을 향해 울부짖으며 땅을 치고 울면서 말하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0111', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0186', '유생전', '劉生傳', '3인칭', '한문', '“噫! 娘子娘子! 是何事? 是何事?”', '“아! 아가씨! 아가씨! 이것이 무슨 일이랍니까? 이것이 무슨 일이랍니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0112', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0187', '유생전', '劉生傳', '3인칭', '한문', '達門一家諸族, 一邊無聊, 一邊悲感.', '달씨의 모든 가족들이 한편으로는 당황해하고 또 한편으로는 슬퍼하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택_당하', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0113', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0188', '유생전', '劉生傳', '3인칭', '한문', '蘭蕙卽發喪痛哭, 其慘懆情狀, 不忍可見.', '난혜가 즉시 상을 치르며 통곡했으니 그 참담한 정황은 차마 볼 수가 없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택', '달 한림 ,방영애 ,난해, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0114', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0189', '유생전', '劉生傳', '3인칭', '한문', '承相謂翰林曰:', '달 승상이 달 한림에게 일러 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택', '달승상, 달 한림', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0115', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0190', '유생전', '劉生傳', '3인칭', '한문', '“此方娘子自絕, 實非爲吾家死. 乃爲劉生而死, 其貞節雖篤, 情狀不忍. 當初若知如此之事, 何以強婚? 此皆是老夫之過也, 後悔何及? 然而娘子之屍體, 豈留吾家哉?”', '“이 방 낭자가 자결한 것은 실로 우리 집안을 위해 죽은 것이 아니다. 곧 유생을 위해서 죽은 것이니 그 정절은 비록 돈독하지만 그 정황은 차마 못 볼 일이다. 애당초 이러한 일이 일어날 줄 알았더라면 어찌 억지로 혼사를 치렀겠는가? 이는 모두 나의 잘못이나 후회해도 무슨 소용이겠느냐? 그러나 낭자의 시체를 어찌 우리 집에 두겠느냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택', '달승상, 달 한림', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0116', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0191', '유생전', '劉生傳', '3인칭', '한문', '乃以素轎, 回程送之, 道路觀者, 莫不嗟嘆曰:', '이윽고 낭자를 흰색 가마에 싣고 돌려보내니 길에서 이를 본 사람들이 모두 탄식하며 이렇게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택', '달승상, 달 한림, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0117', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0192', '유생전', '劉生傳', '3인칭', '한문', '“娘子之貞節也! 此古今無所, 然, 噫! 去時風流, 來時哭聲, 其爲父母者之心事, 幾斷肝腸也.”', '“낭자의 정절이여! 이는 옛날에도 지금에도 없었다. 그러나 아! 떠나갈 때는 풍치가 있었으나 돌아올 때는 곡소리 들리니, 그 부모된 사람의 마음은 거의 애간장이 끊어졌을 것이다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '달 승상의 저택', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0118', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0193', '유생전', '劉生傳', '3인칭', '한문', '此時, 尙書夫婦, 送娘子之後, 一室如空, 不可情狀, 忽聞哭聲哀怨而來. 夫人謂尙書曰:', '이때 상서 부부는 낭자를 떠나보낸 뒤로 온 집이 텅 빈 듯하였고 꼴이 말이 아니었는데 갑자기 애원하는 곡소리가 들려왔다. 그러자 부인이 상서에게 일러 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0119', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0194', '유생전', '劉生傳', '3인칭', '한문', '“彼哭聲者, 何許哭聲? 若是哀痛, 送感愁人也? 怪哉. 其哭漸漸可近是, 何故也.”', '“저 곡소리는 무슨 곡소리길래 이처럼 애통하여 전해오는 느낌이 사람을 근심 들게 한답니까? 괴이합니다. 저 곡소리가 점점 여기에 가까워지고 있으니 무슨 연고입니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0120', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0195', '유생전', '劉生傳', '3인칭', '한문', '心神紛亂, 悚然聽之, 俄而當於門前, 果蘭蕙也.', '상서 부부가 심란한 정신에 두려워하며 곡소리를 듣자 이윽고 문 앞까지 소리가 들려왔는데 과연 난혜였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_대문(大門)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0121', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0196', '유생전', '劉生傳', '3인칭', '한문', '尙書夫婦, 驚駭罔極, 顚倒出門曰:', '상서 부부가 깜짝 놀라고 망극해하며 허둥지둥 문밖으로 나가 난혜에게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_대문(大門)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0122', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0197', '유생전', '劉生傳', '3인칭', '한문', '“素轎何事, 發喪奚爲?”', '“흰색 가마는 어떻게 된 일이며, 발상(發喪)한 것은 무엇 때문이냐?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_대문(大門)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0123', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0198', '유생전', '劉生傳', '3인칭', '한문', '尙書夫妻, 抱娘子之屍, 呼天叩地, 大聲痛哭, 天愁地恨, 不忍情狀.', '상서 부부가 낭자의 시신을 끌어안고는 하늘을 향해 울부짖고 땅을 치며 대성통곡하니 하늘이 슬퍼하고 땅도 근심할 정도로 차마 볼 수 없는 상황이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_대문(大門)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0124', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0199', '유생전', '劉生傳', '3인칭', '한문', '夫人乃自絕者三, 親戚奴僕共救之, 雖得珍精, 其家哀慘, 何以勝記?', '상서 부인이 곧 3번이나 기절했는데 친척과 노복들이 모두 부인을 간호한 덕에 비록 귀한 목숨을 보전했으니 그 집안의 참담함을 어찌 다 기록할 수 있겠는가?', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)_방 상서 부인의 내실(內室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0125', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0200', '유생전', '劉生傳', '3인칭', '한문', '尙書亦不勝哀痛, 撫屍而泣曰:', '방 상서 또한 애통함을 가누지 못하고 낭자의 시신을 어루만진 채 울면서 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0126', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0201', '유생전', '劉生傳', '3인칭', '한문', '“噫! 夫禮不可廢, 故今日送汝之後, 終日心神亂迷, 不能定情, 待望歸寧之日矣. 今當如此之情狀, 白首吾等, 何所望也? 當初若知始終如此, 吾等, 難死於皇命, 豈爲達婚也? 吾本無他子, 只有汝一介, 而如汝千金之重也者, 得其汝之如配匹, 以奉吾家之先祀, 以收吾地下之白骨矣. 今汝已矣, 何所望也?”', '“아! 대저 예는 없앨 수가 없으니 오늘 너를 보낸 후로 종일토록 마음이 혼란스러워 진정하지 못하고 네가 친정에 방문할 날만 기다리고 있었다. 그런데 지금 이러한 일을 당하였으니 백발이 된 우리 부부가 바랄 게 뭐가 있겠는가? 애초에 사정의 전말이 이와 같을 줄을 알았다면 우리 부부가 황명에 죽는 것을 난처해 한들 어찌 달씨 집안과 혼사를 치렀겠느냐? 나는 본래 다른 자식이 없고 단지 너 하나만을 두었는데 너를 천금만큼 소중히 여겼던 것은 네가 배필을 얻어 우리 집안의 선사(先祀)를 받들고 지하로 갈 우리 부부의 백골을 거두어 줄 것 같아서였다. 그런데 지금 네가 이미 명을 다했으니 무엇을 바라겠는가?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0127', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0202', '유생전', '劉生傳', '3인칭', '한문', '如是之言, 不可勝記. 然顯晦殊道, 不可久留娘子之屍. 故俱棺槨斂襲之際, 娘子懷中, 忽有一封書.', '이러한 말들을 다 기록할 수 없었다. 그러나 이승과 저승의 길이 달라 낭자의 시신을 오랫동안 내버려 둘 수 없었다. 그러므로 관을 마련하고 염습을 하려고 하던 참에 낭자의 품속에 문득 편지 하나가 있었다.', '斂襲 : 원본에는 欽濕', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0128', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0203', '유생전', '劉生傳', '3인칭', '한문', '卽開見, 其書曰:', '곧장 편지를 펼쳐 보니 그 내용은 다음과 같다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0129', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0204', '유생전', '劉生傳', '3인칭', '한문', '“不孝榮愛, 謹再拜謝罪, 于父母堂下. 小女久處閨中, 粗通詩書, 非不知父母難酬之澤, 亦少察夫婦昌隨之義. 是以, 又小女與劉郎, 雖無奠鴈之道, 亦有納幣之禮, 小女心中, 終不忘也. 噫! 今以權門之所迫, 永失劉氏之定約, 此小女一身, 如維谷羝羊, 進退難堪. 是以, 一身死外無策. 若死後, 則父母主, 無妨皇禍, 而亦莫失劉相公, 黃河泰山之約. 小女無奈失禮, 而亦免罪玉指環先受之道, 小女何忍彎鳳之姿, 寧配於烏鵲之惡, 亦以蒲柳之弱質, 豈合馹儈之材也? 夫生而辱者, 不如死而榮. 由是, 不取瓦全於狂風, 惟知玉碎之夜月. 雖云赤子之入井, 豈是飛蛾之撲燈也? 乃己之自取. 然而情雖篤於夫妻, 恩敢忘於父母乎? 況此小女與劉郎, 元無私眤之情, 而亦無結縭之事, 豈有身死之貞哉? 劉相公之定約, 尙在耳邊, 相公之指環, 亦在衣帶. 思其言, 則不忍背之, 見其環, 則不棄之. 勢出於不得已之中, 義出於不得已之中, 願父母, 赦罪察焉. 噫! 薄命此身, 無孝之罪, 死不洗焉, 守貞之道, 死當布焉. 願父母百歲之後, 小女庶報萬一之澤於地下, 以小女沒故, 不爲哀痛, 保體珍重. 然而小女身體, 以召劉郎君, 親爲斂襲, 亦埋劉相公墓下, 庶雪今生之冤恨, 庶冤地下之孤魂也, 今以此一封書, 永訣父母, 悠然棄世, 罔極罔極. 心神昏迷, 不能盡記.”', '“불효녀 영애가 삼가 부모님 당하(堂下)에서 두 번 절하고 사죄드립니다. 제가 오랫동안 규방 안에 거처하면서 거칠게나마 시서(詩書)를 알아서 부모님께 보답하기 어려운 은택을 모르지 않고, 또한 부창부수(夫唱婦隨)의 의리도 조금 압니다. 그러므로 또 소녀가 유 낭군과 비록 전안(奠鴈)의 예를 행하지는 않았으나 또한 납폐(納幣)의 예는 지냈으니, 소녀의 마음속에 끝내 잊히지 않습니다. 아! 지금 권세 있는 가문이 핍박하고 있는 바 영원히 유씨 집안과 정한 혼약을 저버리게 되었으니 이 소녀 한 몸이 마치 유곡(維谷)의 숫양의 뿔이 울타리에 걸린 마냥 꼼짝없이 이러지도 저러지도 못하고 있습니다. 이 때문에 이 한 몸이 죽는 것 말고는 다른 방법이 없었습니다. 만약 제가 죽게 된다면 부모님께서는 황제의 재앙과 무관하게 되고 또한 유 상공께서 황하와 태산을 두고 한 약속을 저버리지 않게 될 것입니다. 소녀는 어쩔 수 없이 예를 잃었으나 또한 옥지환을 먼저 받은 도리에 대한 죄는 면할 것이니 소녀가 어찌 차마 난새와 봉황의 자질로 어찌 까마귀와 까치의 짝이 된다는 싫은 소리를 듣겠으며, 또한 부들과 버들의 연약한 기질로 어찌 거간꾼과 같은 인물의 짝이 되겠습니까? 대저 살아서 욕되는 것이 죽어서 영예로워짐만 못합니다. 이런 까닭에 거센 바람에 멀쩡한 기와를 취하지 않고, 달이 비추는 밤에 부서지는 옥이 귀한 줄 알 뿐입니다. 비록 ‘어린아이가 우물로 기어가는 것이다.’라고 말할 수 있겠으나, 어찌 이것이 나방이 등불을 향해 뛰어드는 격이겠습니까? 이는 곧 제가 자초한 일입니다. 그러나 비록 부부 사이에 정이 두텁다고 하지만 어찌 감히 부모의 은혜를 잊는답니까? 더구나 이 소녀는 낭군과 원래 사사로이 눈길을 주고받는 정도 없었고 또한 혼례를 올린 일도 없었으니 어찌 목숨을 바쳐야 할 정절이 있겠습니까? 그렇지만 유상공과 정한 약속이 아직도 귓가에 맴돌고 있고 유 승상께서 주신 옥지환이 아직 의대(衣帶)에 걸려 있습니다. 그때의 말을 생각하면 차마 배반할 수가 없었고 그 옥지환을 보면 버릴 수가 없었습니다. 사정이 어쩔 수 없는 가운데 나왔고 의리도 마지못한 가운데 나왔으니 바라건대 부모께서는 죄를 용서하시고 살펴주십시오. 아! 박명한 이 몸이 효도하지 못한 죄는 죽어도 씻지 못하겠지만 정절을 지킨 도리는 죽어야 응당 펴질 것입니다. 바라건대 부모님께서 세상을 떠나신 뒤에 제가 지하에서 만분의 일의 은택이나마 갚고자 하니 제가 죽은 것 때문에 애통해하지 마시고 귀한 몸을 보중하십시오. 그렇지만 저의 시신을 유 낭군을 불러서 친히 염습해 주시고 또한 유 상공의 무덤 아래에 묻어주신다면, 지금 살아있는 자들의 원한을 씻어주고 지하의 고혼이 가졌을 원한을 풀어 줄 것입니다. 지금 이 편지 한 통으로 영영 부모님과 이별하고 훌쩍 세상을 떠나게 되었으니 망극하고 망극합니다. 마음이 혼미하여 다 기록하지 못하겠습니다.”', '榮 : 원본에는 熒, 以小女沒故 : 원본에는 勿以小女沒故, 斂襲 : 원본에는 斂濕', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0130', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0205', '유생전', '劉生傳', '3인칭', '한문', '尙書夫人一家親戚老少奴僕, 聞此言, 尤爲絕痛, 哭聲震動.', '상서와 상서 부인, 일가친척 및 모든 노복들이 이 말을 듣고 더욱 애통해하니 통곡하는 소리가 진동했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0131', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0206', '유생전', '劉生傳', '3인칭', '한문', '然娘子書中, 以召劉郎君, 斂襲一身, 劉生既已出去後, 未知去處. 不得已而尙書夫人, 親爲斂襲, 衣以華服, 飾以寶釵, 又以金銀玉帛, 盡置柩中曰:', '그러나 낭자의 편지 내용에 유생을 불러서 시신을 염습해 달라고 되어있었지만 유생이 이미 집을 나간 이후라서 그가 떠난 곳을 알지 못했다. 그래서 어쩔 수 없이 상서 부인이 친히 염습하여 화려한 의복을 입히고 값진 비녀로 장식을 하고 또 금은옥백(金銀玉帛)을 모두 관 속에 놓고 말했다.', '斂襲 : 원본에는 欽濕, 斂襲 : 원본에는 欽濕', '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0132', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0207', '유생전', '劉生傳', '3인칭', '한문', '“此物, 皆由汝以備矣, 今汝已矣, 用之何處? 汝魂魄, 愛而用之.”', '“이 물건들은 모두 너 때문에 준비해 두었는데 지금 네가 이미 세상을 떠났으니 어디에다 쓰겠느냐? 네 혼백이라도 이를 아껴 사용하거라.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0133', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0208', '유생전', '劉生傳', '3인칭', '한문', '無數痛哭矣.', '상서 부부는 수 없이 통곡했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0134', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0209', '유생전', '劉生傳', '3인칭', '한문', '又如娘子之遺言, 欲葬劉相公墓下, 卽行喪而去.', '그리고 낭자의 유언대로 유 승상의 무덤 아래에 장사를 지내고자 하여 즉시 주검을 나르고 집을 떠났다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '방 상서(方尙書)의 저택(巨室)', '방 상서, 방 상서 부인, 난혜', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0135', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0210', '유생전', '劉生傳', '3인칭', '한문', '此時, 國朝大亂, 高郵張氏兵起, 三吳大亂, 盜賊處處蜂起, 道路阻塞.', '이때 나라에 크게 난리가 났으니 고우(高郵) 지역에서 장사성(張士誠)이 군대를 일으켜 삼오(三吳) 지역이 크게 어지러워져 도적이 곳곳에서 벌떼처럼 일어나 길이 막혔다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_강소성(江蘇省)_양주시(揚州市)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0136', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0211', '유생전', '劉生傳', '3인칭', '한문', '尙書行喪, 未能及劉相公墓下, 乃權厝於開元寺靑蓮山下, 乃避亂逃亡.', '그래서 방 상서가 나르는 상여가 유 승상의 무덤 아래까지 미칠 수 없었으므로 곧 개원사(開原寺)가 있는 청련산(靑蓮山) 아래에 임시로 장사지내고 난을 피해 달아났다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', NULL, '방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0137', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0212', '유생전', '劉生傳', '3인칭', '한문', '却說, 此時, 劉生出自方向書之家後, 顧無依托之處, 結一間草堂幕, 於父母墓, 乞食居生, 此間苦行, 不可勝言.', '각설, 이 무렵 유생은 방 상서의 집에서 나온 뒤로 둘러보아도 의탁할 곳이 없어 부모의 무덤 근처에 여막(廬幕) 한 칸을 짓고 걸식하며 지냈으니 요사이 고생한 일은 이루 말할 수 없다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0138', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0213', '유생전', '劉生傳', '3인칭', '한문', '一夕, 心神昏迷, 欲眠而未乃暝目, 忽然哀怨哭聲, 初遠漸近, 果當於墓.', '어느 날 저녁 정신이 혼미해 잠에 들려고 했지만 도리어 눈을 감지 못하고 있었는데, 홀연히 슬프게 원망하는 곡소리가 처음에는 멀리서 들리다가 점차 가까워져 과연 무덤까지 이르렀다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0139', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0214', '유생전', '劉生傳', '3인칭', '한문', '劉生異之, 忽起看之, 則有一處子玉娘, 以綠衣紅裳. 再拜於生, 喟然長嘆. 玉顔花腮, 斑斑血淚, 沾濕成行.', '유생이 이를 이상하게 여기고 급하게 일어나 살펴보니 옥같이 아름다운 어떤 처녀가 녹의홍상(綠衣紅裳) 차림으로 유생에게 재배하고 한숨지으며 길게 탄식하였다. 그러자 옥 같은 얼굴과 꽃 같은 뺨에 아롱아롱 피눈물이 줄줄 흘러내렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0140', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0215', '유생전', '劉生傳', '3인칭', '한문', '生疑而問曰:', '유생이 의아해하며 그녀에게 물었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0141', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0216', '유생전', '劉生傳', '3인칭', '한문', '“娘子以如何處子之身, 誠欲何焉, 如此深山窮谷? 哀痛如此, 是何故也?”', '“아가씨께서는 어찌 처자의 몸으로 무엇을 하려고 하십니까? 이와 같은 깊은 산골짜기에서 이처럼 애통해하는 것은 무슨 까닭이십니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0142', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0217', '유생전', '劉生傳', '3인칭', '한문', '其娘子答曰:', '그 아가씨가 대답했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0143', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0218', '유생전', '劉生傳', '3인칭', '한문', '“嗟呼! 郎君其間爰爲忘之耶? 俗說, 丈夫虛浪云耳, 果然也.”', '“아아! 낭군께서는 그새 저를 잊으셨습니까? 세간의 말에 ‘대장부는 허랑(虛浪)하다.’고 하더니 과연 그러합니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0144', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0219', '유생전', '劉生傳', '3인칭', '한문', '生答曰:', '유생이 대답했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0145', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0220', '유생전', '劉生傳', '3인칭', '한문', '“僕早喪父母, 鰥居此山, 乞食度日. 本與娘子, 元無誠約, 愚昧平生, 娘子何謂虛浪雲也?”', '“저는 일찍 부모를 여의고 이 산에 홀아비로 거주하면서 걸식하며 날을 보내고 있습니다. 본디 아가씨와 애초부터 특별한 약속도 없고 평소에 우매하게 지내는데 아가씨께선 어째서 실속이 없다고 말씀하십니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0146', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0221', '유생전', '劉生傳', '3인칭', '한문', '其娘子泣曰:', '그 낭자가 울면서 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0147', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0222', '유생전', '劉生傳', '3인칭', '한문', '“噫嘻! 悲哉! 妾身年未二十, 俱別父母, 先歸黃壤. 以妾之心, 推思郎君之心, 則同是一般. 故欲侍方尙書榮愛爲劉郎君, 自絕消息矣. 郎君全忘無言, 今此退去.”', '“아아! 슬픕니다! 저의 몸은 나이 스물이 되기 전에 부모와 모두 사별하고 먼저 저승으로 돌아갔습니다. 저의 마음으로 낭군의 마음을 미루어 짐작해 보건대 전부 똑같았습니다. 그래서 방 상서의 딸 영애가 유 낭군을 위해 자결한 소식을 아뢰고자 하였습니다. 그런데 낭군께서는 모두 잊어버리고 아무런 말씀이 없으시니 지금 이렇게 물러납니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0148', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0223', '유생전', '劉生傳', '3인칭', '한문', '以玉手, 幸拭落淚, 忽見一隻指環尙, 在手中.', '그녀가 본인도 모르게 고운 손으로 흐르는 눈물을 닦았는데 문득 한 짝의 옥지환이 여전히 손가락에 끼워져 있었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0149', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0224', '유생전', '劉生傳', '3인칭', '한문', '生始知方娘子魂靈, 驚喜驚喜, 欲把娘子之手, 以敘情懷矣, 其娘子, 忽無去處.', '유생이 그제서야 그녀가 방 낭자의 혼령임을 알아차리고는 무척 놀라고 기뻐하며 방 낭자의 손을 붙잡고서 마음 속 회포를 풀고자 했는데 방 낭자가 홀연 흔적도 없이 사라져버렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 방 영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0150', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0225', '유생전', '劉生傳', '3인칭', '한문', '生如失千金, 後悔莫及, 心神罔極, 情意悲悵, 庶未免如狂之人矣.', '유생이 마치 천금을 잃은 것처럼 후회막급하여 망극한 마음에 몹시 서글퍼하니 거의 미치광이와 다름없었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0151', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0226', '유생전', '劉生傳', '3인칭', '한문', '精神僅得珍重, 默默思之曰:', '마음이 겨우 진정되자 묵묵히 이렇게 생각했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0152', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0227', '유생전', '劉生傳', '3인칭', '한문', '‘怪哉! 眞耶? 夢耶? 頃刻之事也. 方娘子若與達家, 則豈有如此之事也? 應當自絕可也. 噫! 可憐孤魂, 不忘情意, 尋吾而來也, 吾何忘矣? 不使孤魂, 豈可撫慰而送之?’', '‘괴이하구나! 이는 현실인가? 꿈인가? 순식간의 일이로다. 방 낭자가 만약 달씨 집안에 시집을 들었다면 어찌 이러한 일이 생겼겠는가? 분명 낭자가 자결한 것이 맞겠구나. 아! 불쌍한 고혼(孤魂)이 교분을 잊지 않고 나를 찾아 왔으니 내 어찌 있겠는가? 고혼을 어찌 달래지 않고 돌려보낼 수 있겠는가?', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0153', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0228', '유생전', '劉生傳', '3인칭', '한문', '哀歎不已.', '유생은 슬픔을 그치지 못하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0154', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0229', '유생전', '劉生傳', '3인칭', '한문', '既已, 東方漸曙, 生欲聞方氏之消息, 乃下山入村閭.', '이윽고 동쪽에서 점점 날이 밝아지자 유생은 방 낭자의 소식을 듣고자 하여 곧장 산을 내려가 시골 마을로 들어갔다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0155', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0230', '유생전', '劉生傳', '3인칭', '한문', '時避亂者, 相與謂曰:', '이즈음 피난 온 사람들이 서로 이렇게 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0156', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0231', '유생전', '劉生傳', '3인칭', '한문', '“方尙書之女, 與達翰林, 婚姻而爲新行矣. 其中路娘子自絕, 其貞節古今所稀.”', '“방 상서의 딸은 달 한림과 혼례를 올리고 신행(新行)을 하게 되었습니다. 그런데 도중에 방 낭자가 스스로 목숨을 끊었으니 그 정절은 옛날과 지금에 찾아보기 힘든 일입니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0157', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0232', '유생전', '劉生傳', '3인칭', '한문', '稱贊不已, 相與嗟嘆.', '사람들이 칭찬하기를 그치지 않았으며 서로 탄식하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0158', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0233', '유생전', '劉生傳', '3인칭', '한문', '生聞此言, 問於其人曰:', '유생이 이 말을 듣고 그 사람들에게 물어보았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0159', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0234', '유생전', '劉生傳', '3인칭', '한문', '“方娘子自絕, 果何日也?”', '“방 낭자가 자결한 것이 과연 언제입니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0160', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0235', '유생전', '劉生傳', '3인칭', '한문', '其人等答曰: ‘某月某日也’云云,', '그러자 그 사람들이 ‘모월(某月) 모일(某日)입니다.’라고 대답했으니', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0161', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0236', '유생전', '劉生傳', '3인칭', '한문', '生以考其日, 果得見孤魂之日矣.', '유생이 그 날짜를 헤아려 보았는데 아니나 다를까 그 고혼을 만났던 날이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '길거리(街路)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0162', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0237', '유생전', '劉生傳', '3인칭', '한문', '生不勝哀痛, 卽歸山幕, 焚香祝之曰:', '유생이 애통함을 가누지 못해 곧장 산막(山幕)으로 돌아가 향을 피우고 축원했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0163', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0238', '유생전', '劉生傳', '3인칭', '한문', '“噫! 僕本與娘子, 元無繾眷之情. 小有先君微杳之約, 守節死義, 可謂有信, 皆是僕之過也. 娘子何忍棄父母, 而若是? 生前, 無路報娘子之澤也, 願爲娘子, 僕亦守節, 而終身不娶, 以報娘子之德也.”', '“아! 저는 본디 낭자와 더불어 원래 부부의 정이 없었습니다. 그러나 조금이나마 아버님의 자그마한 약속이 있어서 낭자께서 정절을 지키고 의를 위해 죽었으니, 신의가 있다고 할 만하지만 모두 저의 잘못입니다. 낭자께서는 어찌 차마 부모님을 저버리고 이와 같은 일을 저질렀습니까? 제가 살아있는 동안에는 낭자의 은택을 보답할 길이 없으니 바라건대 낭자를 위해 저 또한 정절을 지켜 죽을 때까지 장가들지 않고 낭자의 덕에 보답하겠습니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0164', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0239', '유생전', '劉生傳', '3인칭', '한문', '無數痛哭.', '이렇게 수없이 통곡하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0165', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0240', '유생전', '劉生傳', '3인칭', '한문', '時, 月色在西, 風光飄蕩, 終夜不寢, 徘徊松下, 散步長嘆矣.', '이때 달빛은 서쪽에서 빛나고 경치는 흐드러졌으니 유생은 밤늦게까지 잠들지 못하고 소나무 아래를 배회하고 서성이며 길게 탄식했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_송하(松下)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0166', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0241', '유생전', '劉生傳', '3인칭', '한문', '忽然黑雲, 自北方而來, 直至承相墓下, 須臾, 風吹雲散, 四面寂然矣.', '어느덧 검은 구름이 북쪽으로부터 다가와 유 승상의 무덤 아래까지 곧장 이르더니 잠깐 사이에 바람이 불어 구름이 흩어지고 주변이 고요해졌다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0167', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0242', '유생전', '劉生傳', '3인칭', '한문', '忽有靑童, 來拜於生前, 生亦答拜曰:', '홀연히 푸른 옷을 입은 어떤 동자가 다가와 유생 앞에서 절을 하니 유생도 답배(答拜)하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_송하(松下)', '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0168', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0243', '유생전', '劉生傳', '3인칭', '한문', '“仙童奚爲, 而來臨累處? 惶恐感謝.”', '“선동(仙童)께서는 어찌하여 누추한 곳까지 찾아오셨습니까? 황공하고 감사합니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_송하(松下)', '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0169', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0244', '유생전', '劉生傳', '3인칭', '한문', '童子曰:', '동자가 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_송하(松下)', '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0170', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0245', '유생전', '劉生傳', '3인칭', '한문', '“郎君是何言也? 吾先君欲見郎君, 有所言. 故今遣小童, 如是請奉邀, 願郎君從焉.”', '“낭군께서는 이게 무슨 말씀이십니까? 저의 선군께서는 낭군을 뵙고서 할 말이 있다고 하십니다. 그래서 지금 저를 보내셔서 이처럼 낭군을 초대하셨으니 낭군께서는 저를 따라오시기 바랍니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_송하(松下)', '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0171', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0246', '유생전', '劉生傳', '3인칭', '한문', '生奇之, 以從其童子而去, 至一處,', '유생이 이를 기이하게 여기고 그 동자를 따라가 어느 한 장소에 이르렀으니,', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', NULL, '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0172', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0247', '유생전', '劉生傳', '3인칭', '한문', '有五色彩雲, 片片相飛, 奇異臭, 觸鼻射心, 可謂仙境.', '그곳에는 다섯 빛깔의 고운 구름이 조각조각 떠다니며 기이한 냄새가 코를 찌르고 마음을 끌리게 하니 선경(仙境)이라 할 만하였다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', NULL, '유정옥, 선동(仙童)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0173', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0248', '유생전', '劉生傳', '3인칭', '한문', '其中有珊瑚橋儀, 其上亦有一紅袍仙官, 手執周易, 焚香默坐,', '그 중에는 산호(珊瑚)로 된 다리가 있고 그 위에는 또한 붉은 옷을 입은 한 선관(仙官)이 손에는 『주역(周易)』을 지니고서 향을 피우며 가만히 앉아 있다가', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '산호교(珊瑚橋)', '유정옥, 선관(仙官)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0174', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0249', '유생전', '劉生傳', '3인칭', '한문', '見劉生之來, 急下橋儀, 把生之手曰:', '유생이 오는 것을 보고 급히 다리에서 내려와 유생의 손을 잡으며 말했다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', NULL, '유정옥, 선관(仙官)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0175', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0250', '유생전', '劉生傳', '3인칭', '한문', '“老夫所以奉邀至此者, 君侍墓誠孝. 上帝察焉, 使君身顯名達, 受福無疆. 又上帝奇方娘子節行, 命後土夫人, 使方娘子, 還生人間, 與君同樂, 以未盡續之緣, 子孫萬端, 皆使身達也. 且太乙仙君白奏玉皇, 使玉府仙曹嚴先生, 命爲朱太公三子, 以登大位, 平定天下. 使君爲明顯將相, 以食君祿, 立身揚名, 爲天下第一功臣. 以後則勿爲慮, 以待天時.”', '“제가 초빙하여 여기로 모신 것은 당신께서 시묘살이를 하며 지극정성으로 효도했기 때문입니다. 상제께서 이를 살피시고 그대가 명성을 떨치도록 하여 끝없는 복을 받도록 할 것입니다. 또 상제께서 방 낭자의 절행을 기특하게 여기셔서 후토부인(後土夫人)에게 명하여 방 낭자를 이승에 돌려보내, 그대와 함께 즐기게 하여 속세에서 미처 다하지 못한 인연을 잇게 하고 자손 대대로 모두 현달하게 하실 것입니다. 또 태을선군(太乙仙君)께서 옥황상제께 아뢰어 옥부(玉府)의 선관인 엄군평(嚴君平)으로 하여금 주태공(朱太公)의 셋째 아들이 황제의 자리에 올라 천하를 평정하게 명할 것입니다. 그리고 그대를 아주 명성 높은 장상(將相)이 되게 할 것이니 군주의 녹봉을 먹어 입신양명해서 천하제일의 공신(功臣)이 될 것입니다. 그러니 그대는 이제 걱정하지 마시고 하늘의 때를 기다리소서.”', '曹 : 원본에는 遭', '원_순종(가상)', '비현실계', '선계(仙界)', NULL, '유정옥, 선관(仙官)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0176', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0251', '유생전', '劉生傳', '3인칭', '한문', '生聞此言, 驚喜謝賀, 更無所見, 身上, 只有承相墓,', '유생이 이 말을 듣고 놀라고 기뻐하며 사례하려 하자 그는 다시는 보이지 않았고 자신 주변에 단지 유 승상의 무덤만 있었으니', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_유홍의 묘', '유정옥,', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0177', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0252', '유생전', '劉生傳', '3인칭', '한문', '悠然入幕, 百端思之曰:', '터덜터덜 산막에 들어가서 여러 가지 생각을 하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥,', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0178', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0253', '유생전', '劉生傳', '3인칭', '한문', '‘此非眞非夢, 是何故也? 此必虛事, 豈有此事耶?’', '‘이는 생시도 아니고 꿈도 아니니 이게 무슨 까닭인가? 이는 분명 허황된 일인데 어찌 이러한 일이 있겠는가?’', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥,', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0179', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0254', '유생전', '劉生傳', '3인칭', '한문', '然而身韻昏迷, 就枕, 舊日所使奴僕, 忽然驅馬, 而來拜曰:', '그러고서는 몸과 정신이 혼미해 잠자리에 들려고 하자 옛날에 부리던 노복이 문득 말을 타고 와 절을 하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 유정옥의 노복', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0180', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0255', '유생전', '劉生傳', '3인칭', '한문', '“承相招來, 郎君去耳.”', '“유 승상께서 부르시니 낭군께서는 가셔야 합니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥, 유정옥의 노복', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0181', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0256', '유생전', '劉生傳', '3인칭', '한문', '生聞言大喜, 卽乘其馬而去, 有一處.', '유생이 그 말을 듣고 매우 기뻐하며 곧장 말을 타고 떠나 어떤 곳에 이르렀다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0182', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0257', '유생전', '劉生傳', '3인칭', '한문', '見有大宮殿, 左右庭前, 花草方發, 香氣浮動. 且有鳳鶴雙雙飛去, 芙蓉池上, 玉窓錦帛, 玲瓏相暎, 晶簾玉鉤, 霧中出沒. 若非玄圃梵宇, 應是月宮氷殿.', '살펴보니 그곳에는 커다란 궁전이 있었으며 좌우의 뜰 앞에는 꽃과 풀이 막 피어 향기가 진동하고 있었다. 또 봉황과 학이 짝을 지어 날아다니며 부용(芙蓉)이 있는 못 위에 옥창과 비단이 영롱하게 서로 비추었으며 수정렴(水晶簾)과 옥갈고리가 안개 속에서 나타났다가 사라졌다가 했다. 이는 마치 현포(玄圃)에 있는 도관이나 사찰들이 아니면 응당 월궁(月宮)에 있는 빙전(氷殿)과 같았다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0183', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0258', '유생전', '劉生傳', '3인칭', '한문', '下馬而入, 已侍十餘輩, 靑衣童子五六人, 出迎門外.', '말에서 내려 그 안에 들어가니 이미 시중드는 사람 10여 인과 청의동자 5‧6명이 문밖으로 나와서 맞이했다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0184', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0259', '유생전', '劉生傳', '3인칭', '한문', '生攝衣而入, 度重門, 及華堂,', '유생이 옷섶을 잡고 들어가서 중문(重門)을 넘고 화당(華堂)에 이르러', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 중문(重門) / 대궁전(大宮殿)_ 화당(華堂)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0185', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0260', '유생전', '劉生傳', '3인칭', '한문', '見堂上, 果承相夫妻, 偃然端坐.', '화당 위를 바라보니 과연 유 승상부부가 편안한 모습으로 단정히 앉아 있었다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 화당(華堂)', '유승상 부부, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0186', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0261', '유생전', '劉生傳', '3인칭', '한문', '生卽上堂再拜, 半喜半悲, 淚流成行, 嗚咽不能言.', '유생이 곧장 마루에 올라가 재배하니 한편으로 기쁘고 한편으로 슬퍼서 눈물을 줄줄 흘리며 오열하고 제대로 말을 하지 못했다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 화당(華堂)', '유승상 부부, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0187', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0262', '유생전', '劉生傳', '3인칭', '한문', '承相夫人, 亦不勝悲感, 把生之手, 喟然長嘆曰:', '승상 부인 또한 슬픔을 가누지 못하며 유생의 손을 잡고서 위연(喟然)히 길게 탄식하며 말했다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 화당(華堂)', '유승상 부부, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0188', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0263', '유생전', '劉生傳', '3인칭', '한문', '“噫! 吾夫妻, 人命無常, 天年俱終, 汝幸得保殘命, 至極孝誠, 晝夜哀痛, 上帝感動, 使汝再見吾等. 又使方娘子, 令行大禮, 汝必有立身之日. 爲心慮. 以待好機.”', '“아! 우리 부부는 사람의 운명이 무상(無常)하여 천수(天壽)가 모두 다했지만, 너는 다행히 남은 목숨을 보존해 지극정성으로 효도하고 밤낮으로 애통해했으니 상제께서 감동하여 너를 우리와 다시 만나게 하셨다. 또 방 낭자와 지금 대례(大禮)를 행하게 하셨으니 너는 반드시 입신하는 날이 있을 것이다. 너는 이를 염두에 두고 좋은 때를 기다리도록 하여라.”', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 화당(華堂)', '유승상 부부, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0189', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0264', '유생전', '劉生傳', '3인칭', '한문', '卽設宴中堂, 鋪陳之飲饌, 塵世所無, 左右錦帳繡屏等物, 不可勝記.', '즉시 중당에서 잔치를 베풀었으니 진열된 술과 안주는 속세에서는 없는 것들이었으며 좌우의 비단으로 된 휘장과 수놓은 병풍 등의 물건들은 이루 기록할 수 없었다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 중당(中堂)', '유승상 부부, 유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0190', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0265', '유생전', '劉生傳', '3인칭', '한문', '須臾, 玉女十餘人, 與一娘子, 擁衛而出, 行禮於生前, 生見之, 則果前山幕所時方娘子也.', '잠시 뒤 옥녀(玉女) 십여 인이 한 아가씨를 부축해 호위하여 나와 유생 앞에서 예를 행하였는데, 유생이 보니 과연 예전에 산막에서 보았던 방 낭자였다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 중당(中堂)', '유승상 부부, 유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0191', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0266', '유생전', '劉生傳', '3인칭', '한문', '生大喜, 相與禮畢後, 入寢房, 一邊大喜, 一邊悲感, 不覺沾濕.', '유생이 매우 기뻐하여 서로 혼례를 마친 다음 침실로 들어가니 몹시 기쁜가하면 비통하기도 하여 자기도 모르게 눈물을 적셨다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 중당(中堂)', '유승상 부부, 유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SYSJ02NU001P0192', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0267', '유생전', '劉生傳', '3인칭', '한문', '娘子亦長嘆數聲, 相與語, 心款若平生.', '방 낭자 또한 여러 번 길게 탄식하고 서로 이야기를 나누었는데 그 곡진한 마음이 생전과 다름없었다.', NULL, '원_순종(가상)', '비현실계', '선계(仙界)', '대궁전(大宮殿)_ 중당(中堂)', '유승상 부부, 유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0193', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0268', '유생전', '劉生傳', '3인칭', '한문', '村鷄三聲, 覺來, 果夢也.', '마을의 닭이 세 번 울어 깨어나 보니 과연 꿈이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0194', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0269', '유생전', '劉生傳', '3인칭', '한문', '生異之, 念之曰:', '유생이 그것을 이상하게 여기고 생각하기를', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0195', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0270', '유생전', '劉生傳', '3인칭', '한문', '‘吾日夜哀痛, 父母魂靈感動, 如此見夢, 使孤蹤, 更加愁懷也.’', '‘내가 밤낮으로 애통해하니 부모님의 혼령이 감격하여 이처럼 꿈에 나타나셨으니 고독한 나에게 더욱 근심스러운 마음만 더하게 하는구나.’라하고', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0196', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0271', '유생전', '劉生傳', '3인칭', '한문', '不勝悲咽, 出聲墓下, 大聲痛哭矣.', '슬픔과 울음을 이기지 못하여 무덤 아래에서 부르짖으며 대성통곡했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0197', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0272', '유생전', '劉生傳', '3인칭', '한문', '其再明日夜, 方娘子乘玉轎而來, 拜禮生前, 把手落淚曰:', '또 다음날 밤에 방 낭자가 옥가마를 타고 와서 유생 앞에 절을 한 다음 그의 손을 잡고 눈물을 떨구며 말했다.', '玉轎 : 원본에는 玉橋', '원_순종(가상)', '비현실계', '꿈', '꿈', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0198', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0273', '유생전', '劉生傳', '3인칭', '한문', '“妾薄命無雙, 俱別父母, 早歸黃泉, 無依孤魂, 空結冤恨. 明天感動, 使郎君父母, 行禮於地下, 令郎君, 更續世緣, 相逢既迫. 郎君何其無心空送歲月也? 郎君欲見妾, 訪開元寺靑蓮山而來.”', '“저는 박명하기가 비할 데 없고 부모와 모두 이별하여 일찌감치 저승으로 왔으니, 의지할 데 없는 이 고혼은 부질없이 원한만 맺혔습니다. 그러나 밝으신 하늘께서 감동하셔서 낭군의 부모님으로 하여금 지하에서 예를 치르게 하고 낭군으로 하여금 다시 속세의 인연을 맺게 하시니 서로 만날 날이 임박해졌습니다. 낭군께서는 어째서 그리도 무심하게 부질없이 세월을 보내고 계십니까? 낭군께서 저를 만나고자 하신다면 청련산에 있는 개원사로 찾아오십시오.”', NULL, '원_순종(가상)', '비현실계', '꿈', '꿈', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0199', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0274', '유생전', '劉生傳', '3인칭', '한문', '生大喜, 欲問其曲折之際, 身自擾動而覺, 乃一夢也.', '유생이 크게 기뻐하면서 그 자세한 내용을 물으려고 할 즈음에 몸이 자연히 어지러워졌으며 깨어보니 곧 한바탕 꿈이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0200', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0275', '유생전', '劉生傳', '3인칭', '한문', '生思之曰:', '유생이 그 꿈에 대해 이렇게 생각했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0201', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0276', '유생전', '劉生傳', '3인칭', '한문', '‘怪哉奇哉. 吾在山而後, 再次異夢連見, 今夜又爲善夢, 雖爲許事, 當訪靑蓮, 詢問可也.’', '‘이상하고 신기하구나. 내가 산에서 지낸 뒤로 거듭 이상한 꿈을 연달아 꾸었고, 오늘 밤에 또 좋은 꿈을 꾸었으니 비록 꿈같은 일이지만 마땅히 청련산을 찾아가 물어보는 편이 좋겠다.’', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)', '산골짜기(山谷)_여막(廬幕)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0202', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0277', '유생전', '劉生傳', '3인칭', '한문', '卽下山, 訪靑蓮山開元寺而去, 果大刹.', '이에 곧장 산을 내려가 청련산의 개원사를 찾아가 보니 과연 큰 절이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0203', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0278', '유생전', '劉生傳', '3인칭', '한문', '有一老僧, 見劉生而再拜曰:', '거기에 있는 한 노승이 유생을 보고는 재배하며 말하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0204', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0279', '유생전', '劉生傳', '3인칭', '한문', '“郎君, 何許人斯, 來此深山窮谷, 何能躊躇? 何其事也?”', '“낭군께서는 어떤 분이시길래 이렇게 깊은 산골짜기에 와서 어떻게 왔다 갔다 할 수 있습니까? 또 어쩐 일이십니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0205', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0280', '유생전', '劉生傳', '3인칭', '한문', '生亦拜對答曰:', '유생 역시 절하고 대답하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0206', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0281', '유생전', '劉生傳', '3인칭', '한문', '“小生, 本微賤之寒士, 無依乞食而行也. 然暫聞‘方尙書宅小娘子權厝處, 或在此山’云, 詳未審酌室, 願老禪師, 以爲指揮, 如何?”', '“소생은 본래 보잘 것 없는 한사(寒士)로 의지할 곳 없이 걸식하며 떠돌아다니고 있습니다. 그러나 얼핏 듣기로는 ‘방 상서 댁의 어린 따님이 묻힌 장소가 아마 이 산에 있을 것이다.’고 하는데, 사실은 그 자세하게는 아직 무덤에 대해 알지 못하니 바라건대 선사(禪師)께서 알려 주시면 어떻겠습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0207', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0282', '유생전', '劉生傳', '3인칭', '한문', '其老僧曰:', '그 노승이 말하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0208', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0283', '유생전', '劉生傳', '3인칭', '한문', '“吾長於斯, 遊於斯久矣, 未聞有方娘子之權厝於此也. 然而郎君, 與方娘子, 其間何許也?”', '“제가 여기에서 자라고 여기에서 지낸 지가 오래되었는데 방 낭자가 이곳에 묻혔다는 말은 듣지 못하였습니다. 그런데 낭군께서는 낭자와 더불어 어떤 사이입니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0209', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0284', '유생전', '劉生傳', '3인칭', '한문', '生更再拜, 詳言娘子守節死之事,', '유생이 다시 재배하고 낭자가 절개를 지키다가 죽은 일을 자세히 말하니', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0210', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0285', '유생전', '劉生傳', '3인칭', '한문', '其老僧, 嗟嘆良久曰:', '그 노승이 오랫동안 탄식하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0211', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0286', '유생전', '劉生傳', '3인칭', '한문', '“果若此, 郎君之情意, 實是可憐. 吾何隱匿也?”', '“과연 그러하다면 낭군의 교분은 정말로 가련합니다. 제가 어찌 묻힌 곳을 숨기겠습니까?”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0212', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0287', '유생전', '劉生傳', '3인칭', '한문', '卽指娘子權厝之處, 生再拜謝賀,', '곧장 방 낭자가 묻힌 곳을 알려주자 유생이 재배하며 감사의 인사를 올리고', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '개원사(開原寺)', '유정옥, 노승', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0213', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0288', '유생전', '劉生傳', '3인칭', '한문', '乃越嶺尋穀, 至其處.', '곧 계곡을 넘고 고개를 지나 알려준 장소에 도착했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0214', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0289', '유생전', '劉生傳', '3인칭', '한문', '四面峰巒疊疊, 左右樹木撐天, 不辨人間, 靑猿哀嘯, 谷鳥悲啼.', '사방으로 산봉우리가 겹겹이 이어져 있고 좌우에는 나무들이 하늘까지 솟아있으니 인간 세상과 분별할 수가 없었으며, 푸른 원숭이가 슬피 울고 골짜기의 새가 슬피 지저귀었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0215', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0290', '유생전', '劉生傳', '3인칭', '한문', '生盤桓周覽, 果有娘子墳墓.', '유생이 배회하며 두루 둘러보니 과연 낭자의 무덤이 있었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0216', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0291', '유생전', '劉生傳', '3인칭', '한문', '生不勝悲感, 叩墓痛哭曰:', '유생이 슬픔을 가누지 못해 무덤을 두드리고 통곡하며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0217', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0292', '유생전', '劉生傳', '3인칭', '한문', '“噫! 娘子娘子! 棄人間, 離父母, 奚爲而至此, 若是其無知也? 都是正玉之罪. 娘子若無正玉, 何至此極也? 前日娘子, 於東山秋千之時, 偶然窺見之後, 未能抑情, 自然病臥, 至於死境. 大抵其時, 若可死也, 寧關於閨中之娘子? 厚被大人之深察, 與娘子先君, 全期定婚後, 至死正玉, 無爲而回蘇. 無關娘子, 守節過度, 以別千金之父母, 何化一杯之荒土也? 此生者有恨, 死者有冤, 幽明冤痛, 何處伸訴? 薄福正玉, 出自娘子之家後, 無依投托, 結幕父母之墓下, 盡夜哀痛, 僅得保命矣, 近日夢事, 再巡怪異, 又昨夜夢中, 亦來曰: ‘若欲見我, 訪開元寺靑蓮山下而來云. 故尤益驚奇, 今來到此, 果有娘子墳墓, 怳若對娘子親面. 然形影寂寞, 悲感徒增. 噫! 娘子平生, 聰明才慧, 流輩莫及. 今雖死矣, 豈混同凡人, 竟絕音響? 九原若知, 願賜一見, 敘我情懷, 何如?”', '“아! 낭자여, 낭자여! 인간 세상을 저버리고 부모님과 사별했으니 무엇 때문에 이 지경에 이르러 이처럼 지각(知覺)이 없으시답니까? 모두 이 정옥의 잘못입니다. 낭자께서 만약 저 정옥이 없었다면 어찌 이 지경에 이르렀겠습니까? 지난날 낭자께서 동쪽 산에서 그네를 타고 계셨을 때 우연히 엿본 뒤로 감정을 억누를 수 없어서 자연히 병을 앓고 누워 죽을 고비를 헤맸습니다. 아마 그때 죽었다면 어찌 규방에 계신 낭자와 인연을 맺었겠습니까? 그러나 아버님의 깊은 보살핌에 힘입어 낭자의 선군과 굳게 정혼을 한 이후로, 사경을 헤맸던 제가 특별히 한 것 없이 다시 깨어나게 되었습니다. 그런데 사건과 관련 없는 낭자께서는 정절을 지킴이 매우 지나쳐서 천금과 같은 부모님과 이별하고 어찌 이렇게 한 줌의 거친 흙이 되었답니까? 이는 살아 있는 자는 한이 있고 죽은 자는 원통함이 있는 것이니 이승과 저승의 원통함을 어느 곳에다 호소하겠습니까? 박복한 저 정옥은 낭자의 집에서 나온 뒤로 의탁하여 기댈 곳이 없어 부모님 무덤 아래에 막사를 짓고 밤낮으로 애통해하며 겨우 목숨을 보전하였는데 요사이 꿈꾼 일이 두 차례나 괴이하고 또 어젯밤 꿈속에 낭자가 찾아와서 말하기를 ‘저를 보고자 하신다면 청련산 아래의 개원사로 찾아오십시오.’ 라고 했습니다. 이에 더욱 놀랍고 몹시 기이하여 지금 여기에 와서 보니 과연 낭자의 무덤이 있어서 마치 낭자를 바로 가까이서 대하듯 황홀했습니다. 그러나 저의 모습과 그림자는 적막하고 슬픈 감정만 한갓 더해집니다. 아! 낭자께서는 평소에 총명함과 지혜로움이 주변 사람들이 미칠 바가 아니었습니다. 그러나 지금은 비록 죽게 되더라도 어찌 보통사람들과 마찬가지로 끝내 소리가 끊어지겠습니까? 지하에서 만일 지각이 있으시다면 바라건대 한 번 만나주어 저에게 정회를 풀어보는 것이 어떻겠습니까?”', '懷 : 원본에는 依', '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0218', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0293', '유생전', '劉生傳', '3인칭', '한문', '如是之言, 無數痛恨, 白日帶愁, 草木無光.', '이와 같은 말을 수없이 하며 애통해하고 한탄하니 밝은 해는 수심을 띠고 초목은 빛이 사라졌다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0219', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0294', '유생전', '劉生傳', '3인칭', '한문', '日落西原, 月生東嶺, 松風掃地, 暮煙歸嶺. 此三更將深, 萬籟俱寂.', '해가 서쪽으로 기울어가고 달이 동쪽 산에서 솟아오르니 솔바람이 땅을 쓸어버리고 저녁연기는 산마루에 걸리었다. 이때 시간은 삼경(三更)으로 깊어가고 주위는 온통 잠잠했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0220', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0295', '유생전', '劉生傳', '3인칭', '한문', '生氣力勞困, 乃依墳墓, 假寢矣, 忽然娘子與侍婢, 排一雙紅燈, 至生前, 再拜曰:', '유생이 지치고 노곤하여 곧 무덤에 기대어 잠을 청하려 했는데, 갑자기 낭자가 시비와 함께 한 쌍의 붉은 등불을 들고 유생 앞에 와서 재배하며 말하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0221', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0296', '유생전', '劉生傳', '3인칭', '한문', '“信哉. 郎君不棄私情, 如是來訪, 實是感激. 然而皇天感動, 後土有助, 更續世緣, 今旣回生, 願郎君, 忽起察焉.”', '“저의 말을 믿으십시오. 낭군께서 사사로운 정을 저버리지 않으시고 이렇게 찾아오셨으니 정말 감격스럽습니다. 그리하여 하늘께서 감동하고 후토부인께서 다시 속세의 인연을 맺게 도와주셔서 지금 이미 다시 살아났으니 바라건대 낭군께서는 빨리 일어나 봐주십시오.”', '動 : 원본에는 邊', '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0222', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0297', '유생전', '劉生傳', '3인칭', '한문', '生乃驚喜, 覺思其夢事, 詳察墳墓, 墓裂娘子回生.', '유생이 곧장 놀라 기뻐하여 잠에서 깨어나 그 꿈속 일을 생각하며 낭자의 무덤을 자세히 살펴보았는데 무덤이 갈라지더니 낭자가 다시 살아났다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0223', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0298', '유생전', '劉生傳', '3인칭', '한문', '生驚喜叵測, 嘿嘿無語, 相對流淚.', '유생이 놀라고 기뻐서 헤아리지 못하여 멍하니 아무말 못하고 낭자와 서로 마주하며 눈물을 흘렸다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0224', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0299', '유생전', '劉生傳', '3인칭', '한문', '須臾, 娘子掩淚曰:', '잠시 뒤 방 낭자가 눈물을 닦으며 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0225', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0300', '유생전', '劉生傳', '3인칭', '한문', '“小妾與郎君, 薄緣茲甚, 事多間阻, 故委身黃原, 無處伸冤矣. 上帝以爲貞節, 命後土冥司, 使小妾還生人間, 更與郎君, 以續斷後之日緣, 此事非偶然.”', '“제가 낭군과 더불어 박복한 인연이 이처럼 심하여 일에 장애가 많았기 때문에 저 자신을 저승에다 바쳤으니 원통함을 풀 데가 없었습니다. 그런데 상제께서 정절로 여기셔서 후토부인의 저승 관리에게 명하여 저를 인간 세상으로 다시 돌려보내어 다시 낭군과 함께 끊어진 훗날의 인연을 맺게 해주셨으니 이 일은 우연이 아닙니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0226', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0301', '유생전', '劉生傳', '3인칭', '한문', '生亦再拜謝賀, 盡敘平生辛苦之事, 相思娘子之情, 相與悲感矣.', '유생 또한 재배하고 사례하며 그간 몹시 고생했던 일과 방 낭자를 그리워했던 정을 모두 털어놓고 서로 같이 슬퍼하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0227', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0302', '유생전', '劉生傳', '3인칭', '한문', '娘子曰:', '방 낭자가 말했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0228', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0303', '유생전', '劉生傳', '3인칭', '한문', '“妾今既回甦, 可以歸寧父母, 應當道理也. 然達家聞回生, 則舊惡未盡, 必爲侵猜, 奏達皇帝. 禍及父母, 此生不如死也. 姑隱深山窮谷, 以待達家之權衰, 出見父母, 與君同樂可也.”', '“제가 지금 이미 다시 살아났으니 부모님을 찾아뵙는 것이 응당 도리일 것입니다. 그러나 달씨 가문에서 제가 다시 살아난 소식을 듣게 된다면, 나쁜 구습이 아직 다하지 않아서 반드시 시기하여 황제께 주달(奏達)할 것입니다. 그렇게 된다면 부모님께 화가 미칠 것이니 이는 사는 것이 죽음만 못합니다. 우선 깊은 산골짜기에 숨어서 달씨 가문의 권세가 쇠하기를 기다렸다가 나와서 부모님을 찾아뵙고 낭군과 함께 사는 것이 좋을 것입니다.”', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0229', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0304', '유생전', '劉生傳', '3인칭', '한문', '生亦深然, 卽與娘子, 俱發殉葬之物, 以財論之, 則數巨萬.', '유생 또한 매우 옳다고 여겨 곧장 낭자와 함께 부장품들을 모두 꺼내어 돈으로 따져 보니 값어치가 상당하였다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_미상_청련산(靑蓮山)', '방영애의 무덤', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0230', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0305', '유생전', '劉生傳', '3인칭', '한문', '生與娘子, 負戴厥物, 至會稽山右三峰下, 山高谷深, 幽僻濶然.', '유생이 낭자와 함께 그 부장품들을 등에 짊어지고 머리에 얹어 회계산(會稽山) 오른쪽 삼봉(三峰) 아래에 도착하니 산이 높고 골짜기가 깊어 한적하고 궁벽했다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0231', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0306', '유생전', '劉生傳', '3인칭', '한문', '有居民四五十家, 衣冠高朴, 氣質貞厚.', '거기에는 사람이 거주하는 4·50채의 집이 있었으니 사람들의 옷차림이 몹시 소박하고 인심이 참되고 두터웠다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0232', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0307', '유생전', '劉生傳', '3인칭', '한문', '卽作舍於此, 以殉葬之物, 相與賣買, 財擬王公.', '유생과 낭자는 곧바로 이곳에 집을 짓고 부장품을 매매했으니 재산이 천자와 제후에 견줄 정도가 되었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0233', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0308', '유생전', '劉生傳', '3인칭', '한문', '生與娘子, 同樂之狀, 何可勝記? 蓋鴛鴦之遊綠水, 孔雀之於赤霄, 不勝此也.', '유생이 낭자와 함께 즐기는 모습을 어찌 다 기록할 수 있으리오? 아마 원앙이 푸른 물에서 노닐고, 공작이 붉은 하늘에서 나는 모습도 이보다 낫지 않을 것이다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0234', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0309', '유생전', '劉生傳', '3인칭', '한문', '然歲月如流, 無爲而生三子一女.', '그렇게 세월은 물 흐르듯 지나 유생과 낭자는 별일 없이 아들 셋과 딸 하나를 낳았다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애, 유동영, 유동인, 유동련, 유채란(딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0235', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0310', '유생전', '劉生傳', '3인칭', '한문', '長子之名東榮, 仲子之名東仁, 三子之名東連, 一女之名彩蘭.', '첫째 아들의 이름은 동영(東榮), 둘째 아들의 이름은 동인(東仁), 막내 아들의 이름은 동련(東連)이고, 딸의 이름은 채란(彩蘭)이었다.', NULL, '원_순종(가상)', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)', '유정옥, 방영애, 유동영, 유동인, 유동련, 유채란(딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0236', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0311', '유생전', '劉生傳', '3인칭', '한문', '此時, 我太祖大明皇帝, 奮臂而起, 以滅元家, 掃除群盜,', '이때 우리 태조(太祖) 대명(大明)의 황제(皇帝)께서 팔뚝을 걷어붙이고 일어나 원나라를 멸망시키고 도적떼들을 쓸어버렸으며,', NULL, '명', '현실계', '중국(中國)_북경(北京) / 중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', NULL, '명태조', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0237', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0312', '유생전', '劉生傳', NULL, NULL, '又以方尙書, 有土豪之風, 卽除會稽太守.', '또 방 상서가 토호(土豪)의 풍모를 지녔다고 여겨 즉시 회계(會稽)의 태수(太守)로 임명하였다.', NULL, '명', NULL, '중국(中國)_북경(北京) / 중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', NULL, '명태조, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0238', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0313', '유생전', '劉生傳', '3인칭', '한문', '尙書夫妻, 以皇命, 卽到郡, 治民以道, 治吏以法, 郡中太平.', '그러자 태수 부부가 황명을 따라 바로 회계군으로 가서 도리에 맞게 백성을 다스리고 법으로써 관리들을 주재하니 고을 안이 태평해졌다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', NULL, '방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0239', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0314', '유생전', '劉生傳', '3인칭', '한문', '一日, 太守謁聖鄉校,', '하루는 태수가 향교(鄉校)에서 공자(孔子)에게 참배를 올리고', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '향교(鄉校)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0240', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0315', '유생전', '劉生傳', '3인칭', '한문', '坐起明倫堂, 請鄉中明頭才士, 以或賢才, 欲薦國朝, 果濟濟多士大會堂上.', '명륜당(明倫堂)에서 직무를 맡으면서, 고을 중에 총명한 인재를 불러들여 한 현재(賢才)를 조정에 천거하고자 하니, 과연 굉장히 많은 선비들이 당상(堂上)에 크게 모여 들였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0241', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0316', '유생전', '劉生傳', '3인칭', '한문', '其中有一士, 年可十四五, 講聲玉碎, 述才金鳴.', '그 중 나이가 14·15세 정도로 보이는 한 선비가 있었으니, 강독하는 소리가 옥이 부서지는 듯하고 글재주가 쇳소리가 울리는 듯 했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0242', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0317', '유생전', '劉生傳', '3인칭', '한문', '太守見其士, 奇之曰:', '태수가 그 선비를 보고 이상하게 여기며 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0243', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0318', '유생전', '劉生傳', '3인칭', '한문', '“君誰家子孫, 年歲幾許?”', '“그대는 어느 집안의 자손이며 나이는 어떻게 되는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0244', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0319', '유생전', '劉生傳', '3인칭', '한문', '東仁對曰:', '동인이 대답했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0245', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0320', '유생전', '劉生傳', '3인칭', '한문', '“少生之姓劉, 名東仁, 時年, 十五歲.”', '“저의 성은 유씨이고 이름은 동인이며, 올해로 열다섯입니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0246', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0321', '유생전', '劉生傳', '3인칭', '한문', '太守怪東仁之面目, 彷佛劉生, 把東仁之手, 嘿然落淚曰:', '태수가 동인의 생김새가 유생과 닮은 것을 괴이하게 생각하고 동인의 손을 잡고서 조용히 눈물을 떨구면서 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0247', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0322', '유생전', '劉生傳', '3인칭', '한문', '“君之父親, 尙在否?”', '“자네의 부친은 아직 살아 계시는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0248', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0323', '유생전', '劉生傳', '3인칭', '한문', '對曰:', '동인이 말하였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0249', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0324', '유생전', '劉生傳', '3인칭', '한문', '“然也”', '“네 그러합니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0250', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0325', '유생전', '劉生傳', '3인칭', '한문', '太守曰:', '태수가 물었다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0251', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0326', '유생전', '劉生傳', '3인칭', '한문', '“君之父親之名字, 何謂也?”', '“자네 부친의 이름이 어떻게 되는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0252', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0327', '유생전', '劉生傳', '3인칭', '한문', '東仁對曰:', '동인이 대답했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0253', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0328', '유생전', '劉生傳', '3인칭', '한문', '“生之父親之名字, 成權.”', '“저의 아버지의 성함은 성(成)자 권(權)자 입니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0254', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0329', '유생전', '劉生傳', '3인칭', '한문', '果劉生改名也. 故會之人皆曰: ‘劉成權.’ 亦欲掩跡也.', '이는 과연 유생이 개명한 것이었다. 이 때문에 회계 지역 사람들이 모두 유성권이라 불렀으니 또한 자취를 감추기 위해서였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0255', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0330', '유생전', '劉生傳', '3인칭', '한문', '太守自念於心中曰:', '태수가 혼자 마음속으로 생각했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0256', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0331', '유생전', '劉生傳', '3인칭', '한문', '‘劉正玉一自出後, 不知去處矣, 或入此許處, 誠非怪事. 然而名字相違, 是可恨也.’', '“유정옥이 저번에 한 번 집을 나간 뒤로 떠난 곳을 알지 못했는데 혹시 이 마을에 들어왔다면, 참으로 괴이한 일은 아닐 것이다. 그러나 성명이 서로 다르니 이것이 한스럽구나.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0257', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0332', '유생전', '劉生傳', '3인칭', '한문', '又問曰:', '또 동인에게 물었다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0258', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0333', '유생전', '劉生傳', '3인칭', '한문', '“君本是自先祖, 乃是此君郡之人耶?”', '“자네는 원래 선조(先祖) 때부터 이 고을의 사람이었는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0259', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0334', '유생전', '劉生傳', '3인칭', '한문', '生曰:', '동인이 대답하였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0260', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0335', '유생전', '劉生傳', '3인칭', '한문', '“小生之父親, 本以浙江之人, 元末亂中, 偶入此處也.”', '“저의 아버지께서는 본래 절강 지역 사람으로 원말(元末)의 난리 중에 우연히 이곳에 들어왔다고 하셨습니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '명륜당(明倫堂)_당상(堂上)', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0261', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0336', '유생전', '劉生傳', '3인칭', '한문', '太守使官人, 送騎馬, 請劉生,', '태수가 관리를 시켜 기마(騎馬)를 보내 유생을 불러오게 하였는데,', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)', '관아', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0262', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0337', '유생전', '劉生傳', '3인칭', '한문', '此劉生入山之後, 全不知朝廷之事, 久不知會稽太守誰也. 故問於官人曰:', '유생이 산에 들어온 이후로 조정의 일을 전혀 몰랐으며 오랫동안 회계 태수가 누구인지도 알지 못했으니 관리에게 이를 물어보았다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '방 상서, 유동인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0263', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0338', '유생전', '劉生傳', '3인칭', '한문', '“今太守之姓名, 誰也?”', '“지금 태수의 성함이 어떻게 됩니까?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '유생, 관인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0264', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0339', '유생전', '劉生傳', '3인칭', '한문', '其官人答曰:', '그 관리가 대답했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '유생, 관인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0265', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0340', '유생전', '劉生傳', '3인칭', '한문', '“小人本以賤人, 雖未知其太守之名字, 人皆曰:‘方尙書’也.”', '“저는 본래 미천한 사람으로 태수님의 성함은 알지 못합니다만 사람들이 모두 방 상서라고 부릅니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '유생, 관인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0266', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0341', '유생전', '劉生傳', '3인칭', '한문', '生聞此言, 自念心中曰:', '유생이 이 말을 듣고 스스로 마음속으로 생각했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '유생, 관인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0267', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0342', '유생전', '劉生傳', '3인칭', '한문', '‘此應當娘子之大人也.’', '‘이는 분명 방 낭자의 부친일 것이다.’', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집', '유생, 관인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0268', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0343', '유생전', '劉生傳', '3인칭', '한문', '入內室, 謂娘子曰:', '유생이 방으로 들어와서 방 낭자에게 말하였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집_내실(內室)', '유생, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0269', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0344', '유생전', '劉生傳', '3인칭', '한문', '“今會稽太守, 乃方尙書云云, 朝廷更無他方向書, 此應當娘子之大人也. 且太守, 又使人來請, 是亦可殊常.”', '“지금 회계 태수가 곧 방 상서라고 불리는데, 조정에 다른 방 상서라는 분은 따로 계시지 않으니 이 분이 분명 당신의 부친일 것입니다. 더군다나 태수께서 사람을 보내와서 부탁하고 계시니 이것 또한 수상합니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집_내실(內室)', '유생, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0270', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0345', '유생전', '劉生傳', '3인칭', '한문', '卽乘來馬, 到官中,', '곧바로 유생이 말을 타고 관청 안에 도착하자', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0271', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0346', '유생전', '劉生傳', '3인칭', '한문', '太守下見, 乃劉生, 顚倒堂下, 把劉生之手, 不勝悲感, 爲之痛哭曰:', '태수가 내려다보고 유생임을 알아채고는 허둥지둥 마루 아래로 내려가 유생의 손을 잡고 슬픔을 가누지 못하고 통곡하며 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0272', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0347', '유생전', '劉生傳', '3인칭', '한문', '“生者, 必有更見, 死者, 何其無情?”', '“살아있는 자는 반드시 다시 만난다지만, 죽은 자는 어찌 이리도 무정한가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0273', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0348', '유생전', '劉生傳', '3인칭', '한문', '生亦落淚曰:', '유생 또한 눈물을 떨구며 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0274', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0349', '유생전', '劉生傳', '3인칭', '한문', '“大人, 何至於此也?”', '“대인께서는 어찌하여 이곳에 오시게 되었습니까?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0275', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0350', '유생전', '劉生傳', '3인칭', '한문', '尙書曰:', '방 상서가 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0276', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0351', '유생전', '劉生傳', '3인칭', '한문', '“老夫之女榮愛, 爲君守節而死, 君知之乎?”', '“나의 딸 영애가 자네를 위해 절개를 지키다 죽었는데 자네는 그 사실을 아는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0277', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0352', '유생전', '劉生傳', '3인칭', '한문', '生曰:', '유생이 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0278', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0353', '유생전', '劉生傳', '3인칭', '한문', '“僕一自出大人之宅後, 無依行乞矣, 偶然到此郡右三峰下, 娶良家女子. 僅得居生已, 而何知尙書之消息也? 若知此, 其貞節雖篤, 何甚於父母也? 然大人, 由小生而喪其愛女, 小生何免大人之罪人也?”', '“제가 대인의 집에서 나온 뒤로 의탁할 곳이 없어 구걸하며 다니다가 우연히 이 마을 오른쪽 삼봉(三峰) 아래에 도착하게 되어 양갓집 규수에 장가를 들었습니다. 겨우 자리를 잡고 살아갈 뿐인데 어찌 상서 댁의 소식을 알겠습니까? 만약 이러한 소식을 알았다면 방 낭자의 정절은 비록 독실하긴 하지만 어찌 부모보다 더 소중하겠습니까? 그렇지만 대인께서 저로 인해 따님을 잃으셨으니 제가 어찌 죄인을 면하겠습니까?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0279', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0354', '유생전', '劉生傳', '3인칭', '한문', '夫人亦聞劉生來, 乃撫郎子之畵像, 大聲痛哭曰:', '부인 또한 유생이 왔다는 말을 듣고는 곧 낭자의 화상(畵像)을 어루만지면서 대성통곡하며 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0280', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0355', '유생전', '劉生傳', '3인칭', '한문', '“噫! 劉生生也而更來, 榮愛奚爲而無響也?”', '“아! 유생은 살아서 다시 돌아왔는데 우리 영애는 어찌하여 소식이 없는가?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0281', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0356', '유생전', '劉生傳', '3인칭', '한문', '終日哀痛, 不勝悲感矣.', '날이 다하도록 애통해하며 비통함을 가누지 못했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '유생, 방 상서, 방 상서 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0282', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0357', '유생전', '劉生傳', '3인칭', '한문', '此時, 生暗使人, 以傳所聞所言, 請來娘子,', '이때 유생이 몰래 사람을 시켜 상서 부부와 주고받은 말을 방 낭자에게 전하게 한 다음 그녀를 데려오라고 하니', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집_내실(內室) / 삼봉촌(三峰村)_유정옥의 집_내실(內室)', '유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0283', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0358', '유생전', '劉生傳', '3인칭', '한문', '娘子聞此言, 驚喜不勝, 卽與奴僕等, 乘彩轎而來.', '방 낭자가 이 말을 듣고 놀라움과 기쁨을 견디지 못하고 즉시 노복들과 함께 꽃가마를 타고 관아로 왔다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市)_회계산(會稽山)', '삼봉촌(三峰村)_유정옥의 집_내실(內室) / 관아', '방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0284', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0359', '유생전', '劉生傳', '3인칭', '한문', '此時, 三更將深, 生與尙書, 同寢, 大衙寂然.', '이 무렵 시간은 삼경으로 밤이 장차 깊어고 있어 유생이 상서와 함께 잠자리에 들었으니 관아가 고요했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아', '방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0285', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0360', '유생전', '劉生傳', '3인칭', '한문', '娘子與卽向內衙, 開窓入房曰:', '방 낭자가 기뻐하며 모친이 계신 곳으로 향해 창문을 열고는 방으로 들어가 말하였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0286', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0361', '유생전', '劉生傳', '3인칭', '한문', '“母親何其眠深也? 小妾榮愛來也.”', '“어머니께서는 어찌 이리도 깊이 잠드셨습니까? 저 영애가 왔습니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0287', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0362', '유생전', '劉生傳', '3인칭', '한문', '夫人急起明燭, 果有榮愛也.', '부인이 급히 일어나 불을 밝혀보니 과연 영애가 있었다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0288', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0363', '유생전', '劉生傳', '3인칭', '한문', '大驚曰:', '부인이 매우 놀라며 말하였다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0289', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0364', '유생전', '劉生傳', '3인칭', '한문', '“眞耶? 夢耶? 人耶? 鬼耶? 汝胡爲乎然也?”', '“이게 진짜인가? 꿈인가? 이는 사람인가? 귀신인가? 너는 어찌하여 그렇게 있는 것이냐?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0290', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0365', '유생전', '劉生傳', '3인칭', '한문', '夫人抱娘子之身, 轉輾大聲痛哭, 娘子亦抱夫人之身, 亦大聲痛哭.', '부인이 방 낭자의 몸을 끌어안고 돌면서 대성통곡하니 방 낭자 또한 부인의 몸을끌어 안고 대성통곡했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0291', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0366', '유생전', '劉生傳', '3인칭', '한문', '尙書自外衙, 聞哭聲, 驚駭急起, 入來內房, 爰有瑩愛也.', '방 상서가 외아(外衙)로부터 울음소리가 들려오길래 깜짝 놀라 급히 일어나서 안방으로 들어갔으니 영애가 있었다.', '爰 : 원본에는 急', '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0292', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0367', '유생전', '劉生傳', '3인칭', '한문', '尙書亦驚駭, 撫娘子之身, 痛哭曰:', '방 상서 또한 무척 놀라 방 낭자의 몸을 어루만지며 통곡하며 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0293', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0368', '유생전', '劉生傳', '3인칭', '한문', '“是何也? 是何也? 畵像生耶? 瑩愛生耶?”', '“이게 어찌된 일이냐? 이게 어찌된 일이냐? 화상(畵像)이 살아난 것이냐? 영애가 살아 있는 것이냐?”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0294', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0369', '유생전', '劉生傳', '3인칭', '한문', '其相逢以言之, 娘子具奏事理始末, 以謝不孝之罪殺身之事.', '서로 만나 이야기를 주고받았으니 방 낭자는 사리(事理)의 자초지종을 갖추어 설명드리고 불효한 죄와 자결한 일에 대해 사죄했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0295', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0370', '유생전', '劉生傳', '3인칭', '한문', '尙書夫人, 召入劉生曰:', '상서 부인이 유생을 불러들이고는 말했다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '유생, 방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0296', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0371', '유생전', '劉生傳', '3인칭', '한문', '“君何以欺若此? 然都是君之德也, 非老夫之福也.”', '“그대는 어찌하여 이와 같이 우리를 속였는가? 그러나 이는 모두 그대 덕분이지 우리 부부의 운복이 아니다.”', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '유생, 방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0297', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0372', '유생전', '劉生傳', '3인칭', '한문', '夫天定配匹, 人不可私容. 相與歡樂, 一筆難記, 一口難說, 何以勝記?', '무릇 하늘이 정한 배필은 사람이 마음대로 할 수 없는 것이다. 서로 함께 기뻐하고 즐거워한 것을 붓 하나로 다 적기 어려우며 입으로 말하기에도 어려우니 어찌 다 전할 수 있겠는가?', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)_소흥시(紹興市'')', '관아_내방(內房)', '유생, 방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0298', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0373', '유생전', '劉生傳', '3인칭', '한문', '此時, 達家諸族, 無老少皆被誅.', '한편 달씨 일가는 어른이나 아이나 할 것 없이 모조리 피살되었다.', NULL, '명', '현실계', '중국(中國)', '-', '달 한림, 달승상, 달 승상 부인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0299', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0374', '유생전', '劉生傳', '3인칭', '한문', '尙書乃棄官, 而與劉生娘子, 俱歸鄉里, 晝夜歡樂矣.', '방 상서는 곧 벼슬을 그만두고 유생과 방 낭자와 함께 모두 고향으로 돌아가 밤낮으로 즐겁게 보냈다.', NULL, '명', '현실계', '중국(中國)_절강성(浙江省)', '유홍(劉弘)의 집', '유생, 방 상서, 방 상서 부인, 방영애', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0300', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0375', '유생전', '劉生傳', '3인칭', '한문', '劉生乃登第, 職至金馬玉堂, 爲翰林學士.', '그리고 유생은 과거에 급제하여 벼슬이 금마옥당(金馬玉堂)에 이르렀으며 한림학사(翰林學士)가 되었다.', NULL, '명', '현실계', '중국(中國)', NULL, '유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0301', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0376', '유생전', '劉生傳', '3인칭', '한문', '時, 北虜寇邊, 皇帝遣劉生, 生乃平定而歸.', '그 무렵 북쪽 오랑캐가 변경을 침략하자 황제가 유생을 파견했으니 유생이 이를 평정하고 돌아왔다.', NULL, '명', '현실계', '중국(中國)', NULL, '유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0302', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0377', '유생전', '劉生傳', '3인칭', '한문', '帝以功勞, 卽爲兵部尙書.', '황제가 공로가 있다고 하여 즉시 병부상서(兵部尙書)로 삼았다.', NULL, '명', '현실계', '중국(中國)', NULL, '유생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0303', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0378', '유생전', '劉生傳', '3인칭', '한문', '又三子, 俱爲登第, 食祿高爵, 一時, 富貴榮華, 如此.', '또 세 아들이 과거에 급제하여 녹봉을 받고 관직이 높아졌으니 한때의 부귀영화가 이와 같았다.', NULL, '명', '현실계', '중국(中國)', NULL, '유동영, 유동인, 유동련', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SYSJ02NU001P0304', '장면_유생전_필사본_미국 하버드옌칭도서관_001_S#0379', '유생전', '劉生傳', '3인칭', '한문', '故人皆曰: “苦盡甘來, 而亦萬世所未有者云”.', '그러므로 사람들이 모두 ‘고진감래(苦盡甘來)’요 또 ‘만세에 없었던 일이다.’라고 하였다.', NULL, '명', '현실계', '중국(中國)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0001', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0001', '이생전', '李生傳', '3인칭', '한문', '洛陽北村, 有李生者, 容貌秀麗, 文才過人, 百家詩書, 無不暗通.', '낙양(洛陽) 북촌(北村)에 이생(李生)이란 자가 있었으니 용모가 수려하고 글재주가 남들보다 뛰어났으며 제자백가와 시서(詩書)를 암송하지 않은 것이 없었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0002', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0002', '이생전', '李生傳', '3인칭', '한문', '早喪嚴侍, 只奉偏母, 家計板蕩, 窮不能自存.', '이생은 일찍 아버지를 여의고 홀어머니만을 모셨는데 집안 형편이 좋지 못해 스스로를 보전하지 못할 정도로 궁핍했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0003', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0003', '이생전', '李生傳', '3인칭', '한문', '年過二十, 未得其配, 厥母黃氏, 求婚諸處, 每每見却, 歎世俗之取富, 悶其子之難婚.', '또 나이 스무 살이 넘도록 적절한 배필을 얻지 못하고 있었으니 그 모친 황씨(黃氏)가 여러 곳에 아들의 혼인을 청했으나 매번 거절을 당해 세속이 부유함만 찾는 것에 대해 탄식하며 아들의 혼사가 어려움을 답답하게 여겼다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0004', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0004', '이생전', '李生傳', '3인칭', '한문', '一夕, 忽然下淚曰:', '어느 날 저녁 홀연히 울면서 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0005', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0005', '이생전', '李生傳', '3인칭', '한문', '“汝雖善文, 以寡女之子, 家事甚貧, 零丁孤苦, 年旣長成, 尙未有室, 余心誠慼. 吾聞李監役者, 在於南山下, 而有女極賢云. 欲以汝求婚於彼家, 而吾家則累世不科, 貧賤太甚, 彼家則王室子孫, 富貴兼全. 以吾之子, 求婚於彼家, 困甚不似. 而設畵奇計, 得賢妻致富貴, 古有行之者. 汝若得李女, 則千金可得, 爵祿可占, 一家榮幸, 爲如何哉?”', '“네가 비록 글재주가 뛰어나지만 과부의 아들로 집안이 몹시 가난한 채로 외롭고 쓸쓸한 몸으로 지내다 나이가 이미 장성했는데 아직도 아내가 없으니 내 속으로 무척 근심스럽구나. 내가 듣기로는 감역관 이씨(李氏)라는 자가 남산 아래에 지내고 있는데 무척 어진 딸을 두고 있다고 한다. 너를 데리고 그 집안에 구혼을 하고 싶지만 우리 집안은 몇 대 동안 과거에 합격한 사람이 없어 빈천함이 몹시 심한데, 저 집안은 왕실의 후손으로 부귀를 모두 갖추었다. 따라서 내 자식으로 저 집에 구혼한다고 한들 곤궁함이 몹시 형편없겠으나 특별한 계책을 계획하여 어진 아내를 얻어 부귀에 이르는 일은 옛날에도 이를 시도한 이가 있었다. 네가 만약 이씨네 딸을 아내로 삼는다면 천금의 재산도 얻을 수 있고 작록(爵祿) 차지할 수 있어 온 집안에 영광과 행운이 될 것이니 어떠한가?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0006', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0006', '이생전', '李生傳', '3인칭', '한문', '生泣告曰:', '이생이 울면서 아뢰었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0007', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0007', '이생전', '李生傳', '3인칭', '한문', '“母敎若是, 子心如割, 竭盡心力, 願安承敎.”', '“어머님의 가르침이 마치 제 마음을 칼로 베는 것 같습니다. 마음과 힘을 다해 말씀을 따르겠습니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生), 이생의 모친 황씨(黃氏)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0008', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0008', '이생전', '李生傳', '3인칭', '한문', '卽日, 俠小學, 帶空帒, 詐爲乞人.', '그날로 이생은 『소학』을 옆에 끼고 빈 주머니를 허리에 둘러맨 채 거지로 분장했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_북촌(北村)', '이생(李生)의 집', '이생(李生)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0009', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0009', '이생전', '李生傳', '3인칭', '한문', '尋往李監役家. 立門延, 讀書移時. 李生讀書之聲, 與人殊異, 淸聲換越, 玉盤如碎.', '이윽고 이 감역의 집을 찾아가 대문 바깥에 서서 한참 동안 책을 읽었다. 이생의 책 읽는 소리는 다른 사람들과 남달랐으니 맑은 소리가 멀리 퍼지고 옥쟁반이 부서지는 듯했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_대문', '이생(李生)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0010', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0010', '이생전', '李生傳', '3인칭', '한문', '監役倚枕外堂, 晝眠方熟, 驚起而問曰:', '이 감역이 외당(外堂)에서 베개에 기대며 한참 낮잠을 자고 있다가 놀라 일어나 물었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이생(李生), 이 감역(李監役)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0011', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0011', '이생전', '李生傳', '3인칭', '한문', '“讀書之聲, 是何人也?”', '“이 책 읽는 소리는 누구의 소리인가?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0012', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0012', '이생전', '李生傳', '3인칭', '한문', '蒼頭自外而告曰:', '사내종이 밖에서 아뢰었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 사내종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0013', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0013', '이생전', '李生傳', '3인칭', '한문', '“門外有奇異總角, 讀書乞粮云.”', '“문밖에 기이한 총각이 있는데 책을 읽으며 식량을 구걸한다고 합니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 사내종', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0014', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0014', '이생전', '李生傳', '3인칭', '한문', '監役命奴招之.', '감역이 종에게 명해 이생을 불러오게 했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 사내종, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0015', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0015', '이생전', '李生傳', '3인칭', '한문', '李生鳧趨而入, 跪拜床下,', '이생이 종종걸음으로 재빨리 들어와 상 아래에 꿇어앉아 절을 하자', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 사내종, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0016', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0016', '이생전', '李生傳', '3인칭', '한문', '監役問曰:', '감역이 물었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0017', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0017', '이생전', '李生傳', '3인칭', '한문', '“見爾眉目, 不是常漢也.”', '“네 눈과 눈썹을 보니 상놈들과는 다르구나.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0018', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0018', '이생전', '李生傳', '3인칭', '한문', '問其姓名族派居住,', '그러고는 그 성명과 가문과 거주지를 물었으니', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0019', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0019', '이생전', '李生傳', '3인칭', '한문', '答曰:', '이생이 대답했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0020', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0020', '이생전', '李生傳', '3인칭', '한문', '“小子, 本以兩班, 早喪家君, 只有老母, 病在席, 已多年矣. 囊空甑倒, 旣乏供母之需, 情迫負米.不憚小子之身, 億萬長安, 無處不乞, 偶然今日, 適到高門. 粒米束薪, 惟望救濟.”', '“소인은 본래 양반 출신으로 부친을 일찍 여의고 단지 노모만 계시는데 병들어 자리에 누우신 지가 이미 몇 년이 지났습니다. 쌀 단지도 비고 질그릇도 다해 이미 어머니를 모실 물자가 부족하여 부미할 정도로 사정이 절박했습니다. 그래서 제 몸을 아끼지 않고 수많은 사람들이 있는 장안에서 구걸하지 않은 곳이 없었는데 우연하게도 오늘 귀한 댁에 이르게 되었습니다. 양식과 땔감을 얻어 도움받기를 바랄 뿐입니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0021', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0021', '이생전', '李生傳', '3인칭', '한문', '監役愁然曰:', '감역이 걱정하며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0022', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0022', '이생전', '李生傳', '3인칭', '한문', '“聞汝情狀, 不禁墮淚. 汝若兩班, 則其能識文乎?”', '“네 상황을 듣고 나니 눈물을 멈출 수가 없구나. 네가 만약 양반이라면 글을 잘 아는가?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0023', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0023', '이생전', '李生傳', '3인칭', '한문', '答曰:', '이생이 대답했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0024', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0024', '이생전', '李生傳', '3인칭', '한문', '“稚年已孤, 烏得善文, 然大人若呼一韻, 則願試才拙.”', '“어릴 때부터 이미 홀로 지내 어찌 글에 능숙하겠냐마는 대인께서 운(韻)을 하나 불러주신다면 바라건대 졸렬한 재주를 시험해 보겠습니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0025', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0025', '이생전', '李生傳', '3인칭', '한문', '于時, 昭華滿目, 葉色甚佳.', '마침 이때는 화사한 꽃이 눈에 가득하고 나뭇잎의 빛깔이 매우 아름다웠다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0026', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0026', '이생전', '李生傳', '3인칭', '한문', '監役遂占曰:', '감역이 마침내 한 운을 찍어 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_외당', '이 감역(李監役), 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0027', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0027', '이생전', '李生傳', '3인칭', '한문', '“山帶芳春色, 人閑落日時. 奇童何處來, 詩酒政當施.”', '‘산은 꽃다운 봄빛을 둘렀으며, 사람은 해질 무렵 한가로이 있네. 
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SLSJ01NU001P0088', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0088', '이생전', '李生傳', '3인칭', '한문', '“能.”', '“능숙합니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집', '이생, 옥영', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0089', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0089', '이생전', '李生傳', '3인칭', '한문', '李生卽濡筆, 題詩封給, 玉英傳之.', '이생이 곧장 붓에 먹을 묻혀 시를 써 봉한 다음 옥영에게 전달했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '이생, 옥영', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0090', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0090', '이생전', '李生傳', '3인칭', '한문', '玉英進于桂仙, 曰:', '옥영이 계선에게 편지를 전하며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0091', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0091', '이생전', '李生傳', '3인칭', '한문', '“適出別堂, 則旅客晝寢, 周覽房中, 則一封紙在於丌上. 潛取而來, 不知所書云何.”', '“마침 별당으로 나가보니 손님께서 낮잠을 자고 있어 그 방안을 둘러보았는데 편지 봉투 하나가 책상 위에 있었습니다. 몰래 가지고 왔는데 뭐라고 적혀있는지 알지 못하겠습니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0092', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0092', '이생전', '李生傳', '3인칭', '한문', '桂仙開視之, 乃一絶句也.', '계선이 봉투를 열어 보니 다음과 같이 절구 한 수가 씌여 있었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0093', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0093', '이생전', '李生傳', '3인칭', '한문', '“腸雖深春柳, 魂飄落日邊, 何當生羽翼, 遇訪月中仙.”', '‘마음은 비록 깊은 봄 버들 같더라도, 혼은 해가 지는 끝에서 떠도는구나. 어느 때에 날개가 생겨, 달 속의 선녀를 만나리’', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0094', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0094', '이생전', '李生傳', '3인칭', '한문', '覽畢微笑:', '계선이 시를 다 보고는 웃으며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0095', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0095', '이생전', '李生傳', '3인칭', '한문', '“吾與汝, 相約死生, 何不以實言之? 無以詭術給我乎! 朱鸎之任, 再可能否?”', '“내가 너와 함께 사생을 약속했는데 어찌 사실대로 이야기하지 않는가? 거짓으로 나를 속이지 말거라! 붉은 꾀꼬리의 임무를 다시 맡을 수 있겠는가?”', '詭 : 원본에는 ‘跪’', '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0096', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0096', '이생전', '李生傳', '3인칭', '한문', '卽和其詩, 付于玉榮,', '즉시 그 시에 화답하여 옥영에게 부탁하자', '玉榮 : 원본에는 ‘榮’', '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0097', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0097', '이생전', '李生傳', '3인칭', '한문', '玉英以詩, 傳于李生.', '옥영이 그 시를 이생에게 전해주었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0098', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0098', '이생전', '李生傳', '3인칭', '한문', '李生驚喜, 茫如墮煙霧, 卽見其詩.', '이생이 놀라고 기뻐했으니 안개 속에 떨어진 듯 어리둥절한 상태로 곧장 시를 보았다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0099', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0099', '이생전', '李生傳', '3인칭', '한문', '則.', '내용은 이러하다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0100', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0100', '이생전', '李生傳', '3인칭', '한문', '“春暮南山下, 花紅路北邊, 欲將掃抑意, 尋見武陵仙.”', '“봄날 저물녘 남산 아래에, 길 북쪽 가에 꽃으로 붉게 물들였네. 장차 억눌린 마음 쓸어내리려, 무릉도원 신선을 찾아보리라.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, '개별 소작품', NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0101', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0101', '이생전', '李生傳', '3인칭', '한문', '生覽畢拜謝, 以其銀還, 給玉英曰:', '이생이 이를 다 보고 배사(拜謝)한 다음 은환(銀還)을 옥영에게 주면서 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0102', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0102', '이생전', '李生傳', '3인칭', '한문', '“瑤華一絶, 直當千金. 吾之所願, 終若有成, 則重報厚恩.”', '“아름다운 꽃과 같은 시니 응당 천금의 가치가 있구나. 내가 바라는 것이 끝내 이뤄지게 된다면 후한 은혜를 중히 보답하겠다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0103', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0103', '이생전', '李生傳', '3인칭', '한문', '玉英笑曰:', '옥영이 웃으며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0104', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0104', '이생전', '李生傳', '3인칭', '한문', '“受命娘子, 致書郎君, 職分內事, 豈望報乎?”', '“낭자의 명을 받들어 낭군께 글을 전달한 것은 직분상 해야 하는 일이니 어찌 보답을 바라겠습니까?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0105', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0105', '이생전', '李生傳', '3인칭', '한문', '玉英還, 置舊藏之所.', '옥영이 돌아가 은환을 지난번 감추었던 곳에 보관해 두었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0106', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0106', '이생전', '李生傳', '3인칭', '한문', '李生覽詩之後, 情不自堪, 又告玉英曰:', '이생이 시를 본 뒤로 감정을 스스로 억누르지 못하고 또 옥영에게 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0107', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0107', '이생전', '李生傳', '3인칭', '한문', '“旣得其書, 不見娘子, 此日何堪? 玉英! 玉英! 善爲設策, 使我得見娘子, 今日千萬幸甚.”', '“편지는 이미 받았지만 낭자를 보지 못하니 이날을 어떻게 견디겠는가? 옥영아! 옥영아! 계책을 잘 마련해 내가 낭자를 볼 수 있게 해준다면 오늘 천만다행이겠구나.”', '使我得見娘子 : 원본에는 ‘使我得我得見娘子’', '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0108', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0108', '이생전', '李生傳', '3인칭', '한문', '玉英唯唯,', '옥영이 ‘네 알겠습니다’라고 대답하고', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0109', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0109', '이생전', '李生傳', '3인칭', '한문', '入告于桂仙.', '계선이 있는 방에 들어가 이생의 말을 계선에게 전했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0110', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0110', '이생전', '李生傳', '3인칭', '한문', '旣見李生之容貌, 又見娘子, 不禁春情.', '계선 역시 이미 이생의 용모를 보았는데 또 옥영의 말을 듣고 나니 춘정을 억제하기 어려웠다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0111', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0111', '이생전', '李生傳', '3인칭', '한문', '告于玉榮曰:', '계선이 옥영에게 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0112', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0112', '이생전', '李生傳', '3인칭', '한문', '“今雖欲相見, 晝則, 奴婢滿宅, 夜則, 進賜室內, 俱爲還來, 爲之奈何?”', '“오늘 비록 만나고자 하지만, 낮에는 노비들이 집에 가득하고 밤에는 나리와 부인이 모두 돌아오시니 이를 어떻게 해야 한단 말인가?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0113', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0113', '이생전', '李生傳', '3인칭', '한문', '玉英曰:', '옥영이 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0114', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0114', '이생전', '李生傳', '3인칭', '한문', '“吾聞進賜秀才, 以其返魂, 乘昏入來, 因參祭故, 今日來歸, 室內之行, 亦當明日還家, 此正相會之秋也.”', '“제가 듣기로는 나리께서는 반혼제 때문에 날이 어둑할 때 들어오시는데 제사에 참여해야 하기 때문에 오늘 돌아오시며, 부인께서도 내일 집에 돌아오시니 이때야말로 바로 서로 만날 수 있는 때입니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0115', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0115', '이생전', '李生傳', '3인칭', '한문', '桂仙曰:', '계선이 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0116', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0116', '이생전', '李生傳', '3인칭', '한문', '“此實天授, 余安固辭? 李生之來否, 只在汝策, 汝須好策之, 毋使婢僕漏泄, 幸甚.”', '“이는 실로 하늘이 주신 기회니 내가 어찌 굳이 사양하겠는가? 이생께서 올지 안 올지는 오직 네 계책에 달려있으니 네가 모름지기 좋은 계책을 세워서 종들로 하여금 이 일이 새어나가지 않게 한다면 몹시 다행이겠구나.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0117', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0117', '이생전', '李生傳', '3인칭', '한문', '玉英出而, 告夜以爲期.', '옥영이 방을 나간 뒤 밤에 약속을 잡았음을 알렸다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0118', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0118', '이생전', '李生傳', '3인칭', '한문', '生驚喜顚倒, 莫知所爲, 眼懸西天, 惟待日暮而已.', '이생은 자빠질 정도로 놀랍고도 기뻐하며 어찌할 바를 알지 못하다가 서쪽 하늘을 바라보며 오직 해가 저물기만을 기다릴 뿐이었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0119', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0119', '이생전', '李生傳', '3인칭', '한문', '日沈咸池, 奄及黃昏. 于時, 三春十五日, 夜月明如晝, 萬賴俱寂.', '해가 못에 잠기고 문득 황혼녘이 되었다. 이때는 삼촌(三春) 보름날 한밤의 달빛이 낮과 같이 밝아 삼라만상이 모두 적막할 때였다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0120', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0120', '이생전', '李生傳', '3인칭', '한문', '獨倚窓椽, 苦待玉英, 夜已深二更點矣.', '이생이 홀로 창 서까래에 기대어 옥영을 애타게 기다리고 있었으니 밤이 이미 깊어 이경(二更)을 지나고 있었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0121', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0121', '이생전', '李生傳', '3인칭', '한문', '玉英自內而出, 細聲而呼生曰:', '옥영이 안에서 나와 가느다란 목소리로 이생을 불렀다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0122', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0122', '이생전', '李生傳', '3인칭', '한문', '“李生! 李生! 佳期! 知否?”', '“선비님! 선비님! 지금입니다. 알고 계시죠?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_별당', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0123', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0123', '이생전', '李生傳', '3인칭', '한문', '生驚起出戶, 則玉英携手而入, 踰門數三.', '이생이 놀라 일어나 방을 나왔으니 옥영이 손을 잡고 들어가 서너 개의 문을 넘었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_중문', '옥영, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0124', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0124', '이생전', '李生傳', '3인칭', '한문', '室兪深矣, 到于一房, 則靑燈耿耿, 玉窓乍開. 月光滿地, 庭深如晝, 千花百草, 繞飛窓前, 別一世界.', '건물이 매우 깊은 곳에 있었는데 한 방에 이르니 푸른 등불이 환히 켜져 있고 옥창이 살짝 열려 있었다. 그리고 달빛이 땅에 가득해 깊은 정원이 낮과 같았으며 온갖 화초들이 창 앞을 맴돌면서 흩날리니 하나의 별세계와 다름없었다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0125', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0125', '이생전', '李生傳', '3인칭', '한문', '玉英開窓而告曰:', '옥영이 창문을 열고 계선에게 알렸다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '옥영, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0126', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0126', '이생전', '李生傳', '3인칭', '한문', '“李郞至矣. 桂仙疾出.”', '“이랑(李郞)께서 오셨습니다. 아씨께서는 어서 나오십시오.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0127', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0127', '이생전', '李生傳', '3인칭', '한문', '而迎入于房中, 粉壁玲瓏, 枕席燦爛怳惚, 人間不能盡記.', '그러고는 방안에서 맞아들이니, 분벽(粉壁)은 영롱하고 침석(枕席)은 찬란하고 황홀해 인간 세상에서는 이루 기록할 수 없을 정도였다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0128', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0128', '이생전', '李生傳', '3인칭', '한문', '桂仙明眸皓齒, 態度停停, 分席坐. 微笑而語曰:', '계선이 맑은 눈과 하얀 이를 드러내고 가지런한 태도를 하고는 자리를 나누어 앉았다. 그리고 미소를 지으며 이렇게 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0129', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0129', '이생전', '李生傳', '3인칭', '한문', '“外堂之客, 冒夜入來, 其有罪乎?”', '“외당의 객께서 밤을 무릅쓰고 이곳에 들어오셨으니 아마 죄가 되지 않겠습니까?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0130', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0130', '이생전', '李生傳', '3인칭', '한문', '李生亦笑曰:', '이생이 또한 웃으며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0131', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0131', '이생전', '李生傳', '3인칭', '한문', '“天與不受, 反受其殃, 今夜之期, 烏得失乎?”', '“하늘이 기회를 주었는데도 받지 않는다면 도리어 재앙을 받을 것이니. 오늘 밤의 기약을 어찌 놓칠 수 있겠습니까?”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0132', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0132', '이생전', '李生傳', '3인칭', '한문', '桂仙曰：', '계선이 말했다.', '원본에는 ‘桂仙’', '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0133', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0133', '이생전', '李生傳', '3인칭', '한문', '“郎君不以妾卑, 期今遂目下之逢, 今日之事, 有同鄭衛之風. 失身之罪, 在妾難免, 而妾之中心, 但有所愧也. 第女子欲得賢夫之心, 何異於男子求賢妻之心乎? 吾家父母, 爲我求婚, 而容貌才器, 稱意者也, 遷延未定, 至于今矣. 頃者, 郎君之來, 妾窺窓穴, 效文君之舊事, 不無失身之致. 相會於今日, 郎君若以妾, 爲路柳墻花, 而一折之後, 終當不顧, 則永守一節, 空老深閨. 唯願郎君, 詳度遠慮, 無使妾身抱寃他日.”', '“낭군께서는 저를 천하게 여기지 않으시고 지금 드디어 눈앞에서 만나기를 기약하셨으니 오늘날의 일은 정풍(鄭風)과 위풍(衛風)에 저촉되는 점이 있습니다. 지조를 잃은 죄가 저에게 달려있어 면하기가 어려우니 저의 마음속에 부끄러운 점이 있습니다. 그러나 여자가 어진 남편을 구하려는 마음을 얻고자 하는 것이 어찌 남자가 어진 아내를 구하려는 마음과 다르겠습니까? 저희 집의 부모님이 저를 위해 혼처를 구했으나 용모와 재주가 마음에 드는 자를 시간이 지나도 여태 정하지 못해 지금까지 이르렀습니다. 그런데 근래에 낭군께서 오셔서 첩이 창문 틈으로 엿보고 탁문군의 옛일을 본받았으니 지조를 잃게 되었습니다. 오늘에서야 서로 만났는데 낭군께서 만약 저를 길가의 버들과 담장의 꽃처럼 여기셔서 한번 꺾고 끝내 돌아보지 않으신다면, 저는 영영 절개만 지킨 채 깊은 규문에서 헛되이 늙을 것입니다. 오직 바라건대 낭군께서는 깊이 헤아리고 멀리 내다보셔서 첩으로 하여금 훗날 원한을 품지 않게끔 해주십시오.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0134', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0134', '이생전', '李生傳', '3인칭', '한문', '生欣然一笑曰:', '이생이 기쁘게 웃으며 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0135', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0135', '이생전', '李生傳', '3인칭', '한문', '“娘子之心, 果如是, 則余豈改終. 而但所畏者, 娘子父母, 以一女子, 肯許於貧賤之人乎.”', '“낭자의 마음이 과연 이러하니 내 어찌 뒤에가서 마음을 바꾸겠습니까? 다만 낭자의 부모님께서 한 여식을 빈천한 사람에게 보내는 것을 기꺼이 허락하실까 걱정이 듭니다”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0136', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0136', '이생전', '李生傳', '3인칭', '한문', '桂仙曰：', '계선이 말했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0137', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0137', '이생전', '李生傳', '3인칭', '한문', '“旣定於我, 則妾當期死, 終期此約.”', '“이미 저로 정하셨다면 저는 죽기를 기약하고 끝까지 이 약속을 지킬 것입니다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0138', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0138', '이생전', '李生傳', '3인칭', '한문', '生卽請紙筆, 共書爲盟曰：', '이생이 즉시 종이와 붓을 부탁하고는 함께 서약하며 이렇게 맹세했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0139', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0139', '이생전', '李生傳', '3인칭', '한문', '“天荒地老, 此約無改. 有下芳盟, 鬼神可質.”', '“하늘이 황폐해지고 땅이 오래되어도 이 약속은 변치 않으리. 이곳에서의 아름다운 약속은 귀신에게도 떳떳하도다.”', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0140', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0140', '이생전', '李生傳', '3인칭', '한문', '書畢, 桂仙使玉英, 取酒而來.', '글을 다 쓰고나자 계선은 옥영에게 술을 가져오게 했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0141', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0141', '이생전', '李生傳', '3인칭', '한문', '玉盤珍味, 怳若仙羞梨花酒.', '옥쟁반 위에 진귀한 음식들이 차려졌으니 황홀하기가 마치 신선의 진수성찬과 이화주(梨花酒) 같았다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0142', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0142', '이생전', '李生傳', '3인칭', '한문', '盃氣醺醺, 桂仙纖纖玉手, 强執紙筆, 題歌一曲,', '술기운이 훈훈해지자 계선이 섬섬옥수로 힘껏 종이와 붓을 쥐고서 노래 한 곡조를 지었으니,', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0143', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0143', '이생전', '李生傳', '3인칭', '한문', '其詞曰:', '그 가사는 이러했다.', NULL, '조선', '현실계', '중국(中國)_하남성(河南省)_낙양시(洛陽市)_남산(南山)', '계선의 집_내사(內舍)', '이생, 계선', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSJ01NU001P0144', '장면_이생전_필사본_한국 국사편찬위원회_001_S#0144', '이생전', '李生傳', '3인칭', '한문', '“今夕何夕? 時惟三春, 風習習, 月團團, 兒女春情不自堪, 宿願今成事, 雖死無憾.”', '“오늘 밤이 어떤 밤인가? 오늘 밤이 어떤 밤인가? 이때는 삼촌으로 바람은 살랑이고 달은 두둥실 떠있으니 아녀자의 춘정을 견딜 수가 없구나. 오랜 소원이 오늘 일이 이뤄졌으니 
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SLSGJJ01YU001P0066', '장면_이생규장전_목판본_일본 내각문고_001_S#0066', '이생규장전', '李生窺牆傳', '3인칭', '한문', '女惻然而頷之, 踰垣而遣之.', '여인은 서글퍼하며 고개를 끄덕이고는 담장 너머로 이생을 돌려보냈다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_북원(北園)_소루(小樓)', '이생, 최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0067', '장면_이생규장전_목판본_일본 내각문고_001_S#0067', '이생규장전', '李生窺牆傳', '3인칭', '한문', '生自是以後, 無已不往.', '이생은 이로부터 최씨 집에 들리지 않은 적이 없었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0068', '장면_이생규장전_목판본_일본 내각문고_001_S#0068', '이생규장전', '李生窺牆傳', '3인칭', '한문', '一夕, 李生之父, 問曰:', '어느 날 저녁 이생의 부친이 이생에게 물었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생, 이생의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0069', '장면_이생규장전_목판본_일본 내각문고_001_S#0069', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“汝朝出而暮還者, 將以學先聖仁義之格言, 昏出而曉還, 當爲何事? 必作輕薄子, 踰垣墻, 折樹檀耳. 事如彰露, 人皆譴我敎子之不嚴. 而如其女, 定是高門右族, 則必以爾之狂狡, 穢彼門戶, 獲戾人家, 其事不小. 速去嶺南, 率奴隷監農, 勿得復還.”', '“네가 아침에 집을 나갔다가 저녁에 돌아오는 것은 공자님의 인의(仁義)의 격언을 배우기 위함이겠지만, 저녁에 나갔다가 새벽에 돌아오는 것은 무슨 일 때문이냐? 분명 경박한 놈들이 되어 남의 집 담장을 넘고 박달나무를 꺾는 일을 벌였겠구나. 일이 만약 드러난다면 사람들은 모두 내가 자식을 엄하게 가르치지 않았다고 비난할 것이다. 그리고 만약 그 여인이 정말로 높은 가문의 귀족이라면 필시 네 미친 짓으로 집안을 더럽힌 것 때문에 남의 가문에 죄를 얻게 될 것이니 그 일이 작지 않다. 당장 영남으로 떠나 종들을 거느려 농사일을 감독하고 다시는 돌아오지 마라.”', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생, 이생의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0070', '장면_이생규장전_목판본_일본 내각문고_001_S#0070', '이생규장전', '李生窺牆傳', '3인칭', '한문', '卽於翌日, 謫送蔚州.', '바로 이튿날 이생을 울주(蔚州)로 귀양 보냈다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생, 이생의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0071', '장면_이생규장전_목판본_일본 내각문고_001_S#0071', '이생규장전', '李生窺牆傳', '3인칭', '한문', '女每夕, 於花園待之, 數月不還.', '여인은 매일 저녁 화원에서 그를 기다렸으나 몇 달이 지나도 돌아오지 않았다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_북원(北園)', '최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0072', '장면_이생규장전_목판본_일본 내각문고_001_S#0072', '이생규장전', '李生窺牆傳', '3인칭', '한문', '女意其得病, 命香兒, 密問於李生之鄰,', '여인은 그가 병이 들었다고 생각해 향아를 시켜 이생의 이웃에게 몰래 물어보게 했으니', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_북원(北園)', '최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0073', '장면_이생규장전_목판본_일본 내각문고_001_S#0073', '이생규장전', '李生窺牆傳', '3인칭', '한문', '鄰人曰:', '이웃 사람의 말은 이러하다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_북원(北園)', '최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0074', '장면_이생규장전_목판본_일본 내각문고_001_S#0074', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“李郞, 得罪於家君, 去嶺南, 已數月矣.”', '“이 도령은 부친에게 죄를 얻어 영남으로 떠난 지 이미 몇 달이 되었다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_북원(北園)', '최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0075', '장면_이생규장전_목판본_일본 내각문고_001_S#0075', '이생규장전', '李生窺牆傳', '3인칭', '한문', '女聞之, 臥疾在床, 輾轉不起. 水醬不入於口, 言語支離, 肌膚憔悴.', '여인이 그 말을 듣고 병이 들어 침상에 누워 뒤척이며 일어나지 못했다. 물 한 모금도 입에 대지 않고 말도 제대로 못하고 피부도 초췌해졌다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 향아', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0076', '장면_이생규장전_목판본_일본 내각문고_001_S#0076', '이생규장전', '李生窺牆傳', '3인칭', '한문', '父母怪之, 問其病狀, 喑喑不言.', '부모가 이를 괴이하게 여겨 그 병세를 물었으나 여인은 묵묵히 답하지 않았다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0077', '장면_이생규장전_목판본_일본 내각문고_001_S#0077', '이생규장전', '李生窺牆傳', '3인칭', '한문', '搜其箱篋, 得李生前日唱和詩, 擊節驚訝曰:', '부모가 그녀의 상자를 뒤져보다가 딸이 이생과 지난날 주고받았던 시를 찾아내고는 무릎을 치며 놀라 말했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0078', '장면_이생규장전_목판본_일본 내각문고_001_S#0078', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“幾乎失我女子矣.”', '“하마터면 우리 딸을 잃을 뻔했구나.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0079', '장면_이생규장전_목판본_일본 내각문고_001_S#0079', '이생규장전', '李生窺牆傳', '3인칭', '한문', '問曰:', '그러고는 물었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0080', '장면_이생규장전_목판본_일본 내각문고_001_S#0080', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“李生誰耶?”', '“이생이 누구냐?”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0081', '장면_이생규장전_목판본_일본 내각문고_001_S#0081', '이생규장전', '李生窺牆傳', '3인칭', '한문', '至是, 女不能復隱, 細語在咽中, 告父母曰:', '일이 이렇게 되자 여인은 더 이상 숨길 수 없어 가느다란 목소리로 목이 멘 채 부모님께 고했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0082', '장면_이생규장전_목판본_일본 내각문고_001_S#0082', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“父親母親, 鞠育恩深, 不能相匿. 竊念男女相感, 人情至重. 是以, 標梅迨吉, 咏於召南, 咸腓之凶, 戒於羲易. 自將蒲柳之質, 不念桑落之詩, 行露沾衣, 竊被傍人之嗤. 絲蘿托木, 已作渭兒之行. 罪已貫盈, 累及門戶. 然而彼狡童兮, 一偸賈香, 千生喬怨. 以眇眇之弱軀, 忍悄悄之獨處, 情念日深, 沈痾日篤, 濱於死地, 將化窮鬼. 父母如從我願, 終保餘生, 倘違情款, 斃而有已. 當與李生, 重遊黃壞之下, 誓不登他門也.”', '“아버님 어머님께서 길러주신 은혜가 깊으니 숨길 수가 없습니다. 삼가 생각해 보건대 남녀가 서로 느끼는 것은 인정상 지극히 중한 것입니다. 이 때문에 좋은 시기를 잃지 말라는 표유매(標有梅)가 『시경』·「소남」에서 읊고 있으며 함비(咸腓)의 흉함을 복희씨(伏羲氏)의 『주역』에서 경계했던 것입니다. 저는 버드나무처럼 연약한 자질을 가지고 뽕잎이 떨어지는 시를 염두에 두지 않고 길 위의 이슬에 옷이 젖고 말아 남들의 비웃음을 사게 되었습니다. 토사(菟絲)와 송라(松蘿)가이 나무에 기대여야 하지만 이미 위아(渭兒)의 행실을 저질렀으니 죄가 이미 가득 차 집안에 누를 끼치고 말았습니다. 그러나 저 교동(狡童)이 한번 가충의 향을 훔친 뒤 수없이 교생(喬生)에 대한 원망이 생겨났습니다. 이 보잘것없는 약한 몸으로 근심스러운 독수공방을 참아보았으나 그리운 정은 날로 깊어지고 깊은 병은 날로 위독해져 죽을 지경에 가까워졌으니 곧 원귀가 되려고 합니다. 부모님께서 제 소원을 들어주신다면 여생을 보전하겠지만 만약 제 간곡한 정을 어기신다면 죽음만이 있을 뿐입니다. 응당 이생과 함께 저승에서 다시 놀지언정 맹세코 다른 가문에는 시집가지 않겠습니다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0083', '장면_이생규장전_목판본_일본 내각문고_001_S#0083', '이생규장전', '李生窺牆傳', '3인칭', '한문', '於是, 父母已知其志, 不復問病, 且警且誘, 以寬其心.', '이에 부모는 그의 뜻을 알아차리고는 다시 병에 대해 묻지 않았으니 타이르기도 하고 달래기도 하며 그 마음을 누그러뜨렸다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0084', '장면_이생규장전_목판본_일본 내각문고_001_S#0084', '이생규장전', '李生窺牆傳', '3인칭', '한문', '復修媒妁之禮, 問于李家.', '그리고 다시 중매의 예절을 갖추어 이씨 집안에 혼인 의사를 물었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집_규방(閨房)', '최랑, 최랑의 부친, 최랑의 모친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0085', '장면_이생규장전_목판본_일본 내각문고_001_S#0085', '이생규장전', '李生窺牆傳', '3인칭', '한문', '李氏問崔家門戶優劣, 曰:', '이씨가 최씨 집안 문벌과의 우열을 묻고는 말했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0086', '장면_이생규장전_목판본_일본 내각문고_001_S#0086', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“吾家豚犬, 雖年少風狂, 學問精通, 身彩似人. 所冀捷龍頭於異日, 占鳳鳴於他年, 不願速求婚媾也.”', '“우리 집 못난 자식이 비록 나이가 어리고 미치광이 같으나 학문에 정통하고 풍채도 남들 못지않습니다. 훗날에 과거에 장원 급제하고 미래에 봉황의 울음을 기대하고 있으니 서둘러 혼례를 치르고 싶지 않습니다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0087', '장면_이생규장전_목판본_일본 내각문고_001_S#0087', '이생규장전', '李生窺牆傳', '3인칭', '한문', '媒者以言返告,', '매파가 이 말을 돌아가서 고하자', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0088', '장면_이생규장전_목판본_일본 내각문고_001_S#0088', '이생규장전', '李生窺牆傳', '3인칭', '한문', '崔氏復遣曰:', '최씨가 다시 보내어 말했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0089', '장면_이생규장전_목판본_일본 내각문고_001_S#0089', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“一時朋伴, 皆稱:‘令嗣才華邁人’, 今雖蟠屈, 豈是池中之物? 宜速定嘉會之晨, 以合二姓之好.”', '“한때의 벗들도 모두 아드님의 재주가 남들보다 뛰어나다고 칭찬하니 지금은 비록 웅크리고 있으나 어찌 연못 속의 물건이겠습니까? 마땅히 빨리 좋은 날을 잡아 두 집안의 우호를 맺도록 합시다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0090', '장면_이생규장전_목판본_일본 내각문고_001_S#0090', '이생규장전', '李生窺牆傳', '3인칭', '한문', '媒者, 又以其言, 返告李生之父,', '매파가 또 그 말을 이생의 부친에게 고하니,', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0091', '장면_이생규장전_목판본_일본 내각문고_001_S#0091', '이생규장전', '李生窺牆傳', '3인칭', '한문', '曰:', '이생의 부친이 말했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0092', '장면_이생규장전_목판본_일본 내각문고_001_S#0092', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“吾亦自少, 把冊窮經, 年老無成. 奴僕逋逃, 親戚寡助, 生涯疎闊, 家計伶俜, 巨家大族, 豈以一人寒儒, 留意爲贅郞乎? 是必好事者, 過譽吾家, 以誣高門也.”', '“나 역시 젊어서부터 책을 잡고 경전을 궁구했으나 늙도록 이룬 것이 없습니다. 노비들은 도망가고 친척들의 도움도 적어 생계가 옹색하고 가계도 보잘것없는데 명문거족께서 어찌 한갓 가난한 선비를 사위로 삼는 데 뜻을 두겠습니까? 이는 분명 호사가가 우리 집안을 지나치게 칭찬해 높은 가문을 속인 것입니다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0093', '장면_이생규장전_목판본_일본 내각문고_001_S#0093', '이생규장전', '李生窺牆傳', '3인칭', '한문', '媒又告崔家,', '매파가 또 최씨 집안에 알리니', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0094', '장면_이생규장전_목판본_일본 내각문고_001_S#0094', '이생규장전', '李生窺牆傳', '3인칭', '한문', '崔家曰:', '최씨 집안에서 말했다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0095', '장면_이생규장전_목판본_일본 내각문고_001_S#0095', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“納采之禮, 裝束之事, 吾盡辨矣. 宜差穀旦, 以定花燭之期.”', '“납채(納采)의 예와 옷을 준비하는 일은 우리가 모두 마련하겠습니다. 응당 좋은 날을 가려 화촉을 밝힐 때만 정합시다.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0096', '장면_이생규장전_목판본_일본 내각문고_001_S#0096', '이생규장전', '李生窺牆傳', '3인칭', '한문', '媒者, 又返告之李家.', '매파가 이를 이씨 집안에 알렸다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 매파', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0097', '장면_이생규장전_목판본_일본 내각문고_001_S#0097', '이생규장전', '李生窺牆傳', '3인칭', '한문', '至是, 稍回其意, 卽遣人, 召生問之.', '이씨 집안도 이렇게 되자 뜻을 조금 돌리고 즉시 사람을 보내서 이생을 불러 뜻을 물어보았다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생의 부친, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0098', '장면_이생규장전_목판본_일본 내각문고_001_S#0098', '이생규장전', '李生窺牆傳', '3인칭', '한문', '生喜不自勝, 乃作詩曰:', '이생은 기쁨을 스스로 가누지 못해 곧바로 시를 지었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0099', '장면_이생규장전_목판본_일본 내각문고_001_S#0099', '이생규장전', '李生窺牆傳', '3인칭', '한문', '“破鏡重圓會有時, 天津烏鵲助佳期. 從今月老纏繩去, 莫向東風怨子規.”', '“깨진 거울이 다시 둥글어지는 것은 적절한 때가 있으니, 은하수의 까마귀와 까치가 아름다운 기약을 돕는구나. 이제부터 월하노인이 붉은 실을 묶어줄 것이니, 봄바람을 향해 두견새를 원망하지 말거라.”', NULL, '고려', '현실계', '한국 황해북도_개성', '낙타교 부근_이생의 집', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0100', '장면_이생규장전_목판본_일본 내각문고_001_S#0100', '이생규장전', '李生窺牆傳', '3인칭', '한문', '女聞之, 病亦稍愈, 又作詩曰:', '최씨도 이 소식을 듣고 병이 조금 나아졌으니 또 이렇게 시를 지었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0101', '장면_이생규장전_목판본_일본 내각문고_001_S#0101', '이생규장전', '李生窺牆傳', '3인칭', '한문', '惡因緣是好因緣, 盟語終須到底圓. 共輓鹿車何日是, 倩人扶起理花鈿.', '“나쁜 인연이 좋은 인연이 되고, 맹세한 말이 끝내 이루어졌구나. 함께 사슴 수레를 끌고 가는 날이 언제인가, 사람을 시켜 부축해 일어나 꽃비녀를 다듬네.”', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0102', '장면_이생규장전_목판본_일본 내각문고_001_S#0102', '이생규장전', '李生窺牆傳', '3인칭', '한문', '於是, 擇吉日, 遂定婚禮, 而續其絃焉.', '그리하여 길일을 택해 마침내 혼례를 치러 끊어진 거문고 줄을 다시 이었다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑, 이생, 이생-최랑 부모', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0103', '장면_이생규장전_목판본_일본 내각문고_001_S#0103', '이생규장전', '李生窺牆傳', '3인칭', '한문', '自同牢之後, 夫婦愛而敬之, 相待如賓, 雖鴻光鮑桓, 不足言其節義也.', '동뢰연(同牢宴)을 치른 뒤로 부부는 서로 사랑하고 공경하며 손님을 대하듯 서로 대우하니 비록 양홍(梁鴻)과 맹광(孟光) 부부, 포선(鮑宣)과 환소군(桓少君) 부부라고 할지라도 그 절도와 의리를 다 말하기에 부족할 정도였다.', NULL, '고려', '현실계', '한국 황해북도_개성', '선죽리_최씨의 집', '최랑, 이생,', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0104', '장면_이생규장전_목판본_일본 내각문고_001_S#0104', '이생규장전', '李生窺牆傳', '3인칭', '한문', '生翌年, 捷高科, 登顯仕, 聲價聞于朝著.', '이생은 이듬해 과거에 급제해 현달한 벼슬에 올라 명성이 조정에까지 알려졌다.', NULL, '고려', '현실계', '한국 황해북도_개성', '조정(朝廷)', '이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSGJJ01YU001P0105', '장면_이생규장전_목판본_일본 내각문고_001_S#0105', '이생규장전', '李生窺牆傳', '3인칭', '한문', '辛丑年, 紅賊據京城, 王移福州.', '신축년(辛丑年,1361년)에 홍건적이 서울을 점령하자 공민왕(恭愍王)이 복주(福州)로 피난했다.', NULL, '고려', '현실계', '한국 황해북도_개성;
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SLSDJ01NU005P0104', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0104', '이석단전', '李石丹傳', '3인칭', '한문', '頃假寐, 夢中仙人, 自天降來曰:', '그러다 잠깐 선잠을 잤는데 꿈 속에 선인(仙人)이 하늘로부터 내려와 말했다.', NULL, '조선', '현실계', '꿈', '꿈', '홍대, 선인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0105', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0105', '이석단전', '李石丹傳', '3인칭', '한문', '“汝命百有六旬, 分爾之命, 半給於李石丹, 各受八十, 終身同住.”', '“네 수명은 160년이었으나 너의 수명을 나누어 그 절반을 이석단에게 줄 것이니 각각 팔십 년을 받아 죽을 때까지 함께 지내거라.”', NULL, '조선', '현실계', '꿈', '꿈', '홍대, 선인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0106', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0106', '이석단전', '李石丹傳', '3인칭', '한문', '言訖, 乗雲而去.', '선인은 말을 마치고 구름을 타고 떠나갔다.', NULL, '조선', '현실계', '꿈', '꿈', '홍대, 선인', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0107', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0107', '이석단전', '李石丹傳', '3인칭', '한문', '已而, 欠伸而覺, 乃一夢也.', '이윽고 기지개를 켜고 일어나보니 곧 꿈이었다.', NULL, '조선', '현실계', '한국 한양', '길상사', '홍대', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0108', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0108', '이석단전', '李石丹傳', '3인칭', '한문', '女卽就殯前開棺, 合抱李生之胸,', '홍대가 곧바로 이생의 관 앞에 가서 관을 열고 이생의 가슴을 껴안으니,', NULL, '조선', '현실계', '한국 한양', '길상사', '홍대, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0109', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0109', '이석단전', '李石丹傳', '3인칭', '한문', '移時乃甦.', '잠시 후 이생이 되살아났다.', NULL, '조선', '현실계', '한국 한양', '길상사', '홍대, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0110', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0110', '이석단전', '李石丹傳', '3인칭', '한문', '携來其家, 偕和夫婦, 如合符節.', '그녀는 그를 집으로 데려와 함께 부부를 이루었으니 부절(符節)을 맞춘 듯했다.', NULL, '조선', '현실계', '한국 한양', '홍대의 집', '홍대, 이생', NULL, '孟子_離婁下', NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0111', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0111', '이석단전', '李石丹傳', '3인칭', '한문', '兩人願誓曰:', '두 사람은 이렇게 맹세하였다.', NULL, '조선', '현실계', '한국 한양', '홍대의 집', '홍대, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0112', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0112', '이석단전', '李石丹傳', '3인칭', '한문', '“在天願作比翼鳥, 在地願爲連理枝. 共盡八十同死生, 天長地久永相隨.”', '“하늘에서는 비익조(比翼鳥)가 되길 원하고, 땅에서는 연리지(連理枝)가 되길 바라네. 모두 80세가 되기까지 생사를 같이하며, 천지처럼 오래도록 영원히 함께하리.”', NULL, '조선', '현실계', '한국 한양', '홍대의 집', '홍대, 이생', NULL, '「장한가(長恨歌)」', NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0113', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0113', '이석단전', '李石丹傳', '3인칭', '한문', '年至八十一年, 一時俱沒.', '나이가 81세가 되자 두 사람은 같은 날 세상을 떠났다.', NULL, '조선', '현실계', '한국 한양', '홍대의 집', '홍대, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0114', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0114', '이석단전', '李石丹傳', '3인칭', '한문', '時人, 有詩曰:', '사람들은 이를 보고 시를 지었다.', NULL, '조선', '현실계', '한국 한양', '미상', '홍대, 이생', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0115', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0115', '이석단전', '李石丹傳', '3인칭', '한문', '“寂寞深山裡, 雙魂一時歸. 可憐夫婦意. 生死一樣之.”', '“쓸쓸한 깊은 산속에서, 두 혼령이 같은 때에 돌아갔네. 가련하구나! 부부의 뜻이여, 삶과 죽음을 함께 하는구나.', NULL, '조선', '현실계', '한국 한양', '미상', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0116', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0116', '이석단전', '李石丹傳', '3인칭', '한문', '合葬于北山之麓, 墓邊忽生連理樹. 又有元央一雙, 常集于此樹之上, 雙棲不離.', '그들은 북산 기슭에 합장되었는데 무덤가에 홀연히 연리지가 돋아났다. 또 원앙 한 쌍이 늘 이 나무 위에 모여들어 함께 깃들어 떠나지를 않았다.', NULL, '조선', '현실계', '한국 한양', '북산(北山)', '홍대, 이생', NULL, '「장한가(長恨歌)」', NULL, NULL, NULL, NULL),
    ('SLSDJ01NU005P0117', '장면_이석단전_필사본_한국 충북 충주 고불선원_001_S#0117', '이석단전', '李石丹傳', '3인칭', '한문', '世之人, 以奇之事稱歎焉.', '세상 사람들은 이를 기이한 일이라 여기며 칭탄(稱歎)했다.', NULL, '조선', '현실계', '한국 한양', '미상', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0001', '장면_이석단전_필사본_한국 이길환_001_S#0001', '이석단전', '李石丹傳', '3인칭', '한문', '昔者, 有士大夫李生者, 號石檀.', '옛날에 사대부 이생이라는 자가 있었으니 호는 석단(石檀)이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0002', '장면_이석단전_필사본_한국 이길환_001_S#0002', '이석단전', '李石丹傳', '3인칭', '한문', '遊於太學館, 朝夕往來, 常過洪氏之門.', '그는 태학관(太學館)을 드나들며 아침저녁으로 오가다가 매번 홍씨(洪氏)의 집 문을 지나곤 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0003', '장면_이석단전_필사본_한국 이길환_001_S#0003', '이석단전', '李石丹傳', '3인칭', '한문', '有一女名洪臺, 年甫二八. 性嚴聰惠, 能解文字, 亦能詩賦.', '그 집에는 이름이 홍대(洪臺)인 딸이 있었으니 나이는 겨우 열여섯이었다. 홍대는 성품이 엄하고 총명하며 지혜로운데다 글을 지을 수 있었고 시부에도 능숙했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0004', '장면_이석단전_필사본_한국 이길환_001_S#0004', '이석단전', '李石丹傳', '3인칭', '한문', '宅北路傍, 別構高樓, 昇階自來以通之.', '홍대의 집은 북쪽 길가에는 따로 높은 누각을 지어두었는데 오르는 계단은 집 안으로부터 토하게 되어있었따.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0005', '장면_이석단전_필사본_한국 이길환_001_S#0005', '이석단전', '李石丹傳', '3인칭', '한문', '侍婢梳鴨, 共登斯樓, 常從侍陪.', '홍대는 시비 소압(梳鴨)을 데리고 이 누각을 함께 올랐으니 소압은 곁에서 늘 그녀를 시중들었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0006', '장면_이석단전_필사본_한국 이길환_001_S#0006', '이석단전', '李石丹傳', '3인칭', '한문', '一日, 生歸館經路, 適通樓下, 休息於樓邊垂柳之間.', '어느 날 이생이 태학관으로 돌아가던 길에 따라가다가 누각 아래에 이르러 누각 옆에 늘어진 수양버들 사이에 쉬고 있었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0007', '장면_이석단전_필사본_한국 이길환_001_S#0007', '이석단전', '李石丹傳', '3인칭', '한문', '洪氏見生休憩于此, 不禁私意, 卽吟曰:', '홍대는 이생이 그곳에서 쉬는 것을 보고는 마음속의 정을 참지 못해 곧 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0008', '장면_이석단전_필사본_한국 이길환_001_S#0008', '이석단전', '李石丹傳', '3인칭', '한문', '“桃花李花杏花發, 南里北里西里春. 不熱不寒好時節, 半醉半醒無事人.”', '복사꽃과 오얏꽃과 은행나무 꽃 만발하니, 남쪽, 북쪽, 서쪽 마을 모두 봄이 되었구나. 덥지도 않고 춥지도 않은 좋은 계절에, 반쯤 취하고 반쯤 깬 한가로운 사람이여.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0009', '장면_이석단전_필사본_한국 이길환_001_S#0009', '이석단전', '李石丹傳', '3인칭', '한문', '翌日, 生又過於其處,', '다음 날 이생이 다시 그곳을 지나가자', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0010', '장면_이석단전_필사본_한국 이길환_001_S#0010', '이석단전', '李石丹傳', '3인칭', '한문', '女使梳鴨投鞋路中.', '홍대는 몸종 소압에게 신발 한 짝을 길 한가운데로 던지게 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0011', '장면_이석단전_필사본_한국 이길환_001_S#0011', '이석단전', '李石丹傳', '3인칭', '한문', '生到此, 吟曰:', '이생이 그곳에 이르러 신발을 보고 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0012', '장면_이석단전_필사본_한국 이길환_001_S#0012', '이석단전', '李石丹傳', '3인칭', '한문', '“此鞋非常鞋, 如何棄路中?”', '“이 신발은 보통 사람 신발이 아닌데, 어찌하여 길 가운데 버려졌는가?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0013', '장면_이석단전_필사본_한국 이길환_001_S#0013', '이석단전', '李石丹傳', '3인칭', '한문', '女卽吟曰:', '그러자 홍대가 곧바로 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0014', '장면_이석단전_필사본_한국 이길환_001_S#0014', '이석단전', '李石丹傳', '3인칭', '한문', '“非是常人鞋, 思君擲路中.”', '“이는 보통 사람의 신발이 아니니, 그대를 생각해 길에 던졌습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0015', '장면_이석단전_필사본_한국 이길환_001_S#0015', '이석단전', '李石丹傳', '3인칭', '한문', '生聞吟聲, 仰見樓上, 果有一女.', '이생은 읊조리는 소리를 듣고 누각 위를 올려다 보니 과연 한 여인이 있었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0016', '장면_이석단전_필사본_한국 이길환_001_S#0016', '이석단전', '李石丹傳', '3인칭', '한문', '面似芙蓉, 色如秋月, 雖西施之萬態, 不能過也, 貴妃之百媚, 亦不能愈也.', '그녀의 얼굴은 부용과 같고 안색은 가을 달과 같아 비록 서시(西施)의 온갖 자태도 능가할 수 없었으며 양귀비(楊貴妃)의 갖가지 아양도 넘어서지 못했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0017', '장면_이석단전_필사본_한국 이길환_001_S#0017', '이석단전', '李石丹傳', '3인칭', '한문', '生不能定情, 作詩吟曰:', '이생은 자신의 마음을 가누지 못하고 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0018', '장면_이석단전_필사본_한국 이길환_001_S#0018', '이석단전', '李石丹傳', '3인칭', '한문', '“隣有桃花色, 枝高不可攀.”', '“이웃에 복사꽃 빛깔이 있지만, 가지가 높아 손이 닿지를 않네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0019', '장면_이석단전_필사본_한국 이길환_001_S#0019', '이석단전', '李石丹傳', '3인칭', '한문', '女繼吟曰:', '홍대가 시를 이어 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0020', '장면_이석단전_필사본_한국 이길환_001_S#0020', '이석단전', '李石丹傳', '3인칭', '한문', '“仍風依近枝, 折得解愁情.”', '“바람 따라서 가까운 가지에 의지해, 꺾어 얻으면 근심을 풀 수 있겠구나.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0021', '장면_이석단전_필사본_한국 이길환_001_S#0021', '이석단전', '李石丹傳', '3인칭', '한문', '女卽使梳鴨, 垂鴛鴦襟於樓下,', '홍대가 곧 소압에게 원앙 무늬가 있는 금령(襟領)을 누각 아래로 보내게 하니', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0022', '장면_이석단전_필사본_한국 이길환_001_S#0022', '이석단전', '李石丹傳', '3인칭', '한문', '扶而上樓.', '이생이 그것을 잡고 누각으로 올라갔다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0023', '장면_이석단전_필사본_한국 이길환_001_S#0023', '이석단전', '李石丹傳', '3인칭', '한문', '留宿三夜, 極歡極樂也.', '이생은 사흘 밤을 그곳에서 지내며 홍대와 극진한 기쁨과 즐거움을 누렸다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0024', '장면_이석단전_필사본_한국 이길환_001_S#0024', '이석단전', '李石丹傳', '3인칭', '한문', '女之父母, 與梳鴨問曰:', '홍대의 부모가 몸종 소압에게 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0025', '장면_이석단전_필사본_한국 이길환_001_S#0025', '이석단전', '李石丹傳', '3인칭', '한문', '“向者, 少娘洗水淸潔, 飯有多食, 何故洗水汚濁, 飯無所餘?”', '“예전에 낭자는 세숫물을 깨끗하게 쓰고 밥도 남겼는데 지금은 어째서 물도 탁해지고 밥도 남은 것이 없느냐?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0026', '장면_이석단전_필사본_한국 이길환_001_S#0026', '이석단전', '李石丹傳', '3인칭', '한문', '梳鴨對曰:', '소압이 답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0027', '장면_이석단전_필사본_한국 이길환_001_S#0027', '이석단전', '李石丹傳', '3인칭', '한문', '“向者, 少細腮, 故洗水淸潔, 飯有多食,今則年壯豊面, 故洗水汚濁, 飯無所餘.”', '“저번에는 아가씨가 어려서 얼굴이 갸름해 물도 맑고 밥도 남았지만 지금은 나이가 들어 얼굴에 살이 올랐으니 세숫물도 탁해지고 밥도 남지 않게 되었습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0028', '장면_이석단전_필사본_한국 이길환_001_S#0028', '이석단전', '李石丹傳', '3인칭', '한문', '父母信言, 又問洪臺曰:', '홍대의 부모는 그 말을 믿었으나 또 홍대에게 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0029', '장면_이석단전_필사본_한국 이길환_001_S#0029', '이석단전', '李石丹傳', '3인칭', '한문', '“梳鴨之言, 是乎?”', '“소압이 말이 이러한데 사실이냐?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0030', '장면_이석단전_필사본_한국 이길환_001_S#0030', '이석단전', '李石丹傳', '3인칭', '한문', '女黙然無答, 籌思遽對曰:', '홍대는 묵묵히 답하지 않고 오랫동안 생각하다가 급히 대답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0031', '장면_이석단전_필사본_한국 이길환_001_S#0031', '이석단전', '李石丹傳', '3인칭', '한문', '“人新可乎? 衣新可乎?”', '“사람은 새 사람이 낫지 않습니까? 옷은 새 옷이 더 좋지 않습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0032', '장면_이석단전_필사본_한국 이길환_001_S#0032', '이석단전', '李石丹傳', '3인칭', '한문', '父母知其所由, 怒曰:', '부모는 그 까닭을 알아채고 노하여 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0033', '장면_이석단전_필사본_한국 이길환_001_S#0033', '이석단전', '李石丹傳', '3인칭', '한문', '“吾無二獨女子, 信愛於掛天, 將欲嫁, 汝奈何遽出此言, 非吾之息也”', '“우린 다른 외동딸은 없어 하늘에 걸고 자식을 믿고 사랑해 장차 시집보내려고 했는데 어찌 갑자기 이런 말을 하느냐? 이는 내 자식이 아니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0034', '장면_이석단전_필사본_한국 이길환_001_S#0034', '이석단전', '李石丹傳', '3인칭', '한문', '生所拘留日, 思還家曰 :', '이때 이생은 홍대에게 얽매여 며칠 동안 있다가 집에 돌아가고 싶어하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0035', '장면_이석단전_필사본_한국 이길환_001_S#0035', '이석단전', '李石丹傳', '3인칭', '한문', '“東方已啓明, 以我欲還家.”', '“동쪽 하늘이 이미 밝아오고 있으니 저는 집으로 돌아가고자 합니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0036', '장면_이석단전_필사본_한국 이길환_001_S#0036', '이석단전', '李石丹傳', '3인칭', '한문', '女曰:', '홍대가 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0037', '장면_이석단전_필사본_한국 이길환_001_S#0037', '이석단전', '李石丹傳', '3인칭', '한문', '“非東方之明矣, 月出之光矣.”', '“이는 동쪽에서 해가 밝아오는 것이 아니라 달이 나와 비추는 것입니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0038', '장면_이석단전_필사본_한국 이길환_001_S#0038', '이석단전', '李石丹傳', '3인칭', '한문', '卽以掩, 吟曰:', '곧 병풍으로 창을 가리고 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0039', '장면_이석단전_필사본_한국 이길환_001_S#0039', '이석단전', '李石丹傳', '3인칭', '한문', '“鴦襟半脫玉細腰, 屛掩東窓月來朝, 玉齒乍咬卽臂肉, 更扣盟誓到今宵.”', '“원앙금 반쯤 벗겨지니 옥처럼 가는 허리 보이니, 장막으로 가린 동쪽 창에 아침 달이 비추네. 옥 같은 치아로 팔을 살짝 깨무네. 오늘 밤에 다시금 맹세를 다지는구나.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0040', '장면_이석단전_필사본_한국 이길환_001_S#0040', '이석단전', '李石丹傳', '3인칭', '한문', '四日之次, 生還家,', '나흘 뒤 이생은 집으로 돌아가자', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0041', '장면_이석단전_필사본_한국 이길환_001_S#0041', '이석단전', '李石丹傳', '3인칭', '한문', '生之父母知其由, 且驚且戒曰:', '이생의 부모는 그 연유를 알게 되었으니 놀라고 훈계하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0042', '장면_이석단전_필사본_한국 이길환_001_S#0042', '이석단전', '李石丹傳', '3인칭', '한문', '“貪花蜂蝶, 亡身於蛛網之間, 愛雉蒼鷹, 折翼於山林之下.”', '“꽃을 탐하는 벌과 나비는 거미줄에 걸려 목숨을 잃고, 꿩을 사랑하는 푸른 매는 산림에서 날개가 꺾이는 법이다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0043', '장면_이석단전_필사본_한국 이길환_001_S#0043', '이석단전', '李石丹傳', '3인칭', '한문', '生對曰:', '이생이 대답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0044', '장면_이석단전_필사본_한국 이길환_001_S#0044', '이석단전', '李石丹傳', '3인칭', '한문', '“彼女紅袖遮面, 如雲裏之明月, 玉顔開笑, 若水中之紅蓮也, 寧死何休?”', '“저 여인은 붉은 소매로 얼굴을 가리면 구름 속 밝은 달과 같고, 옥 같은 얼굴로 미소를 띠면 물속의 붉은 연꽃과 같은데 차라리 죽을지언정 어찌 저버리겠습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0045', '장면_이석단전_필사본_한국 이길환_001_S#0045', '이석단전', '李石丹傳', '3인칭', '한문', '父母, 知其不禁不辭, 囚生于石庫.', '그러자 이생의 부모는 그가 굽히지 않을 것을 말리지 못할 것을 알고 이에 이생을 석고(石庫) 안에 가두었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0046', '장면_이석단전_필사본_한국 이길환_001_S#0046', '이석단전', '李石丹傳', '3인칭', '한문', '出三日而還, 開視之, 生旣死矣.', '나온 지 사흘 뒤에 석고를 열어 살펴보니 이생은 이미 죽어 있었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0047', '장면_이석단전_필사본_한국 이길환_001_S#0047', '이석단전', '李石丹傳', '3인칭', '한문', '噬指書曰:', '그곳에는 손가락을 깨물어 남긴 글이 있었는데 살펴보니 그 글은 이러하다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0048', '장면_이석단전_필사본_한국 이길환_001_S#0048', '이석단전', '李石丹傳', '3인칭', '한문', '“人生非百歲, 君莫愛紅顔? 白骨成塵後, 何人訪碧山?”', '“인생은 백 년이 채 되지 않는데, 그대는 고운 얼굴을 사랑하지 않는가? 백골이 먼지가 된 뒤에는, 누가 벽산을 찾아오겠는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0049', '장면_이석단전_필사본_한국 이길환_001_S#0049', '이석단전', '李石丹傳', '3인칭', '한문', '父母奴僕, 皆見此書, 哀痛哭泣, 聲震雲宵', '부모와 하인들이 이 글을 보고 모두 애통해하고 울었으니 그 소리가 구름과 하늘을 뒤흔들었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0050', '장면_이석단전_필사본_한국 이길환_001_S#0050', '이석단전', '李石丹傳', '3인칭', '한문', '斂生于棺中, 置殯吉祥寺, 將進一七日也.', '이생을 관에 넣어 길상사(吉祥寺)에 안치하고 이레째 되는 날 제사를 지내려 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0051', '장면_이석단전_필사본_한국 이길환_001_S#0051', '이석단전', '李石丹傳', '3인칭', '한문', '女不知其故, 以李生不來, 企待爲難, 開窓視之, 但聞悲風竹', '당시 홍대는 이 연고를 알지 못하고 이생이 돌아오지 않자 기다리기가 힘들어 창문을 열고 밖을 보았으나 그저 슬픈 바람에 흔들리는 소리만 들려올 뿐이었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0052', '장면_이석단전_필사본_한국 이길환_001_S#0052', '이석단전', '李石丹傳', '3인칭', '한문', '作詩, 吟曰:', '그리하여 시를 지어 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0053', '장면_이석단전_필사본_한국 이길환_001_S#0053', '이석단전', '李石丹傳', '3인칭', '한문', '“昨夜東窓月, 今宵又東來, 人情不如月, 一去不還來.”', '“어젯밤 동쪽 창가에 비치던 달, 오늘 밤에도 동쪽에서 떠오르나, 사람 마음은 달과 같지 않으니, 한 번 떠나면 돌아오지를 않네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0054', '장면_이석단전_필사본_한국 이길환_001_S#0054', '이석단전', '李石丹傳', '3인칭', '한문', '作此之後 心胸脈脈, 涕泣如雨, 罔知所措, 四顧無親.', '이 시를 지은 뒤 홍대는 가슴이 막막해 눈물을 비처럼 흘리며 어찌할 바를 몰랐으니 사방을 둘러보아도 사고무친(四顧無親)이었다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0055', '장면_이석단전_필사본_한국 이길환_001_S#0055', '이석단전', '李石丹傳', '3인칭', '한문', '又作詩曰:', '또 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0056', '장면_이석단전_필사본_한국 이길환_001_S#0056', '이석단전', '李石丹傳', '3인칭', '한문', '“胸中自出無煙火, 十幅元襟半已燒. 若不思君雙淚眼, 此身應得變成灰.”', '“가슴 속에 연기 없는 마음의 불 절로 일어나, 열 폭 원앙금 중 다섯 폭이 이미 타버렸네. 그대 생각에 한 쌍의 눈물 흐르지 않았다면, 이 몸은 분명 병을 앓고 재로 변했으리.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0057', '장면_이석단전_필사본_한국 이길환_001_S#0057', '이석단전', '李石丹傳', '3인칭', '한문', '仍成惱疾之間,', '홍대는 더욱 답답해하여 괴로운 병을 앓던 사이', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0058', '장면_이석단전_필사본_한국 이길환_001_S#0058', '이석단전', '李石丹傳', '3인칭', '한문', '生之神魂, 變成生質, 一日忽登樓上.', '생의 혼령이 형체로 변하더니 하루는 홀연 누각 위로 올라왔다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0059', '장면_이석단전_필사본_한국 이길환_001_S#0059', '이석단전', '李石丹傳', '3인칭', '한문', '女驚喜且極, 遽問曰:', '홍대는 놀람과 기쁨이 극에 달해 다급히 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0060', '장면_이석단전_필사본_한국 이길환_001_S#0060', '이석단전', '李石丹傳', '3인칭', '한문', '“昔者, 郎君, 登此樓之時, 甚以爲難, 今步斯樓之日, 如何容易乎?”', '“예전에 낭군께서 이 누각에 올라왔을 때는 몹시 힘들어하셨는데 오늘 이 누각을 걸어 올라온 날은 어떻게 쉽게 하신 것입니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0061', '장면_이석단전_필사본_한국 이길환_001_S#0061', '이석단전', '李石丹傳', '3인칭', '한문', '石檀神靈, 微笑而答曰:', '이생이 미소 지으며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0062', '장면_이석단전_필사본_한국 이길환_001_S#0062', '이석단전', '李石丹傳', '3인칭', '한문', '“思君之切, 故如是急登也', '“그대를 그리워하는 마음이 간절해 훌쩍 날아오르게 되었습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0063', '장면_이석단전_필사본_한국 이길환_001_S#0063', '이석단전', '李石丹傳', '3인칭', '한문', '“喉渴, 酒水中. 欲飮”', '“목이 마르니 술을 마시고 싶소”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0064', '장면_이석단전_필사본_한국 이길환_001_S#0064', '이석단전', '李石丹傳', '3인칭', '한문', '女使梳鴨取酒, 以銀鐥進之.', '홍대는 소압에게 술과 은술잔을 가져오게 하여 건넸다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0065', '장면_이석단전_필사본_한국 이길환_001_S#0065', '이석단전', '李石丹傳', '3인칭', '한문', '飮後, 懷鐥, 卽曰:', '이생은 술을 마신 뒤 그 은그릇을 품에 간직하며 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0066', '장면_이석단전_필사본_한국 이길환_001_S#0066', '이석단전', '李石丹傳', '3인칭', '한문', '“予之父母, 明日欲行水陸齋, 命我請汝故 以來”', '“우리 부모님께서 오늘 길상사에서 수륙재(水陸齋)를 지내려 하시는데, 나더러 그대와 함께 가라고 말씀하셨습니다. 따라가겠습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0067', '장면_이석단전_필사본_한국 이길환_001_S#0067', '이석단전', '李石丹傳', '3인칭', '한문', '女曰:', '홍대는 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0068', '장면_이석단전_필사본_한국 이길환_001_S#0068', '이석단전', '李石丹傳', '3인칭', '한문', '“此非夫人之行, 欲辭.”', '“이는 여인이 행동이 아니니 사양하고자 합니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0069', '장면_이석단전_필사본_한국 이길환_001_S#0069', '이석단전', '李石丹傳', '3인칭', '한문', '强之曰:', '이생이 강하게 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0070', '장면_이석단전_필사본_한국 이길환_001_S#0070', '이석단전', '李石丹傳', '3인칭', '한문', '“汝非思我也. 同死不避.”', '“그대는 나를 그리워한 게 아닙니다. 만약 날 그리워한다면 비록 죽더라도 피하지 않을 것이오.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0071', '장면_이석단전_필사본_한국 이길환_001_S#0071', '이석단전', '李石丹傳', '3인칭', '한문', '女不得已, 從之與梳鴨, 偕到吉祥寺.', '홍대가 마지못해 소압과 함께 이생을 따라가 셋 모두 길상사로 향했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0072', '장면_이석단전_필사본_한국 이길환_001_S#0072', '이석단전', '李石丹傳', '3인칭', '한문', '橋邊, 桃花盛開.', '다리 근처에 이르니 복숭아꽃이 만발하였다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0073', '장면_이석단전_필사본_한국 이길환_001_S#0073', '이석단전', '李石丹傳', '3인칭', '한문', '已開枝贈洪臺, 未開枝贈梳鴨, 半枯枝自持.', '이생은 꽃을 꺾어 와서 이미 핀 가지는 홍대에게 주고 피지 않은 가지는 몸종 소압에게 주며 반쯤 시든 가지는 스스로 지녔다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0074', '장면_이석단전_필사본_한국 이길환_001_S#0074', '이석단전', '李石丹傳', '3인칭', '한문', '作詩曰:', '곧 오언절구 하나를 지어 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0075', '장면_이석단전_필사본_한국 이길환_001_S#0075', '이석단전', '李石丹傳', '3인칭', '한문', '“人生如草露, 會合不多時. 三人歸去路, 二人哭還來.”', '“인생은 풀잎 위 이슬과 같아, 만날 수 있는 시간이 길지 않구나. 세 사람이 함께 갔던 돌아갔던 길, 두 사람만 울면서 돌아오겠지.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0076', '장면_이석단전_필사본_한국 이길환_001_S#0076', '이석단전', '李石丹傳', '3인칭', '한문', '女聞此詩, 驚曰:', '홍대가 이 시를 듣고 놀라 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0077', '장면_이석단전_필사본_한국 이길환_001_S#0077', '이석단전', '李石丹傳', '3인칭', '한문', '“郎君, 何以出此言耶?”', '“낭군께서는 어째서 이런 말을 하십니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0078', '장면_이석단전_필사본_한국 이길환_001_S#0078', '이석단전', '李石丹傳', '3인칭', '한문', '卽橋, 生又吟曰:', '곧 다리에서 이생이 또 시를 읊었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0079', '장면_이석단전_필사본_한국 이길환_001_S#0079', '이석단전', '李石丹傳', '3인칭', '한문', '「詩」', '「여기에 시가 있었음」', '원본에는 아주 작은 글씨로 ''詩''라는 표시가 있음', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0080', '장면_이석단전_필사본_한국 이길환_001_S#0080', '이석단전', '李石丹傳', '3인칭', '한문', '“耿耿山中火, 郎君造墓時, 明月歸山中, 孤魂人不知.', '“깜빡거리는 산중의 불빛, 낭군의 무덤을 만들 때라네. 밝은 달 옛 산속을 돌아오는데, 고혼을 사람은 알지 못하네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0081', '장면_이석단전_필사본_한국 이길환_001_S#0081', '이석단전', '李石丹傳', '3인칭', '한문', '此三詩, 皆有惻然不泄之情, 然女不知生已死故.', '이 세 시는 모두 측연히 세상에 알려지지 정을 담고 있었는데 홍대는 이생이 이미 죽었다는 사실을 알지 못했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0082', '장면_이석단전_필사본_한국 이길환_001_S#0082', '이석단전', '李石丹傳', '3인칭', '한문', '偕到吉祥寺, 至涉門外,', '모두 길상사에 도착해 문밖에 다다랐다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0083', '장면_이석단전_필사본_한국 이길환_001_S#0083', '이석단전', '李石丹傳', '3인칭', '한문', '立謂二女曰:', '이생은 그곳에 서서 두 여인에게 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0084', '장면_이석단전_필사본_한국 이길환_001_S#0084', '이석단전', '李石丹傳', '3인칭', '한문', '“早晩待我出來.”', '“조금만 기다리면 내가 나올 것입니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0085', '장면_이석단전_필사본_한국 이길환_001_S#0085', '이석단전', '李石丹傳', '3인칭', '한문', '入後, 通曉不出, 始知生之已死.', '그러나 이생은 절 안으로 들어간 뒤로 밤이 새도록 나오지 않았으니 홍대는 그제서야 이생이 이미 죽었음을 알게 되었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0086', '장면_이석단전_필사본_한국 이길환_001_S#0086', '이석단전', '李石丹傳', '3인칭', '한문', '乃作詩曰:', '그리하여 시를 지었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0087', '장면_이석단전_필사본_한국 이길환_001_S#0087', '이석단전', '李石丹傳', '3인칭', '한문', '“梳鴨還歸去. 月落曉星殘. 折花分二贈, 郎君已亡魂.”', '“소압이 돌아간 뒤로, 달은 지고 새벽의 잔성만 남았네. 꽃가지 꺾어 나눠주었지만, 낭군은 이미 망혼이 되었네.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0088', '장면_이석단전_필사본_한국 이길환_001_S#0088', '이석단전', '李石丹傳', '3인칭', '한문', '此夜曉頭, 一僧灑掃開門, 問二女曰:', '이날 새벽 무렵 한 승려가 마당을 쓸며 문을 열고 두 여인에게 물었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0089', '장면_이석단전_필사본_한국 이길환_001_S#0089', '이석단전', '李石丹傳', '3인칭', '한문', '“何女也?”', '“그대들은 누구십니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0090', '장면_이석단전_필사본_한국 이길환_001_S#0090', '이석단전', '李石丹傳', '3인칭', '한문', '女曰:', '홍대가 대답했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0091', '장면_이석단전_필사본_한국 이길환_001_S#0091', '이석단전', '李石丹傳', '3인칭', '한문', '“昨夕, 石檀到吾家, 誘我曰: ‘予之父母明日, 欲行水陸齋, 命我率來’云 故遂到于此耳.”', '“어젯밤 이석단이 우리 집에 와서 저를 꾀며 “우리 부모가 내일 수륙재를 지내려 하니 나더러 데리고 오라고 하셨다.”라고 했다. 이곳에 드디어 이곳으로 오게 되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0092', '장면_이석단전_필사본_한국 이길환_001_S#0092', '이석단전', '李石丹傳', '3인칭', '한문', '其言, 又告于石檀之父,', '이 말을 이석단의 부친에게 알리자', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0093', '장면_이석단전_필사본_한국 이길환_001_S#0093', '이석단전', '李石丹傳', '3인칭', '한문', '父:', '이생의 부친이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0094', '장면_이석단전_필사본_한국 이길환_001_S#0094', '이석단전', '李石丹傳', '3인칭', '한문', '“昔聞, 夜中之女老狐, 戴人頭骨, 假成人像, 以欺回人. 石檀死經七日矣, 今從石檀云, 何以妄說之甚者乎? 是妖狐.”', '“예전에 듣기로는 밤중에 늙은 암여우가 사람의 두개골을 쓰고 인간의 형상을 빌려 사람들을 속인다고 한다. 내 아들이 죽은 지가 이미 칠 일이 지났는데 지금 석단 이야기를 가지고 운운하니 어찌 허황된 말을 이리 심하게 하는가? 이는 분명 요망한 여우로구나.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0095', '장면_이석단전_필사본_한국 이길환_001_S#0095', '이석단전', '李石丹傳', '3인칭', '한문', '令僕逐之.', '하인들 시켜 쫓아내자', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0096', '장면_이석단전_필사본_한국 이길환_001_S#0096', '이석단전', '李石丹傳', '3인칭', '한문', '洪臺曰:', '홍대가 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0097', '장면_이석단전_필사본_한국 이길환_001_S#0097', '이석단전', '李石丹傳', '3인칭', '한문', '“若不信吾言, 則別有驗事. 石檀到吾家之時, 喉渴酒水中欲飮, 以酒兼銀鐥而進之. 飮畢, 懷鐥而來.”', '“만약 제 말을 믿지 못하신다면 따로 증험할 일이 있습니다. 이석단께서 저의 집에 왔을 때 목이 말라 술을 달라고 하여 술과 은술잔을 함께 드린 적이 있습니다. 그때 이생께서는 술을 마신 후 은술잔을 품고 돌아갔습니다.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0098', '장면_이석단전_필사본_한국 이길환_001_S#0098', '이석단전', '李石丹傳', '3인칭', '한문', '其父初不爲信, 然欲知女之妖眞, 開棺視之.', '이생의 부친은 처음에는 믿지 않았으나 그녀가 요괴인지 아닌지 확인하고자 관을 열어보았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0099', '장면_이석단전_필사본_한국 이길환_001_S#0099', '이석단전', '李石丹傳', '3인칭', '한문', '紅顔似醉, 懷中果有銀鐥, 始知女之至誠之意, 竟請獻', '그러자 이생은 술에 취한 듯 붉은 얼굴에 품속에 과연 은 술잔이 들어 있었으니 그제서야 홍대의 지극정성한 뜻을 알고 마침내 공양을 올리도록 청했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0100', '장면_이석단전_필사본_한국 이길환_001_S#0100', '이석단전', '李石丹傳', '3인칭', '한문', '洪臺, 卽脫綃衫, 造幡掛佛前, 燃香奉佛成誓曰:', '홍대는 곧장 비단옷을 벗고 깃발을 만들어 부처 앞에 걸어둘 깃발을 만들고 향을 피워 부처께 바치며 이렇게 맹세했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0101', '장면_이석단전_필사본_한국 이길환_001_S#0101', '이석단전', '李石丹傳', '3인칭', '한문', '“日月何處不照, 先照於高山之嶺. 諸佛何人不濟? 先濟於我願之人乎.”', '“해와 달은 어디인들 비추지 않겠는가마는, 먼저 높은 산의 고개를 비추고, 모든 부처님이 누군들 돕지 않겠는가마는, 먼저 우리가 원하는 사람을 구제하시리라.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0102', '장면_이석단전_필사본_한국 이길환_001_S#0102', '이석단전', '李石丹傳', '3인칭', '한문', '有頃假寐, 夢中仙人, 自天降來曰:', '그러다 잠깐 선잠을 잤는데 꿈 속에 선인(仙人)이 하늘로부터 내려와 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0103', '장면_이석단전_필사본_한국 이길환_001_S#0103', '이석단전', '李石丹傳', '3인칭', '한문', '“汝命百有六旬, 分爾之命, 半給於石檀. 各授八十, 終身同住.”', '“네 수명은 160년이었으나 너의 수명을 나누어 그 절반을 이석단에게 줄 것이다. 각각 팔십 년을 줄테니 죽을 때까지 함께 지내거라.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0104', '장면_이석단전_필사본_한국 이길환_001_S#0104', '이석단전', '李石丹傳', '3인칭', '한문', '言訖, 乗雲而去.', '선인은 말을 마치고 구름을 타고 떠나갔다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0105', '장면_이석단전_필사본_한국 이길환_001_S#0105', '이석단전', '李石丹傳', '3인칭', '한문', '已而, 欠伸而覺, 乃一夢也.', '이윽고 기지개를 켜고 일어나보니 곧 꿈이었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0106', '장면_이석단전_필사본_한국 이길환_001_S#0106', '이석단전', '李石丹傳', '3인칭', '한문', '卽就殯前開棺, 合抱石檀之胸,', '홍대가 곧바로 이생의 관 앞에 가서 관을 열고 이생의 가슴을 껴안으니,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0107', '장면_이석단전_필사본_한국 이길환_001_S#0107', '이석단전', '李石丹傳', '3인칭', '한문', '移時更甦.', '잠시 후 이생이 되살아났다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0108', '장면_이석단전_필사본_한국 이길환_001_S#0108', '이석단전', '李石丹傳', '3인칭', '한문', '携來其家, 婦夫偕和, 如合符節', '그녀는 그를 집으로 데려와 부부가 되어 화목하게 어울렸으니 부절(符節)을 맞춘 듯했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0109', '장면_이석단전_필사본_한국 이길환_001_S#0109', '이석단전', '李石丹傳', '3인칭', '한문', '兩人願誓曰:', '두 사람은 이렇게 맹세하였다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0110', '장면_이석단전_필사본_한국 이길환_001_S#0110', '이석단전', '李石丹傳', '3인칭', '한문', '“在天願作比翼鳥, 在地願爲連理枝. 共盡八十同死生, 天長地久永相隨.”', '“하늘에서는 비익조(比翼鳥)가 되길 원하고, 땅에서는 연리지(連理枝)가 되길 바라네. 모두 80세가 되기까지 생사를 같이하며, 천지처럼 오래도록 영원히 서로 따르리라.”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0111', '장면_이석단전_필사본_한국 이길환_001_S#0111', '이석단전', '李石丹傳', '3인칭', '한문', '年至八十一歲, 俱沒.', '나이가 81세가 되자 두 사람은 같은 날 세상을 떠났다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0112', '장면_이석단전_필사본_한국 이길환_001_S#0112', '이석단전', '李石丹傳', '3인칭', '한문', '時人, 有詩曰:', '사람들은 이를 보고 시를 지었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0113', '장면_이석단전_필사본_한국 이길환_001_S#0113', '이석단전', '李石丹傳', '3인칭', '한문', '“寂寞深山裡, 雙魂一時歸. 可憐夫婦室. 生死一探探.”', '“쓸쓸한 깊은 산속에서, 두 혼령이 같은 때에 돌아갔네. 가련하구나! 부부의 방이여, 생사가 하나로 얽혀있구나."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0114', '장면_이석단전_필사본_한국 이길환_001_S#0114', '이석단전', '李石丹傳', '3인칭', '한문', '合葬於基山之墓, 邊忽生連理枝. 鴛鴦一雙, 常集自樹之上, 棲不離之.', '그들은 북산 기슭의 무덤에 합장되었는데 무덤가에 홀연히 연리지가 돋아났다. 또 원앙 한 쌍이 늘 이 나무 위에 모여들어 깃들어 떠나지를 않았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLSDJ01NU001P0115', '장면_이석단전_필사본_한국 이길환_001_S#0115', '이석단전', '李石丹傳', '3인칭', '한문', '世之人以爲奇事, 至今稱歎焉.', '세상 사람들은 이를 기이한 일로 여겨 지금까지도 칭송하고 감탄했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0001', '장면_이진사효행록_한국 대전시립박물관_001_S#0001', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '漢陽南山洞, 有李進士者, 名不知, 而本士族也.', '한양(漢陽) 남산동(南山洞)에 이진사(李進士)이라는 자가 있었으니 이름은 알지 못하나 사족(양반) 출신이다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0002', '장면_이진사효행록_한국 대전시립박물관_001_S#0002', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '家道窭空, 門庭荒涼, 奉七耆慈母,', '집안이 가난해 문정(門庭)도 텅 빈 채로 일흔 살의 모친을 봉양하고 있었는데,', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0003', '장면_이진사효행록_한국 대전시립박물관_001_S#0003', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '而辛壬癸甲之運凶, 夫乞妻織, 以奉甘旨.', '4년 동안[辛壬癸甲] 흉년이 드는 바람에 이 진사는 구걸하고 아내는 베를 짜며 맛좋은 음식을 올렸다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0004', '장면_이진사효행록_한국 대전시립박물관_001_S#0004', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '其爲誠孝, 出自天性, 揜體糊口, 艱難甚矣.', '그들의 지극한 효성은 천성에서 나왔으나 몸만 가리고 입만 풀칠할 정도로 몹시 힘들게 지냈다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0005', '장면_이진사효행록_한국 대전시립박물관_001_S#0005', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '己丑二月日, 不幸遭內艱, 進士夫妻之攀號擗踊, 已無可言.', '기축년 2월 어느 날 불행히도 모친상을 당하니 진사 부부는 가슴을 두드리고 땅을 차며 이루 말할 수 없는 지경이었다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0006', '장면_이진사효행록_한국 대전시립박물관_001_S#0006', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '而奄至四日,無路斂屍,人子至情,豈有生意?', '그러나 사흘이 지나도록 시신을 염할 방도가 없었으니 자식의 지극한 정으로 어찌 살아갈 마음이 생기겠는가?', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0007', '장면_이진사효행록_한국 대전시립박물관_001_S#0007', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '計窮思縮,自料於心,曰:', '계속하여 계책을 궁리해 보다가 혼자 마음속으로 이렇게 생각했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0008', '장면_이진사효행록_한국 대전시립박물관_001_S#0008', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“寧欲自鬻,以斂母屍.”', '“차라리 나를 팔아서 모친의 시신을 염습해야 겠구나.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0009', '장면_이진사효행록_한국 대전시립박물관_001_S#0009', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '言于夫人,', '이를 부인에게 이야기하자', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0010', '장면_이진사효행록_한국 대전시립박물관_001_S#0010', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人聞而痛哭曰:', '부인이 듣고는 통곡하며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0011', '장면_이진사효행록_한국 대전시립박물관_001_S#0011', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“至矣盡矣!夫子之言.罔極之中,發誠如是,妾何獨全?亦賣吾身,可以無憾.”', '“그대의 말씀이 지극하고 극진합니다. 망극한 가운데 이토록 정성을 드러내시니 제가 어찌 홀로 몸을 보전하겠습니까? 또한 제 몸을 팔아서 유감이 없게 할 것입니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0012', '장면_이진사효행록_한국 대전시립박물관_001_S#0012', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士曰:', '진사가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0013', '장면_이진사효행록_한국 대전시립박물관_001_S#0013', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“吾則男子,賣之無傷,君以士族家婦女,豈忍爲此?”', '“나는 남자라 몸을 팔아도 해될 것이 없으나 그대는 사족 집안의 부녀(婦女)인데 어찌 차마 이런 일을 하십니까?”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0014', '장면_이진사효행록_한국 대전시립박물관_001_S#0014', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人痛哭曰:', '부인이 통곡하며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0015', '장면_이진사효행록_한국 대전시립박물관_001_S#0015', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“妾聞之,女子有嫁,遠父母,離兄弟,死生榮辱,專委於夫子.夫子旣爲親賣身,欲盡人子之道,則妾何獨廢其人婦之道乎?”', '“첩이 듣기로는 여자가 시집을 가면 부모와도 멀어지고 형제와도 떨어져 사생과 영욕을 남편에게 전부 맡긴다고 했습니다. 부군께서 이미 모친을 위해 몸을 팔아 자식의 도리를 다하려고 하시는데 제가 어찌 홀로 부인의 도를 저버리겠습니까?', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, '『시경(詩經)』‧「국풍(國風‧천수(泉水)」', NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0016', '장면_이진사효행록_한국 대전시립박물관_001_S#0016', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人二人,拊屍痛哭,俱以喪服,奔往鰲興府院宅,扣門請謁.', '부부가 함께 시신을 붙들고 통곡하며 함께 상복을 차려입고 오흥 부원군(鰲興府院君)댁으로 달려가 문을 두드리며 뵙기를 청했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0017', '장면_이진사효행록_한국 대전시립박물관_001_S#0017', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '閽者入告曰:', '그러자 문지기가 들어가 아뢰었다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0018', '장면_이진사효행록_한국 대전시립박물관_001_S#0018', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“有人到門,謂有急事,乞求現謁.”', '“어떤 사람이 문에 찾아와 급한 일이 있다고 하며 뵙기를 간곡히 청하고 있습니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0019', '장면_이진사효행록_한국 대전시립박물관_001_S#0019', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '卽招入,', '곧 부름을 받고 들어오니', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0020', '장면_이진사효행록_한국 대전시립박물관_001_S#0020', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '問曰:', '오흥부 관원이 물었다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0021', '장면_이진사효행록_한국 대전시립박물관_001_S#0021', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“汝是何人?有何急事而來耶?”', '“너는 어떠한 사람이냐?무슨 급한 일이 있길래 여기를 왔느냐?”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0022', '장면_이진사효행록_한국 대전시립박물관_001_S#0022', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士曰:', '진사가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0023', '장면_이진사효행록_한국 대전시립박물관_001_S#0023', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“小人,卽南山洞李進士宅奴子也.奴矣上典,素來寒儒,家道零替,中大夫人喪事.出於不意,初終凡需,勢難猝辦,小人夫妻,斯速賣納之意分付.故仰慕大監宅厚恤奴僕之盛德,敢來請賣.”', '“소인은 곧 남산동 이진사 댁의 노비입니다.저의 상전은 본래 빈한한 선비로 살림이 몹시 어려웠는데 중대부인(中大夫人)이 세상을 떠나게 되었습니다.뜻하지 않게 일어난 일이어서 초종례의 모든 음식을 갑자기 마련하기 어려운 상황입니다.저희 부부에게 서둘러 몸을 팔라는 분부를 들었습니다.그래서 대감댁이 노복을 몹시 어여삐 여기신다는 성대한 덕을 우러러 사모하여 감히 여기에 찾아와 매신(賣身)하기를 청합니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0024', '장면_이진사효행록_한국 대전시립박물관_001_S#0024', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '鰲興曰:', '오흥댁이 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0025', '장면_이진사효행록_한국 대전시립박물관_001_S#0025', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“矜哉!汝宅形勢也.汝言若此,買則買矣,只聞汝言,事近無常,必受牌子而來.”', '“너희 집안의 형편이 참으로 딱하구나.너의 말이 이러하니 너희를 사들인다면 사들이겠다만,너의 말을 들어보면 일이 변덕스러울 수 있으니 반드시 패자(牌子)를 받아서 오거라.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0026', '장면_이진사효행록_한국 대전시립박물관_001_S#0026', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士卽歸本家,自筆牌子而去.', '진사가 곧장 본가로 돌아가 스스로 패자를 작성해 오흥댁으로 갔다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0027', '장면_이진사효행록_한국 대전시립박물관_001_S#0027', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '則鰲興見而信之,給價五十兩而買之.', '오흥댁이 이를 보고 그의 말을 믿어 오십 냥으로 값을 지불하여 그들을 샀다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0028', '장면_이진사효행록_한국 대전시립박물관_001_S#0028', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士曰:', '진사가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0029', '장면_이진사효행록_한국 대전시립박물관_001_S#0029', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“小人旣爲大監宅奴婢,此後死生,專在於大監命下.第伏念舊主喪側,無他使喚,小人暫治,喪後卽還.敢請處分.”', '“소인이 대감댁의 노비가 되었으니 앞으로의 사생은 전부 대감의 말씀에 달려있습니다.다만 생각건대 옛 주인의 상측(喪側)에 다른 심부름꾼이 없으니 소인이 잠깐 도왔다가 상이 마치면 곧 돌아오겠습니다.부디 처분해주기를 청합니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0030', '장면_이진사효행록_한국 대전시립박물관_001_S#0030', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '大監曰:', '대감이 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0031', '장면_이진사효행록_한국 대전시립박물관_001_S#0031', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“善哉,是言.始勤如此,豈慮終怠?”', '“그 말이 참으로 좋구나.처음의 부지런함이 이와 같으니 어찌 나중에 게으를 것을 염려하겠는가?”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0032', '장면_이진사효행록_한국 대전시립박물관_001_S#0032', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '許令往護.', '그러고는 가서 돕도록 허락 해주었다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0033', '장면_이진사효행록_한국 대전시립박물관_001_S#0033', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士曰:', '진사가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0034', '장면_이진사효행록_한국 대전시립박물관_001_S#0034', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“只留一張牌子而去.事涉疎虞,小人之妻留此而去.”', '“패자 한 장만 두고 떠나겠습니다.일이 잘못될 수 있으니 소인의 아내를 여기에 남기고 가겠습니다..”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0035', '장면_이진사효행록_한국 대전시립박물관_001_S#0035', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '大監曰:', '대감이 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0036', '장면_이진사효행록_한국 대전시립박물관_001_S#0036', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“諾.依爲之.”', '“알겠다.그렇게 하거라.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0037', '장면_이진사효행록_한국 대전시립박물관_001_S#0037', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士獨負錢而來,', '진사가 홀로 돈을 짊어지고 본가로 와서', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0038', '장면_이진사효행록_한국 대전시립박물관_001_S#0038', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '斂殯之節,盡誠爲之,如此景狀,窮天罔極.', '염습과 초빈의 절차를 지극정성으로 다했으니 이러한 모습은 끝없는 하늘처럼 망극했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0039', '장면_이진사효행록_한국 대전시립박물관_001_S#0039', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '此時,進士夫人在於鰲興宅,晝則談笑自若,夜則血淚沾席.', '이때 진사의 부인이 오흥댁에 남아 있으면서 낮에는 아무렇지도 않게 담소를 나눴으나 밤에는 피눈물로 침상을 적셨다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0040', '장면_이진사효행록_한국 대전시립박물관_001_S#0040', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '凡于事投,盡誠盡忠,事事稱善.針線紡績,亦出諸婢,嬌容艶態,極佳且雅,大監愛而欲狎之.', '그녀는 모든 일에 성심과 정성을 다해 집안사람들이 일마다 잘한다고 칭찬했다.바느질과 길쌈 역시 다른 여종들보다 뛰어났으며 아리따운 용모와 예쁜 자태가 몹시 아름답고 고왔으니 대감이 아끼고 가까이하고자 했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0041', '장면_이진사효행록_한국 대전시립박물관_001_S#0041', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '鰲興夫人知其意向,卽爲下堂,定爲洗踏.', '오흥댁 부인이 남편의 마음을 알아차리고 곧장 진사 부인을 당으로 내려보내 빨래를 하도록 정했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0042', '장면_이진사효행록_한국 대전시립박물관_001_S#0042', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '婢班中,有一老嫗,見夫人之性質柔順,怜其苦役,同作分勞.', '여종 중에 한 노구(老嫗)가 부인의 성품이 유순한 것을 보고는 그녀의 고된 일을 딱하게 여겨 함께 일을 나누었다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0043', '장면_이진사효행록_한국 대전시립박물관_001_S#0043', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '李進士曾有叛奴,聞喪報來.', '한편 이 진사에게는 원래 도망쳤던 노비가 있었는데 그 노비가 상중이라는 전보를 듣고 왔다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0044', '장면_이진사효행록_한국 대전시립박물관_001_S#0044', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '哭喪側畢,告于進士曰:', '노비는 상측에서 곡을 마치고 진사에게 아뢰었다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0045', '장면_이진사효행록_한국 대전시립박물관_001_S#0045', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“宅本至窮,初終諸節,何以備禮耶?”', '“상전의 집은 본래 지극히 가난한데 초종례의 절차를 지내셨으니 어떻게 예식을 갖추셨습니까?”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0046', '장면_이진사효행록_한국 대전시립박물관_001_S#0046', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士曰:', '진사가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0047', '장면_이진사효행록_한국 대전시립박물관_001_S#0047', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“顧此窮儒,誰能救助?”', '“돌아보건대 이 가난한 선비를 누가 도와주겠는가?”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0048', '장면_이진사효행록_한국 대전시립박물관_001_S#0048', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴曰:', '노비가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0049', '장면_이진사효행록_한국 대전시립박물관_001_S#0049', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“阿只氏安在?”', '“아씨는 어디에 계십니까?”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0050', '장면_이진사효행록_한국 대전시립박물관_001_S#0050', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士黙然不答,含淚而已.', '진사가 묵묵히 아무 대답도 못하고 눈물만 머금었다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0051', '장면_이진사효행록_한국 대전시립박물관_001_S#0051', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴曰:', '노비가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0052', '장면_이진사효행록_한국 대전시립박물관_001_S#0052', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“小人不忠,雖有叛名,曾被厚眷,恩已深矣.誠欲現謁,伏望指敎焉.”', '“소인이 불충해 비록 배반했다는 오명이 있으나 일전에 두터운 정성을 입었으니 은혜가 이미 깊습니다.정성을 다해 주인님을 뵙고자 하니 바라건대 말씀을 내려주십시오.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0053', '장면_이진사효행록_한국 대전시립박물관_001_S#0053', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士痛哭曰:', '진사가 통곡하며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0054', '장면_이진사효행록_한국 대전시립박물관_001_S#0054', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“汝之多問,出於至誠,豈忍諱秘?遭此巨創,多日未斂,百計無策.吾之內外,俱買於鰲興府院君宅.汝之內上典,在彼仰役,吾則治喪次姑留耳.”', '“너의 많은 질문들이 지극한 정성에서 나왔으니 어찌 차마 숨기겠는가?내가 큰 불행을 당해 여러 날 동안 시신을 염습을 하지 못했는데 온갖 방법으로도 어찌할 도리가 없었다.그래서 우리 부부 모두 오흥 부원군 댁에 몸을 팔았다.네 안주인도 그곳에서 일하고 있으며 나는 상례를 치르며 잠시 머물러 있을 뿐이다.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0055', '장면_이진사효행록_한국 대전시립박물관_001_S#0055', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴聞大驚大哀,擗地痛哭曰:', '노비가 그 말을 듣고 몹시 놀라고 슬퍼하고는 땅을 치며 통곡했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0056', '장면_이진사효행록_한국 대전시립박물관_001_S#0056', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“天道無心,偏使孝子貧窮,世上豈有此慘哀之事耶?請其往現.”', '“천도가 무심하여 멋대로 효자를 빈궁하게 만들었으니 세상에 어찌 이렇게 참담하고 슬픈 일이 있습니까?제가 가서 아가씨를 뵙겠습니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0057', '장면_이진사효행록_한국 대전시립박물관_001_S#0057', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '進士驚止曰:', '진사가 놀라며 만류했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0058', '장면_이진사효행록_한국 대전시립박물관_001_S#0058', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“此何言!此何言也!愼勿更煩.”', '“이게 무슨 소리냐!이게 무슨 소리냐!더 이상 번거롭게 하지 마라.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0059', '장면_이진사효행록_한국 대전시립박물관_001_S#0059', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '强請不已,知其難禁,乃作一封書而送之曰:', '그러나 노비가 계속하여 억지로 간청하자 진사는 이를 막기 어렵다는 것을 알고 마침내 편지 한 통을 써서 건네며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0060', '장면_이진사효행록_한국 대전시립박물관_001_S#0060', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“汝須密訪,傳此書.切勿形色.毋使見疑於人也.”', '“너는 반드시 몰래 찾아가 이 편지를 전달하거라.절대로 겉으로 드러내지 말고 남들에게 의심을 사서는 아니된다.”', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0061', '장면_이진사효행록_한국 대전시립박물관_001_S#0061', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴承命,往訪曰:', '노비가 명을 받들어 오흥댁을 찾아가 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집, 오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0062', '장면_이진사효행록_한국 대전시립박물관_001_S#0062', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“此宅新買婢,卽吾昔日班下也,今欲一見而來矣.”', '“이 집이 새로 노비를 샀다고 하는데 저는 이전의 양반집 하인으로 오늘 한번 보고자 찾아왔습니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0063', '장면_이진사효행록_한국 대전시립박물관_001_S#0063', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '閽者答曰:', '문지기가 대답했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0064', '장면_이진사효행록_한국 대전시립박물관_001_S#0064', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“浣紗於南山下時,未還來耳.”', '“남산 아래에서 빨래를 하고 있을 시간인데 아직 돌아오지 않았다.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0065', '장면_이진사효행록_한국 대전시립박물관_001_S#0065', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴卽轉往訪之,則果與老嫗,同坐方洗.', '노비가 곧 돌아가서 부인을 찾아보았는데 과연 노구와 함께 앉아서 빨래를 하고 있었다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0066', '장면_이진사효행록_한국 대전시립박물관_001_S#0066', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '趨前拜謁,', '노비가 부인의 앞으로 달려가 인사를 올리자', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0067', '장면_이진사효행록_한국 대전시립박물관_001_S#0067', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人慮其情跡之綻露,佯若不知,外面而語曰:', '부인이 그간의 정황이 탄로날까 염려하여 일부러 모른 체하고는 얼굴을 돌리며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0068', '장면_이진사효행록_한국 대전시립박물관_001_S#0068', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“素昧何狀人,拜之,必也狂人也.”', '“평소 알던 사람이 아닌데 절을 하니 분명 미친 사람이다.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0069', '장면_이진사효행록_한국 대전시립박물관_001_S#0069', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '更不回顧,', '그러고는 더는 돌아보지 않자', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0070', '장면_이진사효행록_한국 대전시립박물관_001_S#0070', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴乃痛哭曰:', '노비가 곧 통곡하며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0071', '장면_이진사효행록_한국 대전시립박물관_001_S#0071', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“阿只氏不知小人耶?本非狂人.前日叛奴某也.”', '“아가씨는 소인을 모르겠습니까?저는 미친 사람이 아닙니다.예전에 도망쳤던 노비 아무개입니다.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SLJSHHR01NU001P0072', '장면_이진사효행록_한국 대전시립박물관_001_S#0072', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '因納書封,夫人不得已受之,納諸懷中,卓然更洗.', '그러고는 편지를 건네자 부인이 하는 수 없이 받고 품 속에 넣고 아무렇지 않은 듯 다시 빨래를 했다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0073', '장면_이진사효행록_한국 대전시립박물관_001_S#0073', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '老嫗聞此奴言,忽生訝,或問其奴曰:', '노구가 이 노비의 말을 듣고 문득 의심이 들어 그 노비에게 물었다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0074', '장면_이진사효행록_한국 대전시립박물관_001_S#0074', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“我聞汝言,必有曲折.毋隱直吐.”', '“내가 너의 말을 들어보니 분명 사연이 있구나.숨기지 말고 바른대로 말하거라.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0075', '장면_이진사효행록_한국 대전시립박물관_001_S#0075', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '再三詰問,', '이렇게 누차 추궁하자', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0076', '장면_이진사효행록_한국 대전시립박물관_001_S#0076', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '奴始陳其自賣之事情.', '노비가 그제서야 이진사가 매신한 사정을 밝혔다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0077', '장면_이진사효행록_한국 대전시립박물관_001_S#0077', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '老嫗聽罷,心切惻隱,乃謂夫人曰:', '노구가 다 듣고 속으로 몹시 측은히 여기고는 곧 부인에게 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0078', '장면_이진사효행록_한국 대전시립박물관_001_S#0078', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“吾有事還家,待吾出來.”', '“내가 일이 있어 집에 다녀올 것이니 내가 갔다 오기까지 기다려라.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0079', '장면_이진사효행록_한국 대전시립박물관_001_S#0079', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人乘間嚼指,血書答付,', '부인이 그 틈을 타 손가락을 물어 뜯어 혈서로 답장을 지었으니', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0080', '장면_이진사효행록_한국 대전시립박물관_001_S#0080', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '老嫗蹶然入去,具告厥由.', '노구가 서둘러 들어가 곧바로 그간의 사정을 대감께 전달했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0081', '장면_이진사효행록_한국 대전시립박물관_001_S#0081', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '大監亦爲驚惑,卽使率來.', '대감이 또한 놀라고 의아해하며 곧장 부인을 데려오게 했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0082', '장면_이진사효행록_한국 대전시립박물관_001_S#0082', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '老嫗急還,謂曰:', '노구가 서둘러 돌아가 부인에게 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁, 남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0083', '장면_이진사효행록_한국 대전시립박물관_001_S#0083', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“大監有招矣.”', '“대감께서 부르신다.”', NULL, '조선', '현실계', '한국 한양_남산동', '남산 빨래터', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0084', '장면_이진사효행록_한국 대전시립박물관_001_S#0084', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '卽與偕入,則大監使之近坐,從容問曰:', '곧 노구가 부인과 함께 들어왔으니 대감이 가까이 앉히게 하고 차분히 물었다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0085', '장면_이진사효행록_한국 대전시립박물관_001_S#0085', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“俄聞老婢所告,心甚訝鬱.毋隱直告.”', '“방금 노비가 말해준 일을 들으니 마음이 몹시 이상하고 답답하구나.숨김 없이 솔직히 말하라.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0086', '장면_이진사효행록_한국 대전시립박물관_001_S#0086', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人節節秘之,一向不吐.', '그러나 부인은 전부 숨기며 줄곧 입을 열지 않았다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0087', '장면_이진사효행록_한국 대전시립박물관_001_S#0087', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '大監曰:', '대감이 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0088', '장면_이진사효행록_한국 대전시립박물관_001_S#0088', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“終若隱諱,則買賣兩家,將有不好之擧,何執迷若是耶?”', '“끝내 그렇게 숨긴다면 두 집안의 사람을 매매한 일로 장차 좋지 않은 일들이 일어날 텐데 어찌 이렇게 고집스럽게 구느냐?”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0089', '장면_이진사효행록_한국 대전시립박물관_001_S#0089', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '夫人聞其‘兩家不好’之說,始陳實狀.', '부인이 두 집안에 좋지 않게 된다는 말을 듣고 그제서야 이실직고했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0090', '장면_이진사효행록_한국 대전시립박물관_001_S#0090', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '大監驚起,拜謝曰:', '대감이 놀라서 일어나며 배사했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0091', '장면_이진사효행록_한국 대전시립박물관_001_S#0091', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“安知夫人有如此卓異之節孝也?”', '“부인께서 이렇게 뛰어난 절효(節孝)를 지녔을 줄 어찌 알았겠습니까?”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0092', '장면_이진사효행록_한국 대전시립박물관_001_S#0092', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '卽起,闔門而出,分付老婢曰:', '곧장 일어나서 문을 열고 나와 노비들에게 분부했다.', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0093', '장면_이진사효행록_한국 대전시립박물관_001_S#0093', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“別掃中堂,陪此夫人.”', '“따로 중당(中堂)을 청소하고 이 부인을 모시거라.”', NULL, '조선', '현실계', '한국 한양_남산동', '오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0094', '장면_이진사효행록_한국 대전시립박물관_001_S#0094', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '命治轎子,親自陪行,輸錢三百緡,而臨其家賻儀.', '가마를 준비하라고 명하니 노비들이 몸소 행차를 모시고3백만 전을 보내어 그 집에 부의했다.', NULL, '조선', '현실계', '한국 한양_남산동', '이진사 집, 오흥댁', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0095', '장면_이진사효행록_한국 대전시립박물관_001_S#0095', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '翌日入侍,奏達筵中,', '다음날 대감이 조정에 들어가 임금을 모시다가 경연에 이 일을 아뢰자', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0096', '장면_이진사효행록_한국 대전시립박물관_001_S#0096', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '上曰:', '임금이 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0097', '장면_이진사효행록_한국 대전시립박물관_001_S#0097', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“孝矣,此人也.如此之孝,千古無雙,特自賻以六百兩.”', '“이 사람은 참으로 효성스럽구나.이러한 효심은 천고에도 둘도 없으니 특별히 직접 육백 냥을 부의 할 것이다.”', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0098', '장면_이진사효행록_한국 대전시립박물관_001_S#0098', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '顧謂侍臣曰:', '그리고 신하들을 돌아보며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0099', '장면_이진사효행록_한국 대전시립박물관_001_S#0099', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“予亦致賻,卿等隨力賻之.”', '“나 또한 부의를 표할 것이니,경들도 역량에 따라 부의하라.”', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0100', '장면_이진사효행록_한국 대전시립박물관_001_S#0100', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '因卽傳敎曰:', '이에 전교하며 말했다.', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0101', '장면_이진사효행록_한국 대전시립박물관_001_S#0101', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '“求忠臣,於孝子之門,若是出天之孝,則於國必爲忠臣.”', '“충신은 효자의 가문에서 구해야 하니 만약 하늘이 낸 효성이라면 나라에 반드시 충성스러운 신하가 될 것이다.”', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, '후한서(後漢書) 〈위표열전(韋彪列傳)〉', NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0102', '장면_이진사효행록_한국 대전시립박물관_001_S#0102', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '其夫人卽立旌門,先獎其行,李某待闋服調用.', '그리하여 그 부인에게 정려문을 세워 먼저 그 행실을 표창하고 이진사도 3년상을 마치기를 기다렸다가 벼슬에 임명시켰다.', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0103', '장면_이진사효행록_한국 대전시립박물관_001_S#0103', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '使聞閭巷之愚夫愚婦,曉然知之.', '이를 통해 여항의 일반 백성들에게 소문이 나게 하여 분명히 알도록 했다.', NULL, '조선', '현실계', '한국 한양_남산동', '대궐', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0104', '장면_이진사효행록_한국 대전시립박물관_001_S#0104', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '亦以此設科擧題,則賣身斂姑屍.', '또 이 일을 가지고 과제(科題)를 내걸었으니 문제는‘몸을 팔아 시어머니의 시신을 염습하다.’이다.', NULL, '조선', '현실계', '한국 한양_남산동', '특정 불필요', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SLJSHHR01NU001P0105', '장면_이진사효행록_한국 대전시립박물관_001_S#0105', '이진사효행록', '李進士孝行錄', '3인칭', '한문', '英宗朝四十六年,己丑年事也,鰲興府院君,卽慶州金漢耇,英宗大王國舅,後妃莊僖王后之父也.', '이 이야기는 영종(英宗) 46년 기축(己丑)년 일로 오흥부원군은 곧 경주(慶州)의 김한구(金漢耇)이니 영조대왕의 장인어른이자 후비 정순 왕후[莊僖王后]의 부친이다.', NULL, '평결부', '평결부', '평결부', '평결부', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0001', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0001', '조신', '調信', '3인칭', '한문', '昔, 新羅爲京師時, 有世達寺【今興敎寺也】之莊舍, 在溟州㮈李郡【按地理志, 溟州無㮈李郡, 唯有㮈城郡, 本㮈生郡, 今寧越. 又牛首州領縣, 有㮈靈郡, 本㮈已郡, 今剛州. 牛首州, 今春州. 今言㮈李郡, 未知孰是.】.', '옛날 신라가 도읍이었을 때, 세달사(世達寺)【지금의 흥교사(興敎寺)다】의 장원이 명주(溟州) 나리군(㮈李郡)에 있었다. 【지리지를 살펴보면 명주에는 날리군(㮈李郡)이 없고 오직 날성군(㮈城郡)만 있으니 원래는 날생군(㮈生郡)으로 지금의 영월(寧越)이다. 또한 우수주(牛首州) 영현(領縣)에 날령군(㮈靈郡)이 있는데 원래는 날이군(㮈已郡)으로 지금의 강주(剛州)다. 우수주(牛首州)는 지금은 춘주(春州)인데 지금 날리군이라고 말했으니 누가 옳은지 알지 못하겠다.】', NULL, '신라', '현실계', '한국 강원도_영월군_영월읍', '세달사(世達寺)_장원(莊舍)', '-', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0002', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0002', '조신', '調信', '3인칭', '한문', '本寺遣僧調信, 爲知莊.', '세달사에서 조신(調信)을 보내 장원을 관리하게 했다.', NULL, '신라', '현실계', '한국 강원도_영월군_영월읍', '세달사(世達寺)_장원(莊舍)', '조신', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0003', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0003', '조신', '調信', '3인칭', '한문', '信到莊上, 悅太守金昕公之女, 惑之深,', '조신이 장원에 도착해 태수(太守) 김흔(金昕)의 딸을 좋아해 그녀에게 깊이 반해', NULL, '신라', '현실계', '한국 강원도_영월군_영월읍', '세달사(世達寺)_장원(莊舍)', '조신, 김낭자(김흔의 딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0004', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0004', '조신', '調信', '3인칭', '한문', '屢就洛山大悲前, 潛祈得幸.', '자주 낙산대비(洛山大悲:관음보살) 앞에 나아가서 몰래 그녀와 맺어지게 해달라고 빌었다.', NULL, '신라', '현실계', '한국 강원도_양양군_강현면', '낙산사(落山寺)_대비전(大悲殿)', '조신', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0005', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0005', '조신', '調信', '3인칭', '한문', '方數年間, 其女已有配矣.', '그러나 곧 몇 년 사이에 그 딸이 이미 배필이 있게 되었다.', NULL, '신라', '현실계', '한국 강원도_영월군_영월읍', '세달사(世達寺)_장원(莊舍)', '김낭자(김흔의 딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0006', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0006', '조신', '調信', '3인칭', '한문', '又往堂前, 怨大悲之不遂己, 哀泣至日暮, 情思倦憊, 俄成假寢.', '조신은 관음보살이 자신의 소원을 이뤄주지 않는 것을 원망하며 해가 저물도록 슬피 울다가 애틋함과 그리움에 지치고는 깜빡 설잠에 빠졌다.', NULL, '신라', '현실계', '한국 강원도_양양군_강현면', '낙산사(落山寺)_대비전(大悲殿)', '조신', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0007', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0007', '조신', '調信', '3인칭', '한문', '忽夢金氏娘, 容豫入門, 粲然啓齒而謂曰:', '홀연 꿈 속에서 김씨(金氏) 낭자가 사뿐사뿐 문으로 들어와 환하게 이빨을 드러내고서 일러 말했다.', NULL, '신라', '비현실계(꿈)', '꿈', '꿈', '조신, 김낭자(김흔의 딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0008', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0008', '조신', '調信', '3인칭', '한문', '“兒早識上人於半面, 心乎愛矣, 未嘗暫忘, 迫於父母之命, 强從人矣. 今願爲同穴之友, 故來爾.”', '“저는 일찍부터 스님을 먼발치에서 알고서 속으로 사모하고 여태껏 잠시도 잊은 적이 없는데, 부모님의 명령에 쫓겨 억지로 다른 사람을 따르게 되었습니다. 이제 무덤을 함께하는 사이가 되고자하여 찾아왔습니다.”', NULL, '신라', '비현실계(꿈)', '꿈', '꿈', '조신, 김낭자(김흔의 딸)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0009', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0009', '조신', '調信', '3인칭', '한문', '信乃顚喜, 同歸鄕里.', '조신이 곧 매우 기뻐하여 함께 고향으로 돌아갔다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_영월군', '조신의 집', '조신, 김낭자(김흔의 딸), 큰아들, 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0010', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0010', '조신', '調信', '3인칭', '한문', '計活四十餘星霜, 有兒息五, 家徒四壁, 藜藿不給.', '그렇게 40여 년을 살며 다섯 자녀를 두었는데 집안은 그저 네 벽만 있고 거친 나물조차 먹지 못했다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_영월군', '조신의 집', '조신, 김낭자(김흔의 딸), 큰아들, 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0011', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0011', '조신', '調信', '3인칭', '한문', '遂乃落魄扶携, 糊其口於四方. 如是十年, 周流草野, 懸鶉百結, 亦不掩体.', '결국 그들은 실의한 채 붙들고 이끌며 사방으로 구걸하며 지냈으니 이렇게 10년 동안 들판을 헤메다 누더기 옷을 여러 번 꿰매도 몸을 가리지 못했다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_영월군', '길가', '조신, 김낭자(김흔의 딸), 큰아들, 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0012', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0012', '조신', '調信', '3인칭', '한문', '適過溟州蟹縣嶺, 大兒十五歲者, 忽餧死, 痛哭收瘞於道.', '마침 명주(溟州) 해현령(蟹縣嶺)을 지나는데 15살짜리 큰아이가 굶어 죽게 되었으니 통곡하며 길에 시신을 묻었다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_강릉시', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0013', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0013', '조신', '調信', '3인칭', '한문', '從率餘四口, 到羽曲縣【今羽谿縣也】, 結茅於路傍而舍.', '나머지 네 식구를 데리고 우곡현(羽曲縣)에 이르러서【지금의 우계현이다】 길가에 초가집을 짓고 살았다.', '今羽谿縣也 : 원본에는 今羽■縣也', '신라', '비현실계(꿈)', '한국 강원도_강릉시_옥곡면', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0014', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0014', '조신', '調信', '3인칭', '한문', '夫婦老且病, 飢不能興,', '부부가 늙고 또 병이 들며 굶주려 일어서지도 못하고', NULL, '신라', '비현실계(꿈)', '한국 강원도_강릉시_옥곡면', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0015', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0015', '조신', '調信', '3인칭', '한문', '十歲女兒巡乞, 乃爲里獒所噬, 號痛臥於前,', '10살인 딸은 돌아다니며 구걸하다가 곧 마을의 개에게 물려 울부짖으며 앞에서 쓰러지니', NULL, '신라', '비현실계(꿈)', '한국 강원도_강릉시_옥곡면', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0016', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0016', '조신', '調信', '3인칭', '한문', '父母爲之歔欷, 泣下數行.', '부모가 그 때문에 탄식하며 몇 줄기 눈물을 흘렸다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_강릉시_옥곡면', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0017', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0017', '조신', '調信', '3인칭', '한문', '婦乃■皺澁拭涕, 倉卒而語曰:', '부인이 곧 목이 멘 채 눈물을 닦더니 갑자기 이렇게 말했다.', NULL, '신라', '비현실계(꿈)', '한국 강원도_강릉시_옥곡면', '길가', '조신, 김낭자(김흔의 딸), 딸, 자녀C, 자녀D, 자녀E', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SJS01NU001P0018', '장면_조신_목판본_한국 규장각한국학연구원_001_S#0018', '조신', '調信', '3인칭', '한문', '“予之始遇君也, 色美年芳, 衣袴稠鮮. 一味之甘, 得與子分之, 數尺之煖, 得與子共之. 出處五十年, 情鍾莫逆, 恩愛綢繆, 可謂厚緣. 自比年來, 衰病歲益深, 飢寒日益迫, 傍舍壺漿, 人不容乞, 千門之耻, 重似丘山. 兒寒兒飢, 未遑計補, 何暇有愛悅夫婦之心哉? 紅顔巧笑, 草上之露, 約束芝蘭, 柳絮飄風. 君有我而爲累, 我爲君而足憂, 細思昔日之歡, 適爲憂患所階. 君乎予乎, 奚至此極? 與其衆鳥之同餧, 焉知 知: ‘知’는 ‘如’의 오자임.
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SCCW01NU001P0089', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0089', '최치원', '崔致遠', '3인칭', '한문', '“不向閨中作黃公之子婿, 翻來塚側夾陳氏之女奴, 未測何緣得逢此會.”', '“규방을 향해 황공(黃公)의 사위는 되지 못하고 도리어 무덤가에 와서 진씨(陳氏)네 여종을 끼고 있으니 무슨 인연으로 이러한 만남을 갖게 되었는지 알지 못하겠습니다.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0090', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0090', '최치원', '崔致遠', '3인칭', '한문', '女兄作詩曰:', '팔낭자가 시를 지었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0091', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0091', '최치원', '崔致遠', '3인칭', '한문', '“聞語知君不是賢, 應緣慣與女奴眠.”', '“말씀을 들으니 그대가 현인이 아님을 알겠으니, 분명 계집종과 자는 일에만 익숙한 까닭이리라.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, '칠언이구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0092', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0092', '최치원', '崔致遠', '3인칭', '한문', '弟應聲續尾曰:', '구낭자가 소리에 응해 그 뒤를 이었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0093', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0093', '최치원', '崔致遠', '3인칭', '한문', '“無端嫁得風狂漢, 强被輕言辱地仙.”', '“까닭 없이 미치광이 사내에게 시집을 가서, 억지로 가벼운 말에 지선을 욕보이게 되었네.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, '칠언이구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0094', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0094', '최치원', '崔致遠', '3인칭', '한문', '公答爲詩曰:', '최치원이 답하며 시를 지었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0095', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0095', '최치원', '崔致遠', '3인칭', '한문', '“五百年來始遇賢, 且歡今夜得雙眠. 芳心莫怪親狂客, 會向春風占謫仙.”', '“오백 년 만에 비로소 어진 짝을 만났으니, 우선 오늘 밤 나란히 잠드는 것을 기뻐하세. 꽃다운 마음들이여, 광객과 친해짐을 이상히 보지 말라. 일찍이 봄바람을 향해 적선을 점지했노라', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, '칠언절구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0096', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0096', '최치원', '崔致遠', '3인칭', '한문', '小頃, 月落鷄鳴, 二女皆驚, 謂公曰:', '잠시 후 달이 지고 닭이 울자 두 여자가 모두 놀라며 최치원에게 말했다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0097', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0097', '최치원', '崔致遠', '3인칭', '한문', '“樂極悲來, 離長會促, 是人世貴賤同傷, 況乃存沒異途, 升沈殊路, 每慚白晝, 虛擲芳時. 只應拜一夜之歡, 從此作千年之恨. 始喜同衾之有幸, 遽嗟破鏡之無期.”', '“즐거움이 다하면 슬픔이 오고 이별은 길고 만남은 짧으니 이는 인간 세상의 누구든 같이 슬퍼하는 바인데, 더구나 삶과 죽음은 길이 다르고 사람과 귀신도 길이 다릅니다. 늘 대낮을 부끄러워하느라 꽃다운 시절을 헛되이 보냈습니다. 그저 하룻밤의 즐거움에 감사히 절하고 이로부터 천년의 한을 품게 될 것입니다. 처음에는 이불을 함께하게 된 행운이 있음을 기뻐했으나 대번에 파경(破鏡)의 기약이 없음을 탄식하게 되었습니다.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0098', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0098', '최치원', '崔致遠', '3인칭', '한문', '二女各贈詩曰:', '두 여인이 각각 시를 지어 주었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0099', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0099', '최치원', '崔致遠', '3인칭', '한문', '“星斗初回更漏闌, 欲言離緖淚闌干. 從玆便結千年恨, 無計重尋五夜歡.”', '“별들이 처음으로 돌아가고 물시계도 다 하려는데, 이별의 심정 말하고자 하나 눈물만 난간에 가득하네. 이제부터 문득 천년의 한을 맺게 될 것이니, 오경의 즐거움을 다시 찾을 방도가 없구나.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, '칠언절구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0100', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0100', '최치원', '崔致遠', '3인칭', '한문', '又曰:', '또 구낭자가 읊었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0101', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0101', '최치원', '崔致遠', '3인칭', '한문', '“斜月照窓紅臉冷, 曉風飄袖翠眉攢. 辭君步步偏腸斷, 雨散雲歸入夢難.”', '“비낀 달빛 창가에 비치자 붉은 뺨이 식어가고, 새벽바람 소매에 나부끼니 푸른 눈썹 찌푸려지네. 그대와 작별하고 걸음걸음마다 유독 애간장이 끊어지니, 운우지정 끝나고 나면 꿈속에 들기조차 어려우리.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, '칠언절구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0102', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0102', '최치원', '崔致遠', '3인칭', '한문', '致遠見詩, 不覺垂淚.', '최치원이 시를 보고 자기도 모르게 눈물을 흘렸다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0103', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0103', '최치원', '崔致遠', '3인칭', '한문', '二女謂致遠曰:', '두 여자가 최치원에게 말했다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0104', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0104', '최치원', '崔致遠', '3인칭', '한문', '“倘或他時, 重經此處, 修掃荒塚.”', '“만일 훗날에라도 다시 이곳을 지나시게 된다면 이 황폐한 무덤을 쓰다듬어 주십시오.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0105', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0105', '최치원', '崔致遠', '3인칭', '한문', '言訖卽滅.', '말을 마치자 곧 사라졌다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0106', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0106', '최치원', '崔致遠', '3인칭', '한문', '明旦, 致遠歸塚邊, 彷徨嘯咏, 感嘆尤甚,', '다음 날 아침, 치원이 무덤가로 돌아가 서성거리며 시를 읊조리니 슬픈 감회가 더욱 심해졌다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館)', '최치원, 팔낭자(八娘子), 구낭자(九娘子)', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0107', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0107', '최치원', '崔致遠', '3인칭', '한문', '作長歌, 自慰曰:', '곧 장가(長歌)를 지어 스스로 위로하며 말했다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館) 근처 쌍녀분(雙女墳)_석문', '최치원', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0108', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0108', '최치원', '崔致遠', '3인칭', '한문', '“草暗塵昏雙女墳, 古來名迹竟誰聞? 唯傷曠野千秋月, 空鎖巫山兩片雲. 自恨雄才爲遠吏, 偶來孤館尋幽邃. 戱將詞句向門題, 感得仙姿侵夜至. 紅錦袖紫羅裙, 坐來蘭麝逼人薰. 翠眉丹頰皆超俗, 飮態詩情又出群. 對殘花傾美酒, 雙雙妙舞呈纖手. 狂心已亂不知羞, 芳意試看相許否. 美人顔色久低迷, 半含笑態半含啼. 面熟自然心似火, 臉紅寧假醉如泥. 歌艶詞打懽合, 芳宵良會應前定. 纔聞謝女啓淸談, 又見班姬摛雅詠. 情深意密始求親, 正是艶陽桃李辰. 明月倍添衾枕恩, 香風偏惹綺羅身. 綺羅身衾枕恩, 幽懽未已離愁至. 數聲餘歌斷孤魂, 一點殘燈照雙淚. 曉天鸞鶴各西東, 獨坐思量疑夢中. 沈思疑夢又非夢, 愁對朝雲歸碧空. 馬長嘶望行路, 狂生猶再尋遺墓. 不逢羅襪步芳塵, 但見花枝泣朝露. 腸欲斷首頻回, 泉戶寂寥誰爲開? 頓轡望時無限淚, 垂鞭吟處有餘哀. 暮春風暮春日, 柳花撩亂迎風疾. 常將旅思怨韶光, 況是離情念芳質. 人間事愁殺人, 始聞達路又迷津. 草沒銅臺千古恨, 花開金谷一朝春. 阮肇劉晨是凡物, 秦皇漢帝非仙骨. 當時嘉會杳難追, 後代遺名徒可悲. 悠然來忽然去, 是知風雨無常主. 我來此地逢雙女, 遙似襄王夢雲雨. 大丈夫大丈夫. 壯氣須除兒女恨, 莫將心事戀妖狐.”', '“잡초 우거지고 먼지 뒤덮인 두 여인의 무덤이여, 예부터 내려온 이름과 자취를 끝내 누가 들었으리. 오직 넓은 들판 천추의 달빛만이 서글프고, 무산의 두 조각 구름은 헛되이 갇혀 있네. 스스로 뛰어난 재주로 먼 곳의 관리가 된 것을 한탄하다가, 우연히 외로운 객관에 와서 깊고 그윽한 곳을 찾았네. 장난삼아 시구를 문을 향해 적었더니, 감동한 선녀의 자태가 밤을 틈타 이르렀네. 붉은색 비단 소매와 자줏빛 비단 치마, 앉으니 난초와 사향 향기가 사람에게 다가와 찌르네. 푸른 눈썹과 붉은 뺨은 모두 속세를 초월하였고, 술 마시는 자태와 시 읊는 정취 역시 무리에서 뛰어나네. 저무는 꽃을 마주하고 맛좋은 술을 기울이자, 쌍쌍이 오묘한 춤 추며 가느다란 손길 드러내네. 미친 마음이 이미 어지러워 부끄러움 알지 못하고, 꽃다운 뜻이 서로 허락할지를 시험해 보려네. 미인들이 한참 동안 고개 숙이고 머뭇거리니, 반쯤은 웃는 모습이고 반쯤은 우는 모습이네. 얼굴이 익숙해지자 자연스레 마음은 불과 같아지고, 뺨이 붉어지니 어찌 진흙처럼 취해지기를 빌리겠는가. 아름다운 가사를 노래하며 즐겁게 화답하니, 꽃다운 밤의 좋은 만남은 분명 미리 정해진 것이리라. 방금 사녀(謝女)가 맑은 담론을 여는 것을 듣고, 다시 반희(班姬)가 고운 노래를 읊는 것을 보네. 정이 깊어지고 뜻이 깊어져 비로소 가까워지길 구하니, 바로 화창한 봄날 복숭아꽃 오얏꽃 피는 시절이로다. 밝은 달은 이불과 베개의 은혜를 배로 더하고, 향긋한 바람은 유독 비단옷 걸친 그대들 몸을 당기네. 비단옷 입은 몸에 이불과 베개의 은혜를 입고서, 그윽한 기쁨이 다하지 않았는데 이별의 시름이 찾아오네. 몇 마디 남은 노래는 외로운 넋을 끊고, 한 점 꺼져가는 등불은 두 줄기 눈물을 비추네. 새벽 하늘엔 난새와 학이 각각 좌우로 흩어지니, 홀로 앉아 생각하며 꿈속인가 의심하노라. 곰곰이 생각하니 꿈인 듯하나 또 꿈은 아니니, 시름겹게 아침 구름이 푸른 하늘로 돌아가는 것 대하네. 말은 길게 울며 가야 할 길을 바라보는데, 미치광이 선비는 오히려 다시 버려진 무덤을 찾네. 비단 버선발로 꽃다운 먼지 밟는 모습 만나지 못하고, 그저 꽃가지가 아침 이슬에 우는 것만을 보네. 창자가 끊어질 듯하여 고개를 자주 돌아보지만, 적막한 저승의 문을 누가 날 위해 열어주겠는가. 고삐를 멈추고 바라볼 때 끝없이 눈물이 흐르고, 채찍을 내리고 읊조리는 곳에 남은 슬픔이 있네. 저무는 봄날의 바람과 저무는 봄날의 햇살 아래, 버들꽃 어지러이 날리며 바람을 맞아 빠르구나.늘 나그네의 시름으로 화창한 봄빛을 원망했는데, 더구나 이별의 정으로 꽃다운 그대들 생각함에랴. 인간 세상의 일은 사람을 시름겹게 하니, 처음에는 통하는 길을 들었다가 또 나루터에서 헤매네. 풀은 동작대에 묻혔으니 천고의 한이요, 꽃은 금곡원에 피었으니 하루아침의 봄이로다. 완조(阮肇)와 유신(劉晨)도 평버한 존재일 뿐이고, 진 시황(秦始皇)과 한 무제(漢武帝)도 신선의 골격은 아니었네. 당시 아름다운 모임 아득해 쫓기 어려우니, 후대에 남겨진 이름 한갓 슬퍼할 따름이네. 유유히 왔다가 홀연히 사라지니, 비와 바람에는 정해진 주인이 없음을 알겠네. 내가 이곳에 와서 두 여인을 만난 것은, 옛 초 양왕이 운우지정을 꿈꾼 것과 같구나. 대장부여, 대장부여! 씩씩한 기운으로 아녀자의 정한을 떨쳐버려야지, 마음속 일에 요망한 여우를 그리워하지 말라.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '초현관(招賢館) 근처 쌍녀분(雙女墳)_석문', '최치원', NULL, '칠언고시', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0109', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0109', '최치원', '崔致遠', '3인칭', '한문', '後, 致遠擢第東還, 路上歌詩云:', '훗날 최치원이 과거에 급제하고 신라로 돌아올 때 길 위에서 시를 읊었다.', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '길가(귀국길)', '최치원', NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0110', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0110', '최치원', '崔致遠', '3인칭', '한문', '“浮世榮華夢中夢, 白雲深處好安身.”', '“뜬 세상의 영화로움은 꿈속의 꿈이니, 흰 구름처럼 깊은 곳이 몸 편히 쉬기 좋구나.”', NULL, '신라', '현실계', '중국_강소성_남경시_율수현', '길가(귀국길)', '최치원', NULL, '칠언이구', NULL, NULL, NULL, NULL),
    ('SCCW01NU001P0111', '장면_최치원_신연활자본_한국 국립중앙도서관_001_S#0111', '최치원', '崔致遠', '3인칭', '한문', '乃退而長往, 尋僧於山林江海, 結小齋, 尋石臺, 耽玩文書, 嘯咏風月, 逍遙偃仰於其間.', '곧 물러가 속세를 멀리 떠나 산림과 강해로 승려들을 찾아다니다가 작은 서재를 짓고 석대(石臺)를 쌓은 뒤 글을 즐겨 읽고 풍월을 읊조리며 그곳에서 한가로이 노닐며 지냈다.', NULL, '신라', '현실계', '한국', '산림강해(山林江海)_소재(小齋) 및 
INSERT INTO "scene" ("id", "name", "work_kor", "work_chi", "viewpoint", "language", "original_text", "translation", "notes", "temporal_background", "spatial_background_1", "spatial_background_2", "place_background", "characters", "allusions", "spatial_background_link", "place_background_link", "character_link", "allusion_link", "embedded_work_status") VALUES
    ('SHSGUJ01NU001P0176', '장면_하생기우전_필사본_일본 천리대학교_001_S#0176', '하생기우전', '何生奇遇傳', '3인칭', '한문', '“其新孔嘉, 其舊如之何? 吾與子, 新歡舊意, 自異尋常, 誰無夫婦, 孰如我員?”', '“새로 맺는 혼인이 참으로 아름다우니 오래된 인연은 어떻겠는가? 나와 그대는 새로 맞는 기쁨과 오래된 정이 본래 보통 사람들과는 다르니, 누군들 부부 아닌 사람이 없으나 누가 우리 부부처럼 원만하겠는가?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0177', '장면_하생기우전_필사본_일본 천리대학교_001_S#0177', '하생기우전', '何生奇遇傳', '3인칭', '한문', '女曰:', '여인이 말했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0178', '장면_하생기우전_필사본_일본 천리대학교_001_S#0178', '하생기우전', '何生奇遇傳', '3인칭', '한문', '“嘗聞釋氏有三生之說, 是謂去來今. 過去已與君爲夫婦, 今生又與君爲夫婦, 第未知方來何如. 三生結緣, 古亦有之乎?”', '“일찍이 들으니 불가(釋氏)에 삼생설(三生說)이 있어 과거·미래·현재를 말한다고 들었습니다. 과거에 이미 그대와 함께 부부가 되었고 이번 생에 다시 낭군과 더불어 부부가 되었습니다만 미래에는 어떨지 알지 못하겠습니다. 삼생의 인연을 맺는 것이 옛날에도 있었습니까?”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0179', '장면_하생기우전_필사본_일본 천리대학교_001_S#0179', '하생기우전', '何生奇遇傳', '3인칭', '한문', '自是, 夫婦敬愛, 雖鴻之光, 缺之妻, 未足喩也.', '이로부터 부부가 서로 공경하고 사랑함이 비록 양홍(梁鴻)의 아내 맹광(孟光)과 극결(郤缺)의 아내라도 비유할 수 없었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0180', '장면_하생기우전_필사본_일본 천리대학교_001_S#0180', '하생기우전', '何生奇遇傳', '3인칭', '한문', '翌年, 生捷巍科, 初仕寶文閣, 後至尙書令.', '이듬해 하생이 문과에 장원급제해 보문각(寶文閣)에서 처음 벼슬하고 훗날 상서령(尙書令)까지 이르렀다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0181', '장면_하생기우전_필사본_일본 천리대학교_001_S#0181', '하생기우전', '何生奇遇傳', '3인칭', '한문', '與女爲夫婦, 凡四十餘年. 生二男, 長曰積善, 次曰餘慶, 皆顯于世.', '여인과 더불어 부부가 된 지 무릇 40여 년이었다. 두 아들을 낳았는데 장남은 적선(積善), 차남은 여경(餘慶)이니 모두 세상에 현달했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSGUJ01NU001P0182', '장면_하생기우전_필사본_일본 천리대학교_001_S#0182', '하생기우전', '何生奇遇傳', '3인칭', '한문', '生定婚之日, 求前之卜師, 則已易其肆云.', '하생이 혼인 날짜를 정하던 날에 앞서 만던 점쟁이를 찾았으나 이미 그 점포를 옮겼다고 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0001', '장면_허생전B_필사본_한국 임형택_001_S#0001', '허생전', '許生傳', '3인칭', '한문', '燕京有許生者, 忘其名字. 自小風采秀麗, 好喜戲, 以馳騁爲娯.', '연경(燕京)에 허생(許生)이란 자가 있었는데 그 이름과 자(字)는 잊어버렸다. 어려서부터 풍채가 수려하고 노는 것을 좋아했으며 말을 타고 달리는 것을 즐거움으로 삼았다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '허생의 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0002', '장면_허생전B_필사본_한국 임형택_001_S#0002', '허생전', '許生傳', '3인칭', '한문', '一日, 訪友而返, 路邊見有高樓, 隱照於花柳中, 設朱紅簾.', '하루는 벗을 만나고 돌아오다가 길가에 높은 누각이 이 꽃과 버들 사이에 은은하게 드러나 있는 것을 보았는데 거기에는 주홍빛 발이 쳐져 있었었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0003', '장면_허생전B_필사본_한국 임형택_001_S#0003', '허생전', '許生傳', '3인칭', '한문', '簾內有一少姝, 年纔二旬, 方倚欄刺繡.', '그 발 안에는 한 젊고 여인이 있었으니 나이가 겨우 스무 살 정도 되었고 막 난간에 기대어 수를 놓고 있었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0004', '장면_허생전B_필사본_한국 임형택_001_S#0004', '허생전', '許生傳', '3인칭', '한문', '適因風動, 睨而視之, 眞月中姮娥也.', '마침 바람에 발이 움직인 틈을 타 곁눈질로 바라보았는데 참으로 달 속의 항아(姮娥)였다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0005', '장면_허생전B_필사본_한국 임형택_001_S#0005', '허생전', '許生傳', '3인칭', '한문', '生魂飛雲外, 不能定情, 佇立斜陽, 無計可施.', '허생은 혼이 구름 밖으로 날아가 마음을 진정시킬 수 없었고 석양에 우두커니 선 채로 아무런 계책도 낼 수 없었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0006', '장면_허생전B_필사본_한국 임형택_001_S#0006', '허생전', '許生傳', '3인칭', '한문', '黯然還家, 坐而待朝.', '암담히 집으로 돌아와 앉아서 날이 밝기만을 기다렸다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0007', '장면_허생전B_필사본_한국 임형택_001_S#0007', '허생전', '許生傳', '3인칭', '한문', '再往其處, 則更無所覩者, 數旬爲之瘦瘠', '다음 날 다시 그곳에 갔으나 더는 여인을 볼 수 없었고, 수십 일 동안 그로 인해 몸이 야위고 말았다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_고루(高樓)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0008', '장면_허생전B_필사본_한국 임형택_001_S#0008', '허생전', '許生傳', '3인칭', '한문', '一日, 適有老女僧, 自外而出, 入其家.', '하루는 마침 늙은 여승이 밖에서부터 오더니 여인의 집으로 들어갔다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집[某家]', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0009', '장면_허생전B_필사본_한국 임형택_001_S#0009', '허생전', '許生傳', '3인칭', '한문', '生坐於蓬丘之上, 待其出來, 尾而隨之.', '허생은 언덕 위에 앉아 여승이 나오기를 기다리고 있다가 꼬리를 밟아 따라갔다.', '生坐於蓬丘之上 : 원본에는 生於坐蓬丘之上', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '언덕(蓬丘)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0010', '장면_허생전B_필사본_한국 임형택_001_S#0010', '허생전', '許生傳', '3인칭', '한문', '趨其所止, 則乃僧房也.', '여승이 발길이 멈춘 곳으로 쫓아가보니 곧 승방(僧房)이었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0011', '장면_허생전B_필사본_한국 임형택_001_S#0011', '허생전', '許生傳', '3인칭', '한문', '趨入拜之,', '허생이 달려 들어가 절을 하니,', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0012', '장면_허생전B_필사본_한국 임형택_001_S#0012', '허생전', '許生傳', '3인칭', '한문', '則老僧問曰:', '늙은 승려가 물었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0013', '장면_허생전B_필사본_한국 임형택_001_S#0013', '허생전', '許生傳', '3인칭', '한문', '“郎君, 何故辱臨蓬蓽乎?”', '“낭군께서는 무슨 까닭으로 누추한 곳에 욕되게 왕림하셨습니까?”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0014', '장면_허생전B_필사본_한국 임형택_001_S#0014', '허생전', '許生傳', '3인칭', '한문', '生答曰:', '허생이 대답했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0015', '장면_허생전B_필사본_한국 임형택_001_S#0015', '허생전', '許生傳', '3인칭', '한문', '“我以獨子, 年將三十, 尙無繼嗣, 日夜憂悶, 恐得罪於先人矣. 得祈禱於佛聖, 則必有應矣, 故不避尊嚴, 敢來唐突. 幸望勿譴, 指云人倫之道. 則其於仙僧之恩, 白骨難忘.”', '“저는 집안의 독자로 나이가 장차 서른인데 아직 후사가 없어 밤낮으로 근심하며 조상님께 죄를 지을까 두려워하고 있습니다. 부처님께 기도를 드릴 수만 있다면 분명 감응이 있을 것이라고 여겨 위엄을 무릅쓰고 감히 와서 당돌하게 굴었습니다. 부디 꾸짖지 마시고 인륜의 도리를 지적해 일러주십시오. 그러면 스님의 은혜는 백골이 되어도 잊지 않겠습니다.”', '白骨難忘 : 원본에는 白骨難妄', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0016', '장면_허생전B_필사본_한국 임형택_001_S#0016', '허생전', '許生傳', '3인칭', '한문', '僧曰:', '여승이 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0017', '장면_허생전B_필사본_한국 임형택_001_S#0017', '허생전', '許生傳', '3인칭', '한문', '“豈有禱佛有子之理? 但至誠感天, 似有此心事耳.”', '“어찌 부처에게 기도하여 아들을 얻는 이치가 있겠습니까? 다만 지극한 정성이 하늘을 감동시킨다면 마음 속 일이 이루어질 듯합니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0018', '장면_허생전B_필사본_한국 임형택_001_S#0018', '허생전', '許生傳', '3인칭', '한문', '生喜曰:', '허생이 기뻐하며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0019', '장면_허생전B_필사본_한국 임형택_001_S#0019', '허생전', '許生傳', '3인칭', '한문', '“此乃素志也.”', '“그것이 평소 바라던 뜻입니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0020', '장면_허생전B_필사본_한국 임형택_001_S#0020', '허생전', '許生傳', '3인칭', '한문', '因拜謝而還.', '그러고는 절하고 사례하며 돌아갔다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0021', '장면_허생전B_필사본_한국 임형택_001_S#0021', '허생전', '許生傳', '3인칭', '한문', '將費千金, 祈禱數次, 盛設過度.', '이후 천금을 쏟아 여러 번 기도를 올렸는데 성대하게 차린 것이 도를 넘었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0022', '장면_허생전B_필사본_한국 임형택_001_S#0022', '허생전', '許生傳', '3인칭', '한문', '寺僧疑有他事, 問於生曰:', '여승은 그가 다른 속셈이 있을 것으로 의심해 허생에게 물었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0023', '장면_허생전B_필사본_한국 임형택_001_S#0023', '허생전', '許生傳', '3인칭', '한문', '“行此設齋, 乃一而足, 何費千金之累資乎? 無乃有所然而然耶? 妾以蒲柳之資, 濫蒙厚恩, 死無所辭, 實不識其然也.”', '“이 재(齋)를 베푸는 것은 곧 한 번이면 충분한데 어찌하여 천금의 막대한 재물을 허비하십니까? 곧 그럴 만한 까닭이 있어서 그러한 것이 아니겠습니까? 제가 보잘것없는 자질로 외람되게 두터운 은혜를 입었으니 죽음도 사양할 바가 없지만 참으로 그 연유를 알지 못하겠습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0024', '장면_허생전B_필사본_한국 임형택_001_S#0024', '허생전', '許生傳', '3인칭', '한문', '生乃以實對之.', '허생이 마침내 사실대로 대답하였다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0025', '장면_허생전B_필사본_한국 임형택_001_S#0025', '허생전', '許生傳', '3인칭', '한문', '老僧默然良久, 釋然頓悟曰:', '노승이 한참 동안 묵묵히 있다가 번뜩 깨달으며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0026', '장면_허생전B_필사본_한국 임형택_001_S#0026', '허생전', '許生傳', '3인칭', '한문', '“果有之. 此女雖非士族, 亦有節行, 而夫婦好合, 百爾思之, 誠難誠難.”', '“과연 그런 일이 있으셨군요. 그러나 이 여인은 비록 사족(士族)은 아니지만 또한 절개와 행실이 있고 부부의 금슬이 좋으니 갖가지로 생각해 보아도 참으로 도모하기 어렵습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0027', '장면_허생전B_필사본_한국 임형택_001_S#0027', '허생전', '許生傳', '3인칭', '한문', '生仰天歎曰:', '허생이 하늘을 우러러 탄식하며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0028', '장면_허생전B_필사본_한국 임형택_001_S#0028', '허생전', '許生傳', '3인칭', '한문', '“然則, 有死而已!”', '“그렇다면 죽는 수밖에 없습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0029', '장면_허생전B_필사본_한국 임형택_001_S#0029', '허생전', '許生傳', '3인칭', '한문', '嘘嚱數聲.', '이렇게 여러 번 한숨을 내쉬었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0030', '장면_허생전B_필사본_한국 임형택_001_S#0030', '허생전', '許生傳', '3인칭', '한문', '老僧撫然, 有間曰:', '여승이 어루만지더니 조금 있다가 이렇게 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0031', '장면_허생전B_필사본_한국 임형택_001_S#0031', '허생전', '許生傳', '3인칭', '한문', '“若無已, 則妾有一計, 可報厚恩, 而妾亦有所施矣. 郎君且歸, 以待某月之會, 則何難乎佳期哉!”', '“만약 그만두지 못하시겠다면 제게 한 계책이 있으니 두터운 은혜에 보답할 수 있고 저 또한 베풀 바가 있습니다. 낭군께서는 우선 돌아가서 훗날의 만남을 기다리셨다가 가약을 맺는 것이 어찌 어렵겠습니까!”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0032', '장면_허생전B_필사본_한국 임형택_001_S#0032', '허생전', '許生傳', '3인칭', '한문', '生喜起而拜謝曰:', '허생이 기뻐 일어나 절하고 사례하며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0033', '장면_허생전B_필사본_한국 임형택_001_S#0033', '허생전', '許生傳', '3인칭', '한문', '“果若仙僧之言, 殞結難報. 萬祝無違.”', '“과연 선승의 말씀대로라면 몸을 바쳐 결초보은해도 보답하기 어려울 것입니다. 만 번 축원하오니 어긋남이 없게 해 주십시오.”', '殞結難報 : 원본에는 殞結難保', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0034', '장면_허생전B_필사본_한국 임형택_001_S#0034', '허생전', '許生傳', '3인칭', '한문', '兩人牢定約束而退.', '두 사람이 굳게 약속을 정하고 물러났다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)_승방(僧房)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0035', '장면_허생전B_필사본_한국 임형택_001_S#0035', '허생전', '許生傳', '3인칭', '한문', '待佳期, 如不及, 度一日如三秋, 寢食專廢者, 累日矣.', '허생은 안절부절하듯 만날 날만 고대했으니 하루를 지내는 것이 3년 같았고 잠자고 먹는 것을 전폐한 지가 여러 날이 되었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '허생(許生)의 집', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0036', '장면_허생전B_필사본_한국 임형택_001_S#0036', '허생전', '許生傳', '3인칭', '한문', '老僧進扣其女之門,', '여승이 가서 그 여인 집의 문을 두드렸는데', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0037', '장면_허생전B_필사본_한국 임형택_001_S#0037', '허생전', '許生傳', '3인칭', '한문', '則適付畵像, 而有祈禱之事.', '마침 여인도 화상(畵像)을 걸어두고 기도하는 일이 있었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0038', '장면_허생전B_필사본_한국 임형택_001_S#0038', '허생전', '許生傳', '3인칭', '한문', '問曰:', '여승이 물었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0039', '장면_허생전B_필사본_한국 임형택_001_S#0039', '허생전', '許生傳', '3인칭', '한문', '“此爲何事耶?”', '“이것은 무슨 연유로 차린 것입니까?”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0040', '장면_허생전B_필사본_한국 임형택_001_S#0040', '허생전', '許生傳', '3인칭', '한문', '其女答曰:', '그 여인이 답했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0041', '장면_허생전B_필사본_한국 임형택_001_S#0041', '허생전', '許生傳', '3인칭', '한문', '“我以無子, 故設此也.”', '“제가 자식이 없는 까닭에 이것을 차렸습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0042', '장면_허생전B_필사본_한국 임형택_001_S#0042', '허생전', '許生傳', '3인칭', '한문', '僧曰:', '여승이 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0043', '장면_허생전B_필사본_한국 임형택_001_S#0043', '허생전', '許生傳', '3인칭', '한문', '“我前日, 固行西域時, 逢一生佛, 畵其像而來, 極其靈驗. 願得繼嗣之人, 祈禱此前, 則百無一虛, 何不早言?”', '“제가 예전에 서역(西域)을 다닐 때 어떤 생불(生佛)을 만나고 그 화상을 그려서 왔는데 아주 영험합니다. 자식 얻기를 원하는 사람이 이 앞에서 기도를 드리면 백 번 중에 한 번도 헛됨이 없으니 어찌 진작 말씀하지 않으셨습니까?”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0044', '장면_허생전B_필사본_한국 임형택_001_S#0044', '허생전', '許生傳', '3인칭', '한문', '女大喜曰:', '여인이 크게 기뻐하며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0045', '장면_허생전B_필사본_한국 임형택_001_S#0045', '허생전', '許生傳', '3인칭', '한문', '“若仙言, 志願畢矣! 爲賜不淺, 卽欲往祝. 而女子私自出入不可, 當告于家翁, 擇日行之.”', '“스님의 말씀대로라면 제 평생 소원을 이룬 것입니다! 베풀어 주심이 얕지 않으니 곧장 가서 축원하겠습니다. 하지만 여자가 사사로이 출입할 수는 없으니 응당 남편께 아뢰고 날을 정해 행하겠습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0046', '장면_허생전B_필사본_한국 임형택_001_S#0046', '허생전', '許生傳', '3인칭', '한문', '仙僧小安,', '여승이 잠시 편안히 앉아 기다리자', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0047', '장면_허생전B_필사본_한국 임형택_001_S#0047', '허생전', '許生傳', '3인칭', '한문', '卽起入內, 乃且告其夫.', '여자는 곧바로 일어나 안채에 들어가 이내 남편에게 이 사실을 알렸다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)_안채(內堂)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0048', '장면_허생전B_필사본_한국 임형택_001_S#0048', '허생전', '許生傳', '3인칭', '한문', '夫幸喜曰:', '남편이 다행스레 여기고는 기뻐하며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0049', '장면_허생전B_필사본_한국 임형택_001_S#0049', '허생전', '許生傳', '3인칭', '한문', '“速行無遲, 不失機會.”', '“지체하지 말고 속히 가서 기회를 놓치지 마시오.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0050', '장면_허생전B_필사본_한국 임형택_001_S#0050', '허생전', '許生傳', '3인칭', '한문', '女卽以返告, 定約.', '여인이 즉시 돌아와 소식을 전하고 약속을 정했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0051', '장면_허생전B_필사본_한국 임형택_001_S#0051', '허생전', '許生傳', '3인칭', '한문', '老僧還歸, 以設計之事, 一一告生, 如此如此.', '여승이 사찰로 돌아와 계획한 일을 하나하나 허생에게 일러주었으니 이러이러하게 하겠다고 하였다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0052', '장면_허생전B_필사본_한국 임형택_001_S#0052', '허생전', '許生傳', '3인칭', '한문', '其女及期, 率奴僕, 盛此祈禱之物, 進往.', '그 여인이 기약한 날이 되자 노복들을 거느리고 기도할 때 쓸 제물들을 성대히 챙겨 절로 향했다.', '率奴僕 : 원본에는 卒奴僕', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0053', '장면_허생전B_필사본_한국 임형택_001_S#0053', '허생전', '許生傳', '3인칭', '한문', '則老僧喜其來, 如赤子之見慈母也.', '여승은 그녀가 오는 것을 기뻐했으니 갓난아이가 어머니를 만나는 것같이 하였다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0054', '장면_허생전B_필사본_한국 임형택_001_S#0054', '허생전', '許生傳', '3인칭', '한문', '設齋焚香, 夜已將闌.', '상을 차리고 향을 피우다 보니 밤이 이미 장차 깊어갔다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0055', '장면_허생전B_필사본_한국 임형택_001_S#0055', '허생전', '許生傳', '3인칭', '한문', '待其飢困之時, 和藥酒食以進於女, 而竝勸奴僕,', '여승은 허기지고 지칠 때를 기다렸다가 약을 섞은 술과 음식을 여인에게 올리고 아울러 노복들에게도 권하니', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0056', '장면_허생전B_필사본_한국 임형택_001_S#0056', '허생전', '許生傳', '3인칭', '한문', '皆昏倒不省.', '모두 혼절하여 인사불성이 되었다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0057', '장면_허생전B_필사본_한국 임형택_001_S#0057', '허생전', '許生傳', '3인칭', '한문', '生出自後房, 將入盡繾綣之時,', '허생이 뒷방으로부터 나와 장차 들어와 곡진한 정을 다하려 할 때,', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0058', '장면_허생전B_필사본_한국 임형택_001_S#0058', '허생전', '許生傳', '3인칭', '한문', '其女忽然醒.', '그 여인이 갑자기 술이 깨고 말았다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0059', '장면_허생전B_필사본_한국 임형택_001_S#0059', '허생전', '許生傳', '3인칭', '한문', '意謂事已如此, 無可奈何, 坐而待朝.', '여인은 속으로 일이 이미 이와 같이 되었으니 어찌할 도리가 없다고 여겨 앉아서 아침이 되기를 기다렸다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0060', '장면_허생전B_필사본_한국 임형택_001_S#0060', '허생전', '許生傳', '3인칭', '한문', '還家, 以實告其夫曰:', '그리고 집에 돌아와 사실대로 남편에게 고백했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0061', '장면_허생전B_필사본_한국 임형택_001_S#0061', '허생전', '許生傳', '3인칭', '한문', '“妾奸僧所賣, 旣犯行露之名. 若不告而死, 則妾亦有罪矣. 本欲永奉巾櫛, 以遂平生之意, 而天不佑我, 以致如此, 豈非命乎? 但願郎君, 妾死之後, 更得賢配, 以安奉姑之禮. 則雖死之日, 猶生之年.”', '“첩이 간악한 여승에게 속아 이미 행로(行露)의 오명을 저질렀습니다. 만약 전하지 않고 죽는다면 저 또한 죄가 있을 것입니다. 본디 영원토록 건즐(巾櫛)을 받들며 백년해로를 이루고자 했으나 하늘이 저를 돕지 않아 이 지경에 이르렀으니 아마 운명이 아니겠습니까? 다만 바라건대 낭군께서는 제가 죽은 뒤에 다시 어진 배필을 얻어 편히 시어머니를 모시는 예를 행해주십시오. 그러면 비록 죽는 날이어도 오히려 살아있는 해와 같을 것입니다.”', '更得賢配 : 원본에는 更得覽配', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0062', '장면_허생전B_필사본_한국 임형택_001_S#0062', '허생전', '許生傳', '3인칭', '한문', '因以羅巾自縊.', '이로 인하여 비단 수건으로 스스로 목을 매려 하였다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0063', '장면_허생전B_필사본_한국 임형택_001_S#0063', '허생전', '許生傳', '3인칭', '한문', '其夫慰而解之曰:', '그 남편이 위로하며 이를 수건을 풀며 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0064', '장면_허생전B_필사본_한국 임형택_001_S#0064', '허생전', '許生傳', '3인칭', '한문', '“此非娘子之素志, 而乃奸僧不賢所致. 雪恨無路, 生不能報, 死亦何望? 娘子甚熟思之.”', '“이는 낭자께서 평소 품은 뜻이 아니고 곧 간악한 여승과 어질지 못한 이가 벌인 것이오. 원한을 씻을 방도가 없다만 살아서 갚아주지 못한다면 죽어서는 또한 무엇을 바라겠소? 낭자는 깊이 생각하시오.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0065', '장면_허생전B_필사본_한국 임형택_001_S#0065', '허생전', '許生傳', '3인칭', '한문', '女垂淚而答曰:', '여인이 눈물을 흘리며 대답했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0066', '장면_허생전B_필사본_한국 임형택_001_S#0066', '허생전', '許生傳', '3인칭', '한문', '“若得報怨, 死無所感.”', '“만약 원수를 갚을 수 있다면 죽어도 유감이 없습니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0067', '장면_허생전B_필사본_한국 임형택_001_S#0067', '허생전', '許生傳', '3인칭', '한문', '沉吟良久曰:', '여인이 한참을 깊이 생각하다가 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0068', '장면_허생전B_필사본_한국 임형택_001_S#0068', '허생전', '許生傳', '3인칭', '한문', '“妾有妙計, 可雪通天之恨.”', '“제게 묘책이 있으니 하늘에 사무친 원한을 씻을 수 있을 것입니다.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0069', '장면_허생전B_필사본_한국 임형택_001_S#0069', '허생전', '許生傳', '3인칭', '한문', '卽寫片簡, 送于老僧.', '곧장 짧은 편지를 써서 여승에게 보냈다.', '卽寫片簡 : 원본에는 卽雪片簡', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0070', '장면_허생전B_필사본_한국 임형택_001_S#0070', '허생전', '許生傳', '3인칭', '한문', '其書曰:', '그 편지 내용은 이러하다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0071', '장면_허생전B_필사본_한국 임형택_001_S#0071', '허생전', '許生傳', '3인칭', '한문', '“日昨, 信聽仙言, 誤落花柳之中, 貞節乃虛耳. 正似春夢, 思彼之心, 與日俱長. 古語云：‘一日誤身, 百年含情.’ 良有以也. 若因先生, 更結月下之緣, 則其心鴻恩, 莫大於斯矣. 雖堯夫之麥舟, 亦不過此. 且有一言, 枉顧幸甚.”', '“요전 날 스님의 말씀을 믿고 들었다가 화류(花柳) 속에 잘못 떨어져 정절이 곧 허사가 되었습니다. 꼭 봄날의 꿈과 같으니 그를 그리워하는 마음이 날이 갈수록 자라납니다. 옛말에 ‘하루 만에 몸을 망치고 백 년 동안 정을 품는다’라고 했으니 참으로 까닭이 있습니다. 만약 선생을 통해 다시 달빛 아래의 인연을 맺게 된다면 그 마음의 크나큰 은혜는 이보다 큰 게 없을 것입니다. 비록 범순인(范純仁)의 보리를 실은 배를 내준 것 또한 여기에 미치지 못할 것입니다. 또 따로 드릴 말씀이 있으니 친히 왕림해 주시면 몹시 다행이겠습니다.”', '思彼之心 : 원본에는 思被之心', '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '사찰(寺刹)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0072', '장면_허생전B_필사본_한국 임형택_001_S#0072', '허생전', '許生傳', '3인칭', '한문', '老僧見其書辭, 喜甚, 卽往其家.', '노승이 그 편지의 내용을 보고 매우 기뻐해 곧장 여인의 집으로 갔다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0073', '장면_허생전B_필사본_한국 임형택_001_S#0073', '허생전', '許生傳', '3인칭', '한문', '其女迎接甚禮, 而言曰:', '그 여인이 극진한 예우로 영접하며 이렇게 말했다.', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SHSJ02NU001P0074', '장면_허생전B_필사본_한국 임형택_001_S#0074', '허생전', '許生傳', '3인칭', '한문', '“路柳牆花, 平生所惡, 而頓因先生, 身雖陋矣, 亦有緣也. 若得一見, 盡展所蘊, 則雖死無恨. 當以削髮, 以報先生之恩. 適有家翁有事他出, 不以此時相訪, 則求我於黃泉之下, 更待何日? 家北有壞垣處, 某日乘昏黑而來, 由此而入, 則可以遂團圓之約矣. 伏乞先生如此懇懇意, 傳于許生.”', '“길가의 버들과 담장의 꽃은 평소 싫어하던 바였으나 갑자기 선생 덕분에 비록 몸은 더럽혀졌어도 또한 인연을 두게 되었습니다. 만약 한번 다시 만나 품은 정을 전부 펼칠 수 있다면 죽더라도 한이 없겠습니다. 그렇게 된다면 응당 머리를 깎고 출가해 선생의 은혜에 보답하겠습니다. 마침 남편께서 볼일이 있어 다른 곳으로 나가셨는데 이때 방문하지 않는다면 저를 황천 아래에서 찾아야 할 것이니 또 어느 날을 기다리겠습니까? 집 북쪽에 담장이 허물어진 곳이 있으니 모일 저녁 어둠을 틈타 와서 여기로 들어오게 하시면 다시 만나는 약속을 이룰 수 있을 것입니다. 삼가 바라오니 선생께서는 이 간절한 뜻을 허생에게 전해주십시오.”', NULL, '시대_중국_미상_미상_T', '현실계', '중국(中國)_북경(北京)', '여인의 집(某家)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU002P9999', '장면_최척전_필사본_프랑스 기메박물관_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '奇哉奇哉! 略記其奇蹟傳奇, 俾後人之拍案, 稱奇乃命之曰: ‘三國奇逢’. 奇哉!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU003P9999', '장면_최척전_필사본_한국 간호윤_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父子夫妻, 舅姑兄弟, 分離四國, 悵望三紀, 經營賊所, 出入死地, 竟畢團圓, 無不如意, 此豈人力之所致? 皇天后土, 必感於至誠, 而能致此奇特之事. 匹婦有誠, 天且不違, 誠之不可掩, 如是夫! 余流寓南原之周浦, 陟時時來訪, 備陳此事, 請記其顚末, 無使堙沒, 余不獲已, 略擧其槪. 天啓元年閏二月日.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU004P9999', '장면_최척전_필사본_한국 강릉최씨 산황 장현댁 002_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '嘻! 父子夫妻, 兄弟, 分離四國, 悵望三紀, 經營賊所, 出入死地, 畢竟團圓, 無不如意, 此豈人力之所致? 皇天后土, 必感至誠, 而能致此, 奇特之事耳. 匹婦有誠, 天且不違, 誠之不可掩, 如是! 余流寓南原之周浦, 陟時來訪, 余道其事如此, 請記其始末, 無使湮滅, 余不獲已, 略擧其槪.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU006P9999', '장면_최척전_필사본_한국 고려대학교 001_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父子夫妻, 舅姑兄弟, 雖離五國, 悵望三紀, 經營賊所, 出入死地, 竟畢團圓, 無不如意, 此豈人力之所致? 皇天后土, 必感於至誠, 而能致此奇特之事. 匹■■■, 天且不違, 誠之不可掩, 其如是夫! 余流寓南原周浦, 陟時來訪, 余道其■■■, ■■■■, 乃記其顚末, 使無湮沒, 不獲已, 略擧其槪. 天啓元年辛酉閏二月日, 素翁趙緯韓.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU007P9999', '장면_최척전_필사본_한국 고려대학교 002_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '固父子夫妻, 舅姑兄弟, 分離四國, 悵望三紀, 經營賊所, 出入死地, 畢竟團圓, 無不如意, 此豈人力之所致也? 皇天后土, 必感至誠, 而能致此奇異之事. 匹婦有誠, 天且不違, 誠之不可掩, 如是夫! 余流寓南原之周浦, 陟時時來訪, 道其事如是, 請記其事顚末, 無使湮滅, 不獲已, 略擧其槪.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU008P9999', '장면_최척전_필사본_한국 고려대학교 003_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '陟間詣余, 道其事如此, 請記顚末, 無使湮滅, 余略擧其槪, 以傳云云.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU009P9999', '장면_최척전_필사본_한국 광산김씨 유일재 종택 가본_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父子夫妻, 舅姑兄弟, 分離四國, 悵望三紀, 經營賊所, 出入死地, 竟畢團圓, 無不如意, 此豈人力之所致? 皇天后土, 必感於至誠, 而能致此奇特之事. 匹婦有誠, 天且不違, 誠之不可掩, 其如是夫! 余流寓南原之周浦, 陟時來訪, 余道其事如此, 請記其顚末, 無使湮沒, 不獲已, 略擧其槪. 天啓元年辛酉閏月, 素翁題.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU010P9999', '장면_최척전_필사본_한국 규장각한국학연구원_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父母夫妻, 兄弟舅姑, 分離四國, 悵望三紀, 經營賊所, 出沒死地, 畢竟團會, 無一零落, 此豈人力之所致? 皇天后土, 必感於至誠, 而能致此奇異之事. 匹婦有誠, 天且不違, 誠之不可掩, 如是夫! 余流寓南原之周浦, 陟時來訪余, 道其事如此, 請記其顚末, 無使湮沒, 不獲已, 略擧其槪. 天啓元年辛酉閏二月日, 素翁題. [素翁, 趙緯韓号, 又号玄谷.]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU013P9999', '장면_최척전_필사본_한국 엄태식_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父子夫妻, 舅姑兄弟, 分離四國, 悵望二紀, 經營賊所, 出入死地, 竟畢團圓, 無不如意, 此豈人力之所致? 皇天后土, 必感於至誠, 而能致此, 此奇特之事. 匹婦有誠, 天且不違, 誠之不可掩, 其如是夫! 余流南原之周浦, 陟時訪來余, 道其事如此, 請記其顚末, 無使湮滅, 故不復已, 略擧其槪.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCCJ01NU015P9999', '장면_최척전_필사본_한국 이시천_S#9999', '최척전', '崔陟傳', '3인칭', '한문', '噫! 父子夫婦, 兄弟舅姑, 分離四國, 隔絶三紀, 畢竟團圓, 無不如意, 人力不至於此, 非天其孰能使之耶?” 邯鄲子流寓南方, 與陟同隣, 採陟終始, 作傳廣布, 閭巷婦人, 諺以釋之, 以便觀覽, 余又因其譯, 再繹以文.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    ('SCENE_ROW_002320', '장면데이터는 장면 구분 원칙에 대해서 재 규정할 필요 있음. 전반적으로 검수 필요', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "embedded_work" ("id", "name", "work_kor", "work_chi", "ew_title", "ew_type", "ew_genre", "language", "original_text", "translation", "notes") VALUES
    ('EWGCSMJM01NU00101', '소작품_관처사묘지명_목판본_한국 국립중앙도서관_001_01_산문_명', '관처사묘지명', '管處士墓誌銘', '최종평', '산문', '銘', '한문', '“年癸丑月建子, 龍山岡堂後址. 一抔土兮, 管述古葬于是.”', '“계축년 동짓날, 용산(龍山) 기슭 독서당 뒤편 언덕, 한 줌의 흙이여, 관술고는 이곳에 묻혔도다.”', NULL),
    ('EWGHGH01YU00101', '소작품_김현감호_한국 고려대학교_001_01_운문_오언절구', '김현감호', '金現感虎', '신도징의 시', '운문', '五言絶句', '한문', '“一宦慚梅福, 三年愧孟光. 此情何所喩? 川上有鴛鴦.”', '“한번 벼슬하니 매복(梅福)에게 부끄럽고, 3년을 지내니 맹광(孟光)에게 부끄럽네. 이 마음을 무엇에 비유하겠는가? 냇물 위에는 원앙새 있구나.”', NULL),
    ('EWGHGH01YU00102', '소작품_김현감호_한국 고려대학교_001_02_운문_오언절구', '김현감호', '金現感虎', '호녀의 시', '운문', '五言絶句', '한문', '“琴瑟情雖重, 山林志自深. 常憂時節變, 辜負百年心.”', '“부부의 정이 비록 중요하지만, 산림을 향한 뜻이 저절로 깊구나. 매번 근심하는 것은 시절이 변하여, 헛되이 백년가약 저버리는 것이라네.”', NULL),
    ('EWGHGH01YU00103', '소작품_김현감호_한국 고려대학교_001_03_운문_찬', '김현감호', '金現感虎', '김현감호에 대한 찬', '운문', '七言絶句', '한문', '“山家不耐三兄惡, 蘭吐那堪一諾芳. 義重數條輕萬死, 許身林下落花忙.”', '다음과 같이 찬한다. “산가(山家)는 세 오빠의 죄악을 견딜 수 없는데, 어찌 난초가 내뿜는 꽃다운 승낙을 견디겠는가. 의리의 소중함 몇 가지에 만 번 죽음은 가벼워, 수풀 아래 스스로 희생했으니 낙화처럼 졌구나.”', '논평_김현감호_고려대본_최종평_001'),
    ('EWDGJMYR01NU00101', '소작품_대관재몽유록_한국 계명대학교_001_운문_칠언절구', '대관재몽유록', '大觀齋夢遊錄', '최종평', '운문', '七言絶句', '한문', '“寄生何地不爲虛, 十載南柯一夢餘. 萬事等觀皆可樂, 魚應知我我知魚.”', '기생하는 인생 어느 곳이든 허망하지 않으랴, 십 년 동안의 일도 남가일몽만 남았을 뿐이다. 만사를 평등하게 바라보면 모두 즐거울 수 있으니, 물고기도 나를 알고 나도 물고기를 아네.', NULL),
    ('EWMPSJPG01YU00101', '소작품_만복사저포기_일본 내각문고_001_01_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '양생의 시', '운문', '七言絶句', '한문', '“一樹梨花伴寂寥, 可憐辜負月明宵. 靑年獨臥孤窓畔, 何處玉人吹鳳簫?”', '“배꽃 한 그루 적막함을 짝하는데, 가련히도 달 밝은 밤을 그냥 저버리는구나. 청년이 홀로 외로운 창가에 누웠는데, 어디서 미인이 봉황 피리를 부는가?', NULL),
    ('EWMPSJPG01YU00102', '소작품_만복사저포기_일본 내각문고_001_02_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '양생의 시', '운문', '七言絶句', '한문', '“翡翠孤飛不作雙, 鴛鴦失侶浴晴江. 誰家有約敲碁子, 夜卜燈花愁倚窓.”', '“비취새는 외로이 날며 짝을 짓지 못하고, 원앙새는 짝을 잃고 맑은 강에서 목욕하네. 누구 집에 약속이 있는지 바둑돌을 두드리며, 밤에 등불로 점치다가 시름스레 창에 기대네.”', NULL),
    ('EWMPSJPG01YU00103', '소작품_만복사저포기_일본 내각문고_001_03_산문_축문', '만복사저포기', '萬福寺樗蒲記', '하씨의 축문', '산문', '祝文', '한문', '“某州某地居住何氏某, 竊以曩者邊方失禦, 倭寇來侵, 干戈滿目, 烽燧連年. 焚蕩室廬, 虜掠生民, 東西奔竄, 左右逋逃, 親戚僮僕, 各相亂離. 妾以蒲柳弱質, 不能遠逝, 自入深閨, 終守幽貞, 不爲行露之沾, 以避橫逆之禍. 父母以女子守節不爽, 避地僻處, 僑居草野, 已三年矣. 然而秋月春花, 傷心虛度, 野雲流水, 無聊送日, 幽居在空谷, 歎平生之薄命, 獨宿度良宵, 傷彩鸞之獨舞, 日居月諸, 魂銷魄喪, 夏夕冬宵, 膽裂腸摧, 惟願覺皇, 曲垂憐愍. 生涯前定, 業不可避, 賦命有緣, 早得歡娛, 無任懇禱之至.”', '“아무 고을 아무 곳에 거주하는 하씨(何氏) 아무개는 삼가 아뢰니 지난번에 변방의 방어가 무너져 왜구가 침략해 와 창고 방패가 눈에 가득하고 봉화가 해마다 이어졌습니다. 집들을 불태워 쓸어버리고 백성들을 노략질하니 동서로 달아나 숨고 좌우로 도망쳐 친척과 노복들이 각기 뿔뿔이 흩어졌습니다. 저는 물가의 버들 같은 연약한 자질이라 멀리 도망갈 수 없어 스스로 깊은 규방에 들어가 끝내 절개를 지켜 길가 이슬에 젖는 모욕을 당하지 않고 뜻밖의 화를 피했습니다. 부모님께서는 여자가 절개를 지켜 어긋남이 없다 하여 궁벽한 곳으로 피신해 초야에 임시로 머무르게 하신 지가 이미 3년이 되었습니다. 그러나 가을에 달이 뜨고 봄에 꽃이 필 때면 마음만 상한 채 헛되이 보내고, 들판의 구름과 흐르는 물처럼 무료하게 세월을 보냈습니다. 빈 골짜기에 숨어 지내며 평생의 박명함을 한탄하고 홀로 지새며 좋은 밤을 보내니 아름다운 난새가 홀로 춤추는 것을 슬퍼했습니다. 세월이 흘러 혼백이 사라지고 여름과 겨울밤마다 간담이 찢어지며 애간장이 뒤틀립니다. 오직 바라건대 부처님께서는 굽어 연민을 베풀어 주십시오. 저의 생애가 전생에 정해져 그 업을 피할 수 없으나 타고난 운명에 인연이 있다면 일찍 기쁨과 즐거움을 얻게 해 주시기를 간절히 빕니다.”', NULL),
    ('EWMPSJPG01YU00104', '소작품_만복사저포기_일본 내각문고_001_04_운문_사', '만복사저포기', '萬福寺樗蒲記', '양생의 사', '운문', '詞', '한문', '“惻惻春寒羅衫薄, 幾回腸斷金鴨冷. 晩山凝黛, 暮雲張繖. 錦帳鴛衾無與伴, 寶釵半倒吹龍管.可惜許光陰易跳丸. 中情懣. 燈無焰銀屛短, 徒收淚誰從款. 喜今宵. 鄒律一吹回暖. 破我佳城千古恨, 細歌金縷傾銀椀. 悔昔時, 抱恨蹙眉, 兒眠孤館.”', '“싸늘한 봄추위에 얇은 비단 적삼. 몇 번이나 애가 끊어지고 금향로가 식었던가? 저녁 산은 눈썹 먹처럼 어둑하고, 저무는 구름은 일산처럼 퍼져있네. 비단 장막과 원앙금침은 함께할 짝이 없고, 보배로운 비녀 반쯤 기운 채 피리를 부네. 애석하게도 세월은 튀는 탄환처럼 빠르니, 마음속엔 번민만 가득하구나. 등불엔 불빛이 없고 은병풍은 짧은데, 한갓 눈물만 거둘뿐 누구를 따라 사랑할까? 기쁘구나 이 밤이여. 추연의 피리 한 번 불어 따스함 돌아와서. 나의 무덤 속 천고의 한을 깨뜨리니, 가만히 금루곡 부르며 은 술잔 기울이네. 옛날을 후회하네. 한을 머금고 눈썹 찌푸리며, 외로운 객사에서 내 잠들었던 것을.”', '「만강홍(滿江紅)」'),
    ('EWMPSJPG01YU00105', '소작품_만복사저포기_일본 내각문고_001_05_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '정씨의 시', '운문', '七言絶句', '한문', '“春宵花月兩嬋娟, 長把春愁不記年. 自恨不能如比翼, 雙雙相戱舞靑天."', '“봄밤의 꽃과 달은 모두 아름다우나, 길게 봄 시름을 안고 세월 가는 것도 잊었네, 스스로 한탄하는 것은 비익조(比翼鳥)처럼, 함께 푸른 하늘에서 춤추지 못하는 것이라네.', NULL),
    ('EWMPSJPG01YU00106', '소작품_만복사저포기_일본 내각문고_001_06_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '정씨의 시', '운문', '七言絶句', '한문', '"漆燈無焰夜如何, 星斗初橫月半斜. 惆悵幽宮人不到, 翠衫撩亂鬢鬖髿."', '검은 등잔에 불꽃 없으니 이 밤을 어찌할까, 북두칠성이 막 비끼고 달은 반쯤 기울었네. 쓸쓸하고 그윽한 무덤에는 사람 오지 않고, 푸른 적삼 어지럽게 흔들리니 귀밑머리 흐트러지네.', NULL),
    ('EWMPSJPG01YU00107', '소작품_만복사저포기_일본 내각문고_001_07_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '정씨의 시', '운문', '七言絶句', '한문', '"標梅情約竟蹉跎, 辜負春風事已過. 枕上淚痕幾圓點, 滿庭山雨打梨花."', '정다운 혼인의 약속은 끝내 어긋나니, 봄바람 저버린 채 일은 이미 지나버렸네. 베갯머리 눈물 자국 몇 번을 찍었는가, 뜰에 가득한 산 비는 배꽃을 두드리네.', NULL),
    ('EWMPSJPG01YU00108', '소작품_만복사저포기_일본 내각문고_001_08_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '정씨의 시', '운문', '七言絶句', '한문', '"一春心事已無聊, 寂寞空山幾度宵. 不見藍橋經過客, 何年裴航遇雲翹."', '봄날의 심사가 이미 무료해졌으니, 적막한 빈 산에서 몇 밤이나 보냈던가. 남교를 지나는 길손을 보지 못했으니, 어느 해에 배항이 운교를 만날까.', NULL),
    ('EWMPSJPG01YU00109', '소작품_만복사저포기_일본 내각문고_001_09_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '오씨의 시', '운문', '七言絶句', '한문', '“寺裏燒香歸去來, 金錢暗擲竟誰媒. 春花秋月無窮恨, 銷却樽前酒一盃.”', '“절에서 향을 사르고 돌아왔으니, 금전을 몰래 던졌으나 끝내 누가 중매 설까. 봄꽃과 가을 달에 다함이 없는 한을, 술동이 앞에서 술 한 잔으로 달래네.”', NULL),
    ('EWMPSJPG01YU00110', '소작품_만복사저포기_일본 내각문고_001_10_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '오씨의 시', '운문', '七言絶句', '한문', '“漙漙曉露浥桃腮, 幽谷春深蝶不來. 却喜隣家銅鏡合, 更歌新曲酌金罍.”', '“흠뻑 맺힌 새벽이슬이 복사꽃 같은 뺨 적시는데, 깊은 골짜기엔 봄 깊어도 나비는 오지 않네. 도리어 이웃집의 거울이 합쳐짐을 기뻐해, 다시 새 곡조를 노래하며 금 술잔에 술 따르네.”', NULL),
    ('EWMPSJPG01YU00111', '소작품_만복사저포기_일본 내각문고_001_11_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '오씨의 시', '운문', '七言絶句', '한문', '“年年燕子舞東風, 腸斷春心事已空. 羨却芙蕖猶竝蔕, 夜深同浴一池中.”', '“해마다 제비는 봄바람에 춤추는데, 애끊는 춘정은 일이 이미 헛되었네. 오히려 연꽃이 꽃대를 나란히하고서, 한밤중에 같은 연못 속에서 함께 목욕하는 것을 부러워하네.”', NULL),
    ('EWMPSJPG01YU00112', '소작품_만복사저포기_일본 내각문고_001_12_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '오씨의 시', '운문', '七言絶句', '한문', '“一層樓在碧山中, 連理枝頭花正紅. 却恨人生不如樹, 靑年薄命淚凝瞳.”', '“한 층 누각이 푸른 산속에 있는데, 연리지 가지 끝에는 꽃이 참으로 붉구나. 도리어 인생이 나무만 못함을 한스럽게 여겨, 박명한 청춘은 눈물이 눈동자에 맺히네.”', NULL),
    ('EWMPSJPG01YU00113', '소작품_만복사저포기_일본 내각문고_001_13_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '김씨의 시', '운문', '七言絶句', '한문', '“杜鵑鳴了五更風, 寥落星河已轉東. 莫把玉簫重再弄, 風情恐與俗人通.”', '“두견새 울어대는 오경 무렵의 바람에, 희미한 은하수는 이미 동쪽으로 돌아섰네. 옥퉁소를 다시는 불지 마시오. 풍정이 속인에게 알려질까 두렵구나.”', NULL),
    ('EWMPSJPG01YU00114', '소작품_만복사저포기_일본 내각문고_001_14_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '김씨의 시', '운문', '七言絶句', '한문', '“滿酌烏程金叵羅, 會須取醉莫辭多. 明朝捲地東風惡, 一段春光奈夢何.”', '“금 술잔에 오정주(烏程酒) 가득 부었으니, 모름지기 취해야지 많다고 사양하지 마소서. 내일 아침엔 땅을 휩쓰는 사나운 동풍 불 텐데, 한 조각 봄빛은 꿈같으니 어찌하겠는가?”', NULL),
    ('EWMPSJPG01YU00115', '소작품_만복사저포기_일본 내각문고_001_15_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '김씨의 시', '운문', '七言絶句', '한문', '“綠紗衣袂懶來垂, 絃管聲中酒百巵. 淸興未闌歸未可, 更將新語製新詞.”', '“푸른 비단 옷소매를 게을리 늘어뜨리고, 현악기와 관악기 소리 속에 술 백 잔을 돌리네. 맑은 흥취 다하지 않아 아직 돌아갈 수 없으니, 다시 새로운 말로 새로운 노래를 짓노라.”', NULL),
    ('EWMPSJPG01YU00116', '소작품_만복사저포기_일본 내각문고_001_16_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '김씨의 시', '운문', '七言絶句', '한문', '“幾年塵土惹雲鬟, 今日逢人一解顔. 莫把高唐神境事, 風流話柄落人間.”', '“몇 년 동안 땅속에서 구름머리 묻혔었나. 오늘 님을 만나 한 번 얼굴을 펴보네. 그러니 고당의 선경에서 있었던 일을 가져다가, 풍류의 이야깃거리로 인간 세상에 퍼뜨리지 마소서.”', NULL),
    ('EWMPSJPG01YU00117', '소작품_만복사저포기_일본 내각문고_001_17_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '유씨의 시', '운문', '七言絶句', '한문', '“確守幽貞經幾年, 香魂玉骨掩重泉. 春宵每與姮娥伴, 叢桂花邊愛獨眠.”', '“그윽한 정절 굳게 지키며 몇 년이나 지냈던가. 향기로운 혼과 옥 같은 뼈는 황천에 묻혀서, 봄밤마다 늘 항아와 함께하면서 육계나무 꽃가에서 홀로 자기를 즐기네.”', NULL),
    ('EWMPSJPG01YU00118', '소작품_만복사저포기_일본 내각문고_001_18_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '유씨의 시', '운문', '七言絶句', '한문', '“却笑春風桃李花, 飄飄萬點落人家. 平生莫把靑蠅點, 誤作崑山玉上瑕.”', '“문득 봄바람의 복사꽃과 오얏꽃이 흩날리며 만 점 꽃이 남의 집에 떨어지네. 평소 푸른 파리가 싸놓은 똥을 곤륜산 옥의 흠으로 잘못 여기지 않았네.”', NULL),
    ('EWMPSJPG01YU00119', '소작품_만복사저포기_일본 내각문고_001_19_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '유씨의 시', '운문', '七言絶句', '한문', '“脂粉慵拈首似蓬, 塵埋香匣綠生銅. 今朝幸預鄰家宴, 羞看冠花別樣紅.”', '“연지와 분 바르길 게을리해 머리는 쑥대 같고, 향갑엔 먼지가 쌓이고 구리거울엔 푸른 녹이 슬었네. 오늘 아침 다행히 이웃집 잔치에 참여해, 관화가 유별나게 붉은 것을 부끄럽게 보네.”', NULL),
    ('EWMPSJPG01YU00120', '소작품_만복사저포기_일본 내각문고_001_20_운문_칠언절구', '만복사저포기', '萬福寺樗蒲記', '유씨의 시', '운문', '七言絶句', '한문', '“娘娘今配白面郞, 天定因緣契闊香. 月老已傳琴瑟線, 從今相待似鴻光.”', '“낭자께서 이제 백면 낭군과 짝지었으니, 하늘이 정한 인연은 매우 향기롭네. 월하노인 이미 금슬의 실을 전했으니, 이제부터 양홍과 맹광처럼 서로 대하리라.”', NULL),
    ('EWMPSJPG01YU00121', '소작품_만복사저포기_일본 내각문고_001_21_운문_칠언율시', '만복사저포기', '萬福寺樗蒲記', '하씨의 시', '운문', '七言律詩', '한문', '“開寧洞裏抱春愁, 花落花開感百憂. 楚峽雲中君不見, 湘江竹下泣盈眸? 晴江日暖鴛鴦竝, 碧落雲銷翡翠遊. 好是同心雙綰結, 莫將紈扇怨淸秋.”', '“개령동 속에서 봄 시름 품었으니, 꽃 지고 피자 온갖 근심 가졌네. 초나라 골짜기 구름 속에 그대는 보지 못했는가? 소상강 대나무 아래 눈물만 눈동자에 가득하네. 맑은 강물엔 따스한 햇살 비치니 원앙새 나란히 놀고, 푸른 하늘엔 구름 걷히자 비취새 날아다니네. 좋구나 이렇게 동심결을 맺었으니, 부디 비단 부채를 가지고 맑은 가을 원망하지 마소서.”', NULL),
    ('EWMPSJPG01YU00122', '소작품_만복사저포기_일본 내각문고_001_22_운문_고풍장단편', '만복사저포기', '萬福寺樗蒲記', '양생의 시', '운문', '古風長短篇', '한문', '“今夕何夕? 見此仙姝. 花顔何婥妁, 絳脣似櫻珠. 風騷尤巧妙, 易安當含糊. 織女投機下天津, 嫦娥抛杵離淸都. 靚粧照此玳瑁筵, 羽觴交飛淸讌娛. 殢雨尤雲雖未慣, 淺斟低唱相怡愉. 自喜誤入蓬萊島, 對此仙府風流徒. 瑤漿瓊液溢芳樽, 瑞腦霧噴金猊爐. 白玉牀前香屑飛, 微風撼波靑紗廚. 眞人會我合巹巵, 綵雲冉冉相縈紆. 君不見文簫遇彩鸞, 張碩逢杜蘭. 人生相合定有緣, 會須擧白相闌珊. 娘子何爲出輕言, 道我掩棄秋風紈. 世世生生爲配耦, 花前月下相盤桓.”', '“오늘 밤이 무슨 밤이길래 이러한 선녀를 만났는가? 꽃 같은 얼굴 어찌 이리 아름다운가? 붉은 입술은 앵두 구슬 같구나. 풍소(風騷)가 더욱 교묘하니 이안(易安)도 입을 다물겠구나. 직녀가 베틀 던져두고 은하수에서 내려왔나, 항아가 절굿공이 버리고 청도를 떠나왔나. 단장한 모습은 이 대모연(玳瑁筵)을 비추고 깃털 술잔 교차하며 청아한 잔치를 즐겁구나. 운우지정이 비록 아직 익숙하지 않으나 술 조금 따르고 나직이 노래하며 즐거워하네. 스스로 기뻐하는 것은 봉래도에 잘못 들어와 이 신선 고을의 풍류객들을 마주하는 것이라네. 옥 같은 술은 향기로운 술동이에 넘치고 서뇌(瑞腦) 연기가 금사자 향로에서 뿜어 나오네. 백옥 침상 앞엔 향가루 흩날리고 미풍은 푸른 비단 휘장에 물결을 일으키네. 진인께서 나를 만나 합환주를 마시니 오색구름 뭉게뭉게 서로 휘감는구나. 그대는 보지 못했는가? 문소가 채란을 만나고 장석이 두란향을 만난 일을. 인생에서 서로 만남은 정해진 인연 있으니 마땅히 막걸리 잔을 들어 흠뻑 취해야 하리. 낭자께서는 어찌 가벼운 말씀을 내시어 내가 가을바람 속 깁부채처럼 버릴 것이라 하십니까? 대대손손 살아가며 배필이 되어 꽃 앞과 달 아래에서 서로 머무르리.”', NULL),
    ('EWMPSJPG01YU00123', '소작품_만복사저포기_일본 내각문고_001_23_운문_사언시', '만복사저포기', '萬福寺樗蒲記', '하씨의 시', '운문', '四言詩', '한문', '“冥數有限, 慘然將別. 願我良人, 無或疎闊. 哀哀父母, 不我匹兮. 漠漠九原, 心糾結兮.”', '“저승의 운수에 한계가 있어, 처연히 이별하게 되었습니다. 바라건대 우리 낭군께서는, 혹여 자기 몸을 소홀히하지 마십시오. 슬프고 슬프구나 부모님이여, 내게 짝을 지어 주지 못하셨네. 아득하고 아득한 구천에서, 내 마음이 얽히고 맺히겠구나.”', NULL),
    ('EWMPSJPG01YU00124', '소작품_만복사저포기_일본 내각문고_001_24_산문_제문', '만복사저포기', '萬福寺樗蒲記', '양생의 제문', '산문', '祭文', '한문', '“惟靈生而溫麗, 長而淸渟. 儀容侔於西施, 詩賦高於淑眞. 不出香閨之內, 常聽鯉庭之箴, 逢亂離而璧完, 遇寇賊而珠沈. 托蓬蒿而獨處, 對花月而傷心. 腸斷春風, 哀杜鵑之啼血, 膽裂秋霜, 歎紈扇之無緣. 嚮者, 一夜邂逅, 心緖纏綿. 雖識幽明之相隔, 實盡魚水之同歡. 將謂百年以偕老, 豈期一夕而悲酸? 月窟驂鸞之姝, 巫山行雨之娘, 地黯黯而莫歸, 天漠漠而難望. 入不言兮恍惚, 出不逝兮蒼茫. 對靈幃而掩泣, 酌瓊漿而增傷. 感音容之窈窈, 想言語之琅琅. 嗚虖哀哉! 爾性聰慧, 爾氣精詳. 三魂縱散, 一靈何亡? 應降臨而陟庭, 或薰蒿而在傍. 雖死生之有異, 庶有感於些章!”', '“그대의 영령은 태어남에 온화하고 고왔으며 자라서는 맑고 깨끗했습니다. 용모는 서시(西施)에 견줄 만하고 시부(詩賦)는 주숙진(朱淑眞)보다 뛰어났습니다. 규방 안을 벗어나지 않고 늘 부모의 가르침을 듣다가 난리를 만났을 때 절개를 옥처럼 온전히 했는데, 도적을 만나 진주가 물에 잠기듯 안타깝게 죽었습니다. 쑥대밭에 의탁해 홀로 지내다가 꽃과 달을 대하며 상심했습니다. 봄바람에 애간장 끊어지니 두견새가 피눈물 흘리는 것을 슬퍼했고, 가을 서리에 간담이 쪼개지니 버림받은 비단 부채가 인연을 만나지 못한 신세를 탄식했습니다. 지난번 하룻밤 만남에 마음이 서로 얽히고 말았으니 비록 이승과 저승이 막혀 있음을 알고서도 참으로 물고기가 물을 만난 것처럼 기쁨을 다했습니다. 장차 백년해로를 하고자 했으나 어찌 하룻밤 만에 헤어져 슬프고 쓰라릴 줄을 기약했겠습니까? 달 속 궁궐에서 난새를 타던 여인이었으며, 무산에서 비를 뿌리는 낭자였구나. 땅은 어둑어둑해 돌아갈 수 없고 하늘은 아득해 바라보기가 어렵습니다. 들어와서는 멍하니 말이 없고 나가서는 아득히 갈 길이 없습니다. 영위(靈幃)를 대하고 눈물 훔치며 맑은 술을 따르니 상심만 더해지지만, 그윽한 음성과 용모를 떠올리며 낭랑했던 목소리를 그리워합니다. 아아! 슬프도다! 그대의 성품은 총명했으며 그대의 기운은 빼어났으니 삼혼(三魂)이 비록 흩어졌더라도 그대의 혼령이 어찌 사라졌겠습니까? 응당 강림해 뜰에 오르시거나 아니면 아지랑이처럼 옆에 있을 것입니다. 비록 삶과 죽음에는 차이가 있겠으나 바라건대 이 제문에 감응하소서.”', NULL),
    ('EWMOMYR01NU00101', '소작품_만옹몽유록_한국 국립중앙도서관_001_01_운문_오언절구', '만옹몽유록', '謾翁夢遊錄', '종결평', '운문', '五言絶句', '한문', '"一自飮仙酒, 身輕眼又明. 從知吾夢信, 豈曰構虛成."', '"한번 신선의 술을 마신 뒤로, 몸이 가벼워지고 눈 또한 밝아지네. 이로부터 내 꿈이 참됨을 알겠으니 어찌 허황되게 얽었다고 하겠는가?"', NULL),
    ('EWSJYNJ01NU00101', '소작품_산중열녀전_한국 경북대학교_001_01_운문_육언시', '산중열녀전', '山中列女傳', '산중부인의 시', '운문', '六言詩', '한문', '“新人對於黑夜, 舊夫泣於黃泉.”', '“새 사람을 캄캄한 밤에 마주하니, 옛 남편은 황천에서 울고 있구나.”', NULL),
    ('EWOHMJM01NU00101', '소작품_옹후묘지명_한국 규장각한국학연구원_001_산문_명', '옹후묘지명', '雍侯墓誌銘', '최종평', '산문', '銘', '한문', '“繄君之先, 氏自雍伯, 曰糾曰廩, 亦載其跡. 在漢爲侯, 惟齒乃聞, 不顯亦世, 爰及于君. 彭蠡秋江, 浩浩襟胷, 旣窈且深, 載廓有容. 不曰堅乎? 磨而不磷. 銘君之德, 永示後人.”', '마침내 그를 위하여 명을 짓는다. “아!옹군의 선계여, 그의 성씨는 옹백(雍伯)부터 시작하니 옹규(雍糾)나 옹름(雍廩)이라 하는이들, 또한 그 자취를 남겼네. 한(漢)대에 제후를 지낸, 옹치(雍齒)만이 이에 알려졌으나. 또한 세상에 현달하지 못했는데, 마침내 옹군에 이르렀네. 동정호(洞庭湖)의 가을 강처럼, 드넓은 마음씨를 지녔고. 그윽하면서 또한 깊으며, 더욱이 관대한데다 아량을 갖췄다네. 굳세다고 해야하지 않겠는가? 갈더라도 닳지를 않는구나. 옹군의 덕을 새겨서, 영원히 후인들에게 보게 하리라.', NULL),
    ('EWWRPHJ01NU00201', '소작품_왕랑반혼전_한국 동국대학교_001_01_운문_게송', '왕랑반혼전', '王郞返魂傳', '저승사자의 게송', '운문', '偈頌', '한문', '“我作冥間使, 今已百千劫. 不見念佛人, 墮於惡道中.”', '“우리가 저승의 차사가 된 지, 올해로 백천 겁이 이미 지났는데, 부처를 염하는 사람 중에 , 악도에 떨어진 이는 보지 못했네”', NULL),
    ('EWWRPHJ01NU00202', '소작품_왕랑반혼전_한국 동국대학교_001_02_운문_게송', '왕랑반혼전', '王郞返魂傳', '시왕의 게송', '운문', '偈頌', '한문', '“西方主彌陁佛, 此娑婆別有緣. 若不一念彼佛, 冥曺猛使難降.', '“서방의 임금 아미타불께서는, 이 사바세계와 각별한 인연이 있도다. 만약 한결같이 저 부처를 염하지 않는다면, 저승의 용맹한 차사를 당해내기 어려울 것이다.”', NULL),
    ('EWWRPHJ01NU00203', '소작품_왕랑반혼전_한국 동국대학교_001_03_운문_게송', '왕랑반혼전', '王郞返魂傳', '왕랑의 게송', '운문', '偈頌', '한문', '“蒲堂妻子與財珍, 受苦當時不代身, 一念彌陁消罪報, 還生延命更修眞.”', '“집에 가득한 처자와 재물과 보화도, 고통을 받을 때는 이 몸을 대신하지 못하네. 일념으로 아미타불을 염해 죄보 사라지리니, 환생해 수명을 늘려 다시 진리를 닦으리라.”', NULL),
    ('EWYSJ02NU00101', '소작품_유생전_미국 하버드옌칭도서관_001_01_산문_소', '유생전', '劉生傳', '방상서의 상소', '산문', '疏', '한문', '“臣敢冒雷霆之威, 不避鐵鉞之誅, 敢玆仰疏. 臣果有一女息, 而今與左承相劉弘子, 相對定婚, 旣行納幣, 又大禮之日, 不遠矣. 今聖敎未知, 由此詔封後宮, 臣若退劉婚, 則於禮不可, 若不從國命, 於義不可. 願陛下深察焉.”', '“신(臣)이 감히 천둥과 같은 폐하의 위엄을 무릅쓰고 극형의 처벌을 피하지 않고서 감히 이렇게 우러러 소문(疏文)를 올립니다. 신에게 과연 딸 하나가 있는데 지금 좌승상 유홍의 아들과 서로 혼사를 정하여 이미 납폐(納幣)의 예를 행했고 또 혼례를 치를 날이 멀지 않았습니다. 지금 성상(聖上)의 하교는 이러한 연유를 알지 못하시고 이로 말미암아 조서를 내려 후궁으로 삼겠다고 하시니, 신이 만약 유씨의 집안과 혼약을 저버린다면 예(禮)에 어긋나고, 만약 국명(國命)을 따르지 않는다면 의(義)에 어긋납니다. 바라건대 폐하께서는 깊이 살펴주시옵소서.”', NULL),
    ('EWYSJ02NU00102', '소작품_유생전_미국 하버드옌칭도서관_001_02_산문_소', '유생전', '劉生傳', '방상서의 상소', '산문', '疏', '한문', '“夫君臣之義, 乃父子之間, 凡君父在上, 使臣子, 勿失其禮, 臣子在下, 使君父, 勿失其禮. 上下以禮, 相與自固, 國以永存, 爰及苗裔. 夫義之所在, 禮之所從, 君以禮, 臣以禮, 君無幽厲之道, 臣無指鹿之風. 今陛下, 聖神文武, 躬察禮義, 兆民咸戴其澤, 臣庶各臨其職, 朝野共爲安寧, 太平之風, 庶可望也. 今聖敎, 傳詔小臣曰: ‘不從國命, 誠欲避封, 勿爲更疏.’ 事特令敎下. 嚴威之下, 不必煩訴, 勢出不得已, 如是更疏, 觸怒君父, 探龍額編虎頭, 豈敢求生? 生不失禮義, 下亦從比干, 生而辱者, 不如死而榮. 願陛下, 以賜鐵鉞, 洗刃臣血, 以治逆命之罪. 夫忠臣不事二君, 烈女不更二夫, 小臣之女子, 既行亂於劉家, 更封後宮, 則液此無異於二夫. 臣恐萬歲後, 損傷陛下之威德也.”', '“무릇 군신의 의리는 곧 부자의 사이이니 군주와 어버이가 위에 계실 때는 신하와 아들이 그 예를 잃지 않도록 해야 하고, 신하와 자식이 아래에 있을 때는 군주와 어버이가 그 예를 잃지 않도록 해야 합니다. 위와 아래가 예로써 행한다면 서로 자연히 견고해지고 나라가 길이 보존되어 후대의 자손들까지 미치게 될 것입니다. 대저 의가 있는 곳이 예가 따르는 곳이니 군주가 예로써 하며 신하가 예로써 하면 군주는 유왕(幽王)과 여왕(厲王)의 도를 행하지 않고, 신하는 지록위마(指鹿爲馬)하는 관습이 사라질 것입니다. 지금 폐하께서 성신문무(聖神文武)하셔서 몸소 예의를 살피신다면 수많은 백성들이 전부 그 은택을 입고, 여러 신하들이 각각 그 직분에 임하며 조정과 민간이 모두 평안하게 되어 태평성대(太平聖代)의 모습을 기대할 수 있을 것입니다. 그런데 지금 성상의 하교가 소신에게 전하여 내리기를 ‘국명을 따르지 않고 진실로 후궁의 책봉을 피하려고 하니 다시는 상소하지 말라.’라고 하시고, 이 일에 특별히 교하(敎下)를 명령하셨습니다. 위엄 아래 번거롭게 호소해서는 안되지만 상황이 부득이하여 이렇게 다시 소문을 올려 폐하를 노하게 만들어, 용의 이마를 더듬고 호랑이의 머리털을 묶는 격이 되었으니 어찌 감히 살기를 바라겠습니까? 살아서 예의를 잃지 않아야 지하에서도 또한 비간(比干)을 따를 수 있으니, 살아서 욕되는 것이 죽어서 영화롭게 되느니만 못합니다. 바라건대 폐하께서는 극형을 내리셔서 신의 피로 칼날을 씻어 국명을 거역한 죄를 다스려주십시오. 대저 ‘충신(忠臣)은 두 임금을 섬기지 않고 열녀(烈女)는 두 지아비를 섬기지 않는다.’고 했으니, 소신의 딸이 이미 유씨 집안에 외람되이 제멋대로 약혼을 저질렀는데 다시 후궁으로 봉한다면 이는 두 남편을 섬기는 것과 다름이 없을 것입니다. 신은 폐하께서 세상을 떠나신 뒤에 폐하의 위엄과 덕망이 손상될까 두렵습니다.”', NULL),
    ('EWYSJ02NU00103', '소작품_유생전_미국 하버드옌칭도서관_001_03_산문_소', '유생전', '劉生傳', '유홍의 상소', '산문', '疏', '한문', '“臣聞之先聖, 上不失禮, 下不奸犯. 臣果與方家女子, 金石定婚, 旣行先禮, 今陛下, 不察禮義之所失, 威怯方家之女子. 臣意, 禮之失也小, 封後宮大乎? 願陛下察焉.”', '“신이 과거 성인의 말을 듣건대, 윗사람이 예를 잃지 않아야 아랫사람이 잘못된 일을 저지르지 않는다고 하였습니다. 신은 과연 방 상서네 딸과 금석처럼 굳게 정혼하고 이미 먼저 예를 행했는데, 지금 폐하께서 예의를 잃는 것을 살피지 않으시고 방 상서네 딸을 위협하주며 겁을 주고 계십니다. 신이 생각해보건대 폐하께서는 예를 잃는 것은 작다고 여기시고 후궁을 책봉하는 것은 크다고 여기십니까? 바라건대 폐하께서는 살펴주시옵소서.”', NULL),
    ('EWYSJ02NU00104', '소작품_유생전_미국 하버드옌칭도서관_001_04_산문_서찰', '유생전', '劉生傳', '방영애의 편지', '산문', '書札', '한문', '“方氏榮愛, 謹再拜奉書于劉郎君案下. 妾本與郎君, 雖無奠鴈親迎之道, 亦有玉環先聘之禮. 是以, 妾唐突私書, 敢瀆請覽. 誠知閨中處子之道理不可, 此勢不得已者, 何事? 妾薄命無雙, 在世之日不遠, 故暫忘恥廉, 以記情懷, 令人敢達. 願郎君勿責無禮, 深察情勢, 使篋扇懷恩, 綈布戀德, 則雖死之日, 猶生之年. 且前日郎君之大人, 與妾之先君, 以金石定約, 以玉環先禮曰: ‘泰山若礪, 黃河如帶, 永勿失期, 更無追懷.’ 妾自是後, 思入劉門, 而願捧箕箒. 造物爲猜, 好事多魔, 不意兩家先君, 久係皇獄, 痛恨不已. 幸被神明, 無事得釋, 相歡無比. 噫! 皇天無常, 時運不幸, 郎君連遭患喪, 失所無依, 流離道路, 妾之大人, 見之救之. 不忘前期, 與處客室, 令姑度日, 妾之私幸. 惟望婚禮, 百年偕老矣, 今右丞相達睦, 假托皇命, 威㤼求婚, 妾若不從國命, 先罪郎君, 禍及父母. 又若從國命, 則以背郎君, 爲永失前期, 以此一身, 進退難得, 無數哀痛. 百以思之, 則幸得一體慮, 死外則無策. 是以, 如是敘情, 鑑察焉. 妾之一身, 若死則皇詔無奈? 郎君免禍, 妾之父母免策也. 妾亦無愧於心, 此妾一得之計料. 然妾之父母, 本無他子, 只有小妾一身, 今既死後, 誰憐妾父之母之年老, 誰收父母之白骨乎? 願郎君勿以妾沒後故, 自同外人, 憐恤妾之父母, 雖黃泉之下, 庶幾暝目也. 且妾死後, 勿謂鄙累, 郎君親自斂襲, 乞埋骨於郎君先塋, 無依孤魂, 庶有依托, 免於地下之冤魂也.”', '“방영애는 삼가 재배하고 유 낭군께 편지 올립니다. 저는 본래 낭군과 비록 전안(奠雁)하고 친영(親迎)하는 예를 행하지 못했으나 또한 옥지환으로 먼저 납폐(納幣)의 예를 갖추었습니다. 이 때문에 제가 당돌하게 사사로이 편지를 올리니 감히 외람되이 읽어봐 주시길 청합니다. 진실로 규중 처자의 도리로 안된다는 것을 알지만 지금 상황이 어쩔 수가 없으니 무슨 일이겠습니까? 첩은 운명이 기구하기가 견줄 데 없어 세상에 있을 날이 얼마 남지 않았기에 우선 염치불고하고 정회를 적고 사람을 시켜 감히 전달했습니다. 바라건대 낭군께서는 저의 무례함을 꾸짖지 마시고 깊이 사정을 살피셔서 상자 속 부채 신세로 은혜를 품게 하고 명주 솜옷 신세로 덕을 그리워하게 해주신다면 비록 죽는 날이 오히려 사는 해일 것입니다. 또 전날에 낭군의 어르신께서 저의 아버님과 금석과 같은 다짐으로 혼사를 정하시고, 옥지환로 먼저 예를 행하시며 ‘태산이 숫돌처럼 갈아 없어지고 황하가 허리띠처럼 마르게 될 때 까지 길이 약속을 잃지 않아 다시 후회하는 일이 없도록 합시다.’라고 말씀하셨습니다. 저는 이날로부터 유씨 집안에 들어가서 부녀의 도리를 받들고자 생각했습니다. 그러나 조물주께서 시기하시고 좋은 일에는 방해가 많은지라 뜻밖에 두 집안의 어르신께서 오랫동안 황제의 옥사에 연루되어 통한을 금치 못했습니다. 다행히 신명(神明)을 입어 무사히 풀려났으니 서로 기뻐하심이 비할 데가 없었습니다. 아! 그러나 하늘이 무심하시고 운수가 불행하여 낭군께서 연이어 불상사를 당해 의지할 곳을 잃은 채 길에서 떠돌아다니게 되셨는데, 저의 아버님께서 발견하시고 도와주셨습니다. 그리고 전날의 약속을 잊지 않으셔서 객실에 머물게 하여 우선 날을 보내도록 해주셨으니 제게 있어 무척 다행입니다. 오직 혼례를 치르고 백년해로하기를 바라고 있었는데 지금 우승상 달목이 황명을 가탁하여 위협하고 겁을 주며 혼인을 요구하니, 만일 제가 국명을 따르지 않는다면 먼저 낭군에게 죄를 물을 것이고 재앙이 부모에게 미칠 것입니다. 또 국명을 따른다면 낭군을 배신하고 영영 전날의 약속을 어기는 것이 되니 이 한 몸이 이러지도 저러지도 못하여 수없이 애통해했습니다. 온갖 방법으로 고민하다가 마침 한 가지 대안을 냈으니 죽는 것 말고는 방법이 없습니다. 이 때문에 이와 같이 사정을 말씀드리는 것이니 살펴봐주십시오. 저 한 몸이 만약 죽게 된다면 황제의 조서가 내려와도 어찌할 수 없고 낭군께서도 화를 면하고 저의 부모님도 황제의 책명(策命)에서 벗어나며 저 역시 마음에 부끄러움이 없을 것이니 이것이 제가 생각해 낸 한 방법입니다. 그러나 첩의 부모님께서는 본래 다른 자식이 없고 단지 저 하나만 있으니 지금 죽은 후에 누가 저의 부모님의 연로함을 불쌍하게 생각해 주겠으며 누가 부모님의 백골을 거두어주겠습니까? 바라건대 낭군께서는 제가 이미 죽은 뒤라고 해서 남들과 똑같이 여기지 않아 첩의 부모님을 불쌍히 여겨주신다면 비록 황천의 아래에서라도 눈 감을 수 있을 것입니다. 또 제가 죽은 뒤에 저를 비루하다고 여기지 마시고 낭군께서 직접 저를 염습(斂襲)하셔서 부디 낭군의 선영에 유골을 묻어준다면, 의지할 곳 없는 고혼이 의탁할 수 있어 지하의 원혼이 되는 것을 면할 것입니다.”', NULL),
    ('EWYSJ02NU00105', '소작품_유생전_미국 하버드옌칭도서관_001_05_산문_서찰', '유생전', '劉生傳', '유정옥의 편지', '산문', '書札', '한문', '“薄命劉生正玉, 謹再拜奉答于玉娘子座下. 僕蓋前某月某日, 過窺玉娘子於後苑, 弄競秋千之狀, 歸來以後, 自然心神蕩亂, 伎癢不禁. 因遂疾病, 轉輾枕席, 遲離不起. 父母私憫, 深察情私, 果與娘子大人, 相約定婚, 欣喜無極, 感謝何勝? 其自以後, 結願少解, 窹寢思服, 苦待袵席之日矣. 噫! 皇天無助, 世道不振, 先君捐館, 老母亦辭堂. 孑孑單身, 零丁獨立, 三載風霜, 盡禮侍墓而歸, 家禍連綿, 婢僕分散, 財用空竭, 百事零替. 一身無依, 流離漂泊, 東西奔走, 娘子大人, 見而哀之, 收處客室, 衣食款待, 此不忘前日吾先君之言約. 是以, 日夜所念, 幸遇娘子, 若遂于飛, 庶報娘子之父母, 亦遂僕父母願. 故不能玉碎, 姑爲瓦全, 寄跡人門, 遷延歲月, 所望婚期. 今姑度日, 意外今夕, 伏承來使, 忙受尺素, 一喜一驚, 如對娘子. 然而看來未半, 心寒骨冷, 令人感傷. 僕三載所幹, 一朝冷落, 誰謂有志者, 事竟成也? 宿緣旣薄, 魔妖有戲, 失侶孤鴈, 飛落於何渚, 求友暮鶯, 驚散於秋風. 浮萍身勢, 落葉行色, 更歸何處? 娘子書中, 亦有絕雲, 何其過言也? 此非娘子之愆尤也. 乃是賤僕之薄福. 勿慮忘事. 保以貴體, 永奉父母, 以登達門, 萬端子孫, 百年同樂也. 且孝子, 百行之源也. 娘子知一未知二. 欲傷孝儀, 以取禮節, 誰謂娘子可也? 且娘子之父母, 更無他子, 只有娘子, 娘子不從親命, 若爲身死, 則白骨父母, 何所依託, 何處歸焉? 僕之八字奇薄, 夙遭憫凶, 俱喪父母, 辛苦歲月, 若此一身, 在世無益. 誠欲自絕, 則綿綿劉氏殘孫, 自絕無後, 不祀先塋, 此倫禮, 莫大罪焉, 必永失父母之遺言也. 此死亦未能, 生亦不敢, 可憐身勢, 罔極無托. 然而何面目, 更留此家, 以對相公? 噫! 夜色將曙, 則僕之行色, 重人所恥, 令欲乘昏退去, 不勝悲感, 躊躇難堪. 願娘子莫惜一盃酒, 使人受送, 則僕醉中暫忘憤感, 以察去向. 臨楮鳴咽, 小記萬一, 伏乞鑑之.”', '“박명한 유정옥은 삼가 재배하고 옥낭자(玉娘子)에게 답장 올립니다. 저는 이전 모월 모일에 뒤 정원에서 낭자께서 그네를 타고 노는 모습을 지나가다 엿보고, 집에 돌아온 다음 자연히 마음이 혼란스러워 간질거리는 마음을 견딜 수 없었습니다. 이에 병을 앓아 잠자리에서 엎치락뒤치락하며 마음에서 떠나지 않아 일어나지 못했습니다. 부모님께서 속으로 걱정하시고 제 심경을 깊이 살피셔서 과연 낭자의 부모님과 서로 정혼을 맺었다고 하니, 저의 기쁨이 그지없었는데 감사함을 어찌 다하겠습니까? 그 뒤로부터 결심했던 소원이 조금 풀려 자나 깨나 그리워하며 같이 지낼 날만 몹시 기다렸습니다. 아! 그러나 하늘께서 돕지 않으시고 세상의 도가 떨쳐지지 않아 아버지께서 돌아가시고 어머니께서도 세상을 떠났습니다. 혈혈단신으로 의지할 데 없이 홀로 3년 동안 풍상(風霜)을 겪으며 예를 다해 시묘살이를 마치고 돌아왔는데, 집안의 재앙이 끊이지 않아 노복들이 이리저리 흩어지고 가산이 전부 소모되어 모든 일이 허사가 되었습니다. 이 한 몸 의지할 곳 없는 채 정처 없이 헤매며 여기저기 떠돌아다니고 있었는데 낭자의 부친께서 저를 보고 불쌍히 안타까워하고는 데려다 객실에 거처하게 하고 의복과 음식으로 정성껏 대접해주셨으니, 이는 전날 제 부친과의 약속을 잊지 않으신 것입니다. 그리하여 ‘다행히 낭자를 만나서 만약 혼례를 치른다면 아마 낭자의 부모님에게 보답하고 나의 부모님의 바람도 이뤄지게 될텐데.’하고 밤낮으로 생각했습니다. 그래서 깨끗하게 죽지 못하고 겨우 심신만 보전하여 남의 집에 자취를 맡겨 세월만 보내며 혼인날만 바라보았습니다. 지금 이렇게 그냥저냥 날만 보내는데 뜻밖에 오늘 저녁 엎드려 삼가 심부름 온 시비에게서 바삐 편지를 받으니 한편으로 기쁘고 한편으로 놀라 마치 낭자를 마주하는 듯 했습니다. 그러나 반도 채 읽지 않았는데 마음이 서늘하고 뼈가 오싹하여 사람을 상심하게 합니다. 제가 3년 동안 도모하던 일이 하루아침에 무너졌으니 누가 “뜻이 있는 자는 일이 마침내 이루어진다.”라고 했습니까? 묵은 인연이 기박해졌고 마귀와 요괴가 희롱을 하고 있으니 짝 잃은 외로운 기러기는 어느 물가에 날아가 앉겠으며, 짝 찾는 저녁의 꾀꼬리는 가을바람에 놀라 흩어지게 되었습니다. 부평초 같은 신세와 낙엽과 같은 행색으로 다시 어디로 돌아가겠습니까? 낭자께서는 편지 내용에 또한 목숨을 끊겠다고 하시니 어찌하여 지나친 말씀을 하십니까? 이는 낭자의 잘못이 아니고 곧 미천한 제가 박복한 탓입니다. 혼약을 저버리는 것을 염려하지 마시고 귀한 몸을 보존하시어 길이 부모님을 모시고 달씨 가문에 시집가서 수많은 자손들과 백년해로하십시오. 또 효성스러운 자식은 모든 행동의 근원입니다. 그런데 낭자는 하나는 알고 둘은 모릅니다. 효의(孝儀)를 상하게 하여 예절을 취하려 하니 누가 낭자더러 옳다고 하겠습니까? 또 낭자의 부모님께서는 더욱이 다른 자식이 없으시고 다만 낭자만 있으니, 낭자께서 부모님의 명을 따르지 않고 만약 죽어버린다면 백골이 된 부모님께서는 어디에 의탁하며 어디로 가겠습니까? 저의 팔자가 기구하여 일찍이 우환과 변고를 만나 부모님을 모두 여의고 힘들게 세월을 보내고 있으니 이 한 몸 같은 경우는 세상에 있어봤자 도움이 안 됩니다. 그러나 진실로 스스로 목숨을 끊고자 한다면 겨우겨우 이어진 유씨가문이 저절로 끊겨 후손이 없어져 선영에 제사를 지내지 못하게 되니, 이는 인륜(人倫)에 있어 이보다 큰 죄가 없고 필시 부모님의 유언을 영원히 저버리는 것입니다. 이렇게 죽는 것 또한 할 수 없고 사는 것 또한 감당하지 못하고 있으니 가련한 제 신세가 망극하여 어쩔 줄 모르겠습니다. 그러하니 무슨 면목으로 다시 이 집에 머물며 상공을 대하겠습니까? 아 밤빛이 장차 밝아지면 저의 행색이 더욱 남에게 부끄러우니 어두울 때를 틈타 물러나고 싶지만 슬픔을 견디지 못해 주저하여 어쩌지 못하고 있습니다. 바라건대 낭자께서는 한 잔의 술을 아끼지 마시고 사람을 시켜 보내주신다면 제가 취중에 잠시라도 괴로움을 잊고서 어디로 떠날지 생각해 보겠습니다. 편지를 대하고 오열하며 수많은 저의 생각 중 일부를 조금 적었으니 바라건대 살펴봐주십시오.”', NULL),
    ('EWYSJ02NU00106', '소작품_유생전_미국 하버드옌칭도서관_001_06_산문_서찰', '유생전', '劉生傳', '방영애의 편지', '산문', '書札', '한문', '“酒肴雖薄, 出於情表, 指環無雙, 出於情勢. 然察於私情, 勿以重咎, 姑留外堂, 以看始末. 以憐秦涉之玉碎, 可迷金穀之花飛, 恤之哀之. 薄緣弱質, 雖未酬父母養育之恩, 亦知夫婦三從之禮, 且取義捨生, 古聖所戒. 妾以奉天霍女之心, 豈忍息國不言之婦? 噫! 郎君若不棄此情, 當合鏡於後世, 訪倩娘於來生也.”', '“술과 안주가 비록 보잘 것 없지만 정표(情表)에서 나온 것이고, 옥지환이 한 쌍이 없는 것은 부득이한 처지에서 나온 것입니다. 그러나 제 개인적인 사정을 살피셔서 너무 허물하지 마시고 우선 외당에 계셔서 일의 전말을 살펴보십시오. 진(秦)나라 진섭(陳涉)의 죽음을 불쌍히 여기는 마음이라면 금곡(金穀)의 흩날리는 꽃잎을 심취하실 수 있으실 테니 불쌍하고 애처롭게 여겨 주십시오. 운수가 사납고 체질이 연약해 비록 부모님께서 길러주신 은혜를 아직 갚을 수는 없으나, 또한 부부의 삼종(三從)의 예법을 알고 있고 또 의를 취해 목숨을 저버리는 것은 과거 성인께서 경계하신 바 입니다. 제가 천명을 받든 곽녀(霍女)의 마음을 가지고 어찌 식국(息國)의 말하지 않은 부인의 행동을 차마 하겠습니까? 아! 낭군께서 만일 이러한 정을 버리지 않으신다면 제가 응당 후세에 거울을 합하고, 내세에서 천랑(倩娘)을 찾을 것입니다.”', NULL),
    ('EWYSJ02NU00107', '소작품_유생전_미국 하버드옌칭도서관_001_07_산문_서찰', '유생전', '劉生傳', '유정옥의 편지', '산문', '書札', '한문', '“所送酒肴, 雖表三盃, 似重千金. 然娘子之言, 何其薄倖也? 娘子棄父母而先死, 三千之罪, 莫大焉, 娘子胡爲小節, 欲絕大義, 於心安乎? 更勿心慮, 善自珍重. 多罪正玉, 今爲退去, 然而彼百歲後, 如此情意, 庶敘地下爲望. 伏願娘子, 勿謂心慮, 百年無疆. 僕從此永決, 後期來生, 言止此矣. 伏乞察焉.”', '“보내주신 술과 안주는 비록 석 잔으로 표했지만 마치 천금처럼 귀중합니다. 그러나 낭자의 말은 어찌 이리도 매정하답니까? 낭자께서 부모를 버리고 먼저 죽는다면 삼천 가지 죄 중에 이보다 큰 것이 없으니 낭자께선 어찌 작은 절개를 위해 대의(大義)를 저버리려고 해야만 마음에 편하시겠습니까? 다시는 걱정하지 마시고 스스로 몸을 잘 보존하십시오. 죄 많은 저 정옥은 지금 물러가지만 저 100년 후에 이와 같은 마음을 지하에서 펴지기를 기대합니다. 삼가 바라건대 낭자께서는 염려스럽다는 말 마시고 만수무강하십시오. 저는 이로부터 영영 이별하고 이후 다음 생을 기약할 것이니 말을 이만 마치겠습니다. 삼가 살펴주십시오”', NULL),
    ('EWYSJ02NU00108', '소작품_유생전_미국 하버드옌칭도서관_001_08_산문_서찰', '유생전', '劉生傳', '유정옥의 편지', '산문', '書札', '한문', '“門下罪人劉正玉, 謹再拜奉書于座下, 生夙遭憫凶, 早喪父母, 東西丏乞, 流離行道. 尙書大人, 見而收之, 使困鳥, 托一枝之安, 俾枯魚, 籍斗水之活, 僅得保身, 安過餘日. 淺慮, 尙書以無依一人, 如是厚待, 此非他. 尙書應當不忘於先君之定約也, 此實感激. 生前未報之恩, 死後當爲含珠, 庶報其萬一矣, 意外今夕, 暫聞風便, 相公以達婚事, 心慮過度, 遺辱貴體, 此皆由小生之過也. 如是之後, 生更留此家, 於心誠爲否便, 於事體亦可殊常. 是以今夕姑爲退去, 後期雖爲極無常. 然今對相公尊儀, 以敘萬端之恩澤, 可以退去, 於事理當然, 反以思之, 則無面目對相公故, 姑未能下直, 私自出家. 其不美罪狀許赦!”', '“문하의 죄인 유정옥이 삼가 재배하고 상서의 좌하에 편지를 올립니다. 저는 젊은 나이에 우환과 변고를 만나 일찌감치 부모님을 여의고 이리저리 걸식하며 길거리를 떠돌아 다녔습니다. 그런데 상서 대인께서 저를 보고 거두셨으니 지친 새를 한 나뭇가지의 편안함에 깃들게 하고 다 죽어가는 물고기를 동이 물에 살도록 머물게 하는 격이라 겨우 몸을 보존할 수 있어 남은 날을 편안히 보내었습니다. 얕은 제 생각으로는 상서께서 의지할 데 없는 저를 이처럼 후하게 대접해주셨으니 이는 다른 뜻이 아닙니다. 상서께서는 분명 제 아버님과 정한 약속을 잊지 않으신 것이니 이는 정말 감격스러운 일입니다. 제가 살아서 아직 갚지 못한 은혜는 죽은 뒤에라도 마땅히 갚아야 하니 바라건대 만분의 일이라도 보답하고자 하였습니다. 그런데 뜻밖에도 오늘 저녁 소식을 잠깐 듣기로는 상공께서 달씨 가문과의 혼사 때문에 걱정이 많으셔서 귀하신 몸에 누를 끼친다고 하니 이는 모두 저의 잘못에서 비롯된 것입니다. 만일 이런 상황을 겪고도 제가 또 이 집에 머무른다면 마음에 진실로 불편하게 되며 도리상으로도 일반적이지 않습니다. 그러므로 오늘 저녁에 일단 물러나고자 하니 이후의 만남은 비록 지극히 무상합니다. 그러나 지금 상공의 모습을 직접 대하여 만단의 은택을 펼치고 물러나는 것이 일의 이치상 당연하지만. 돌이켜 생각해보니 상공을 뵐 면목이 없으므로 일단 작별인사를 드리지 않고 사사로이 집에서 떠나겠습니다. 이 불미스러운 죄상을 용서해 주십시오.”', NULL),
    ('EWYSJ02NU00109', '소작품_유생전_미국 하버드옌칭도서관_001_09_산문_서찰', '유생전', '劉生傳', '방영애의 편지', '산문', '書札', '한문', '“不孝榮愛, 謹再拜謝罪, 于父母堂下. 小女久處閨中, 粗通詩書, 非不知父母難酬之澤, 亦少察夫婦昌隨之義. 是以, 又小女與劉郎, 雖無奠鴈之道, 亦有納幣之禮, 小女心中, 終不忘也. 噫! 今以權門之所迫, 永失劉氏之定約, 此小女一身, 如維谷羝羊, 進退難堪. 是以, 一身死外無策. 若死後, 則父母主, 無妨皇禍, 而亦莫失劉相公, 黃河泰山之約. 小女無奈失禮, 而亦免罪玉指環先受之道, 小女何忍彎鳳之姿, 寧配於烏鵲之惡, 亦以蒲柳之弱質, 豈合馹儈之材也? 夫生而辱者, 不如死而榮. 由是, 不取瓦全於狂風, 惟知玉碎之夜月. 雖云赤子之入井, 豈是飛蛾之撲燈也? 乃己之自取. 然而情雖篤於夫妻, 恩敢忘於父母乎? 況此小女與劉郎, 元無私眤之情, 而亦無結縭之事, 豈有身死之貞哉? 劉相公之定約, 尙在耳邊, 相公之指環, 亦在衣帶. 思其言, 則不忍背之, 見其環, 則不棄之. 勢出於不得已之中, 義出於不得已之中, 願父母, 赦罪察焉. 噫! 薄命此身, 無孝之罪, 死不洗焉, 守貞之道, 死當布焉. 願父母百歲之後, 小女庶報萬一之澤於地下, 以小女沒故, 不爲哀痛, 保體珍重. 然而小女身體, 以召劉郎君, 親爲斂襲, 亦埋劉相公墓下, 庶雪今生之冤恨, 庶冤地下之孤魂也, 今以此一封書, 永訣父母, 悠然棄世, 罔極罔極. 心神昏迷, 不能盡記.”', '“불효녀 영애가 삼가 부모님 당하(堂下)에서 두 번 절하고 사죄드립니다. 제가 오랫동안 규방 안에 거처하면서 거칠게나마 시서(詩書)를 알아서 부모님께 보답하기 어려운 은택을 모르지 않고, 또한 부창부수(夫唱婦隨)의 의리도 조금 압니다. 그러므로 또 소녀가 유 낭군과 비록 전안(奠鴈)의 예를 행하지는 않았으나 또한 납폐(納幣)의 예는 지냈으니, 소녀의 마음속에 끝내 잊히지 않습니다. 아! 지금 권세 있는 가문이 핍박하고 있는 바 영원히 유씨 집안과 정한 혼약을 저버리게 되었으니 이 소녀 한 몸이 마치 유곡(維谷)의 숫양의 뿔이 울타리에 걸린 마냥 꼼짝없이 이러지도 저러지도 못하고 있습니다. 이 때문에 이 한 몸이 죽는 것 말고는 다른 방법이 없었습니다. 만약 제가 죽게 된다면 부모님께서는 황제의 재앙과 무관하게 되고 또한 유 상공께서 황하와 태산을 두고 한 약속을 저버리지 않게 될 것입니다. 소녀는 어쩔 수 없이 예를 잃었으나 또한 옥지환을 먼저 받은 도리에 대한 죄는 면할 것이니 소녀가 어찌 차마 난새와 봉황의 자질로 어찌 까마귀와 까치의 짝이 된다는 싫은 소리를 듣겠으며, 또한 부들과 버들의 연약한 기질로 어찌 거간꾼과 같은 인물의 짝이 되겠습니까? 대저 살아서 욕되는 것이 죽어서 영예로워짐만 못합니다. 이런 까닭에 거센 바람에 멀쩡한 기와를 취하지 않고, 달이 비추는 밤에 부서지는 옥이 귀한 줄 알 뿐입니다. 비록 ‘어린아이가 우물로 기어가는 것이다.’라고 말할 수 있겠으나, 어찌 이것이 나방이 등불을 향해 뛰어드는 격이겠습니까? 이는 곧 제가 자초한 일입니다. 그러나 비록 부부 사이에 정이 두텁다고 하지만 어찌 감히 부모의 은혜를 잊는답니까? 더구나 이 소녀는 낭군과 원래 사사로이 눈길을 주고받는 정도 없었고 또한 혼례를 올린 일도 없었으니 어찌 목숨을 바쳐야 할 정절이 있겠습니까? 그렇지만 유상공과 정한 약속이 아직도 귓가에 맴돌고 있고 유 승상께서 주신 옥지환이 아직 의대(衣帶)에 걸려 있습니다. 그때의 말을 생각하면 차마 배반할 수가 없었고 그 옥지환을 보면 버릴 수가 없었습니다. 사정이 어쩔 수 없는 가운데 나왔고 의리도 마지못한 가운데 나왔으니 바라건대 부모께서는 죄를 용서하시고 살펴주십시오. 아! 박명한 이 몸이 효도하지 못한 죄는 죽어도 씻지 못하겠지만 정절을 지킨 도리는 죽어야 응당 펴질 것입니다. 바라건대 부모님께서 세상을 떠나신 뒤에 제가 지하에서 만분의 일의 은택이나마 갚고자 하니 제가 죽은 것 때문에 애통해하지 마시고 귀한 몸을 보중하십시오. 그렇지만 저의 시신을 유 낭군을 불러서 친히 염습해 주시고 또한 유 상공의 무덤 아래에 묻어주신다면, 지금 살아있는 자들의 원한을 씻어주고 지하의 고혼이 가졌을 원한을 풀어 줄 것입니다. 지금 이 편지 한 통으로 영영 부모님과 이별하고 훌쩍 세상을 떠나게 되었으니 망극하고 망극합니다. 마음이 혼미하여 다 기록하지 못하겠습니다.”', NULL),
    ('EWLSJ01NU00101', '소작품_이생전_한국 국사편찬위원회_001_01_운문_오언절구', '이생전', '李生傳', '이감역의 시', '운문', '五言絶句', '한문', '“山帶芳春色, 人閑落日時. 奇童何處來, 詩酒政當施.”', '‘산은 꽃다운 봄빛을 둘렀으며, 사람은 해질 무렵 한가로이 있네. 
INSERT INTO "allusion" ("id", "name", "citation_type", "title_chi", "title_kor", "work_chi", "work_kor", "allusion_type", "explain", "original_text", "translation", "notes", "source_work") VALUES
    ('A001', '전고_어전_경_사서류_논어_팔일_000', '어전', '論語', '논어', '八佾', '팔일', '경(經)', '사서류(四書類)', '成事不說, 遂事不諫, 旣往不咎', '다 된 일은 말하지 않고, 벌어진 일인 일은 나무라지 않으며, 이미 지난 것은 탓하지 않는다.', NULL, '김현감호'),
    ('A002', '전고_어전_경_시류_시경_국풍_빈풍_동산_000', '어전', '詩經', '시경', '國風_豳風_東山', '국풍_빈풍_동산', '경(經)', '시류(詩類)', '之子于歸, 皇駁其馬. 親結其縭, 九十其儀.', '아가씨 시집가니 누런 말과 얼룩말이로다. 어머니가 향주머니 채워 주니 그 위의 성대하도다', NULL, '김현감호'),
    ('A003', '전고_어전_사_정사류_진서_갈홍전_000', '어전', '晉書', '진서', '葛洪傳', '갈홍전', '사(史)', '정사류(正史類)', '藜藿有八珍之甘, 蓬蓽有藻梲之樂也', '여곽(藜藿)을 먹어도 팔진(八珍)의 감미로움이 있고, 봉필(蓬蓽)에 살아도 조절(藻梲)의 즐거움이 있다', NULL, '김현감호'),
    ('A004', '전고_사전_사_정사류_한서_매복전_000', '사전', '漢書', '한서', '梅福傳', '매복전', '사(史)', '정사류(正史類)', '王莽顓政，福一朝棄妻子，去九江，至今傳以爲仙', '왕망이 정권을 전횡하자 매복은 하루아침에 처자를 버리고 구강으로 갔으니 지금은 신선이 되었다고 한다.', NULL, '김현감호'),
    ('A005', '전고_사전_사_정사류_후한서_일민열전_양홍전_000', '사전', '後漢書', '후한서', '逸民列傳_梁鴻傳', '일민열전_양홍전', '사(史)', '정사류(正史類)', '遂至吳, 依大家皐伯通, 居廡下, 爲人賃舂. 每歸, 妻爲具食, 不敢於鴻前仰視, 舉案齊眉. 伯通察而異之, 曰: “彼傭能使其妻敬之如此, 非凡人也.', '양홍이 드디어 오(吳)나라에 도착해 대가(大家) 고백통(皐伯通)에게 의지해 행랑채 아래에 거처하며 남의 집 절구질을 해주는 품을 팔았다. 매번 돌아올 때마다 아내 맹광이 음식을 준비했는데 감히 양홍의 앞에서 우러러보지 못하고 밥상을 눈썹 높이까지 받들어 올렸다. 고백통이 살펴보고 그것을 기이하게 여겨 말했다. “저 품꾼이 능히 그 아내로 하여금 공경하기를 이토록 하니 평범한 사람이 아니다.', NULL, '김현감호'),
    ('A006', '전고_어전_경_역류_주역_관괘_000', '어전', '周易', '주역', '觀卦', '관괘', '경(經)', '역류(易類)', '觀國之光, 利用賓于王', '“나라의 빛을 보는 것이니, 임금께 손님이 되는 것이 이롭다', NULL, '낙우애우기'),
    ('A007', '전고_어전_경_사서류_맹자_등문공하_000', '어전', '孟子', '맹자', '滕文公下', '등문공하', '경(經)', '사서류(四書類)', '不待父母之命, 媒妁之言, 鑽穴隙相窺, 踰牆相從, 則父母國人, 皆賤之.', '부모의 명과 중매의 말을 기다리지 않고 구멍의 틈을 뚫고 서로 엿보며 담을 넘어 상종하면 부모와 나라 사람들이 모두 천하게 여긴다.', NULL, '낙우애우기'),
    ('A008', '전고_어전_경_사서류_논어_자한_000', '어전', '論語', '논어', '子罕', '자한', '경(經)', '사서류(四書類)', '子貢曰: 有美玉於斯, 韞櫝而藏諸? 求善賈而沽諸? 子曰: “沽之哉! 沽之哉! 我待賈者也.”', '자공이 말했다. "아름다운 옥이 여기에 있다면 이를 궤에 담아서 감춰 두시겠습니까? 좋은 값을 받고 파시겠습니까?" 
INSERT INTO "allusion" ("id", "name", "citation_type", "title_chi", "title_kor", "work_chi", "work_kor", "allusion_type", "explain", "original_text", "translation", "notes", "source_work") VALUES
    ('A201', '전고_어전_사_정사류_한서_고제기_000', '어전', '漢書', '한서', '高帝紀', '고제기', '사(史)', '정사류(正史類)', '臣有息女, 願爲箕箒妾.', '신에게 여식이 있는데 기추첩으로 바치기를 바랍니다.', NULL, '유생전'),
    ('A202', '전고_사전_자_소설가류_세설신어_혹닉_000', '사전', '世說新語', '세설신어', '惑溺', '혹닉', '자(子)', '소설가류(小說家類)', '韓壽美姿容, 賈充辟以爲掾. 充每聚會, 賈女於靑璅中看, 見壽, 說之. 恆懷存想, 發於吟詠. 後婢往壽家, 具述如此, 并言女光麗. 壽聞之心動, 遂請婢潛修音問. 及期往宿. 壽蹻捷絕人, 踰牆而入, 家中莫知. 自是充覺女盛自拂拭, 說暢有異於常. 後會諸吏, 聞壽有奇香之氣, 是外國所貢, 一著人, 則歷月不歇. 充計武帝唯賜己及陳騫, 餘家無此香, 疑壽與女通, 而垣牆重密, 門閤急峻, 何由得爾? 乃託言有盜, 令人修牆. 使反曰：“其餘無異, 唯東北角如有人跡. 而牆高, 非人所踰.” 充乃取女左右婢考問, 卽以狀對. 充秘之, 以女妻壽.', NULL, NULL, NULL),
    ('A203', '전고_사전_집_별집류_도연명집_도화원기_000', '사전', '陶淵明集', '도연명집', '桃花源記', '도화원기', '집(集)', '별집류(別集類)', '太元中, 武陵人捕魚爲業, 緣溪行, 忘路之遠近, 忽達桃花林', '진나라 태원 연간에 무릉 사람으로 고기잡이를 업으로 삼고 있는 사람이 있었다. 하루는 물길을 따라 갔다가 얼마나 멀리 왔는지도 모를 무렵 홀연히 복숭아꽃 숲이 눈앞에 나타났다.', NULL, NULL),
    ('A204', '전고_사전_자_잡가류_회남자_남명훈_000', '사전', '淮南子', '회남자', '覽冥訓', '남명훈', '자(子)', '잡가류(雜家類)', '羿請不死之藥於西王母, 姮娥竊以奔月, 悵然有喪, 無以續之. 何則? 不知不死之藥所由生也. 是故乞火不若取燧, 寄汲不若鑿井.', '예(羿)가 서왕모(西王母)에게 불사약을 했는데 항아가 이를 몰래 훔쳐 달나라로 도망갔다.', NULL, '이생전'),
    ('A205', '전고_사전_도_도경류_열자_탕문_000', '사전', '列子', '열자', '湯問', '탕문', '도(道)', '도경류(道經類)', '八紘九野之水, 天漢之流, 莫不注之, 而無增無減焉. 其中有五山焉:一曰岱輿, 二曰員嶠, 三曰方壺, 四曰瀛洲, 五曰蓬萊.', '팔현(八紘)과 구야(九野)의 물과 은하수(天漢)의 흐름이 이곳으로 쏟아져 들어가지 않는 것이 없으나 늘어나지도 줄어들지도 않는다. 그 가운데에 다섯 산이 있으니, 첫째는 대여(岱輿), 둘째는 원교(員嶠), 셋째는 방호(方壺), 넷째는 영주(瀛洲), 다섯째는 봉래(蓬萊)라 한다.', NULL, '최치원'),
    ('A206', '전고_사전_사_전기류_열녀전_모의전_유후이비_000', '사전', '列女傳', '열녀전', '母儀傳_有虞二妃', '모의전_유후이비', '사(史)', '전기류(傳記類)', '旣納於百揆, 賓於四門, 選於林木, 入於大麓 堯試之百方 每事常謀於二女. 舜旣嗣位, 升爲天子, 娥皇爲后, 女英爲妃. 封象於有庳, 事瞽叟猶若初焉. 天下稱二妃聰明貞仁. 舜陟方, 死於蒼梧, 號曰重華. 二妃死於江湘之間, 俗謂之湘君.', NULL, NULL, '유생전, 최치원'),
    ('A207', '전고_어전_집_별집류_매월당집_제유황고목도_000', '어전', '梅月堂集', '매월당집', '題幽篁古木圖', '제유황고목도', '집(集)', '별집류(別集類)', '韋偃與可已爲鬼, 阿誰下筆傳高蹤.', '위언(韋偃)과 여가(與可)는 이미 귀신이 되었거늘, 누가 붓을 들어 고귀한 자취를 전하는가.', NULL, NULL),
    ('A208', '전고_사전_사_정사류_원사_조맹부전_000', '사전', '元史', '원사', '趙孟頫傳', '조맹부전', '사(史)', '정사류(正史類)', '孟頫所著, 有尙書註, 有琴原、樂原, 得律呂不傳之妙, 詩文淸邃奇逸, 讀之, 使人有飄飄出塵之想. 篆籀分隸眞行草書, 無不冠絕古今, 遂以書名天下. 天竺有僧, 數萬里來求其書歸, 國中寶之. 其畵山水木石花竹人馬尤精緻. 前史官楊載稱孟頫之才頗爲書畵所掩, 知其書畵者, 不知其文章, 知其文章者, 不知其經濟之學. 人以爲知言云.', NULL, NULL, NULL),
    ('A209', '전고_사전_자_예술류_서사회요_원_관부인_000', '사전', '書史會要', '서사회요', '元_管夫人', '원_관부인', '자(子)', '예술류(藝術類)', '管夫人諱道昇, 字仲姫, 吳興人, 趙魏公室, 封魏國夫人. 有才略, 聰明過人. 爲詞章, 作墨竹, 筆意淸絕亦能書. 仁宗嘗取夫人書, 合魏公及子雍書, 善裝爲卷軸, 識以御寳, 命藏之祕書監, 曰：“使後世知我朝有一家, 夫婦父子, 皆善書也', NULL, NULL, NULL),
    ('A210', '전고_어전_집_별집류_산곡집_질사수지명주행_000', '어전', '山谷集', '산곡집', '姪㭒隨知命舟行', '질사수지명주행', '집(集)', '별집류(別集類)', '淸江濯足江下坐, 燕子日長宜讀書', '맑은 강물에 발을 씻고 강 아래에 앉으니, 제비 날아다니고 해가 길어지는 때라 글 읽기에 마땅하구나.', NULL, NULL),
    ('A211', '전고_어전_집_총집류_문선_고시십구수_초초견우성_000', '어전', '文選', '문선', '古詩十九首_迢迢牽牛星', '고시십구수_초초견우성', '집(集)', '총집류(總集類)', '盈盈一水間, 脈脈不得語.', '맑고 찰랑거리는 한 줄기 은하수 사이에 두니, 애틋하게 바라만 볼 뿐 서로 말하지 못하는도다', NULL, NULL),
    ('A212', '전고_어전_집_별집류_두공부집_강반독보심화_000', '어전', '杜工部集', '두공부집', '江畔獨步尋花', '강반독보심화', '집(集)', '별집류(別集類)', '黃四娘家花滿蹊 千朵萬朵壓枝低', NULL, NULL, NULL),
    ('A213', '전고_어전_집_별집류_매월당집_초하지상_000', '어전', '梅月堂集', '매월당집', '初夏池上', '초하지상', '집(集)', '별집류(別集類)', '正是一年風景老, 薔薇架下更逡巡.', NULL, NULL, NULL),
    ('A214', '전고_사전_집_별집류_백씨장경집_장한가_000', '사전', '白氏長慶集', '백씨장경집', '長恨歌', '장한가', '집(集)', '별집류(別集類)', '鴛鴦瓦冷霜華重, 翡翠衾寒誰與共', '원앙 기와 차갑고 서리꽃 무거운데, 비취 이불 싸늘하니 누구와 함께 덮으리', NULL, '이석단전'),
    ('A215', '전고_어전_경_사서류_논어_이인_000', '어전', '論語', '논어', '里仁', '이인', '경(經)', '사서류(四書類)', '父母在, 不遠遊, 遊必有方.', '부모가 생존해 계시거든 먼 곳에 가지 않으며, 가더라도 반드시 일정한 장소가 있어야 한다.', NULL, '낙우애우기'),
    ('A216', '전고_어전_경_예류_예기_곡례상_000', '어전', '禮記', '예기', '曲禮上', '곡례상', '경(經)', '예류(禮類)', '凡爲人子之體, 冬溫而夏凊, 昏定而晨省', '자식이 된 자는 어버이에 대해서 겨울에는 따뜻하게 해 드리고 여름에는 시원하게 해 드려야 하며, 저녁에는 잠자리를 보살펴 드리고 아침에는 문안 인사를 올려야 한다.', NULL, NULL),
    ('A217', '전고_어전_경_시류_시경_국풍_정풍_장중자_000', '어전', '詩經', '시경', '國風_鄭風_將仲子', '국풍_정풍_장중자', '경(經)', '시류(詩類)', '將仲子兮, 無踰我園, 無折我樹檀.', '중자(仲子)여, 우리 집 동산 담을 넘지 마시고, 내가 심은 박달나무를 꺾지 마세요', NULL, NULL),
    ('A218', '전고_어전_자_법가류_관자_대광_000', '어전', '管子', '관자', '大匡', '대광', '자(子)', '법가류(法家類)', '知子莫若父, 知臣莫若君', '자식을 아는 데는 아비만한 사람이 없고 신하를 아는 데는 임금만한 사람이 없다.', NULL, NULL),
    ('A219', '전고_어전_경_서류_서경_상서_반경상_000', '어전', '書經', '서경', '商書_盤庚上', '상서_반경상', '경(經)', '서류(書類)', '我視汝情, 明若觀火', '내가 너희들의 심정을 봄이 불을 보듯이 분명하다', NULL, NULL),
    ('A220', '전고_어전_경_시류_시경_국풍_소남_표유매_000', '어전', '詩經', '시경', '國風_召南_摽有梅', '국풍_소남_표유매', '경(經)', '시류(詩類)', '摽有梅, 其實七兮. 求我庶士, 迨其吉兮', '떨어지는 매화여 그 열매가 일곱이로다. 나를 구하는 서사는 길일에 미칠진저', NULL, NULL),
    ('A221', '전고_어전_경_역류_주역_함괘_000', '어전', '周易', '주역', '咸卦', '함괘', '경(經)', '역류(易類)', '六二 咸其腓, 凶. 居吉.', NULL, NULL, NULL),
    ('A222', '전고_어전_경_시류_시경_국풍_위풍_맹_000', '어전', '詩經', '시경', '國風_衛風_氓', '국풍_위풍_맹', '경(經)', '시류(詩類)', '桑之落矣, 其黃而隕.', '뽕나무 잎이 떨어지려 하니, 누렇게 시들어 떨어지는구나', NULL, NULL),
    ('A223', '전고_어전_경_시류_시경_국풍_소남_행로_000', '어전', '詩經', '시경', '國風_召南_行露', '국풍_소남_행로', '경(經)', '시류(詩類)', '厭浥行露, 豈不夙夜, 謂行多露.', '함초롬히 이슬 젖은 길에 어찌 조석으로 다니지 않으랴마는, 길에 이슬이 많아서 못 하느니라', NULL, '허생전'),
    ('A224', '전고_어전_집_총집류_문선_고시십구수_염염호생죽_000', '어전', '文選', '문선', '古詩十九首_冉冉狐生竹', '고시십구수_염염호생죽', '집(集)', '총집류(總集類)', '與君爲新婚, 兔絲附松蘿.', '그대와 새로 혼인을 했으니, 토사가 송라에 부침이로다', NULL, NULL),
    ('A225', '전고_어전_집_소설류_전등신화_위당기우기_000', '어전', '剪燈新話', '전등신화', '渭塘奇遇記', '위당기우기', '집(集)', '소설류(小說類)', '女見生至, 與之承迎, 執手入室, 極其歡謔, 會宿於寢. 雞鳴始覺, 乃困臥篷窗底耳', '위아가 왕생을 보고 첫눈에 반해 부모 허락 없이 정을 통한 것을 염두에 둔 것으로 보임. 여자가 왕생이 이른 것을 보고 그를 영접하여, 손을 잡고 방으로 들어가 지극히 즐겁게 희롱하고 침소에서 함께 잤다. 닭이 울어서야 비로소 깨어보니, 왕생은 배의 창가 아래에 곤히 누워 있었을 뿐이었다.', NULL, NULL),
    ('A226', '전고_어전_경_시류_시경_국풍_정풍_산유부소_000', '어전', '詩經', '시경', '國風_鄭風_山有扶蘇', '국풍_정풍_산유부소', '경(經)', '시류(詩類)', '山有扶蘇 隰有荷華 不見子都 乃見狂且 山有橋松 隰有游龍 不見子充 乃見狡童', '산에는 부소가 있고, 습지에는 연꽃이 있거늘, 자도는 만나지 못하고, 미친놈만 만난단 말인가. 산에는 우뚝한 소나무가 있고, 습지에는 너울거리는 홍초(紅草)가 있거늘, 자충을 만나지 못하고, 마침내 교활한 아이를 만난단 말인가.', NULL, NULL),
    ('A227', '전고_사전_집_소설류_전등신화_모란등기_000', '사전', '剪燈新話', '전등신화', '牡丹燈記', '모란등기', '집(集)', '소설류(小說類)', '女宛然在坐, 數之曰：“妾與君素非相識, 偶於燈下一見, 感君之意, 遂以全體事君, 暮往朝來, 於君不薄。奈何信妖道士之言, 遽生疑惑, 便欲永絕？ 薄倖如是, 妾恨君深矣! 今幸得見, 豈能相捨?” 卽握生手, 至柩前, 柩忽自開, 擁之同入, 隨卽閉矣, 生遂死於柩中.', '여자가 완연히 앉아 있다가 그를 몰아세우며 말하기를, "첩은 그대와 평소 서로 알던 사이가 아니었으나, 우연히 등 아래에서 한 번 뵙고 그대의 마음에 감동하여, 마침내 온 몸으로 그대를 섬기며 저녁에 왔다가 아침에 떠나기를 그대에게 박하게 하지 않았습니다. 어찌하여 요사스러운 도사의 말을 믿고 갑자기 의혹을 내어 곧 영원히 끊으려 하였습니까? 박정함이 이와 같으니, 첩은 그대를 원망함이 깊습니다! 이제 다행히 뵙게 되었으니, 어찌 놓아줄 수 있겠습니까?"라 했다. 즉시 생(生)의 손을 잡고 관(柩) 앞으로 가니, 관이 홀연히 저절로 열리거늘 그를 껴안고 함께 들어가니 곧바로 닫혔고, 생은 마침내 관 속에서 죽었다', NULL, NULL),
    ('A228', '전고_어전_경_시류_시경_대아_생민지십_권아_000', '사전', '詩經', '시경', '大雅_生民之什_卷阿', '대아_생민지십_권아', '경(經)', '시류(詩類)', '鳳凰鳴矣 于彼高岡 梧桐生矣 于彼朝陽 菶菶萋萋 雝雝喈喈', '봉황이 우니, 저 높은 언덕에서 울도다. 오동이 자라니저 아침 햇살 비치는 언덕에서 오동나무는 무성하고 울창하며 봉황 소리는 화목하고 평온하구나.', NULL, NULL),
    ('A229', '전고_어전_사_정사류_삼국지_주유전_000', '어전', '三國志', '삼국지', '周瑜傳', '주유전', '사(史)', '정사류(正史類)', '聚此三人, 俱在疆埸, 恐蛟龍得雲雨, 終非池中物也.', '이 세 사람을 모아 모두 강장에 있게 하니 교룡이 비구름을 얻은 격이라 끝내 연못 속 물건으로 있지 않을까 두렵습니다', NULL, NULL),
    ('A230', '전고_사전_집_시문평류_본사시_정감_양소_000', '사전', '本事詩', '본사시', '情感_楊素', '정감_양소', '집(集)', '시문평류(詩文評類)', '德言直引至其居, 設食, 具言其故, 出半鏡以合之. … 素知之，愴然改容，即召德言，還其妻，仍厚遺之', '서덕언이 곧장 그 노복을 자신의 거처로 데리고 와서 먹을 것을 베풀며 그간의 일들을 자세히 말해준 다음 반쪽짜리 거울을 꺼내 합쳐보았다. (중략) 양소가 그들의 사연을 알고 몹시 슬픈 얼굴을 하더니 곧장 서덕언을 불러 그에게 아내를 돌려주고 후하게 재물을 주었다.', NULL, '이생전;허생전,최치원'),
    ('A231', '전고_사전_사_시령류_세시광기_진하오_000', '사전', '歲時廣記', '세시광기', '塡河烏', '진하오', '사(史)', '시령류(時令類)', '淮南子, 烏鵲塡河成橋, 以渡織女', '『회남자』에 따르면, 까마귀와 까치가 은하수를 메워 다리를 놓아 직녀가 건너갈 수 있게 한다고 한다', NULL, NULL),
    ('A232', '전고_사전_집_자_소설가류_속현괴록_정혼점_000', '사전', '續玄怪錄', '속현괴록', '定婚店', '정혼점', '자(子)', '소설가류(小說家類)', '固曰: “然則君何主?” 曰: “天下之婚牘耳.” 固喜曰: “固少孤, 嘗願早娶, 以廣後嗣. 爾來十年, 多方求之. 竟不遂意. 今者人有期此, 與議潘司馬女, 可以成乎?” 曰: “未也, 君之婦適三歲矣. 年十七, 當入君門.” 因問囊中何物, 曰: “赤繩子耳, 以繫夫婦之足, 及其坐則潛用相繫. 雖讐敵之家. 貴賤懸隔, 天涯從宦, 吳楚異鄉, 此繩一繫, 終不可逭. 君之脚已繫於彼矣, 他求何益.”', NULL, NULL, '허생전'),
    ('A233', '전고_어전_사_정사류_사기_한장유열전_000', '어전', '史記', '사기', '韓長孺列傳', '한장유열전', '사(史)', '정사류(正史類)', '安國坐法抵罪, 蒙獄吏田甲辱安國. 安國曰: “死灰獨不復燃乎?” 田甲曰: “燃則溺之.', '한안국(韓安國)이 법에 걸려 죄를 입게 되었는데, 몽(蒙) 지방의 옥리(獄吏)인 전갑(田甲)이 한안국을 모욕하였다. 한안국이 말하였다. “다 타버린 재(死灰)라고 해서 어찌 다시 불붙지 않겠는가?” 전갑이 말했다. “불이 붙는다면 곧 거기에 오줌을 누겠노라.', NULL, NULL),
    ('A234', '전고_사전_사_정사류_후한서_열녀전_포선처_000', '사전', '後漢書', '후한서', '列女傳_鮑宣妻', '열녀전_포선처', '사(史)', '정사류(正史類)', '妻曰：“大人以先生脩德守約, 故使賤妾侍執巾櫛. 旣奉承君子, 唯命是從.” 宣笑曰: “能如是, 是吾志也.” 妻乃悉歸侍御服飾, 更著短布裳, 與宣共挽鹿車歸鄉里. 拜姑禮畢, 提甕出汲. 脩行婦道, 鄉邦稱之.', '환소군(桓少君)이 말했다. “부친께서 선생께서 덕을 닦고 검소함을 지키신다 여기셔서 저로 하여금 시중을 들게 하신 것입니다. 이미 남편을 받들게 되었으니 오직 말씀을 따를 뿐입니다.” 포선이 웃으며 말했다. “이렇게 할 수 있다면 이것이 내 뜻이오.” 환소군이 곧 몸종과 의복, 장신구를 전부 친정에 돌려보내고 다시 짧은 베옷으로 갈아입고 포선과 함께 사슴 수레를 끌고 고향 마을로 돌아갔다. 그리고 시어머니를 뵙는 예를 마친 뒤 물단지를 들고 나가 물을 길어왔다. 며느리의 도리를 닦고 행하니 고을 사람들이 그녀를 칭찬했다', NULL, NULL),
    ('A235', '전고_사전_자_소설가류_해내십주기_봉린주_000', '사전', '海內十洲記', '해내십주기', '鳳麟洲', '봉린주', '자(子)', '소설가류(小說家類)', '煮鳳喙及麟角, 合煎作膠, 名曰鳳麟膠, 一名連金泥, 一名鸞膠. 能梓弓弩之斷, 續琴瑟之絃, 使強弩射不脫, 琴絃聲不絶.', '봉황의 부리와 기린의 뿔을 삶고, 함께 달여 아교를 만드니, 이름을 ''봉린교''라 하고, 일명 ''연금니''라 하며, 일명 ''난교''라 한다. 이 아교는 부러진 활과 노(弩)를 붙이고, 거문고와 비파의 끊어진 줄을 이으니, 강한 활로 쏘아도 떨어지지 않게 하고 거문고 줄 소리가 끊이지 않게 한다.', NULL, NULL),
    ('A236', '전고_사전_사_정사류_후한서_일민열전_양홍전_000', '사전', '後漢書', '후한서', '逸民列傳_梁鴻傳', '일민열전_양홍전', '사(史)', '정사류(正史類)', '遂至吳, 依大家皐伯通, 居廡下, 爲人賃舂. 每歸, 妻爲具食, 不敢於鴻前仰視, 舉案齊眉. 伯通察而異之, 曰: “彼傭能使其妻敬之如此, 非凡人也.', '양홍이 드디어 오(吳)나라에 도착해 대가(大家) 고백통(皐伯通)에게 의지해 행랑채 아래에 거처하며 남의 집 절구질을 해주는 품을 팔았다. 매번 돌아올 때마다 아내 맹광이 음식을 준비했는데 감히 양홍의 앞에서 우러러보지 못하고 밥상을 눈썹 높이까지 받들어 올렸다. 고백통이 살펴보고 그것을 기이하게 여겨 말했다. “저 품꾼이 능히 그 아내로 하여금 공경하기를 이토록 하니 평범한 사람이 아니다.', NULL, NULL),
    ('A237', '전고_사전_자_소설가류_유양잡조_광지_000', '사전', '酉陽雜俎', '유양잡조', '廣知', '광지', '자(子)', '소설가류(小說家類)', '虎死威乃入地, 得之可卻百邪. 虎初死, 記其頭所藉處, 候月黑夜掘之. 欲掘時必有虎來吼擲前後, 不足畏, 此虎之鬼也', '호랑이는 죽으면 위엄이 곧 땅속으로 들어가니, 그것을 얻으면 온갖 사악한 기운[百邪]을 물리칠 수 있다. 호랑이가 처음 죽었을 때, 그 머리가 땅에 닿아 있던 곳을 기록해 두었다가 달이 없는 어두운 밤[月黑夜]을 기다려 그곳을 판다. 땅을 파려 할 때 반드시 호랑이가 나타나 앞뒤에서 포효하고 몸을 날리며 달려들겠으나, 두려워하기에 부족하니 이는 호랑이의 귀신이다.', NULL, NULL),
    ('A238', '전고_사전_경_사서류_논어_계씨_000', '사전', '論語', '논어', '季氏', '계씨', '경(經)', '사서류(四書類)', '陳亢問於伯魚曰: “子亦有異聞乎?” 對曰: “未也. 嘗獨立, 鯉趨而過庭. 曰: “學詩乎?” 對曰: “未也” “不學詩, 無以言.” 鯉退而學詩. 他日又獨立, 鯉趨而過庭. 曰: “學禮乎?” 對曰: “未也.”“不學禮, 無以立.” 鯉退而學禮. 聞斯二者.” 陳亢退而喜曰: “問一得三, 聞詩, 聞禮, 又聞君子之遠其子也.', NULL, NULL, NULL),
    ('A239', '전고_사전_자_잡가류_회남자_남명훈_000', '사전', '淮南子', '회남자', '覽冥訓', '남명훈', '자(子)', '잡가류(雜家類)', '隋侯見大蛇傷斷, 以藥傅之, 後蛇於江中銜大珠以報之', '수나라 제후가 큰 뱀이 상처를 입어 몸이 찢어진 것을 보고 약을 발라 주었더니 훗날 뱀이 강 속에서 큰 구슬을 물고 와서 은혜에 보답했다', NULL, NULL),
    ('A240', '전고_사전_자_유서류_예문유취_수부_곡_000', '사전', '藝文類聚', '예문유취', '水部_谷', '수부_곡', '자(子)', '유서류(類書類)', '劉向別錄曰: 方士傳言, 鄒衍在燕, 燕有谷, 地美而寒, 不生五穀. 鄒子居之, 吹律而溫氣至, 而穀生, 今名黍谷', NULL, NULL, NULL),
    ('A241', '전고_사전_자_소설가류_태평광기_신_왕주_이혼기_000', '사전', '太平廣記', '태평광기', '神魂_王宙', '신혼_왕주', '자(子)', '소설가류(小說家類)', '家人異之，疾走報鎰. 室中女聞，喜而起, 飾妝更衣, 笑而不語, 出與相迎, 翕然而合爲一体, 其衣裳皆重.', '집안 사람이 이를 괴이하게 여기고 바빠 달려가 장일에게 보고해다. 방 안에 있는 딸이 이를 듣고 기뻐하며 일어나 단장을 하고서 옷을 갈아입고 웃으며 조용히 나와, 분신과 마주해 흡연히 마주하여 한 몸이 되었으니 그 옷들이 모두 겹쳐졌다.', '離魂記', NULL),
    ('A242', '전고_사전_집_별집류_백씨장경집_장한가_000', '사전', '白氏長慶集', '백씨장경집', '長恨歌', '장한가', '집(集)', '별집류(別集類)', '忽聞海上有仙山, 山在虛無縹緲間. 樓殿玲瓏五雲起, 其中綽約多仙子. 中有一人字玉眞, 雪膚花貌參差是.', '문득 들으니 해상에 신선이 사는 산 있는데, 이 산은 허무하고 아득한 사이에 있다 하네. 누각과 궁전 영롱하고 오색 구름 일어나니, 그 속에 아름다운 선녀들 많다네. 그 가운데 자가 옥진이란 사람이 있으니, 백설피부에 꽃 같은 모습 거의 비슷했다오.[', NULL, NULL),
    ('A243', '전고_사전_자_소설가류_해내십주기_취굴주_000', '사전', '海內十洲記', '해내십주기', '聚窟洲', '취굴주', '자(子)', '소설가류(小說家類)', '香氣聞数百里, 死者在地, 聞香氣乃卻活, 不復亡也.', '기가 수백 리까지 풍겨 죽은 자가 땅에 있어도 이 향기를 맡으면 곧 살아나고 다시는 망자가 되지 않는다.', NULL, NULL),
    ('A244', '전고_어전_경_시류_시경_국풍_패풍_격고_000', '어전', '詩經', '시경', '國風_邶風_擊鼓', '국풍_패풍_격고', '경(經)', '시류(詩類)', '死生契闊, 與子成說 執子之手, 與子偕老.', '죽든 살든 멀리 떨어져 있든 그대와의 약속 이루자고 하였노라. 그대의 손을 잡고서, 그대와 함께 늙어가리.', NULL, NULL),
    ('A245', '전고_사전_사_잡사류_국어_진어_000', '사전', '國語', '국어', '晉語', '진어', '사(史)', '잡사류(雜史類)', '申生曰: “不可. 君之使我, 非歡也, 抑欲測吾心也. 是故賜我奇服, 而告我權. 又有甘言焉. 言之大甘, 其中必苦. 譖在中矣, 君故生心. 雖蝎譖, 焉避之? 不若戰也. 不戰而反, 我罪滋厚, 我戰死, 猶有令名焉.” 果敗狄于稷桑而反. 讒言益起, 狐突杜門不出. 君子曰: “善深謀也.”', '참언이 더욱 일어나 호돌이 문을 닫고 나가지 않았다.[', NULL, NULL),
    ('A246', '전고_어전_경_시류_시경_소아_녹명지십_상체_000', '어전', '詩經', '시경', '小雅_鹿鳴之什_常棣', '소아_녹명지십_상체', '경(經)', '시류(詩類)', '妻子好合, 如鼓瑟琴, 兄弟旣翕, 和樂且湛.', '처자가 좋고 화합함이 금슬을 타는 듯하더라도 형제간이 화합하여야 화락하고 또 길이 즐길 수 있다네.', NULL, NULL),
    ('A247', '전고_사전_집_소설류_전등신화_애경전_000', '사전', '剪燈新話', '전등신화', '愛卿傳', '애경전', '집(集)', '소설류(小說類)', '向銷金帳裡，猿驚鶴怨，香羅巾下，玉碎花飛.]', '화려한 금수 휘장 안에서는 원숭이가 놀라고 학이 원망하며, 향기로운 비단 수건 아래에서 옥이 부서지고 꽃이 떨어졌도다', NULL, NULL),
    ('A248', '전고_어전_집_사서류_논어_위정_000', '어전', '論語', '논어', '爲政', '위정', '경(經)', '사서류(四書類)', '生事之以禮, 死葬之以禮, 祭之以禮', '살아 계실 때 예로 섬기고, 돌아가시면 예로 장사 지내고, 제사 지낼 때 예에 맞게 하는 것이다.그러므로 변풍(變風)은 정(情)에서 발현되어 예의(禮義)에서 그친다. 정에서 발현되는 것은 백성의 본성(性)이며, 예의에서 그치는 것은 선왕(先王)의 덕택이다.', NULL, NULL),
    ('A249', '전고_어전_집_총집류_문선_모시서_000', '어전', '文選', '문선', '毛詩序', '모시서', '집(集)', '총집류(總集類)', '故變風發乎情, 止乎禮義. 發乎情, 民之性也. 止乎禮義, 先王之澤也', NULL, NULL, NULL),
    ('A250', '전고_어전_집_총집류_전당시_추일여장빈객서저작동유룡문취중광가범이백삼십팔자_000', '어전', '全唐詩', '전당시', '秋日與張賓客舒著作同遊龍門醉中狂歌凡二百三十八字', '추일여장빈객서저작동유룡문취중광가범이백삼십팔자', '집(集)', '총집류(總集類)', '不寒不熱好時節，鞍馬穩快衣衫輕', '춥지도 덥지도 않은 이 좋은 시절에, 말 타기는 평안하고 상쾌하며 옷차림도 가볍구나', NULL, '이석단전'),
    ('A251', '전고_어전_사_잡사류_대동유사_폐주광해군_000', '어전', '大東遺事', '대동유사', '廢主光海君', '폐주광해군', '사(史)', '잡사류(雜史類)', '自丙辰以後 虹貫之變 蚩尤旗 金星晝現 之災 無歲無之 熒惑累入南斗 光海 莫之悟 益猖其獗. 又復游衍酗酒 每於上林及 別宮 賞春之日 常令宮娥 詠歌一詩曰 桃花李花杏花發 南里西里北里春 不寒不熱好時節 半醉半醒無事人 此與陳后主臨春樂等詞 一轍也.', '병진년(1616년) 이후로 흰 무지개가 해를 꿰뚫는 변괴, 혜성(치우기)의 출현, 대낮에 금성이 나타나는 재앙이 없는 해가 없었고, 화성이 불길하게 남두성 자리로 자주 들어왔다. 그러나 광해군은 이를 깨닫지 못하고 더욱 광포하게 굴었다. 또한 놀이와 과음에 빠져 상림원이나 별궁에서 봄놀이를 할 때면, 항상 궁녀들에게 시 한 수를 노래 부르게 했다. "복숭아꽃 오얏꽃 살구꽃 활짝 피니, 남쪽 마을 서쪽 마을 북쪽 마을이 봄이로구나. 춥지도 덥지도 않은 이 좋은 시절에, 반쯤 취하고 반쯤 깬 한가로운 사람이어라." 이 노래는 망국의 군주인 진 후주(陳后主)가 즐겨 불렀던 <임춘락> 따위의 노래와 똑같은 망조가 깃든 것이다.', NULL, '이석단전'),
    ('A252', '전고_사전_자_유가류_순자_정론_000', '사전', '荀子', '순자', '正論', '정론', '자(子)', '유가류(儒家類)', '譬之, 是猶以人之情爲欲富貴而不欲貨也, 好美而惡西施也.', '비유하자면 마치 사람의 정이 부귀를 바라면서 재물을 바라지 않고, 미인을 좋아하면서 서시를 싫어한다고 생각하는 것과 같다', NULL, '이석단전'),
    ('A253', '전고_사전_사_정사류_구당서_양귀비_000', '사전', '舊唐書', '구당서', '楊貴妃', '양귀비', '사(史)', '정사류(正史類)', '太眞姿質豊豔, 善歌舞, 通音律, 智算過人. 每倩盼承迎, 動移上意', '양귀비는 풍만한 자질에 가무에도 능숙하고 음률에도 통달했으며 지혜와 계산이 남들보다 뛰어났다. 매번 눈짓으로 황제를 맞이해 그의 마음을 움직였다.', NULL, '이석단전'),
    ('A254', '전고_사전_집_소설류_전등신화_연방루기_000', '사전', '剪燈新話', '전등신화', '聯芳樓記', '연방루기', '집(集)', '소설류(小說類)', '則二女以鞦韆絨索, 垂一竹兜, 墜於其前, 生乃乘之而上.', '곧 두 여인이 그네 타는 비단 밧줄로 대나무 바구니 하나를 드리워 그의 앞으로 떨어뜨리니, 생이 이에 그것을 타고 올라갔다.', NULL, '이석단전'),
    ('A255', '전고_어전_자_유서류_태평어람_고염가_000', '어전', '太平御覽', '태평어람', '古豔歌', '고염가', '자(子)', '유서류(類書類)', '衣不厭新 人不厭故', '옷은 새 옷이 좋고 사람은 옛사람이 좋다', NULL, '이석단전'),
    ('A256', '전고_어전_경_시류_시경_국풍_제풍_계명_000', '어전', '詩經', '시경', '國風_齊風_雞鳴', '국풍_제풍_계명', '경(經)', '시류(詩類)', '東方明矣, 朝旣昌矣. 匪東方則明, 月出之光.', '동방이 밝아 조정에 신하들 모였는데, 동방이 밝은 게 아니라 달이 떠 달빛 빛남이라', NULL, '이석단전'),
    ('A257', '전고_어전_사_정사류_한서_소무전_000', '어전', '漢書', '한서', '蘇武傳', '소무전', '사(史)', '정사류(正史類)', '人生如朝露，何久自苦如此', '인생은 새벽 이슬과 같은데 어찌 이렇게 오랫동안 고생을 자초하는가?', NULL, '이석단전'),
    ('A258', '전고_사전_자_소설가류_유양잡조_낙고기_000', '사전', '酉陽雜俎', '유양잡조', '諾皋記下', '낙고기', '자(子)', '소설가류(小說家類)', '舊說, 野狐名紫狐, 夜擊尾火出, 將爲怪, 必戴髑髏拜北斗, 髑髏不墜, 則化爲人矣', '옛설에 이르길, 들여우를 자호라 하는데, 괴물이 되려 할 때는 반드시 해골을 머리에 이고 북두칠성에 절을 한다. 해골이 떨어지지 않으면 사람으로 변한다.', NULL, '이석단전'),
    ('A259', '전고_어전_경_사서류_맹자_이루하_000', '어전', '孟子', '맹자', '離婁下', '이루하', '경(經)', '사서류(四書類)', '地之相去也, 千有餘里, 世之相後也, 千有餘歲. 得志行乎中國, 若合符節, 先聖後聖, 其揆一也.', '땅이 서로 떨어진 것이 천여 리나 되고 시대가 서로 다른 것도 천여 년이나 되지만 뜻을 얻어 중국에 도를 행하면 부절처럼 합치하니, 앞 시대의 성인이나 후대의 성인이나 그 법도는 한가지이다.', NULL, '이석단전'),
    ('A260', '전고_사전_집_별집류_백씨장경집_장한가_000', '사전', '白氏長慶集', '백씨장경집', '長恨歌', '장한가', '집(集)', '별집류(別集類)', '在天願作比翼鳥, 在地願爲連理枝', '하늘에서는 비익조가 되고 싶고 땅에서는 연리지가 되고 싶다고 말했지', NULL, '이석단전'),
    ('A261', '전고_사전_자_소설가류_수신기_한빙부부_000', '사전', '搜神記', '수신기', '韓憑夫婦', '한빙부부', '자(子)', '소설가류(小說家類)', '宿昔之間, 便有大梓木生于二冢之端, 旬日而大盈抱, 屈體相就, 根交于下, 枝錯于上. 又有鴛鴦雌雄各一, 恒棲樹上, 晨夕不去, 交頸悲鳴, 音聲感人. 宋人哀之, 遂號其木曰相思樹, 相思之名, 起于此也.', '그런데 하룻밤 사이에 두 무덤 끝에서 큰 가래나무가 각각 솟아나더니, 열흘 만에 한아름이 넘을 정도로 거대하게 자라났다. 두 나무는 마치 몸을 굽혀 서로에게 다가가듯 자라나, 땅속에서는 뿌리가 맞물리고 공중에서는 가지가 뒤엉켰다. 또한 원앙 암수 한 쌍이 날아와 항상 그 나무 위에서 살았는데, 아침저녁으로 떠나지 않고 서로 목을 비비며 슬피 울어대니 그 소리가 사람들의 심금을 울렸다.', NULL, '이석단전'),
    ('A262', '전고_어전_경_시류_시경_국풍_천수_000', '어전', '詩經', '시경', '國風_泉水', '국풍_천수', '경(經)', '시류(詩類)', '女子有行, 遠父母兄弟.', '여자가 시집을 가면 부모 형제를 멀리하게 된다.', NULL, '이진사효행록'),
    ('A263', '전고_어전_사_정사류_후한서_위표열전_000', '어전', '後漢書', '후한서', '韋彪列傳', '위표열전', '사(史)', '정사류(正史類)', '事親孝, 故忠可移於君. 是以求忠臣, 必於孝子之門.', '어버이를 효도로 섬기는 까닭에 충성을 임금에게 옮길 수가 있다. 그래서 충신은 반드시 효자의 집안에서 구하는 것이다.', NULL, '이진사효행록'),
    ('A264', '전고_어전_사_정사류_후한서_응봉열전_000', '어전', '後漢書', '후한서', '應奉列傳', '응봉열전', '사(史)', '정사류(正史類)', '奉年二十時，嘗詣彭城相袁賀，賀時出行閉門，造車匠於內開扇出半面視奉，奉即委去. 後數十年於路見車匠，識而呼之', '응봉(應奉)이 나이 스무 살 때, 일찍이 팽성상(彭城相) 원하(袁賀)를 찾아간 적이 있다. 그때 원하가 외출하여 문이 닫혀 있었는데, 수레 만드는 장인[車匠]이 안에서 문짝을 열고 얼굴을 반쯤 내밀어 응봉을 쳐다보았다. 응봉은 즉시 발길을 돌려 떠났다. 수십 년 뒤 길에서 그 수레 장인을 보고는, 그를 알아보고 그를 불렀다', NULL, '조신전'),
    ('A265', '전고_어전_경_시류_시경_국풍_왕풍_대거_000', '어전', '詩經', '시경', '國風_王風_大車', '국풍_왕풍_대거', '경(經)', '시류(詩類)', '穀則異室, 死則同穴', '살아서는 집을 달리하였으나 죽어서는 묫자리를 함께하리라', NULL, '조신전'),
    ('A266', '전고_어전_사_정사류_삼국사기_백결선생_000', '어전', '三國史記', '삼국사기', '百結先生', '백결선생', '사(史)', '정사류(正史類)', '百結先生, 不知何許人. 居狼山下, 家極貧，, 百結若懸鶉, 時人號爲東里百結先生', '백결선생은 어떤 사람인지 모른다. 낭산 아래에 살았는데 집이 몹시 가난하여 갈가리 기운 옷은 해진 옷 같아 당시 사람들이 백번 기운 옷을 입은 선생이라 불렀다.', NULL, '조신전'),
    ('A267', '전고_어전_자_소설가류_세설신어_상서_000', '어전', '世說新語', '세설신어', '傷逝', '상서', '자(子)', '소설가류(小說家類)', '聖人忘情 最下不及情 情之所鍾 正在我輩', '성인은 감정을 잊고 가장 낮은 사람은 감정에 미치지 못하니 감정이 깊이 맺히는 곳은 바로 우리 같은 무리에 있다', NULL, '조신전'),
    ('A268', '전고_사전_자_유서류_예문유취_조부_난조시서_000', '사전', '藝文類聚', '예문유취', '鳥部_鸞鳥詩序', '조부_난조시서', '자(子)', '유서류(類書類)', '昔罽賓王結罝峻卯之山, 獲一鸞鳥. 王甚愛之, 欲其鳴而不致也. 乃飾以金樊, 饗以珍羞. 對之有戚, 三年不鳴. 其夫人曰: 嘗聞鳥見其類而後鳴, 何不懸鏡以映之. 王從其意, 鸞睹形悲鳴.', '옛날에 계빈국(罽賓)의 왕이 준묘산에서 덫을 놓아 난조(鸞鳥) 한 마리를 잡았다. 왕은 이를 매우 아끼며 그 울음소리를 듣고자 했으나 소리를 내지 않았다. 곧 금으로 새장을 장식하고 진귀한 음식을 대접했다. 그러나 난조는 이에 대해 근심하는 기색을 보이며 3년 동안 울지 않았다. 왕의 부인이 말했다. “예전에 들기로는 새는 자신의 동류를 보고 나서야 운다고 하니 어찌 거울을 걸어 그 모습을 비추게 하지 않으십니까?” 왕은 그 뜻대로 하자 난조는 거울에 비친 자신의 모습을 보고 슬피 울었다.', NULL, '유생전, 조신전'),
    ('A269', '전고_어전_경_사서류_맹자_양혜왕하_000', '어전', '孟子', '맹자', '梁惠王下', '양혜왕하', '경(經)', '사서류(四書類)', '行或使之, 止或尼之, 行止非人所能也. 吾之不遇魯侯天也, 臧氏之子, 焉能使予不遇哉', '가는 것도 혹 누가 시켜서 할 수 있고, 못 가는 것도 혹 누가 막아서 못 가기도 하지만, 가고 못 가는 것은 사람이 할 수 있는 것이 아니다. 내가 노후를 만나지 못한 것은 하늘의 뜻이니 장씨의 자식이 어떻게 나로 하여금 만나지 못하게 하겠는가.', NULL, '조신전'),
    ('A270', '전고_어전_경_시류_시경_소아_소민지십_소변_000', '어전', '詩經', '시경', '小雅_小旻之什_小弁', '소아_소민지십_소변', '경(經)', '시류(詩類)', '維桑與梓, 必恭敬止.', '어버이가 심어 놓으신 뽕나무와 가래나무도 반드시 공경하거든', NULL, '조신전'),
    ('A271', '전고_사전_자_소설가류_태평광기_이인_여옹_이문집_침중기_000', '사전', '太平廣記', '태평광기', '異人_呂翁', '이인_여옹', '자(子)', '소설가류(小說家類)', '盧生欠伸而悟, 見其身方偃於邸舍, 呂翁坐其傍 主人蒸黍未熟, 觸類如故.', '노생이 기지개를 켜면서 깨어보니 자신은 주막에 누워있고 옆에는 여옹이 앉아 있꼬 주인은 여전히 조바블 짓고 있었으니 모든 게 이전과 다름없었다', '異聞集_枕中記', '조신전'),
    ('A272', '전고_사전_사_정사류_진서_배해전_000', '사전', '晉書', '진서', '裴楷傳', '배해전', '사(史)', '정사류(正史類)', '楷風神高邁, 容儀俊爽, 博涉群書, 特精理義, 時人謂之: "玉人", 又稱: "見裴叔則, 如近玉山, 映照人也', '배해(裴楷)는 풍채와 신수가 높고 빼어났으며, 용모와 거동이 준수하고 시원스러웠다. 여러 책을 널리 섭렵하였고, 특히 의리에 정통하였다. 당시 사람들이 그를 일컬어 "옥인(玉人)"이라 하였고, 또 일컫기를 "배숙칙(裴叔則)을 보는 것은 마치 옥산(玉山)에 가까이 가는 것과 같아서, 사람을 환하게 비춘다"라고 하였다.', NULL, NULL),
    ('A273', '전고_사전_자_소설가류_세설신어_혹닉_000', '사전', '世說新語', '세설신어', '惑溺', '혹닉', '자(子)', '소설가류(小說家類)', '韓壽美姿容, 賈充辟以爲掾. 充每聚會, 賈女於靑璅中看, 見壽, 說之. 恆懷存想, 發於吟詠. 後婢往壽家, 具述如此, 并言女光麗. 壽聞之心動, 遂請婢潛修音問. 及期往宿. 壽蹻捷絕人, 踰牆而入, 家中莫知. 自是充覺女盛自拂拭, 說暢有異於常. 後會諸吏, 聞壽有奇香之氣, 是外國所貢, 一著人, 則歷月不歇. 充計武帝唯賜己及陳騫, 餘家無此香, 疑壽與女通, 而垣牆重密, 門閤急峻, 何由得爾? 乃託言有盜, 令人修牆. 使反曰：“其餘無異, 唯東北角如有人跡. 而牆高, 非人所踰.” 充乃取女左右婢考問, 卽以狀對. 充秘之, 以女妻壽.', NULL, NULL, NULL),
    ('A274', '전고_어전_경_사서류_맹자_공손추하_000', '어전', '孟子', '맹자', '公孫丑下', '공손추하', '경(經)', '사서류(四書類)', '對曰: 不敢請耳, 固所願也.', '감히 청하지는 못할지언정, 진실로 원하는 바입니다.', NULL, NULL),
    ('A275', '전고_어전_경_시류_시경_소아_소민지십_육아_000', '어전', '詩經', '시경', '小雅_小旻之什_蓼莪', '소아_소민지십_육아', '경(經)', '시류(詩類)', '無父何怙, 無母何恃. 出則銜恤, 入則靡至.', '아버지가 없으면 누구를 믿으며 어머니가 없으면 누구를 믿을꼬? 나가면 근심을 품고 들어오면 이를 곳이 없노라.', NULL, NULL),
    ('A276', '전고_어전_사_정사류_사기_고조본기_000', '어전', '史記', '사기', '高祖本紀', '고조본기', '사(史)', '정사류(正史類)', '呂公曰: 臣少好相人, 相人多矣, 無如季相, 願季自愛. 臣有息女, 願爲季箕帚妾.', '신은 젊어서 사람의 관상 보기를 좋아하여, 사람의 관상을 본 것이 많으나 계(季)의 관상과 같은 이가 없었으니, 원컨대 계께서는 스스로를 아끼십시오. 신에게 딸이 있으니, 원컨대 계의 기주첩(箕帚妾)이 되기를 바랍니다', NULL, NULL),
    ('A277', '전고_어전_경_시류_시경_국풍_당풍_주무_000', '어전', '詩經', '시경', '國風_唐風_綢繆', '국풍_당풍_주무', '경(經)', '시류(詩類)', '綢繆束薪, 三星在天. 今夕何夕? 見此良人. 子兮子兮, 如此良人何!', '칭칭 감아 섶을 묶을 적에, 삼성이 하늘에 떠 있도다. 오늘 밤은 어떤 밤인가? 이 양인을 만났노라. 그대여 그대여, 이 양인을 어쩌리오.', NULL, NULL),
    ('A278', '전고_사전_도_신선전류_열선전_소사_000', '사전', '列仙傳', '열선전', '簫史', '소사', '도(道)', '신선전류(神仙傳類)', '日敎弄玉作鳳鳴，居數年，吹似鳳聲，鳳凰來止其屋. 公爲作鳳台，夫婦止其上，不下數年. 一旦，皆隨鳳凰飛去.', '소사(簫史)는 날마다 농옥(弄玉)에게 퉁소로 봉황 울음소리 내는 법을 가르쳤는데 수년이 지나자 농옥은 봉황 소리처럼 투소를 불었으니 봉황이 그 집에 와서 머물렀다. 목공이 이로 인해 봉대를 지어주었으니 부부는 그 위에서 지내면서 몇 년을 내려오지 않다가 어느날 봉황을 따라 날아가버렸다.', NULL, '낙우애우기, 최치원'),
    ('A279', '전고_어전_경_사서류_맹자_공손추상_000', '어전', '孟子', '맹자', '公孫丑上', '공손추상', '경(經)', '사서류(四書類)', '其爲氣也, 至大至剛, 以直養而無害, 則塞于天地之間', '그 기운됨은 지극히 크고 지극히 강하니, 곧은 것으로 길러 해침이 없으면 천지의 사이에 가득 차게 된다.', NULL, NULL),
    ('A280', '전고_어전_경_시류_시경_대아_탕지십_억_000', '어전', '詩經', '시경', '大雅_蕩之什_抑', '대아_탕지십_억', '경(經)', '시류(詩類)', '於乎小子, 未知臧否? 匪手攜之, 言示之事, 匪面命之, 言提其耳.]', '아, 소자여, 좋고 나쁨을 알지 못하는가? 손으로 잡아줄 뿐만 아니라 일로 보여주며, 대면하여 가르쳐줄 뿐만 아니라 그 귀를 잡고 말해주노라.', NULL, NULL),
    ('A281', '전고_사전_경_춘추류_춘추좌씨전_선공3년_000', '사전', '春秋左氏傳', '춘추좌씨전', '宣公三年', '선공3년', '경(經)', '춘추류(春秋類)', '昔夏之方有德也, 遠方圖物, 貢金九牧, 鑄鼎象物, 百物而爲之備, 使民知神姦. 故民入川澤山林, 不逢不若, 魑魅罔兩, 莫能逢之.', '옛날 하나라의 덕이 한창 융성한 때에는 먼 나라들이 각기 그 나라의 괴이한 물건의 형상을 그려 올렸는데, 구주의 장관에게는 쇠[金]를 바치게 하여 솥을 만들어서 여러 가지 형상의 물건을 새겨 넣고 모든 물건을 새겨 넣어 백성들로 하여금 귀신의 간사한 정상을 알아보게 하였다. 그러므로 백성들이 천택이나 산림에 들어가서도 요괴를 만나지 않았고, 도깨비를 만나지 않았다.', NULL, NULL),
    ('A282', '전고_사전_사_정사류_진서_온교전_000', '사전', '晉書', '진서', '溫嶠傳', '온교전', '사(史)', '정사류(正史類)', '至牛渚磯，水深不可測，世雲其下多怪物，嶠遂燬犀角而照之. 須臾，見水族覆火，奇形異狀，或乘馬車著赤衣者. 嶠其夜夢人謂己曰："與君幽明道別，何意相照也?" 意甚惡之.', '온교(溫嶠)가 우저기(牛渚磯)에 이르니 물 깊이를 헤아릴 수 없었는데, 세상에서 이르기를 그 아래에 괴물이 많다고 하였다. 드디어 무소의 뿔을 태워 그것을 비추니, 잠시 후에 수족(水族)들이 불을 덮고 있는 것이 보였는데 기이한 형태와 다른 형상이었으며, 혹은 마차를 타고 붉은 옷을 입은 자도 있었다. 온교가 그날 밤 꿈을 꾸니 어떤 사람이 그에게 일러 말하기를, “그대와 나는 저승과 이승의 길이 다른데, 어찌하여 서로 비추어 보는가?"라고 했다. 온교는 마음속으로 그것을 매우 불쾌하게 여겼다.', NULL, NULL),
    ('A283', '전고_사전_집_총집류_문선_낙신부_000', '사전', '文選', '문선', '洛神賦', '낙신부', '집(集)', '총집류(總集類)', '植還, 度轘轅, 少許時, 將息洛水上, 思甄后. 忽見女來, 自云: 我本託心君王, 其心不遂. 此枕是我在家時, 從嫁前與五官中郎將所被, 今與君王. 遂用薦枕席, 歡情交集, 豈常辭能具. 爲郭后以糠塞口, 今被髮, 羞將此形貌重睹君王爾. 言訖, 遂不復見所在.', '조식(曹植)이 돌아가며 환원(轘轅) 언덕을 지나 낙수(洛水) 위에서 쉬려고 하며 견후(甄后)를 생각했다. 문득 한 여인이 오는 것이 보였는데 스스로 말하길 “저는 본래 마음을 군왕께 부쳤으니 그 마음을 이루지 못했습니다. 이 베개는 제가 집에 있을 때 시집오기 전부터 오관중랑장(五官中郎將)과 함께 벴던 것인데 이제 군왕께 드립니다. 마침내 잠자리를 함께하니 기쁜 정이 교차함을 어찌 평범한 말로 다 갖출 수 있겠습니까. 저는 곽후(郭后)에 의해 겨(糠)로 입이 채워졌고 지금 머리가 풀어 헤쳐져 있으니 이런 모습으로 다시 군왕을 뵙는 것이 부끄러울 따름입니다!”라고 했다. 그녀는 말을 마치고는 다시 보이지 않았다.', NULL, '최치원'),
    ('A284', '전고_어전_도_도경류_장자_양왕_000', '어전', '莊子', '장자', '讓王', '양왕', '도(道)', '도경류(道經類)', '原憲華冠縰履, 杖藜而應門', '원헌은 화려한 관에 끈 떨어진 신발을 신고, 명아주 지팡이를 짚고 문에 응했다.', NULL, '최치원'),
    ('A285', '전고_사전_자_소설가류_태평광기_호_임씨_000', '사전', '太平廣記', '태평광기', '狐_任氏', '호_임씨', '자(子)', '소설가류(小說家類)', '任氏更妝而出, 酣飲極歡. 夜久而寢, 其嬌姿美質, 歌笑態度, 擧措皆豔, 殆非人世所有.', '임씨가 화장을 고치고 나오니 즐겁게 술을 마시니 기쁨이 극에 달했다. 밤새도록 잠자리에 들었는데 그녀의 아리따운 자태와 아름다운 모습, 노래하고 웃을 때의 태도는 손짓 발짓이 모두 요염해 인간세상에 있는 바가 아니었다.', '任氏傳', '최치원'),
    ('A286', '전고_어전_자_소설가류_세설신어_출면_환공_000', '어전', '世說新語', '세설신어', '黜免_桓公', '출면_환공', '자(子)', '소설가류(小說家類)', '桓公入蜀, 至三峽中, 部伍中有得猿子者. 其母緣岸哀號, 行百餘里不去, 遂跳上船, 至便氣絶. 剖其腹視之, 腸皆寸寸斷.', '환공이 촉(蜀)에 들어갈 때 삼협(三峽)으로 이르렀는데, 부대원 중 새끼 원숭이를 잡은 자가 있었다. 그 어미가 강언덕을 따라 슬피 울며 백여 리를 가도록 떠나지 않더니, 마침내 배 위로 뛰어올라 이르고는 곧 숨이 끊어졌다. 그 배를 갈라 보니 창자가 모두 마디마디 끊어져 있었다.', NULL, '최치원'),
    ('A287', '전고_사전_자_소설가류_한무고사_000', '사전', '漢武故事', '한무고사', '-', '-', '자(子)', '소설가류(小說家類)', '七月七日, 上於承華殿齋. 正中, 忽有一靑鳥從西方, 集殿前. 上問東方朔, 朔曰：“此西王母欲來也.” 有頃, 王母至.', '7월 7일에 무제는 승화전에서 재계했다. 해가 중천에 떠오르자 문득 청조 한 마리가 서쪽에서 날아 오더니 궁전 앞에 내려앉았다. 한 무제가 동방삭에게 물어보자 동방삭이 말했다. “이는 서왕모께서 오시려는 것입니다.” 잠시 뒤 서왕모가 찾아왔다.', NULL, '이생전;최치원'),
    ('A288', '전고_사전_집_총집류_악부시집_맥상상_000', '사전', '樂府詩集', '악부시집', '陌上桑', '맥상상', '집(集)', '총집류(總集類)', '使君從南來, 五馬立踟躕. 使君遣吏往, 問此誰家姝. 秦氏有好女, 自名爲羅敷. 羅敷年幾何? 二十尙未滿, 十五頗有餘. 使君謝羅敷, 甯可共載不? 羅敷前置辭, 使君一何愚! 使君自有婦, 羅敷自有夫.', '사군(使君)이 남쪽에서 오다가 다섯 마리 말이 끄는 수레를 멈추고 머뭇거린다. 사군이 관리를 보내 “이 이는 누구 집의 예쁜 아가씨인가?”라고 묻게 한다. “진씨 집에 아름다운 딸이 있는데 스스로 이름을 나부라 합니다.” “나부의 나이는 얼마나 되었는가?” “스무 살은 아직 되지 않았고 열다섯 살은 훌쩍 넘었습니다.” 사군이 나부에게 말을 전하기를 “어찌 나와 수레를 함께 타지 않겠는가?” 하니, 나부가 앞으로 나서며 대답했다. “사군은 어찌 그리 어리석으십니까! 사군께는 이미 아내가 있고 나부에게는 이미 남편이 있습니다.', NULL, '최치원'),
    ('A289', '전고_어전_경_사서류_논어_선진_000', '어전', '論語', '논어', '先進', '선진', '경(經)', '사서류(四書類)', '子曰: 夫人不言, 言必有中', '공자가 말했다. 저 사람은 말이 없으나 말을 하면 반드시 이치에 맞는다.', NULL, '최치원'),
    ('A290', '전고_어전_사_정사류_사기_영행열전_000', '어전', '史記', '사기', '佞幸列傳', '영행열전', '사(史)', '정사류(正史類)', '於是, 賜鄧通蜀嚴道銅山, 得自鑄錢, 鄧氏錢布天下.', '그리하여 한 문제는 등통에게 촉나라 엄도(嚴道) 지역에 있는 동산을 내려주어, 그가 직접 화폐를 만들 수 있도록 허락했다. 이로 인해 등통이 만든 ''등씨전''이 전국에 유통되었다.', NULL, '최치원'),
    ('A291', '전고_사전_사_정사류_진서_석숭전_002', '사전', '晉書', '진서', '石崇傳', '석숭전', '사(史)', '정사류(正史類)', '財產豐積, 室宇宏麗. 後房百數, 皆曳紈繡, 珥金翠. 絲竹盡當時之選, 庖膳窮水陸之珍.', '석숭은 가산이 풍부하게 쌓였으며 집이 웅장하고 화려했다. 첩들이 수백 명이었는데 모두 흰 비단과 자수를 끌며 금과 비취 귀걸이를 달았다. 음악은 당대의 명인들을 선발했고, 요리는 산해진미를 다했다.', NULL, '최치원'),
    ('A292', '전고_사전_도_도경류_열자_탕문_000', '사전', '列子', '열자', '湯問', '탕문', '도(道)', '도경류(道經類)', '而龍伯之國有大人, 舉足不盈數步而暨五山之所. 一釣而連六鼇, 合負而趣歸其國, 灼其骨以數焉.', '용백국(龍伯國)이라는 나라에 한 거인이 있는데 그는 몇 걸음 걷지도 않아 신선들이 사는 다섯 산이 있는 곳까지 다다랐다. 그는 단 한 번의 낚시질로 거대한 거북 여섯 마리를 한꺼번에 낚아 올리고 그것들을 한데 짊어지고 서둘러 자기 나라로 돌아가 그 거북들의 뼈를 불에 태워 점을 쳤다.', NULL, '최치원'),
    ('A293', '전고_어전_경_역류_주역_계사전상_000', '어전', '周易', '주역', '繫辭傳上', '계사전상', '경(經)', '역류(易類)', '引而伸之, 觸類而長之, 天下之能事畢矣.', '이끌어 펴며 유에 따라 확장해 나간다면 천하의 능사가 다할 것이다.', NULL, '낙우애우기, 최치원'),
    ('A294', '전고_사전_자_소설가류_수신기_노충_000', '사전', '搜神記', '수신기', '盧充', '노충', '자(子)', '소설가류(小說家類)', '充年二十, 先冬至一日, 出宅西獵戲, 見一獐, 舉弓而射, 中之, 獐倒, 復起. 充因逐之, 不覺遠, 忽見道北一里許, 高門瓦屋, 四周有如府舍, 不復見獐. 門中一鈴下唱客前. 充曰：「此何府也？」答曰：「少府府也. 」充曰：「我衣惡, 那得見少府？」卽有一人提一襆新衣, 曰：「府君以此遺郎. 」充便著訖, 進見少府. 展姓名 …중략… 充旣至東廊, 女已下車, 立席頭, 卻共拜.', '노충의 나이 스무 살 때, 동지(冬至) 하루 전날 집 서쪽으로 사냥을 나갔다가 노루 한 마리를 보고 활을 들어 쏘아 맞혔다. 노루가 쓰러졌다가 다시 일어나니, 노충이 그를 쫓느라 (가는 길이) 먼 줄도 몰랐다. 문득 길 북쪽 1리쯤 되는 곳에 높은 대문과 기와집이 보였는데, 사방이 마치 관청의 집(府舍) 같았으며 노루는 다시 보이지 않았다. 문 안에서 한 하인(鈴下)이 손님이 왔음을 알렸다. 노충이 묻기를 “여기는 어느 분의 관저입니까?” 하니, 대답하기를 “소부(少府)의 댁입니다” 하였다. 노충이 “내 옷이 남루한데 어찌 소부님을 뵙겠습니까?”라고 하자, 곧 한 사람이 새 옷 한 꾸러미를 들고 와 말하기를 “부군(府君)께서 이것을 도령께 보내셨습니다” 하였다. 노충이 곧 옷을 갈아입고 들어가 소부를 뵙고 성명을 올렸다. -중략- 노충이 이윽고 동쪽 행랑에 이르니, 여자가 이미 수레에서 내려 자리 끝에 서 있다가 노충과 마주하여 함께 절을 올렸다.', NULL, '이석단전, 최치원'),
    ('A295', '전고_사전_자_소설가류_유명록_유신완조_000', '사전', '幽明錄', '유명록', '劉晨阮肇', '유신완조', '자(子)', '소설가류(小說家類)', '漢明帝永平五年, 剡縣劉晨、阮肇共入天臺山取谷皮, 迷不得返. … 便共沒水, 逆流二三里, 得度山出一大溪, 溪邊有二女子, 姿質妙絕, 見二人持杯出, 便笑曰：「劉、阮二郎, 捉向所失流杯來.', '한(漢)나라 명제(明帝) 영평(永平) 5년, 섬현(剡縣)의 유신(劉晨)과 완조(阮肇)가 함께 천태산(天臺山)에 들어가 굿껍질(谷皮)을 채취하다가, 길을 잃어 돌아오지 못했다. …중략… 곧 함께 물속에 몸을 담그고 물줄기를 거슬러 2~3리를 올라가 산을 넘으니 큰 시내가 나타났다. 시냇가에 두 여자가 있었는데 자태와 바탕이 기이하고 빼어났다. (여인들이) 두 사람이 잔을 들고 나오는 것을 보고는 곧 웃으며 말하기를, “유랑(劉郞)과 완랑(阮郞)께서 예전에 잃어버린 잔을 집어 들고 오시는군요', NULL, '최치원'),
    ('A296', '전고_사전_사_전기류_열녀전_모의전_유후이비_000', '사전', '列女傳', '열녀전', '母儀傳_有虞二妃', '모의전_유후이비', '사(史)', '전기류(傳記類)', '有虞二妃者, 帝堯之二女也. 長娥皇, 次女英. …. 四嶽薦之於堯, 堯乃妻以二女以觀厥內.二女承事舜於畎畝之中, 不以天子之女故, 而驕盈怠嫚, 猶謙謙恭儉, 思盡婦道.', '순임금의 두 부인은 제요(帝堯)의 두 딸이다. 장녀는 아황(娥皇)이고 차녀는 여영(女英)이다. …. 사악(四嶽)이 그를 요임금에게 추천하니 요임금이 곧 두 딸을 아내로 주어 그 안을 관찰하게 했다. 두 비는 밭이랑 사이에서 순을 섬겼으며 천자의 딸이라 하여 교만하거나 태만하지 않고 오히려 겸손하고 검소하게 행동하며 부인의 도리를 다하고자 했다', NULL, '유생전, 최치원'),
    ('A297', '전고_사전_사_정사류_삼국지_왕찬전_000', '어전', '三國志', '삼국지', '周瑜傳', '주유전', '사(史)', '정사류(正史類)', '時, 得橋公兩女, 皆國色也. 策自納大橋, 瑜納小橋', '당시 교공(橋公)의 두 딸을 얻었는데 모두 나라에서 으뜸가는 미색이었다. 손책은 대교를 아내로 맞고, 주유는 소교를 맞았다.[', NULL, '안생, 최치원'),
    ('A298', '전고_사전_사_지리류_양양기_000', '어전', '襄陽記', '양양기', '-', '-', '사(史)', '지리류(地理類)', '襄陽記曰：黃承彥者, 高爽開列, 爲沔南名士. 謂諸葛孔明曰：“聞君擇婦. 身有醜女, 黃頭黑色, 而才堪相配.” 孔明許, 卽載送之. 時人以爲笑樂, 鄕里爲之諺曰：“莫作孔明擇婦, 止得阿承醜女', '『양양기』에서 일컬었다. 황승언(黃承彥)은 성격이 호탕하고 시원스러워 면남(沔南) 지역의 명사였다. 제갈공명(諸葛孔明)에게 말했다. “그대가 신붓감을 고른다고 들었소. 내게 못생긴 딸이 있는데 머리는 노랗고 피부는 검으나 재주만은 그대와 짝할 만하오.” 공명이 이를 허락하자 곧 딸을 수레에 태워 보냈다. 당시 사람들이 이를 웃음거리로 삼으니 향리에서 속담이 생겨났다. “공명처럼 아내 고르지마라 겨우 황승언의 못생긴 딸만 얻으리라.”고 하였다.', '두 편(篇)이 모두 문란한 정사(政事)를 읊은 데서 유래', '이생전, 최치원'),
    ('A299', '전고_사전_자_소설가류_태평광기_오행기_진랑비_000', '사전', '太平廣記', '태평광기', '五行記_陳朗婢', '오행기_진랑비', '자(子)', '소설가류(小說家類)', '義熙四年, 琅邪人陳朗婢死, 已葬. 府史夏假歸, 行塚前, 聞土中有人聲, 怪視之. 婢曰: “我今更活, 爲我報家.” 其日已暮, 旦方開土取之, 彊健如常.', '진(晉) 의희(義熙) 4년, 낭야(琅邪) 사람 진랑(陳朗)의 여종이 죽어 이미 장사를 지냈다. 부사가 여름휴가를 받아 돌아가던 중 무덤 앞을 지나다가 흙 속에서 사람 목소리가 들리는 것을 보고 괴이하게 여겨 살펴보았다. 여종이 말했다. “내가 지금 다시 살아났으니 집에 이 일을 전해주십시오.” 그날은 이미 날이 저물어서 이튿날 아침에서야 땅을 파서 그녀를 꺼냈는데 건강한 모습이 평소와 같았다', NULL, '유생전, 최치원'),
    ('A300', '전고_어전_경_사서류_맹자_공손추하_000', '어전', '孟子', '맹자', '公孫丑下', '공손추하', '경(經)', '사서류(四書類)', '五百年必有王者興, 其間必有名世者', '오백 년 만에 반드시 왕자가 태어나는데 그 사이에 반드시 세상에 이름난 인물이 있다.', NULL, '유생전, 최치원'),
    ('A301', '전고_사전_집_시문평류_본사시_정감_양소_000', '사전', '本事詩', '본사시', '情感_楊素', '정감_양소', '집(集)', '시문평류(詩文評類)', '德言直引至其居, 設食, 具言其故, 出半鏡以合之. … 素知之，愴然改容，即召德言，還其妻，仍厚遺之', '서덕언이 곧장 그 노복을 자신의 거처로 데리고 와서 먹을 것을 베풀며 그간의 일들을 자세히 말해준 다음 반쪽짜리 거울을 꺼내 합쳐보았다. (중략) 양소가 그들의 사연을 알고 몹시 슬픈 얼굴을 하더니 곧장 서덕언을 불러 그에게 아내를 돌려주고 후하게 재물을 주었다.', NULL, '이생전;허생전,최치원'),
    ('A302', '전고_사전_집_총집류_문선_고당부_000', '사전', '文選', '문선', '高唐賦', '고당부', '집(集)', '총집류(總集類)', '妾在巫山之陽, 高丘之岨 旦爲朝雲 暮爲行雨 朝朝暮暮 陽臺之下', '저는 무산의 양지쪽 높은 구릉의 험준한 곳에 사는데 매일 아침이면 구름이 되고 저녁이면 내리는 비가 되어, 아침마다 저녁마다 양대 아래에 있습니다.', NULL, '이생전;최치원;이생규장전'),
    ('A303', '전고_어전_자_소설가류_세설신어_언어_사태부_000', '어전', '世說新語', '세설신어', '言語_謝太傅', '언어_사태부', '자(子)', '소설가류(小說家類)', '“謝太傅寒雪日內集, 與兒女講論文義. 俄而雪驟, 公欣然曰: “白雪紛紛何所似?” 兄子胡兒曰: “撒鹽空中差可擬.” 兄女曰: “未若柳絮因風起.” 公大笑樂. 卽公大兄無奕女, 左將軍王凝之妻也.”', '사태부 사안(謝安)이 눈이 내리는 날 가족들을 모아 놓고 자녀들과 함께 문의(文義)를 강론하고 있었다. 이윽고 눈발이 굵어지자 사안이 흐뭇해하며 말했다. “저 흩날리는 흰 눈은 무엇과 비슷하냐?" 조카 사랑(謝朗)이 말했다. “공중에 소금을 뿌리는 것과 비슷하다.” 조카딸 사도온(謝道韞)이 말했다. “버들솜이 바람을 타고 흩날리느니만 못합니다”라고 대답했다. 사안이 그녀의 재치에 웃으며 즐거워했다. 이 여인이 곧 사안의 큰형 사무혁의 딸이자 훗날 좌장군 왕응지의 부인이 된 사도온이다.', NULL, '조신전, 최치원'),
    ('A304', '전고_사전_집_총집류_전당시_원가행_000', '사전', '全唐詩', '전당시', '怨歌行', '원가행', '집(集)', '총집류(總集類)', '常恐秋節至, 凉飇奪炎熱 棄捐篋笥中 恩情中道絶', '늘 근심스러운 것은 가을철이 되어 서늘한 바람이 더위를 빼앗게 되면, 부채가 상자 속에 버려져 은정(恩情)이 도중에 끊어지는 것입니다.', NULL, '유생전'),
    ('A305', '전고_사전_집_총집류_문선_낙신부_002', '사전', '文選', '문선', '洛神賦', '낙신부', '집(集)', '총집류(總集類)', '凌波微步, 羅襪生塵.', '물결을 밟아 사뿐히 걸으니, 비단 버선에 안개가 날리네', NULL, '최치원'),
    ('A306', '전고_어전_경_사서류_논어_미자_000', '어전', '論語', '논어', '微子', '미자', '경(經)', '사서류(四書類)', '長沮桀溺耦而耕. 孔子過之. 使子路問津焉. 長沮曰: “夫執輿者, 爲誰?” 子路曰.: “爲孔丘.” 曰: “是魯孔丘與?” 曰: “是也.” 曰: “是知津矣.”', '장저(長沮)ㆍ걸익(桀溺)이 나란히 밭을 갈고 있었는데, 공자가 지나가다가 자로(子路)를 시켜 나루터를 묻게했다. 장저가 “수레 고삐를 잡은 이는 누구요?”하여, 자로가 “공구(孔丘)라고 합니다.” 하니, 장저가 “노나라 공구라는 사람이요?” 하여, 자로가 “맞습니다.” 하니, 장저가 “그는 나루터를 알 것이다.', NULL, '낙우애우기, 최치원'),
    ('A307', '전고_사전_집_총집류_악부시집_상화가사_업도고사_000', '사전', '樂府詩集', '악부시집', '相和歌辭', '상화가사', '집(集)', '총집류(總集類)', '『鄴都故事』曰：“魏武帝遺命諸子曰: “吾死之後, 葬於鄴中西崗上, 與西門豹祠相近, 無藏金玉珠寶. 餘香可分諸夫人, 不命祭吾. 妾與伎人, 皆著銅雀臺, 臺上施六尺床, 下繐帳. 朝晡上酒脯粻糒之屬, 每月朝十五, 輒向帳前作伎. 汝等時登臺, 望吾西陵墓田.', '“『업도고사』에 말했다. “위(魏) 무제(武帝)가 여러 아들에게 유언으로 명했다. ‘내가 죽은 뒤에 업(鄴)나라 안의 서쪽 언덕(西崗) 위에 장사 지내되 서문표(西門豹)의 사당과 서로 가깝게 하고 금옥(金玉)이나 주보(珠寶)를 부장하지 마라. 남은 향(香)은 여러 부인에게 나누어 주고 나를 제사 지내라고 명하지 않겠다. 나의 첩들과 기녀들은 모두 동작대(銅雀臺)에 머물게 하고 동작대 위에는 6척 침상을 두고 아래에는 가는 삼베 휘장을 쳐라. 또 아침저녁으로 술과 포, 쌀과 말린 밥 같은 종류를 올리고 매달 초하루와 보름에는 곧장 휘장 앞에서 기악을 연주하라. 너희들은 때때로 대에 올라 나의 서릉(西陵) 묘역을 바라보라’ 하였다.”', '업도고사', '최치원'),
    ('A308', '전고_사전_사_정사류_진서_석숭전_000', '사전', '晉書', '진서', '石崇傳', '석숭전', '사(史)', '정사류(正史類)', '崇有別館, 在河陽之金谷, 一名梓澤, 送者傾都, 帳飲於此焉.', '석숭은 가산이 풍부하게 쌓였으며 집이 웅장하고 화려했다. 첩들이 수백 명이었는데 모두 흰 비단과 자수를 끌며 금과 비취 귀걸이를 달았다. 음악은 당대의 명인들을 선발했고, 요리는 산해진미를 다했다.', NULL, '최치원'),
    ('A309', '전고_사전_사_정사류_사기_진시황본기_002', '사전', '史記', '사기', '秦始皇本紀', '진시황본기', '사(史)', '정사류(正史類)', '旣已, 齊人徐市等, 上書言: “海中有三神山, 名曰蓬萊方丈瀛洲, 僊人居之. 請得齋戒, 與童男女求之. 於是, 遣徐市發童男女數千人, 入海求僊人.', '바다 가운데 삼신산(三神山)이 있는데 이름하여 봉래(蓬山)·방장(方丈)·영주(瀛洲)라고 하며 신선이 지낸다고 합니다. 청컨대 목욕재계하고 동남동녀(童男童女)를 데리고 신선을 찾게 해주십시오.” 그러하여 서불에게 동남동녀 수천 명을 선발하여 바다로 나가 신선을 찾게 했다', NULL, '유생전, 최치원'),
    ('A310', '전고_사전_사_정사류_사기_효무본기_01', '사전', '史記', '사기', '孝武本紀', '효무본기', '사(史)', '정사류(正史類)', '於是, 天子始親祠灶, 而遣方士, 入海求蓬萊安期生之屬, 而事化丹沙諸藥齊, 爲黃金矣.', '이에 천자(天子)가 처음으로 직접 조왕신에게 제사 지내고 방사(方士)들을 보내 바다에 들어가 봉래산의 안기생 같은 무리를 찾게 했으며 단사와 여러 약제를 변화시켜 황금을 만드는 일을 맡게 했다.', NULL, '최치원'),
    ('A311', '전고_사전_자_소설가류_태평광기_호_임씨_000', '사전', '太平廣記', '태평광기', '狐_任氏', '호_임씨', '자(子)', '소설가류(小說家類)', '任氏, 女妖也.', '임씨는 요망한 여우다.', '任氏傳', '최치원'),
    ('A312', '전고_어전_경_시류_시경_소아_소민지십_육아_000', '어전', '詩經', '시경', '小雅_小旻之什_蓼莪', '소아_소민지십_육아', '경(經)', '시류(詩類)', '無父何怙, 無母何恃. 出則銜恤, 入則靡至.', '아버지가 없으면 누구를 믿으며 어머니가 없으면 누구를 믿을꼬? 나가면 근심을 품고 들어오면 이를 곳이 없노라.', NULL, NULL),
    ('A313', '전고_사전_사_정사류_한서_종군전_000', '사전', '漢書', '한서', '終軍傳', '종군전', '사(史)', '정사류(正史類)', '初, 軍從濟南當詣博士, 步入關, 關吏予軍繻. 軍問：“以此何爲？” 吏曰；“爲復傳, 還當以合符.” 軍曰: “大丈夫西遊, 終不復傳還” 棄繻而去. 軍爲謁者, 使行郡國, 建節東出關, 關吏識之, 曰: “此使者, 乃前棄繻生也.” 軍行郡國, 所見便宜以聞. 還奏事, 上甚說.', NULL, NULL, NULL),
    ('A314', '전고_사전_자_유서류_태평어람_지부_교_000', '사전', '太平御覽', '태평어람', '地部_橋', '지부_교', '자(子)', '유서류(類書類)', '常璩華陽國志曰: 李冰造七橋, 上應七星. 故光武謂吳漢曰:“安軍宜在七星橋間也.” 又曰: 昇遷橋, 在成都縣北十里, 即司馬相如題橋柱曰: “不乘駟馬高車, 不復過此橋.”', NULL, NULL, NULL),
    ('A315', '전고_어전_경_예류_예기_곡례상_000', '어전', '禮記', '예기', '曲禮上', '곡례상', '경(經)', '예류(禮類)', '人生十年曰幼, 學. 二十曰弱, 冠. 三十曰壯, 有室. 四十曰強, 而仕. 五十曰艾, 服官政. 六十曰耆, 指使. 七十曰老, 而傳. 八十, 九十曰耄. 七年曰悼. 悼與耄雖有罪, 不加刑焉. 百年曰期, 頤.', '사람이 태어나 10세가 된 자를 ‘유(幼)’라 하니 학업을 익힌다. 20세를 ‘약(弱)’이라 하니 관례를 한다. 30세를 ‘장(壯)’이라 하니 아내를 둔다. 40세를 ‘강(强)’이라 하니 벼슬한다. 50세를 ‘애(艾)’라 하니 관정(官政)에 종사한다. 60세를 ‘기(耆)’라 하니 지시하여 부린다. 70세를 ‘노(老)’라 하니 집안일을 물려준다. 80세와 90세를 ‘모(耄)’라 하고, 7세를 ‘도(悼)’라 하니 도와 모는 죄가 있더라도 형벌을 가하지 않는다. 100세를 ‘기(期)’라 하니 봉양을 받는다.', NULL, NULL),
    ('A316', '전고_어전_사_정사류_사기_항우본기_000', '어전', '史記', '사기', '項羽本紀', '항우본기', '사(史)', '정사류(正史類)', '項王見秦宮皆以燒殘破, 又心懷思欲東歸, 曰: “富貴不歸故鄉, 如衣繡夜行, 誰知之者!”', NULL, NULL, NULL),
    ('A317', '전고_어전_사_정사류_사기_범수채택열전_000', '어전', '史記', '사기', '范雎蔡澤列傳', '범수채택열전', '사(史)', '정사류(正史類)', '蔡澤知唐擧戲之, 乃曰: “富貴吾所自有, 吾所不知者壽也, 願聞之.”', '채택은 당거가 자신을 놀린다는 것을 알고 곧 이렇게 말했다. “부귀는 본래 내게 있는 것이고, 내가 알지 못하는 것은 수명이니 듣기를 원하오.', NULL, NULL),
    ('A318', '전고_어전_경_역류_주역_명이괘_000', '어전', '周易', '주역', '明夷卦', '명이괘', '경(經)', '역류(易類)', '明入地中, 明夷.', '밝음이 땅속으로 들어가는 것이 명이이다.', NULL, NULL),
    ('A319', '전고_어전_경_역류_주역_가인괘_000', '어전', '周易', '주역', '家人卦', '가인괘', '경(經)', '역류(易類)', '家人, 利女貞.', '가인은 여자가 바름을 지키는 것이 이롭다.', NULL, NULL),
    ('A320', '전고_어전_경_시류_시경_국풍_정풍_야유만초_000', '어전', '詩經', '시경', '國風_鄭風_野有蔓草', '국풍_정풍_야유만초', '경(經)', '시류(詩類)', '野有蔓草, 零露瀼瀼. 有美一人, 婉如淸揚. 邂逅相遇, 與子偕臧', '들에 덩굴풀이 있고 이슬이 흠뻑 내렸네. 아름다운 사람 하나 있어 맑은 눈매 곱기도 하네. 우연히 서로 만났으니 그대와 함께 아름다운 인연을 이루리라.', NULL, NULL),
    ('A321', '전고_어전_경_시류_시경_국풍_당풍_갈생_000', '어전', '詩經', '시경', '國風_唐風_葛生', '국풍_당풍_갈생', '경(經)', '시류(詩類)', '角枕粲兮, 錦衾爛兮. 予美亡此, 誰與獨旦', '뿔베개는 빛나고 비단 이불은 찬란하건만, 내 사랑하는 이가 여기에 없으니 누구와 홀로 아침을 맞으랴.', NULL, NULL),
    ('A322', '전고_사전_사_정사류_한서_이광소건전_000', '사전', '漢書', '한서', '李廣蘇建傳', '이광소건전', '사(史)', '정사류(正史類)', '昭帝即位數年, 匈奴與漢和親. 漢求武等, 匈奴詭言武死. 後漢使復至匈奴, 常惠請其守者與俱, 得夜見漢使. 具自陳過. 敎使者謂單于, 言:“天子射上林中, 得鴈, 足有係帛書, 言武等在荒澤中.” 使者大喜, 如惠語以讓單于.', '한나라 소제(昭帝)가 즉위하고 몇 년이 지나자, 흉노는 한나라와 화친을 맺었다. 한나라에서는 소무(蘇武) 등을 돌려보내라고 요구하였으나, 흉노는 소무가 이미 죽었다고 거짓말하였다. 그 뒤 한나라 사신이 다시 흉노에 도착하였다. 상혜(常惠)는 자신을 감시하던 자에게 함께 가자고 청하여, 밤중에 한나라 사신을 만날 수 있었다. 상혜는 자신들이 그동안 겪은 일을 낱낱이 진술하고, 사신에게 선우(單于)를 찾아가 다음과 같이 말하도록 일러주었다. “천자께서 상림원(上林苑)에서 사냥하시다가 기러기 한 마리를 잡으셨는데, 그 발에 비단 편지가 묶여 있었습니다. 그 편지에는 소무 등이 황량한 늪지대에 살아 있다고 쓰여 있었습니다.” 한나라 사신은 크게 기뻐하여 상혜가 일러준 대로 말하면서 선우를 책망했다.', NULL, NULL),
    ('A323', '전고_어전_집_별집류_두보시전집_몽이백_000', '어전', '杜甫詩全集', '두보시전집', '夢李白', '몽이백', '집(集)', '별집류(別集類)', '落月滿屋樑, 猶疑照顏色', '기우는 달빛 지붕에 가득하니 마치 그대 모습을 비추는 듯 하네', NULL, NULL),
    ('A324', '전고_사전_집_시문평류_본사시_정감_최호_000', '사전', '本事詩', '본사시', '情感_崔護', '정감_최호', '집(集)', '시문평류(詩文評類)', '博陵崔護, 資質甚美, 而孤潔寡合. 擧進士下第. 淸明日, 獨遊都城南. 得居人莊, 一畝之宮, 而花木叢萃, 寂若無人. 扣門久之, 有女子自門隙窺之, 問曰: “誰耶？”護以姓字對, 曰: “尋春獨行, 酒渴求飲.” 女入, 以杯水至, 開門, 設床命坐.', '박릉의 최호는 용모가 매우 빼어났으나 홀로 고결하여 함께 어울리는 사람이 적었다. 그는 진사과에 급제하고 난 뒤 청명일을 맞아 도성 남쪽을 돌아다니다가 한 장원을 발견했다. 그 장원은 집은 1무 정도밖에는 되지 않았고 나머지는 모두 꽃과 나무가 우거져 있어 마치 사람이 살고 있지 않은 것처럼 적막했다. 그가 오래도록 문을 두드리자 한 여자가 문틈으로 밖을 내다보며 물었다. “누구십니까?” 최호는 자신의 성과 자를 대고는 이렇게 말했다. “봄을 찾아 홀로 여기까지 걸어왔습니다. 술을 마신 뒤라 목이 말라 그러니 물을 좀 얻어 마시고 싶습니다.” 여자는 안으로 들어가더니 물을 한 그릇 떠가지고 나왔다. 그녀는 문을 열고 평상을 피더니 앉으라고 권했다.', NULL, NULL),
    ('A325', '전고_어전_경_역류_주역_관괘_000', '어전', '周易', '주역', '觀卦', '관괘', '경(經)', '역류(易類)', '觀國之光, 利用賓于王', '“나라의 빛을 보는 것이니, 임금께 손님이 되는 것이 이롭다', NULL, NULL),
    ('A326', '전고_어전_경_시류_시경_소아_녹명지십_벌목_000', '어전', '詩經', '시경', '小雅_鹿鳴之什_伐木', '소아_녹명지십_벌목', '경(經)', '시류(詩類)', '伐木丁丁, 鳥鳴嚶嚶. 出自幽谷, 遷于喬木.', '“나무 찍는 소리 떵떵 울리고 새들이 짹짹 노래하네. 깊은 골짜기에서 나와 높은 나무로 옮겨가네."', NULL, NULL),
    ('A327', '전고_어전_경_사서류_맹자_등문공상_000', '어전', '孟子', '맹자', '滕文公上', '등문공상', '경(經)', '사서류(四書類)', '孟子曰: 陳良, 楚産也, 悦周公仲尼之道, 北學於中國. 北方之學者, 未能或之先也', '“맹자가 말했다. 진량은 남쪽 초나라 출신으로 주공과 중니의 도를 좋아해 북쪽으로 중국에서 배우니 북방의 학자들 중 그보다 앞서는 자가 없었다”', NULL, NULL),
    ('A328', '전고_사전_자_소설가류_박물지_잡설하_000', '사전', '博物志', '박물지', '雜說下', '잡설하', '자(子)', '소설가류(小說家類)', '見一丈夫牽牛渚次飲之, 牽牛人乃驚問曰: “何由至此!” 此人具說來意, 并問此是何處. 答曰: “君還至蜀郡, 訪嚴君平則知之.” 竟不上岸, 因還. 如期後至蜀, 問君平, 曰: “某年月日有客星犯牽牛宿, 計年月, 正是此人到天河時也.”', '또 한 장부가 물가에서 소를 끌고 와 물을 먹이고 있는 것이 보였다. 소를 끌던 사람이 깜짝 놀라 물었다. “어떤 경로로 이곳까지 왔습니까?” 그 사람은 자신이 이곳에 오게 된 사정을 자세히 설명하고, 아울러 이곳이 어디인지 물었다. 그러자 장부가 대답하였다. “그대가 돌아가 촉군(蜀郡)에 이르거든 엄군평(嚴君平)을 찾아가 물어보십시오. 그러면 이곳이 어디인지 알게 될 것입니다.” 그 사람은 끝내 뭍에 오르지 않고 그대로 뗏목을 돌려 돌아왔다. 예정된 시기에 돌아온 뒤 촉군으로 가서 엄군평에게 물었다. 엄군평이 말하였다. “어느 해 어느 달 어느 날에 객성(客星)이 견우성(牽牛宿)을 침범한 일이 있었습니다.” 그 연월을 계산해 보니, 바로 그 사람이 은하수에 도착했던 때였다', NULL, NULL),
    ('A329', '전고_사전_집_총집류_문선_고당부_000', '사전', '文選', '문선', '高唐賦', '고당부', '집(集)', '총집류(總集類)', '妾在巫山之陽, 高丘之岨 旦爲朝雲 暮爲行雨 朝朝暮暮 陽臺之下', '저는 무산의 양지쪽 높은 구릉의 험준한 곳에 사는데 매일 아침이면 구름이 되고 저녁이면 내리는 비가 되어, 아침마다 저녁마다 양대 아래에 있습니다.', NULL, NULL),
    ('A330', '전고_어전_집_시문평류_시화총귀_영물문_000', '어전', '詩話總龜', '시화총귀', '咏物門', '영물문', '집(集)', '시문평류(詩文評類)', '聖俞因作莫打鴨一篇曰: 莫打鴨, 打鴨驚鴛鴦. 鴛鴦新向池邊浴, 不比孤洲老秃鶬. 秃鶬尙欲逺飛去, 何况鴛鴦羽翼長?]', '매요신이 이를 듣고 <막타압> 1편을 다음과 같이 지었다. “오리를 때리지 말라. 오리를 때리면 원앙이 놀란다. 원앙은 이제 막 연못가에서 목욕하고 있으니, 외딴 모래톱의 늙은 대머리 물새와는 같지 않다.  그 늙은 대머리 물새조차 멀리 날아가려 하는데, 물며 긴 날개를 가진 원앙이야 말해 무엇하겠는가?', NULL, NULL),
    ('A331', '전고_어전_집_총집류_전당시_대잔등_000', '어전', '全唐詩', '전당시', '對殘燈', '대잔등', '집(集)', '총집류(總集類)', '獨照碧窗久, 欲隨寒燼滅. 幽人將遽眠, 解帶翻成結.', '“홀로 푸른 창을 오래도록 비추다가, 차가운 밤 기운에 꺼져가네. 님께서 곧 잠에 들려고 하는데 띠 풀고 대번에 인연을 이루네”', NULL, NULL),
    ('A332', '전고_어전_사_정사류_사기_범수채택열전_000', '어전', '史記', '사기', '范雎蔡澤列傳', '범수채택열전', '사(史)', '정사류(正史類)', '范睢於是散家財物, 盡以報所嘗困戹者. 一飯之德必償, 睚眥之怨必報.', '범수는 집안의 재물을 풀어 예전에 곤액을 겪었을 때 도움을 준 사람들에게 모두 갚았다. 한 끼 밥의 은혜도 반드시 갚고 눈을 흘겨본 작은 원한도 반드시 갚았다', NULL, NULL),
    ('A333', '전고_어전_경_춘추류_춘추좌씨전_희공22년_000', '어전', '春秋左氏傳', '춘추좌씨전', '僖公二十二年', '희공22년', '경(經)', '춘추류(春秋類)', '寡君之使婢子侍執巾櫛, 以固子也.', '저의 부친인 이 나라 임금님이 저를 당신의 아내로 삼아서 수건과 빗을 들고 모시게 한 것은, 당신을 여기에 묶어 놓기 위해서였습니다', NULL, '허생전'),
    ('A334', '전고_어전_경_시류_시경_국풍_주남_관저_000', '어전', '詩經', '시경', '國風_周南_關雎', '국풍_주남_관저', '경(經)', '시류(詩類)', '關關雎鳩, 在河之洲. 窈窕淑女, 君子好逑.', '끼룩끼룩 물수리는 강가 모래섬에 있네. 요조숙녀는 군자의 좋은 짝이로다', NULL, '심진사전'),
    ('A335', '전고_어전_도_도경류_장자_외물_000', '어전', '莊子', '장자', '外物', '외물', '도(道)', '도경류(道經類)', '儒以詩禮發冢.', '유자들은 『시경(詩經)』과 『예기(禮記)』로 무덤을 파헤치는 이들이다.', NULL, NULL),
    ('A336', '전고_어전_경_사서류_맹자_고자하_000', '어전', '孟子', '맹자', '告子下', '고자하', '경(經)', '사서류(四書類)', '親之過大而不怨, 是愈疏也, 親之過小而怨, 是不可磯也. 愈疏, 不孝也, 不可磯, 亦不孝也.', '부모의 허물이 큰데도 원망하지 않는 것은 더욱 소원해 대하는 것이고, 부모의 허물이 작은데도 원망하는 것은 지나치게 따지는 것이다. 지나치게 소원하게 대하는 것도 불효이고 지나치게 따지는 것도 불효이다.', NULL, NULL),
    ('A337', '전고_어전_경_시류_시경_소아_소민지십_육아_000', '어전', '詩經', '시경', '小雅_小旻之什_蓼莪', '소아_소민지십_육아', '경(經)', '시류(詩類)', '父兮生我, 母兮鞠我. 拊我畜我, 長我育我. 顧我復我, 出入腹我. 欲報之德, 昊天罔極.', '아버지는 나를 낳으시고, 어머니는 나를 기르셨다. 나를 다독이시고 나를 기르시며, 나를 자라게 하고 나를 키우시며, 나를 돌아보시고 나를 다시 살피시며, 출입할 땐 나를 품에 안으셨다. 이 은혜를 갚으려면 하늘이라 한량이 없도다.', NULL, '낙우애우기'),
    ('A338', '전고_어전_경_시류_시경_소아_소민지십_육아_000', '어전', '詩經', '시경', '小雅_小旻之什_蓼莪', '소아_소민지십_육아', '경(經)', '시류(詩類)', '父兮生我, 母兮鞠我. 拊我畜我, 長我育我. 顧我復我, 出入腹我. 欲報之德, 昊天罔極.', '아버지는 나를 낳으시고, 어머니는 나를 기르셨다. 나를 다독이시고 나를 기르시며, 나를 자라게 하고 나를 키우시며, 나를 돌아보시고 나를 다시 살피시며, 출입할 땐 나를 품에 안으셨다. 이 은혜를 갚으려면 하늘이라 한량이 없도다.', NULL, '낙우애우기'),
    ('A339', '전고_어전_경_시류_시경_대아_생민지십_판_000', '어전', '詩經', '시경', '大雅_生民之什_板', '대아_생민지십_판', '경(經)', '시류(詩類)', '昊天曰明, 及爾出往. 昊天曰旦, 及爾游衍.', '하늘은 매우 밝으셔서 네가 어디를 나가는지 알고 계시며, 하늘은 매우 밝으셔서 네가 어디를 노니는지 다 아신다.', NULL, NULL),
    ('A340', '전고_어전_경_서류_서경_주서_홍범_000', '어전', '書經', '서경', '周書_洪範', '주서_홍범', '경(經)', '서류(書類)', '惟天陰騭下民, 相協厥居.', '하늘이 말없이 백성을 안정시키고 그 거처를 조화롭게 한다', NULL, NULL),
    ('A341', '전고_어전_사_잡사류_국어_진어팔_000', '어전', '國語', '국어', '晉語八', '진어팔', '사(史)', '잡사류(雜史類)', '趙文子與叔向游于九原, 曰: “死者若可作也, 吾誰與歸?” 叔向曰: “其陽子乎?”', '조문자(趙文子)가 숙향(叔向)과 함께 구원(九原)에서 노닐다가 말하였다. “죽은 사람을 만일 다시 살아나게 할 수 있다면, 나는 누구를 따라 함께하겠는가?" 숙향이 말하였다. “양자(陽子)가 아니겠습니까?”', NULL, NULL),
    ('A342', '전고_어전_경_시류_시경_국풍_진풍_월출_000', '어전', '詩經', '시경', '國風_陳風_月出', '국풍_진풍_월출', '경(經)', '시류(詩類)', '月出皎兮, 佼人僚兮. 舒窈糾兮, 勞心悄兮.', '달이 떠서 환하거늘, 아름다운 사람 예쁘기도 하네. 어찌 그윽한 시름 펼까? 마음에 애태움이 심하네.', NULL, NULL),
    ('A343', '전고_어전_경_시류_시경_국풍_당풍_주무_000', '어전', '詩經', '시경', '國風_唐風_綢繆', '국풍_당풍_주무', '경(經)', '시류(詩類)', '綢繆束楚, 三星在戶. 今夕何夕? 見此粲者. 子兮子兮, 如此粲者何?', '칭칭 감아 나뭇단을 묶을 적에, 삼성이 문에 있도다. 오늘 밤은 어떤 밤인고, 이 아름다운 분을 만났노라. 그대여 그대여, 이 아름다운 분에 어쩌리오.', NULL, NULL),
    ('A344', '전고_어전_경_시류_시경_국풍_당풍_주무_000', '어전', '詩經', '시경', '國風_唐風_綢繆', '국풍_당풍_주무', '경(經)', '시류(詩類)', '綢繆束楚, 三星在戶. 今夕何夕? 見此粲者. 子兮子兮, 如此粲者何?', '칭칭 감아 나뭇단을 묶을 적에, 삼성이 문에 있도다. 오늘 밤은 어떤 밤인고, 이 아름다운 분을 만났노라. 그대여 그대여, 이 아름다운 분에 어쩌리오.', NULL, NULL),
    ('A345', '전고_어전_경_시류_시경_국풍_소남_행로_000', '어전', '詩經', '시경', '國風_召南_行露', '국풍_소남_행로', '경(經)', '시류(詩類)', '誰謂鼠無牙, 何以穿我墉. 誰謂女無家, 何以速我訟? 雖速我訟, 亦不女從.', '누가 ‘쥐에게 어금니가 없으면 어떻게 내 담을 뚫었겠는가.’ 하며 누가 ‘네가 실가의 예가 없으면 어찌 나를 송사에 불러들였겠는가.’ 하건만 비록 나를 송사에 불러들였으나 또한 너를 따르지 않으리라.', NULL, NULL),
    ('A346', '전고_어전_경_춘추류_춘추좌씨전_은공원년_000', '어전', '春秋左氏傳', '춘추좌씨전', '隱公元年', '은공원년', '경(經)', '춘추류(春秋類)', '公入而賦: 大隧之中, 其樂也融融!” 姜出而賦: “大隧之外, 其樂也洩洩!', '장공이 땅굴 안으로 들어가 노래하였다. "큰 땅굴 안이니, 그 즐거움이 화락하구나!" 강씨가 땅굴 밖으로 나와 노래하였다. "큰 땅굴 밖이니, 그 즐거움이 흡족하구나!', NULL, NULL),
    ('A347', '전고_어전_경_시류_시경_국풍_정풍_장중자_000', '어전', '詩經', '시경', '國風_鄭風_將仲子', '국풍_정풍_장중자', '경(經)', '시류(詩類)', '將仲子兮, 無踰我園, 無折我樹檀.', '중자(仲子)여, 우리 집 동산 담을 넘지 마시고, 내가 심은 박달나무를 꺾지 마세요', NULL, NULL),
    ('A348', '전고_어전_경_시류_시경_국풍_소남_행로_000', '어전', '詩經', '시경', '國風_召南_行露', '국풍_소남_행로', '경(經)', '시류(詩類)', '厭浥行露, 豈不夙夜, 謂行多露.', '함초롬히 이슬 젖은 길에 어찌 조석으로 다니지 않으랴마는, 길에 이슬이 많아서 못 하느니라', NULL, '허생전'),
    ('A349', '전고_어전_경_시류_시경_국풍_정풍_준대로_000', '어전', '詩經', '시경', '國風_鄭風_遵大路', '국풍_정풍_준대로', '경(經)', '시류(詩類)', '遵大路兮, 摻執子之手兮. 無我魗兮, 寁不好也.', '큰길을 따라가며, 그대의 손을 붙잡노라. 나를 싫다 하여 버리지 마오. 우리 사이의 좋은 정을 갑자기 끊지 마오.', NULL, NULL),
    ('A350', '전고_어전_경_시류_시경_대아_문왕지십_문왕유성_000', '어전', '詩經', '시경', '大雅_文王之什_文王有聲', '대아_문왕지십_문왕유성', '경(經)', '시류(詩類)', '豊水有芑, 武王豈不仕. 詒厥孫謀, 以燕翼子. 武王烝哉.', '풍수에도 기풀이 있으니 무왕이 어찌 여기서 일하지 않으시리오. 후손에게 계책을 남겨주사 공경하는 아들을 편안하게 하시니 무왕은 훌륭한 군주로다.', NULL, NULL),
    ('A351', '전고_어전_경_시류_시경_국풍_패풍_포유고엽_000', '어전', '詩經', '시경', '國風_邶風_匏有苦葉', '국풍_패풍_포유고엽', '경(經)', '시류(詩類)', '雝雝鳴雁, 旭日始旦. 士如歸妻, 迨冰未泮.', '화락하게 우는 기러기는, 해 떠올라 아침이 될 제 우느니라. 남자가 만일 아내를 데리고 오려면, 얼음이 풀리기 전에 해야 하느니라.', NULL, NULL),
    ('A352', '전고_어전_경_시류_시경_국풍_주남_도요_000', '어전', '詩經', '시경', '國風_周南_桃夭', '국풍_주남_도요', '경(經)', '시류(詩類)', '桃之夭夭 灼灼其華. 之子于歸, 宜其室家.', '아름다운 복사꽃, 꽃이 활짝 피었도다. 그녀 시집감이여, 집안 살림 잘 하리라', NULL, '이생전'),
    ('A353', '전고_어전_경_시류_시경_국풍_소남_표유매_000', '어전', '詩經', '시경', '國風_召南_標有梅', '국풍_소남_표유매', '경(經)', '시류(詩類)', '摽有梅, 其實七兮. 求我庶士, 迨其吉兮.', '“떨어지는 매화여 그 열매가 일곱이로다. 나를 아내로 맞으려는 여러 사내여, 좋은 때를 놓치지 마라.”', NULL, NULL),
    ('A354', '전고_어전_경_시류_시경_국풍_용풍_백주_000', '어전', '詩經', '시경', '國風_鄘風_柏舟', '국풍_용풍_백주', '경(經)', '시류(詩類)', '汎彼柏舟, 在彼中河. 髧彼兩髦, 實維我儀, 之死矢靡他', '“두둥실 떠 있는 저 잣나무 배여. 저 황하 가운데 떠있네. 두 갈래 머리 더펄거리는 저 분이, 진실로 내 배필이니, 죽기를 맹세코 다른 곳에 시집가지 않으리.', NULL, '낙우애우기'),
    ('A355', '전고_사전_경_시류_모시정의_서_000', '사전', '毛詩正義', '모시정의', '序', '서', '경(經)', '시류(詩類)', '共姜自誓也. 衛世子共伯蚤死, 其妻守義. 父母欲奪而嫁之, 誓而弗許. 故作是詩以絶之.', '공강(共姜)이 스스로 자신의 뜻을 맹세한 시이다. 위나라 세자 공백(共伯)이 일찍 죽자, 그의 아내 공강은 절의를 지켰다. 친정 부모가 그 뜻을 꺾어 다른 사람에게 시집보내려 하였으나, 공강은 맹세하며 허락하지 않았다. 그러므로 이 시를 지어 부모의 재가 요구를 단호히 끊어 버렸다.', NULL, NULL),
    ('A356', '전고_사전_집_자_소설가류_속현괴록_정혼점_000', '사전', '續玄怪錄', '속현괴록', '定婚店', '정혼점', '자(子)', '소설가류(小說家類)', '固曰: “然則君何主?” 曰: “天下之婚牘耳.” 固喜曰: “固少孤, 嘗願早娶, 以廣後嗣. 爾來十年, 多方求之. 竟不遂意. 今者人有期此, 與議潘司馬女, 可以成乎?” 曰: “未也, 君之婦適三歲矣. 年十七, 當入君門.” 因問囊中何物, 曰: “赤繩子耳, 以繫夫婦之足, 及其坐則潛用相繫. 雖讐敵之家. 貴賤懸隔, 天涯從宦, 吳楚異鄉, 此繩一繫, 終不可逭. 君之脚已繫於彼矣, 他求何益.”', NULL, NULL, '허생전'),
    ('A357', '전고_어전_경_시류_시경_국풍_빈풍_동산_000', '어전', '詩經', '시경', '國風_豳風_東山', '국풍_빈풍_동산', '경(經)', '시류(詩類)', '之子于歸, 皇駁其馬. 親結其縭, 九十其儀.', '아가씨 시집가니 누런 말과 얼룩말이로다. 어머니가 향주머니 채워 주니 그 위의 성대하도다', NULL, '김현감호'),
    ('A358', '전고_사전_사_정사류_후한서_일민열전_양홍전_000', '사전', '後漢書', '후한서', '逸民列傳_梁鴻傳', '일민열전_양홍전', '사(史)', '정사류(正史類)', '遂至吳, 依大家皐伯通, 居廡下, 爲人賃舂. 每歸, 妻爲具食, 不敢於鴻前仰視, 舉案齊眉. 伯通察而異之, 曰: “彼傭能使其妻敬之如此, 非凡人也.', '양홍이 드디어 오(吳)나라에 도착해 대가(大家) 고백통(皐伯通)에게 의지해 행랑채 아래에 거처하며 남의 집 절구질을 해주는 품을 팔았다. 매번 돌아올 때마다 아내 맹광이 음식을 준비했는데 감히 양홍의 앞에서 우러러보지 못하고 밥상을 눈썹 높이까지 받들어 올렸다. 고백통이 살펴보고 그것을 기이하게 여겨 말했다. “저 품꾼이 능히 그 아내로 하여금 공경하기를 이토록 하니 평범한 사람이 아니다.', NULL, NULL),
    ('A359', '전고_사전_경_춘추류_춘추좌씨전_희공33년_000', '사전', '春秋左氏傳', '춘추좌씨전', '僖公三十三年', '희공33년', '경(經)', '춘추류(春秋類)', '狄伐晉, 及箕. 八月戊子, 晉侯敗狄于箕. 郤缺獲白狄子. 先軫曰: “匹夫逞志於君, 而無討, 敢不自討乎?” 免冑入狄師, 死焉. 狄人歸其元, 面如生. 初, 臼季使過冀, 見冀缺耨, 其妻饁之. 敬, 相待如賓.', '적(狄)이 진(晉)나라를 침공하여 기(箕) 땅에 이르렀다. 8월 무자일에 진후(晉侯)가 기 땅에서 적군을 격파하였다. 극결(郤缺)은 백적(白狄)의 군주를 사로잡았다. 선진(先軫)이 말하였다. “한낱 필부인 내가 임금 앞에서 제 감정을 멋대로 드러내고도 처벌받지 않았으니, 어찌 감히 스스로를 벌하지 않겠는가?” 선진은 투구를 벗고 적군의 진영으로 들어가 전사하였다. 적인은 그의 머리를 돌려보냈는데, 얼굴빛이 살아 있을 때와 같았다. 당초 구계(臼季)가 사신으로 가다가 기(冀) 땅을 지나면서 기결(冀缺)이 김을 매는 모습을 보았다. 그의 아내가 들밥을 가져다주었는데, 부부가 서로 공경하며 손님을 대하듯 하였다', NULL, NULL),
    ('A360', '전고_어전_경_역류_주역_곤괘_000', '어전', '周易', '주역', '坤卦', '곤괘', '경(經)', '역류(易類)', '積善之家, 必有餘慶, 積不善之家, 必有餘殃.', '“선을 쌓는 집안에는 반드시 경사가 있으며 불선을 쌓는 집안에는 반드시 재앙이 있다.”', NULL, NULL),
    ('A361', '전고_어전_자_잡가류_회남자_남명훈_000', '어전', '淮南子', '회남자', '覽冥訓', '남명훈', '자(子)', '잡가류(雜家類)', '羿請不死之藥於西王母，姮娥竊以奔月', NULL, NULL, '허생전'),
    ('A362', '전고_어전_사_정사류_진서_갈홍전_000', '어전', '晉書', '진서', '葛洪傳', '갈홍전', '사(史)', '정사류(正史類)', '藜藿有八珍之甘, 蓬蓽有藻棁之樂也', '명아주와 콩잎에 여덟 가지 진미의 달콤함이 있고, 쑥대 지붕과 흙벽 집에에도 화려하게 장식된 기둥의 즐거움이 있다', NULL, '허생전'),
    ('A363', '전고_어전_자_소설가류_세설신어_언어_고열_000', '어전', '世說新語', '세설신어', '言語_顧悅', '언어_고열', '자(子)', '소설가류(小說家類)', '蒲柳之姿, 望秋而落, 松柏之質, 經霜彌茂', '표류와 같은 체질은 가을을 바라보기만 해도 시들어 떨어지며 소나무와 잣나무의 자질은 서리를 지나 더욱 무성해집니다', NULL, '허생전'),
    ('A364', '전고_어전_경_춘추류_춘추좌씨전_선공15년_000', '어전', '春秋左氏傳', '춘추좌씨전', '宣公十五年', '선공15년', '경(經)', '춘추류(春秋類)', '及輔氏之役, 顆見老人, 結草以亢杜回, 杜回躓而顛, 故獲之, 夜夢之曰: “余, 而所嫁婦人之父也. 爾用先人之治命, 余是以報.', '보씨(輔氏)의 전투에 이르러, 과(顆)가 한 노인을 보았는데 풀을 묶어서 두회(杜回)를 막으니 두회가 걸려 넘어졌다. 그러므로 그를 사로잡았다. 그날 밤 노인이 꿈에 나타나 말했다. "나는 그대가 시집보낸 부인의 아버지다. 그대가 선인(先人)의 유언을 따른 덕분에 내가 이로써 보답한다', NULL, '허생전'),
    ('A365', '전고_어전_경_사서류_논어_태백_000', '어전', '論語', '논어', '泰伯', '태백', '경(經)', '사서류(四書類)', '子曰: ‘學如不及, 猶恐失之', '배움은 따라가지 못할 듯이 하면서도 오히려 때를 놓칠까 두려워해야 한다', NULL, '허생전'),
    ('A366', '전고_어전_경_시류_시경_국풍_왕풍_채갈_000', '어전', '詩經', '시경', '國風_王風_采葛', '국풍_왕풍_채갈', '경(經)', '시류(詩類)', '一日不見, 如三秋兮.', '하루 동안 보지 못함이 삼년과 같이 느껴지는구나', NULL, '허생전'),
    ('A367', '전고_어전_경_서류_서경_주서_강고_000', '어전', '書經', '서경', '周書_康誥', '주서_강고', '경(經)', '서류(書類)', '若有疾, 惟民其畢棄咎, 若保赤子, 惟民其康乂', '마치 몸에 병이 있는 것처럼 여기면 백성들이 모두 허물을 버릴 것이며, 마치 갓난아이를 보호하듯 하면 백성들이 편안히 다스려질 것이다', NULL, '허생전'),
    ('A368', '전고_어전_경_시류_시경_대아_생민지십_민노_000', '어전', '詩經', '시경', '大雅_生民之什_民勞', '대아_생민지십_민노', '경(經)', '시류(詩類)', '無縱詭隨, 以謹繾綣', '속임을 따르게 두지 않아 매달리게 됨을 금하며', NULL, '안생, 허생전, 최치원'),
    ('A369', '전고_어전_경_시류_시경_국풍_소남_행로_000', '어전', '詩經', '시경', '國風_召南_行露', '국풍_소남_행로', '경(經)', '시류(詩類)', '厭浥行露, 豈不夙夜, 謂行多露.', '함초롬히 이슬 젖은 길에 어찌 조석으로 다니지 않으랴마는, 길에 이슬이 많아서 못 하느니라', NULL, '허생전'),
    ('A370', '전고_어전_경_춘추류_춘추좌씨전_희공22년_000', '어전', '春秋左氏傳', '춘추좌씨전', '僖公二十二年', '희공22년', '경(經)', '춘추류(春秋類)', '寡君之使婢子侍執巾櫛, 以固子也.', '저의 부친인 이 나라 임금님이 저를 당신의 아내로 삼아서 수건과 빗을 들고 모시게 한 것은, 당신을 여기에 묶어 놓기 위해서였습니다', NULL, '허생전'),
    ('A371', '전고_어전_사_정사류_삼국지_손등전_000', '어전', '三國志', '삼국지', '孫登傳', '손등전', '사(史)', '정사류(正史類)', '陛下留意聽采, 臣雖死之日, 猶生之年也', '폐하께서 유의하여 들어주신다면, 신이 비록 오늘 죽는다 하더라도, 오히려 다시 태어나는 해가 될 것입니다.', NULL, '허생전'),
    ('A372', '전고_어전_집_소설류_미상_주생전_000', '어전', '-', '-', '周生傳', '주생전', '집(集)', '소설류(小說類)', '一日誤身, 百年含情, 殘花貯思, 片月凝眸', '하루 만에 몸을 망치고 백년의 정을 품었으니 떨어지는 꽃잎마다 그리움이 쌓여 있고 조각달에는 눈동자 맺혀있습니다.', NULL, '허생전'),
    ('A373', '전고_사전_자_소설가류_속현괴록_정혼점_000', '사전', '續玄怪錄', '속현괴록', '定婚店', '정혼점', '자(子)', '소설가류(小說家類)', '固曰: “然則君何主?” 曰: “天下之婚牘耳.” 固喜曰: “固少孤, 嘗願早娶, 以廣後嗣. 爾來十年, 多方求之. 竟不遂意. 今者人有期此, 與議潘司馬女, 可以成乎?” 曰: “未也, 君之婦適三歲矣. 年十七, 當入君門.” 因問囊中何物, 曰: “赤繩子耳, 以繫夫婦之足, 及其坐則潛用相繫. 雖讐敵之家. 貴賤懸隔, 天涯從宦, 吳楚異鄉, 此繩一繫, 終不可逭. 君之脚已繫於彼矣, 他求何益.”', NULL, NULL, '허생전'),
    ('A374', '전고_사전_자_소설가류_냉재야화_범문정맥주_000', '사전', '冷齋夜話', '냉재야화', '範文正公麥舟', '범문정맥주', '자(子)', '소설가류(小說家類)', '范文正公在睢陽，遣堯夫于姑蘇取麥五百斛. 堯夫時尙少, 既還, 舟次丹陽, 見石曼卿, 問: “寄此久近?” 曼卿曰: “兩月矣. 三喪在淺土, 欲喪之西北皈, 無可與謀者.” 堯夫以所載舟付之, 單騎自長蘆捷徑而去.', NULL, NULL, '허생전'),
    ('A375', '전고_사전_집_시문평류_본사시_정감_양소_000', '사전', '本事詩', '본사시', '情感_楊素', '정감_양소', '집(集)', '시문평류(詩文評類)', '德言直引至其居, 設食, 具言其故, 出半鏡以合之. … 素知之，愴然改容，即召德言，還其妻，仍厚遺之', '서덕언이 곧장 그 노복을 자신의 거처로 데리고 와서 먹을 것을 베풀며 그간의 일들을 자세히 말해준 다음 반쪽짜리 거울을 꺼내 합쳐보았다. (중략) 양소가 그들의 사연을 알고 몹시 슬픈 얼굴을 하더니 곧장 서덕언을 불러 그에게 아내를 돌려주고 후하게 재물을 주었다.', NULL, '이생전;허생전,최치원');
INSERT INTO "remark" ("id", "name", "type", "reviewer", "work_kor", "work_chi", "target_book", "original_text", "translation", "notes") VALUES
    ('MNHPDDDPP01YU002P001', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_001', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '古之屈自郡, 今義安郡.', '옛 굴자군(屈自郡)으로 지금의 의안군(義安郡)이다.', NULL),
    ('MNHPDDDPP01YU002P002', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_002', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '其山, 一體三首, 故云:‘三山.’', '그 산은 몸체는 하나지만 봉우리가 셋이므로 삼산(三山)이라 한다.', NULL),
    ('MNHPDDDPP01YU002P003', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_003', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '望前, 白月影現, 故以名之.', '보름 직전 흰 달의 그림자가 못에 비쳤기 때문에 그것으로 이름한 것이다.', NULL),
    ('MNHPDDDPP01YU002P004', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_004', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '一作等.', '득(得)은 어떤 곳에는 등(等)으로 되어있다.', NULL),
    ('MNHPDDDPP01YU002P005', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_005', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '鄕傳云:‘雉山村’, 誤矣. 二士之名, 方言. 二家各以二士心行騰騰苦節二義, 名之爾.', '향전(鄕傳)에 ‘치산촌(雉山村)’이라 기록한 것은 잘못이다. 두 사람의 이름은 방언이다. 두 집안에서 각각 다 두 사람의 마음가짐과 수행이 드높아지고 굳게 지조를 지킨다는 두 가지 뜻으로서 이름 지은 것이다.', NULL),
    ('MNHPDDDPP01YU002P006', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_006', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '今懷眞洞, 有古寺基, 是也.', '지금 회진동(懷眞洞)에 옛 절터가 남아있는데 이곳이다.', NULL),
    ('MNHPDDDPP01YU002P007', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_007', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '今梨山上, 有寺基, 是也.', '지금 이산(梨山) 위에 있는 절터가 남아있는데 이곳이다.', NULL),
    ('MNHPDDDPP01YU002P008', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_008', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '今南藪洞也.', '지금의 남수동(南藪洞)이다.', NULL),
    ('MNHPDDDPP01YU002P009', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_009', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '鄕傳云: ‘夫得處山北瑠璃洞, 今板房. 朴朴居山南法精洞磊房’, 與此相反. 以今驗之, 鄕傳誤矣.', '향전에는 ‘부득은 산 북쪽의 유리동(瑠璃洞)에 지냈으니 지금의 판방(板房)이고 박박은 산 남쪽의 법정동(法精洞) 뇌방(磊房)에서 지냈다.’고 되어 있으니 이 내용과 상반된다. 그러나 지금 검증해보면 향전이 잘못되었다.', NULL),
    ('MNHPDDDPP01YU002P010', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_010', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '鄕傳云:‘南庵.’', '향전에는 ‘남암(南庵)’이라고 되어있다.', NULL),
    ('MNHPDDDPP01YU002P011', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_011', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '記云:‘我百念灰冷, 無以血囊見試.', '기(記)에는 “나는 온갖 생각이 재처럼 식었으니 육신으로 나를 시험하지 말라.”라고 했다.', NULL),
    ('MNHPDDDPP01YU002P012', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_012', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '傳曰:‘北庵.’', '전(傳)에는 ‘북암’이라고 했다.', NULL),
    ('MNHPDDDPP01YU002P013', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_013', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '古記云:‘天鑑二十四年乙未, 法興卽位’. 何先後倒錯之甚如此?', '고기(古記)에는 ‘천감(天監) 24년 을미(乙未)에 법흥왕(法興)이 즉위했다.’고 하는데 어찌 이리도 그 앞뒤가 뒤바뀜이 심할 수 있을까?】', NULL),
    ('MNHPDDDPP01YU002P014', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_014', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '古記云:‘大曆元年’, 亦誤.', '고기(古記)에는 ‘대력(大曆) 원년’이라고 했는데 또한 잘못이다.', NULL),
    ('MNHPDDDPP01YU002P015', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_015', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '右北庵.', '이는 북암(北庵:달달박박)을 기린 것이다.', '원본에는 본문처럼 판각되어있음'),
    ('MNHPDDDPP01YU002P016', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_016', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '右南庵.', '이는 남암(南庵:노힐부득)을 기린 것이다.', '원본에는 본문처럼 판각되어있음'),
    ('MNHPDDDPP01YU002P017', '평비_남백월이성노힐부득달달박박_목판본_한국 규장각한국학연구원_협주_017', '협주(夾註)', '[未詳]', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '右聖娘.', '이는 성낭(聖娘)을 기린 것이다.', '원본에는 본문처럼 판각되어있음'),
    ('MMPSJPG01YU001H001', '평비_만복사저포기_목판본_일본 내각문고_두주_001', '두주(頭註)', '호산(湖山)', '만복사저포기', '萬福寺樗蒲記', '일본 내각문고', '小野湖山曰: “題曰樗蒲記, 余視以爲尋常戲謔文, 讀至數葉, 情味, 一段深於一段, 詞思, 一章巧於一章, 實是天下奇文. 三百年湮沒, 而復顯於世, 固不足怪. 歐陽公所謂: ‘精氣光怪, 已能自發見’者, 蓋此類也.”', '소야호산이 말한다. 제목을 「저포기」라고 한 것을 내가 처음 보았을 때는 평범한 희문이라고 여겼다. 그러나 몇 장 읽어보니 정미(情味)는 한 단락이 전에 읽은 한 단락 보다 깊어지고 글의 뜻(詞思)은 한 장이 전에 읽은 한 장보다 공교로워 참으로 천하의 기문(奇文)이다. 300년 동안 묻혀있다가 다시 세상에 드러난 것이 진실로 이상할 게 아니다. 구양수(歐陽修)가 말한 ‘정기와 광괴가 먼저 저절로 나타난다 정기의 ... 발현된다 : 『歐陽文忠公文集』‧「蘇氏文集序」에 “비록 그것이 파묻혀서 아직 나타나지 않았으나, 그것의 정령스러운 기운과 기이한 빛은 이미 늘 스스로 드러날 수 있어서 외물 또한 가릴 수 없는 것이다. [雖其埋沒而未出, 其精氣光怪, 已能常自發見, 而物亦不能揜也]”라고 했다.
INSERT INTO "remark" ("id", "name", "type", "reviewer", "work_kor", "work_chi", "target_book", "original_text", "translation", "notes") VALUES
    ('MLSGJJ01YU003H015', '평비_이생규장전_필사본_한국 고려대학교_두주_015', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “喜極生畏怖, 是亦人情所不免”', '호산이 말한다. “기쁨이 극에 달하면 두려움이 생겨나니 이는 인정상 피할 수 없는 것이다.”', NULL),
    ('MLSGJJ01YU003H016', '평비_이생규장전_필사본_한국 고려대학교_두주_016', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “好聯句, 終是貴家兒女口氣”', '호산이 말한다. “좋은 연구로 끝맺음이 귀족 집안의 아녀자의 말투다.”', NULL),
    ('MLSGJJ01YU003H017', '평비_이생규장전_필사본_한국 고려대학교_두주_017', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “可畏”', '중주가 말한다. “가히 두렵다.”', NULL),
    ('MLSGJJ01YU003H018', '평비_이생규장전_필사본_한국 고려대학교_두주_018', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “才女近淫婦, 語氣放縱可憎.”', '호산이 말한다. “재녀가 음부에 가까우니 말투가 방종한 것이 참으로 밉다.”', NULL),
    ('MLSGJJ01YU003H019', '평비_이생규장전_필사본_한국 고려대학교_두주_019', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “父母鐘愛之極, 遂至此, 世間育才女者, 可不戒哉”', '중주가 말한다. “부모가 지극히 사랑을 쏟아 결국 이 지경이 되었으니 세상에서 재녀(才女)를 기르는 사람들은 경계하지 않을 수 있겠는가?”', NULL),
    ('MLSGJJ01YU003H020', '평비_이생규장전_필사본_한국 고려대학교_두주_020', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“閣, 作閤如何?”', '“각(閣)은 합(閤)으로 적는 것이 어떠한가?”', NULL),
    ('MLSGJJ01YU003H021', '평비_이생규장전_필사본_한국 고려대학교_두주_021', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “畏怖之情, 稍定.”', '호산이 말한다. “두려워하는 마음이 조금 가라앉았구나.”', NULL),
    ('MLSGJJ01YU003H022', '평비_이생규장전_필사본_한국 고려대학교_두주_022', '두주(頭註)', '장매외(長梅外)', '이생규장전', '李生窺牆傳', '일본 내각문고', '梅外曰: “一結入妙”', '호산이 말한다. “두 번째 구절이 절묘하다.”', NULL),
    ('MLSGJJ01YU003H023', '평비_이생규장전_필사본_한국 고려대학교_두주_023', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “第二句, 妙”', '매외가 말한다. “결련이 절묘하구나.”', NULL),
    ('MLSGJJ01YU003H024', '평비_이생규장전_필사본_한국 고려대학교_두주_024', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “架空布局, 巧甚”', '호산이 말한다. “가공해 낸 포국이 참으로 교묘하다.”', NULL),
    ('MLSGJJ01YU003H025', '평비_이생규장전_필사본_한국 고려대학교_두주_025', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “四壁書画, 滿幅雲烟, 宛然富貴氣象.”', '중주가 말한다. “사방 벽의 서화들이 온통 구름과 안개로 가득하니 부귀의 기상이 완연하다.”', NULL),
    ('MLSGJJ01YU003H026', '평비_이생규장전_필사본_한국 고려대학교_두주_026', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “詩不知何人所作, 快絶淸絕. 作者得意, 可知已.”', '호산이 말한다. “시가 누구 작품인지 알 수 없으나 통쾌하고 청아하니 작자가 득의했음을 알 수 있다.”', NULL),
    ('MLSGJJ01YU003H027', '평비_이생규장전_필사본_한국 고려대학교_두주_027', '두주(頭註)', '장매외(長梅外)', '이생규장전', '李生窺牆傳', '일본 내각문고', '梅外曰: “四句老蒼.”', '매외가 말한다. “네 번째 구절이 노련하고 힘이 있다.”', NULL),
    ('MLSGJJ01YU003H028', '평비_이생규장전_필사본_한국 고려대학교_두주_028', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“松雪之眞字, 趙孟頫楷體之謂”', '송설의 진자(眞字)는 조맹부(趙孟頫)의 해서체를 말하는 것이다.', NULL),
    ('MLSGJJ01YU003H029', '평비_이생규장전_필사본_한국 고려대학교_두주_029', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “筆則摹松雪眞字, 言外含有管夫人”', '호산이 말한다. “붓글씨는 송설의 진자를 본떴으나 말 밖에는 관부인(管夫人)의의 솜씨가 포함되어있다.”', NULL),
    ('MLSGJJ01YU003H030', '평비_이생규장전_필사본_한국 고려대학교_두주_030', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “淸婉欲絕”', '호산이 말한다. “맑고 아름답기가 기절할 정도다.”', NULL),
    ('MLSGJJ01YU003H031', '평비_이생규장전_필사본_한국 고려대학교_두주_031', '두주(頭註)', '장매외(長梅外)', '이생규장전', '李生窺牆傳', '일본 내각문고', '梅外曰: “首首皆妙”', '매외가 말한다. “작품마다 모두 절묘하다.”', NULL),
    ('MLSGJJ01YU003H032', '평비_이생규장전_필사본_한국 고려대학교_두주_032', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “蕭蕭洒洒, 押韻亦極自然”', '호산이 말한다. “소소하고 깨끗하며 압운 또한 몹시 자연스럽다.”', NULL),
    ('MLSGJJ01YU003H033', '평비_이생규장전_필사본_한국 고려대학교_두주_033', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “風流韶令, 詩亦得趙管夫妻神味”', '호산이 말한다. “풍류스럽고 아름다우며 시 또한 조맹부 관부인 부부의 신묘한 정취를 얻었구나.”', NULL),
    ('MLSGJJ01YU003H034', '평비_이생규장전_필사본_한국 고려대학교_두주_034', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “十六絶, 首首能渾融, 其詞令人永歎而得之”', '호산이 말한다. “열여섯 수의 절구가 작품마다 그림과 잘 어우러져 있으니, 그 내용이 사람들에게 길이 감탄하며 그 맛을 얻게 한다.”', NULL),
    ('MLSGJJ01YU003H035', '평비_이생규장전_필사본_한국 고려대학교_두주_035', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “此是中冓, 不用多言妙矣”', '중주가 말한다. “여기가 곧 내실이니 많은 말을 쓰지 않아도 묘하다.”', NULL),
    ('MLSGJJ01YU003H036', '평비_이생규장전_필사본_한국 고려대학교_두주_036', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “一喜”', '중주가 말한다. “한 번의 기쁨이로다.”', NULL),
    ('MLSGJJ01YU003H037', '평비_이생규장전_필사본_한국 고려대학교_두주_037', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “歡極生畏懼, 才子人品勝才女一等.”', '호산이 말한다. “즐거움이 극에 달하면 두려움이 생겨나니 재자의 인품이 재녀보다 한 등급 위에 있다.”', NULL),
    ('MLSGJJ01YU003H038', '평비_이생규장전_필사본_한국 고려대학교_두주_038', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “常詣國學, 不爲無功”', '중주가 말한다. “늘 국학에 다녔으니 헛된 공은 아니구나.”', NULL),
    ('MLSGJJ01YU003H039', '평비_이생규장전_필사본_한국 고려대학교_두주_039', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “知子莫若父, 明如觀火. 世間此事不少, 言言寫得逼眞”', '중주는 말한다, “자식을 아는 것은 아비만 한 이가 없으니 불을 보듯 명확하다. 세상에 이런 일이 적지 않으니 말 한마디 한마디가 핍진하게 그려졌다.”', NULL),
    ('MLSGJJ01YU003H040', '평비_이생규장전_필사본_한국 고려대학교_두주_040', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“嶺南, 卽慶尙道, 蔚州, 卽今蔚山府”', '영남은 곧 경상도이며 울주는 곧 지금의 울산부다.', NULL),
    ('MLSGJJ01YU003H041', '평비_이생규장전_필사본_한국 고려대학교_두주_041', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “一悲”', '중주가 말한다: “첫 번째 슬픔이로다.”', NULL),
    ('MLSGJJ01YU003H042', '평비_이생규장전_필사본_한국 고려대학교_두주_042', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “細語一句, 能寫含羞之狀”', '중주가 말한다: “가느다란 말로 표현되는 한 문장이 부끄러움을 머금은 모습을 잘 그려냈다.”', NULL),
    ('MLSGJJ01YU003H043', '평비_이생규장전_필사본_한국 고려대학교_두주_043', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “文能盡兒女之情. 才女雖才, 恐不能如此委曲矣. 近世曲亭馬琴戱著中, 時見此等之妙”', '호산이 말한다: “글이 아녀자의 마음을 잘 표현했다. 재녀(才女)가 비록 재주가 있다고 한들 아마 이처럼 곡진할 수는 없을 것이다. 최근 곡정마금(曲亭馬琴)의 희저(戱著) 가운데 간혹 이러한 오묘함을 볼 수 있다.”', NULL),
    ('MLSGJJ01YU003H044', '평비_이생규장전_필사본_한국 고려대학교_두주_044', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“千作平如何?”', '“‘천(千)’을 ‘평(平)’으로 짓는 것은 어떠한가?”', NULL),
    ('MLSGJJ01YU003H045', '평비_이생규장전_필사본_한국 고려대학교_두주_045', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “賢爺! 賢爺!”', '중주가 말한다: “어진 아버지로다. 어진 아버지로다!”', NULL),
    ('MLSGJJ01YU003H046', '평비_이생규장전_필사본_한국 고려대학교_두주_046', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “何持操之確也?”', '중주가 말한다. “얼마나 지조가 확고한가?”', NULL),
    ('MLSGJJ01YU003H047', '평비_이생규장전_필사본_한국 고려대학교_두주_047', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “死灰再燃.”', '중주가 말한다. “죽었던 재가 다시 타오르는구나.”', NULL),
    ('MLSGJJ01YU003H048', '평비_이생규장전_필사본_한국 고려대학교_두주_048', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “詞意沈實眞摯, 不類當初放縱語氣, 可嘉.”', '호산이 말한다. “말의 뜻이 침착하고 진실해 애초에 방종했던 어투와 같지 않아 가상하다.”', NULL),
    ('MLSGJJ01YU003H049', '평비_이생규장전_필사본_한국 고려대학교_두주_049', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “二喜.”', '중주가 말한다. “두 번째 기쁨이로다.”', NULL),
    ('MLSGJJ01YU003H050', '평비_이생규장전_필사본_한국 고려대학교_두주_050', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “世間野合, 何有此禮? 父母勸學之効, 𦤺此乎?”', '중주가 말한다. “세간의 야합한 부부에게 어찌 이러한 예절이 있겠는가? 부모가 배움을 권한 효험이 이렇게 한 것인가?“', NULL),
    ('MLSGJJ01YU003H051', '평비_이생규장전_필사본_한국 고려대학교_두주_051', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“辛丑年云云, 高麗恭愍王十年, 我正平十六年. 紅頭賊, 僞平章事, 潘誠, 沙劉, 關先生, 朱元帥等”', '신축년(辛丑年)을 운운한 것은 고려 공민왕 10년이며, 우리 정평(正平) 16년이다. 홍두적(紅頭賊)은 위평장사(僞平章事)인 반성(潘誠)·사유(沙劉)·관선생(關先生)·주원수(朱元帥) 등이다.', NULL),
    ('MLSGJJ01YU003H052', '평비_이생규장전_필사본_한국 고려대학교_두주_052', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“十餘萬衆, 自遼東來侵, 遂陷京城, 王避於福州, 福州今安東.”', '10여만의 무리가 요동(遼東)으로부터 와서 침략하니, 마침내 경성(京城)을 함락시켰고 공민왕은 복주(福州)로 피난했다. 복주는 지금의 안동(安東)이다.', NULL),
    ('MLSGJJ01YU003H053', '평비_이생규장전_필사본_한국 고려대학교_두주_053', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “鳴呼! 惜哉! 慘哉!”', '중주가 말한다. “아아! 애석하도다! 참혹하도다!”', NULL),
    ('MLSGJJ01YU003H054', '평비_이생규장전_필사본_한국 고려대학교_두주_054', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “貞烈可稱, 所謂丈夫意氣者, 非誇言也.”', '호산이 말한다. “정열(貞烈)이 칭송할 만하니 ‘장부의기(丈夫意氣)’라고 한 말이 과장된 말이 아니었구나.”', NULL),
    ('MLSGJJ01YU003H055', '평비_이생규장전_필사본_한국 고려대학교_두주_055', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “二悲”', '중주가 말한다. “두 번째 슬픔이로다.”', NULL),
    ('MLSGJJ01YU003H056', '평비_이생규장전_필사본_한국 고려대학교_두주_056', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “隂風颯然, 毛髪將竪.”', '중주가 말한다. “음산한 바람이 쓸쓸히 불어오니 머리카락이 곤두서는구나.”', NULL),
    ('MLSGJJ01YU003H057', '평비_이생규장전_필사본_한국 고려대학교_두주_057', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “叙情之言, 痛切甚于病中之語, 文筆之妙, 何能至于此耶?”', '호산이 말한다. “마음을 서술한 말이 병중의 한 말보다 더욱 통절하니, 문장과 필치의 오묘함이 어찌 이런 경지까지 이를 수 있었는가?”', NULL),
    ('MLSGJJ01YU003H058', '평비_이생규장전_필사본_한국 고려대학교_두주_058', '두주(頭註)', '[未詳]', '이생규장전', '李生窺牆傳', '일본 내각문고', '“顚作塡如何?”', '‘전(顚)’을 ‘전(塡)’으로 하는 것이 어떠한가?', NULL),
    ('MLSGJJ01YU003H059', '평비_이생규장전_필사본_한국 고려대학교_두주_059', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “叙情之言, 百誦不壓.”', '중주가 말한다. “마음을 서술한 말이 백 번을 암송해도 싫증 나지 않는다.”', NULL),
    ('MLSGJJ01YU003H060', '평비_이생규장전_필사본_한국 고려대학교_두주_060', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “三喜.”', '중주가 말한다. “세 번째 기쁨이다.”', NULL),
    ('MLSGJJ01YU003H061', '평비_이생규장전_필사본_한국 고려대학교_두주_061', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “孝子孝婦.”', '중주가 말한다. “효자와 효부로다.”', NULL),
    ('MLSGJJ01YU003H062', '평비_이생규장전_필사본_한국 고려대학교_두주_062', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “三悲”', '중주가 말한다. “세 번째 슬픔이다.”', NULL),
    ('MLSGJJ01YU003H063', '평비_이생규장전_필사본_한국 고려대학교_두주_063', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “悲喜循環, 人間常態, 豈惟李崔兩家?”', '중주가 말한다. “슬픔과 기쁨이 반복되는 것은 인간 세상의 늘 있는 모습이니 어찌 이씨와 최씨 두 집안뿐이겠는가?”', NULL),
    ('MLSGJJ01YU003H064', '평비_이생규장전_필사본_한국 고려대학교_두주_064', '두주(頭註)', '장매외(長梅外)', '이생규장전', '李生窺牆傳', '일본 내각문고', '梅外曰: “此詞絕佳.”', '매외가 말한다. “이 가사는 매우 아름답구나.”', NULL),
    ('MLSGJJ01YU003H065', '평비_이생규장전_필사본_한국 고려대학교_두주_065', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “悲風吹地, 悽氣襲人.”', '호산이 말한다. “슬픈 바람이 땅에 불고 처량한 기운이 사람에게 스미는구나.”', NULL),
    ('MLSGJJ01YU003H066', '평비_이생규장전_필사본_한국 고려대학교_두주_066', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “情死, 卽義死.”', '중주가 말한다. “정(情)을 위해 죽는 것이 곧 의(義)를 위해 죽는 것이다.”', NULL),
    ('MLSGJJ01YU003H067', '평비_이생규장전_필사본_한국 고려대학교_두주_067', '두주(頭註)', '호산(湖山)', '이생규장전', '李生窺牆傳', '일본 내각문고', '湖山曰: “全篇, 發于情, 止于禮義, 作者勸懲之意, 深矣.”', '호산이 말한다. “전편이 정(情)에서 발현되어 예의(禮義)에서 그쳤으니 작자가 권선징악의 뜻이 깊도다.”', NULL),
    ('MLSGJJ01YU003H068', '평비_이생규장전_필사본_한국 고려대학교_두주_068', '두주(頭註)', '중주(中洲)', '이생규장전', '李生窺牆傳', '일본 내각문고', '中洲曰: “以一義字, 結全篇, 好夫可以瞑矣.”', '중주가 말한다. “‘의(義)’ 한 글자로 전편을 맺었으니 좋구나! 이제 좋은 남편이 눈을 감아도 되겠도다.”', NULL),
    ('MJS01NU001P001', '평비_조신_목판본_한국 규장각한국학연구원_협주_001', '협주(夾註)', '[未詳]', '조신', '調信', '한국 규장각한국학연구원', '今興敎寺也.', '지금의 흥교사(興敎寺)다', NULL),
    ('MJS01NU001P002', '평비_조신_목판본_한국 규장각한국학연구원_협주_002', '협주(夾註)', '[未詳]', '조신', '調信', '한국 규장각한국학연구원', '按地理志, 溟州無㮈李郡, 唯有㮈城郡, 本㮈生郡, 今寧越. 又牛首州領縣, 有㮈靈郡, 本㮈已郡, 今剛州. 牛首州, 今春州. 今言㮈李郡, 未知孰是.', '지리지를 살펴보면 명주에는 날리군(㮈李郡)이 없고 오직 날성군(㮈城郡)만 있으니 원래는 날생군(㮈生郡)으로 지금의 영월(寧越)이다. 또한 우수주(牛首州) 영현(領縣)에 날령군(㮈靈郡)이 있는데 원래는 날이군(㮈已郡)으로 지금의 강주(剛州)다. 우수주(牛首州)는 지금은 춘주(春州)인데 지금 날리군이라고 말했으니 누가 옳은지 알지 못하겠다.', NULL),
    ('MJS01NU001P003', '평비_조신_목판본_한국 규장각한국학연구원_협주_003', '협주(夾註)', '[未詳]', '조신', '調信', '한국 규장각한국학연구원', '今羽谿縣也.', '지금의 우계현(羽谿縣)이다', '谿 : 원본에는 없음'),
    ('MCYPPJG01YU001H001', '평비_취유부벽정기_목판본_일본 내각문고_두주_001', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '亭, 今作樓', NULL, NULL),
    ('MCYPPJG01YU001H002', '평비_취유부벽정기_목판본_일본 내각문고_두주_002', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '平壤, 在平安道. 錦繡山, 平壤府北山名. 鳳凰臺, 在平壤府南. 綾羅島, 在平壤府下大同江中. 麒麟窟, 上同. 朝天石, 上同. 高句麗始祖朱蒙古跡.', NULL, NULL),
    ('MCYPPJG01YU001H003', '평비_취유부벽정기_목판본_일본 내각문고_두주_003', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "此篇欲以詩句見巧, 故起手整整用記文正格, 亦一作法."', NULL, NULL),
    ('MCYPPJG01YU001H004', '평비_취유부벽정기_목판본_일본 내각문고_두주_004', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "先揭浮碧亭."', NULL, NULL),
    ('MCYPPJG01YU001H005', '평비_취유부벽정기_목판본_일본 내각문고_두주_005', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '楸南墟, 上同. 永明寺, 在平壤城隅. 浮碧樓, 在永明寺前. 東明王, 高句麗王朱蒙也. 我崇神天皇, 六十一年, 九梯宮, 朱蒙之居宮. 大同門, 平壤府城南門.', NULL, NULL),
    ('MCYPPJG01YU001H006', '평비_취유부벽정기_목판본_일본 내각문고_두주_006', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "十里殊簾, 半上鉤."', NULL, NULL),
    ('MCYPPJG01YU001H007', '평비_취유부벽정기_목판본_일본 내각문고_두주_007', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "詩境仙境, 寫來如畵, 畵手却不能及."', NULL, NULL),
    ('MCYPPJG01YU001H008', '평비_취유부벽정기_목판본_일본 내각문고_두주_008', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "讀者亦凜然, 如入仙境."', NULL, NULL),
    ('MCYPPJG01YU001H009', '평비_취유부벽정기_목판본_일본 내각문고_두주_009', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '柳磯, 平壤城下大同江邊.', NULL, NULL),
    ('MCYPPJG01YU001H010', '평비_취유부벽정기_목판본_일본 내각문고_두주_010', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '天順, 明英宗復位年號. 我後花園帝長祿二年. 松京, 同松都. 浿江, 亭在平安道浿江畔.', NULL, NULL),
    ('MCYPPJG01YU001H011', '평비_취유부벽정기_목판본_일본 내각문고_두주_011', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "殷墟二字不泛."', NULL, NULL),
    ('MCYPPJG01YU001H012', '평비_취유부벽정기_목판본_일본 내각문고_두주_012', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "首首俯仰感慨, 悲壯淋漓, 懷古上乘."', NULL, NULL),
    ('MCYPPJG01YU001H013', '평비_취유부벽정기_목판본_일본 내각문고_두주_013', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "不讓劉禹錫西塞山懷古詩."', NULL, NULL),
    ('MCYPPJG01YU001H014', '평비_취유부벽정기_목판본_일본 내각문고_두주_014', '두주(頭註)', '장매외(長梅外)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '梅外曰: "佳聯."', NULL, NULL),
    ('MCYPPJG01YU001H015', '평비_취유부벽정기_목판본_일본 내각문고_두주_015', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '檀君, 姓桓名王儉, 唐堯戊辰廿五年, 卽朝鮮王位.', NULL, NULL),
    ('MCYPPJG01YU001H016', '평비_취유부벽정기_목판본_일본 내각문고_두주_016', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "起手雋爽, 有浿江之水, 一瀉千里概."', NULL, NULL),
    ('MCYPPJG01YU001H017', '평비_취유부벽정기_목판본_일본 내각문고_두주_017', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "說到中秋, 女蘿有綠流彩照衣, 感動仙娥, 其必在于此乎."', NULL, NULL),
    ('MCYPPJG01YU001H018', '평비_취유부벽정기_목판본_일본 내각문고_두주_018', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "雄偉可誦."', NULL, NULL),
    ('MCYPPJG01YU001H019', '평비_취유부벽정기_목판본_일본 내각문고_두주_019', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '隋家, 云云. 隋煬帝八年, 親帥六師征高句麗, 而不勝.', NULL, NULL),
    ('MCYPPJG01YU001H020', '평비_취유부벽정기_목판본_일본 내각문고_두주_020', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "聯翩得佳詩, 撫掌自賞, 豈得已乎?"', NULL, NULL),
    ('MCYPPJG01YU001H021', '평비_취유부벽정기_목판본_일본 내각문고_두주_021', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "仙境果逢, 仙妹驚喜可知."', NULL, NULL),
    ('MCYPPJG01YU001H022', '평비_취유부벽정기_목판본_일본 내각문고_두주_022', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '神護寺, 平壤古寺.', NULL, NULL),
    ('MCYPPJG01YU001H023', '평비_취유부벽정기_목판본_일본 내각문고_두주_023', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "天仙威儀, 不可近, 避之墻隙, 亦是人情."', NULL, NULL),
    ('MCYPPJG01YU001H024', '평비_취유부벽정기_목판본_일본 내각문고_두주_024', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "在墻隙聞此語, 神情如何."', NULL, NULL),
    ('MCYPPJG01YU001H025', '평비_취유부벽정기_목판본_일본 내각문고_두주_025', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "小警咳, 妙妙"', NULL, NULL),
    ('MCYPPJG01YU001H026', '평비_취유부벽정기_목판본_일본 내각문고_두주_026', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "不之甚敬, 終是天仙威儀."', NULL, NULL),
    ('MCYPPJG01YU001H027', '평비_취유부벽정기_목판본_일본 내각문고_두주_027', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "果非人間."', NULL, NULL),
    ('MCYPPJG01YU001H028', '평비_취유부벽정기_목판본_일본 내각문고_두주_028', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "仙几應接處, 寫出亦奇."', NULL, NULL),
    ('MCYPPJG01YU001H029', '평비_취유부벽정기_목판본_일본 내각문고_두주_029', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '酒巖, 在平壤城外江邊."', NULL, NULL),
    ('MCYPPJG01YU001H030', '평비_취유부벽정기_목판본_일본 내각문고_두주_030', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "和詩雖妙, 似讓原作."', NULL, NULL),
    ('MCYPPJG01YU001H031', '평비_취유부벽정기_목판본_일본 내각문고_두주_031', '두주(頭註)', '장매외(長梅外)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '梅外曰: "眞女士之語也."', NULL, NULL),
    ('MCYPPJG01YU001H032', '평비_취유부벽정기_목판본_일본 내각문고_두주_032', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "情致芊綿, 天仙詩亦帶兒女氣."', NULL, NULL),
    ('MCYPPJG01YU001H033', '평비_취유부벽정기_목판본_일본 내각문고_두주_033', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "唱和旣訖, 忽又說起一塲奇話, 筆下湧泉, 無竭."', NULL, NULL),
    ('MCYPPJG01YU001H034', '평비_취유부벽정기_목판본_일본 내각문고_두주_034', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '先考者, 謂箕子孫王準. 後被逼衛滿, 浮海而奔于韓.', NULL, NULL),
    ('MCYPPJG01YU001H035', '평비_취유부벽정기_목판본_일본 내각문고_두주_035', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '衛滿, 燕人. 漢高祖時, 遂王準而自立.', NULL, NULL),
    ('MCYPPJG01YU001H036', '평비_취유부벽정기_목판본_일본 내각문고_두주_036', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "架空奇想."', NULL, NULL),
    ('MCYPPJG01YU001H037', '평비_취유부벽정기_목판본_일본 내각문고_두주_037', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "說神仙秘訣, 如話尋常家事, 亦奇亦妙."', NULL, NULL),
    ('MCYPPJG01YU001H038', '평비_취유부벽정기_목판본_일본 내각문고_두주_038', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "愈進愈奇."', NULL, NULL),
    ('MCYPPJG01YU001H039', '평비_취유부벽정기_목판본_일본 내각문고_두주_039', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "四十韻, 蓋其得意作, 然不如亭下所作六律之妙也."', NULL, NULL),
    ('MCYPPJG01YU001H040', '평비_취유부벽정기_목판본_일본 내각문고_두주_040', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "玉彩爛然, 似雲錦裳."', NULL, NULL),
    ('MCYPPJG01YU001H041', '평비_취유부벽정기_목판본_일본 내각문고_두주_041', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '木覓山, 今京城漢陽府南山. 溝婁, 箕氏時郡名. 肅愼, 今北道."', NULL, NULL),
    ('MCYPPJG01YU001H042', '평비_취유부벽정기_목판본_일본 내각문고_두주_042', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "未盡情款, 其情尤深."', NULL, NULL),
    ('MCYPPJG01YU001H043', '평비_취유부벽정기_목판본_일본 내각문고_두주_043', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "凄婉欲絶."', NULL, NULL),
    ('MCYPPJG01YU001H044', '평비_취유부벽정기_목판본_일본 내각문고_두주_044', '두주(頭註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '平壤城門曰: "長慶."', NULL, NULL),
    ('MCYPPJG01YU001H045', '평비_취유부벽정기_목판본_일본 내각문고_두주_045', '두주(頭註)', '호산(湖山)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '湖山曰: "此段余欲刪其後云云三十二字."', NULL, NULL),
    ('MCYPPJG01YU001H046', '평비_취유부벽정기_목판본_일본 내각문고_두주_046', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "才士多情."', NULL, NULL),
    ('MCYPPJG01YU001H047', '평비_취유부벽정기_목판본_일본 내각문고_두주_047', '두주(頭註)', '중주(中洲)', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '中洲曰: "生死而不死, 始結仙緣."', NULL, NULL),
    ('MCYPPJG01YU001H048', '평비_취유부벽정기_목판본_일본 내각문고_할주_001', '협주(夾註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '寺, 羅漢像在處.', NULL, NULL),
    ('MCYPPJG01YU001H049', '평비_취유부벽정기_목판본_일본 내각문고_할주_002', '협주(夾註)', '[未詳]', '취유부벽정기', '醉遊浮碧亭記', '일본 내각문고', '巖下, 有湫龍在處.', NULL, NULL);
INSERT INTO "comment" ("id", "name", "c_type", "work_kor", "work_chi", "target_book", "original_text", "translation", "notes") VALUES
    ('CGRJ01NU00401', '논평_강로전_한국 국사편찬위원회_001_종결평_01', '종결평', '강로전', '姜虜傳', '한국 국사편찬위원회', '噫! 緇流尙不負其主, 吠堯之賊, 反出於衣冠世族, 何哉? 通天之罪, 曠古之兇, 所可道也, 言之長也. 崇禎庚午秋, 無言子記.', '아! 승려의 무리도 오히려 그 주인을 저버리지 않는데 요임금을 향해 짖는 도적이 도리어 의관을 갖춘 세족 집안에서 나온 것은 어째서인가? 하늘을 덮을 만한 죄와 천고에 없는 흉악함을 저질렀으므로 말할 게 많아 글이 길어졌다. 숭정 경오년 가을에 무언자가 쓰다.', NULL),
    ('CGRJ01NU00601', '논평_강로전_한국 사천목씨 종친회 유물관_001_종결평_01', '종결평', '강로전', '姜虜傳', '한국 사천목씨 종친회 유물관', '噫! 緇流尙不負其主, 吠堯之賊, 反出於衣冠世族, 何哉? 通天之罪, 曠古之兇, 所可道也, 言之長也. 崇禎庚午秋月日, 無言子記.', '아! 승려의 무리도 오히려 그 주인을 저버리지 않는데 요임금을 향해 짖는 도적이 도리어 의관을 갖춘 세족 집안인 것은 어째서인가? 하늘을 덮을 만한 죄와 천고에 없는 흉악함을 저질렀으므로 말할 게 많아 글이 길어졌다. 숭정 경오년 가을에 무언자가 쓰다.', '吠堯之賊 : 원본에는 吠主之賊'),
    ('CGRJ01NU00701', '논평_강로전_한국 이길환_001_종결평_01', '종결평', '강로전', '姜虜傳', '한국 이길환', '噫! 緇流尙不負其主, 吠主之賊, 衣冠世族, 何哉? 通天之罪, 曠古之兇, 所可道哉, 言之長也. 崇禎庚午秋, 無言子記.', '아! 승려의 무리도 오히려 그 주인을 저버리지 않는데 요임금을 향해 짖는 도적이 도리어 의관을 갖춘 세족 집안에서 나온 것은 어째서인가? 하늘을 덮을 만한 죄와 천고에 없는 흉악함을 저질렀으므로 말할 게 많아 글이 길어졌다. 숭정 경오년 가을 모월 모일에 무언자가 쓰다.', NULL),
    ('CGHGH01YU00101', '논평_김현감호_한국 고려대학교_001_종결평_01', '종결평', '김현감호', '金現感虎', '한국 고려대학교', '噫! 澄現二公之接異物也, 變爲人妾, 則同矣, 而贈背人詩, 然後哮吼拏攫而走, 與現之虎異矣. 現之虎, 不得已而傷人, 然善誘良方, 以救人. 獸有爲仁如彼者, 今有人而不如獸者. 何哉? 詳觀事之終始, 感人於旋遶佛寺中, 天唱徵惡. 以自代之, 傳神方以救人, 置精廬講佛戒. 非徒獸之性仁者也, 蓋大聖應物之多方, 感現公之能致精於旋遶, 欲報冥益耳. 宜其當時能受禧佑乎', '슬프구나! 신도징과 김현 두 사람이 이물을 접했을 때 호랑이가 변해 사람의 아내가 된 것은 똑같으나 인간 세상을 저버리는 시를 준 다음 포효하고 움퀴고 할퀴다가 달아났으니 김현의 호랑이와는 다르다. 김현의 호랑이는 어쩔 수 없이 사람을 다치게 했으나 좋은 처방을 알려주어 사람을 도왔다. 짐승인데도 인(仁)을 행함이 저와 같은 자가 있는데 지금은 사람인데도 짐승보다 못한 자가 있는 것은 무엇 때문인가? 이 사적의 전말을 자세히 살펴보면 김현의 호랑이는 사찰에서 탑돌이를 하던 중에 사람과 교감하였고, 하늘이 악행을 징계한다고 소리치자 자신으로써 이를 대신했으며 신효한 처방을 전하여 사람을 구했고 절을 세워 불계(佛戒)를 강설하게 했다. 이는 단지 짐승의 본성이 어진 자일 뿐만 아니라 대개 대성(大聖:관음보살)이 만물에 여러 방면으로 감응한 것이니, 김현이 지성으로 탑돌이를 할 수 있었던 것에 감동하여 명익(冥益)을 갚고자 한 것이다. 당시 복을 받을 수 있었던 것이 마땅하도다.', NULL),
    ('CGHGH01YU00102', '논평_김현감호_한국 고려대학교_001_최종평_01', '최종평', '김현감호', '金現感虎', '한국 고려대학교', '讚曰 : “山家不耐三兄惡, 蘭吐那堪一諾芳. 義重數條輕萬死, 許身林下落花忙.”', '다음과 같이 찬한다. “산가(山家)는 세 오빠의 죄악을 견딜 수 없는데, 어찌 난초가 내뿜는 꽃다운 승낙을 견디겠는가. 의리의 소중함 몇 가지에 만 번 죽음은 가벼워, 수풀 아래 스스로 희생했으니 낙화처럼 졌구나.”', NULL),
    ('CGN01NU00101', '논평_검녀_일본 동양문고_001_종결평_01', '종결평', '검녀', '劍女', '일본 동양문고', '嗟呼! 女子之爲人隷, 而尙能自珍其身, 不忍輕委於凡夫, 況於鴻儒奇士而不擇所從, 如孔鮒之於陳陟, 鮑永之於劉玄, 獨何意哉!', '아아! 남의 종인 여자도 오히려 자신의 몸을 소중히 여겨 평범한 사내에게 가벼이 몸을 허락하지 않았는데 더구나 명망 있는 선비나 기이한 인재로서 자신이 따라야 할 군주를 가리지 아니하는 자들 가령 공부(孔鮒)가 진승(陳勝)을 따르고 포영(鮑永)이 유현(劉玄)을 따른 것처럼 하는 경우는 유독 무슨 생각인가?', NULL),
    ('CGSJ01NU00101', '논평_검승전_한국 국립중앙도서관_001_최종평_01', '최종평', '검승전', '劍僧傳', '한국 국립중앙도서관', '外史氏曰: “劒師, 俠而隱者乎? 當壬辰之難, 草埜勇■■如洪季男、金應瑞輩, 多奮起捍賊, 立奇功。劒師伏而弗出, 不欲以功名自顯, 何哉? 彼有異術, 誠知壬辰之變, 天數也, 非區區智力可弭。自古智勇異能之士, 多不免, 小國尤甚焉。雖以國朝言之, 南怡金德齡, 皆是已. 故劒師寧老死嵁巖而弗悔也. 豈世傳二子所遇白頭隱者, 草衣客之流也歟? 至若不言其姓名, 尤奇矣哉! 然劒師與二倭處十數年, 亦可以知心術矣. 一爲賊, 一爲子, 而肘腋之, 卒以其道授賊自戕, 明於保身, 闇於知人, 殆所謂:‘單豹養內, 虎食其外’者邪? 故孟子曰: ‘羿亦有罪焉.’ 抑五臺老僧, 夷狄而奇男子也夫!”', NULL, NULL),
    ('CGGRGUG01NU00101', '논평_곡강루기우기_한국 단국대학교_001_최종평_01', '최종평', '곡강루기우기', '曲江樓奇遇記', '한국 단국대학교', '余雖不學, 亦有感於此事, 辭不獲已. 詳敍其顚末, 以取一時之笑資. 觀者, 勿以凡文. 其可有補焉爾.', '내가 비록 배움이 없으나 또한 이 일에 감히가 있어 사양하려 해도 그만둘 수 없었다. 이에 그 전말을 상세히 서술해 한때의 웃음거리로 삼고자 했다. 보는 이들은 이를 평범한 글이라 여기지 말라. 아마 보탬이 되는 점이 있을 것이다.', NULL),
    ('CGPIJ01NU00201', '논평_관부인전_한국 고려대학교_002_최종평_01', '최종평', '관부인전', '灌夫人傳', '한국 고려대학교', '史臣曰: “夫人之德, 其至矣乎! 溫潤之性, 能使人心歸向; 生殺之權, 能與春秋匹美. 開闔則順陰陽之理, 含忍則有容物之度, 其他承乾生成之德, 有不可殫記. 後有人作夫人小池詩一絶曰: ‘兩脚山中有小池, 池南池北草離離. 無風白浪翻天起, 一目朱龍出入時.’ 亦可謂記實也.”', NULL, NULL),
    ('CGPIJ01NU00202', '논평_관부인전_한국 고려대학교_002_최종평_02', '최종평', '관부인전', '灌夫人傳', '한국 고려대학교', '史臣曰: “夫人之德, 其至矣! 溫潤之性, 能使人心歸向; 生殺之權, 能與春秋匹美. 開闔則順陰陽之理, 含忍則有容物之度, 其他承乾生成之德, 有不可殫記. 後有人作夫人小池詩一絶曰: ‘兩脚山中有小池, 池南池北草離離. 無風白浪翻天起, 一目朱龍出入時.’ 亦可謂記實也.”', NULL, NULL),
    ('CGUM01NE00301', '논평_구운몽_한국 서강대학교_001_도입평_01', '도입평', '구운몽', '九雲夢', '한국 서강대학교', '天下名山, 曰有五焉 : 東曰:“東岳”, 即泰山, 西曰:“西岳”, 即華山, 南曰:“南岳”, 即衡山, 北曰:“北岳”, 即恒山, 中央之山曰:“中岳”, 即嵩山. 此所謂五岳也. 五岳之中, 惟衡山距中土最遠. 九疑之山在其南, 洞庭之湖經其北, 湘江之水環其三面. 若祖宗儼然中處, 而子孫羅立而拱揖焉. 七十二峰, 或騰踔而矗天, 或嶄㠔而截雲. 如奇標俊彩之美丈夫, 七竅八骸皆秀麗淸爽, 無非元氣所鍾也. 其中最高之峰, 曰:“祝融”,曰:“紫蓋”, 曰:“天柱”, 曰:“石廩”, 曰:“蓮花”五峰也. 其形擢竦, 其勢陟高, 雲掩其直面, 霞氣藏其半腹. 非天氣廓掃, 日光晴朗, 則人不能得其彷佛焉. 昔大禹氏治洪水登其上, 立石記功德, 天書雲篆, 歷千萬古而尙存. 秦時仙女衛夫人, 修練得道, 受上帝之職, 率童仙玉女, 來鎭此山, 即所謂:‘南岳衛夫人’也. 蓋自古昔以來, 靈異之跡, 環奇之事, 不可殫記.天下名山, 曰有五焉 : 東曰:“東岳”, 即泰山, 西曰:“西岳”, 即華山, 南曰:“南岳”, 即衡山, 北曰:“北岳”, 即恒山, 中央之山曰:“中岳”, 即嵩山. 此所謂五岳也. 五岳之中, 惟衡山距中土最遠. 九疑之山在其南, 洞庭之湖經其北, 湘江之水環其三面. 若祖宗儼然中處, 而子孫羅立而拱揖焉. 七十二峰, 或騰踔而矗天, 或嶄㠔而截雲. 如奇標俊彩之美丈夫, 七竅八骸皆秀麗淸爽, 無非元氣所鍾也. 其中最高之峰, 曰:“祝融”,曰:“紫蓋”, 曰:“天柱”, 曰:“石廩”, 曰:“蓮花”五峰也. 其形擢竦, 其勢陟高, 雲掩其直面, 霞氣藏其半腹. 非天氣廓掃, 日光晴朗, 則人不能得其彷佛焉. 昔大禹氏治洪水登其上, 立石記功德, 天書雲篆, 歷千萬古而尙存. 秦時仙女衛夫人, 修練得道, 受上帝之職, 率童仙玉女, 來鎭此山, 即所謂:‘南岳衛夫人’也. 蓋自古昔以來, 靈異之跡, 環奇之事, 不可殫記.', NULL, NULL),
    ('CGSJ07NU00101', '논평_김생전A_한국 박의영_001_도입평_01', '도입평', '김생전', '金生傳', '한국 박의영', '我東山水, 雄乎且奇, 而漢陽爲首, 虎踞龍蟠, 川岳秀麗, 南通北豁, 地氣雄靈, 故豪傑之客, 孕出於漢陽, 風流之輩, 不下於鹿頭', '우리 동방의 산천은 웅장하고 또한 기이하며 그 가운데 한양이 으뜸이다. 호랑이가 웅크리고 용이 서린 듯한 형세에 강과 산이 빼어나고 아름다우며, 남쪽으로는 통하고 북쪽으로는 트여 있어 땅의 기운이 웅장하고 신령하다. 그러므로 호걸과 인걸이 한양에서 태어나고, 풍류를 즐기는 무리는 녹두(鹿頭)의 인물들에 못지않다.', NULL),
    ('CNUAUG01NU00101', '논평_낙우애우기_한국 고려대학교_001_종결평_01', '종결평', '낙우애우기', '樂遇哀遇記', '한국 고려대학교', '憂樂之間, 摠是奇遇矣.', '근심과 기쁨 사이에 모두 기이한 만남이다.', NULL),
    ('CNUAUG01NU00102', '논평_낙우애우기_한국 고려대학교_001_최종평_01', '최종평', '낙우애우기', '樂遇哀遇記', '한국 고려대학교', '外史氏曰: “詩云: ‘娶妻如之何? 非媒不得.’ 以此觀之, 何嘗有媒而後娶妻乎? 非徒娶妻, 新榜槐名, 由此占得, 庸非天意而誰也? 雖然, 以若榮華, 終未得一日養於玆庭, 是爲郭子之大恨也.”', '외사씨가 말한다. “『시경(詩經)』에 ‘아내를 얻으려면 어떻게 해야 하는가? 중매가 아니면 얻을 수 없다.’라고 했으니 이를 통해 본다면 어찌 중매를 둔 다음에야만 아내를 얻을 수 있겠는가? 아내를 얻었을 뿐만 아니라 신방(新榜)에 합격자로 이름을 걸은 것도 이를 통해 차지한 것이니 하늘의 뜻이 아니고 무엇이겠는가? 비록 그렇지만 이러한 영화로움으로 끝내 하루도 모친을 봉양하지 못했으니 이것이 곽생의 큰 한이다.”', NULL),
    ('CNDYE01NE00101', '논평_낙동야언_한국 국립민속박물관_001_도입평_01', '도입평', '낙동야언', '洛東野言', '한국 국립민속박물관', '天下之岳五, 而嵩山在其一也, 以其爲天地之中, 故元氣之所鍾會也. 騰而爲祥雲瑞霧, 流而爲醴泉淸淵, 結而爲精金美玉. 於禽獸, 爲飛鳳走麟, 於草木, 靈芝杞梓, 故生於其間者, 每多奇偉魁傑之人, 若周之申甫, 唐之溫石, 是也.', '천하에는 다섯 개의 큰 산이 있는데, 숭산(嵩山)이 그중 하나로 천하의 중심이 되기에 원기(元氣)가 모여드는 곳이다. 그러므로 원기가 솟구치면 올라가 상서로운 구름과 길한 안개가 되고, 흐르면 달콤한 샘과 맑은 연못이 되며 맺히면 정채(精彩)난 금과 아름다운 옥이 된다. 금수(禽獸)들로 보자면 나는 봉황과 뛰는 기린이 되고 초목으로 보자면 영지(靈芝)와 기재(杞梓)가 된다. 그러므로 그곳에서 태어나는 사람은 특출나고 걸출한 사람이 항상 많으니, 주(周)의 신백(申伯)과 보후(甫侯)나 당(唐)의 온조(溫造)와 석홍(石洪)같은 이가 바로 그들이다.', NULL),
    ('CNHM01NE0010101', '논평_난학몽_천(天)_한국 정기방_001_도입평_01', '도입평', '난학몽', '鸞鶴夢', '한국 정기방', '積善之家, 必有餘慶. 子恭其職, 臣致其節, 婦盡其敬, 修善之道也. 是故忠孝之裔, 天資以福, 悖逆之人, 天降以殃, 善惡感應之理, 豈可誣哉?', '선을 쌓은 집안에는 반드시 자손에게까지 미치는 경사가 있는 법이다. 자식이 그 직분을 공경히 수행하고 신하가 절개를 다하며 아내가 공경함을 다 하는 것이 선을 닦는 도리이다. 그러므로 충신과 효자의 후손에게는 하늘이 복을 부여하고 도리를 거스르고 반역한 자에게는 하늘이 재앙을 내리니 선악에 감응하는 이치를 어찌 기만할 수 있겠는가?', NULL),
    ('CNGSSJ01NU00101', '논평_남궁선생전_한국 규장각한국학연구원_001_최종평_01', '최종평', '남궁선생전', '南宮先生傳', '한국 규장각한국학연구원', '許子曰: “傳言東人尙佛不尙道. 自羅逮鮮數千載, 未聞有一人得道仙去者. 其果徵哉? 然以余所覩南宮先生言之, 可異焉. 先生所師者果何人? 而得於相師者, 未必的然可信, 所悅亦未必盡然, 要之影響之間也. 但以先生年貌看之, 非眞能得道者耶? 那能八十而若是康健耶? 此又不可決以爲實無是事也. 噫! 其奇哉! 我國僻在海外之遐, 氣之士如羨門, 安期, 而巖石間乃有此異人. 累千百年, 俾先生一得遇之, 孰謂偏壤而無其人耶? 達道則仙, 昧道則凡. 傳所言者, 與耳食奚殊? 使先生毋望其速成, 卒收爐鼎之效, 則彼羨門安期, 亦何難拍肩而等夷之? 唯其不忍, 以敗垂成之功, 嗚呼惜哉!”', '허자는 논한다. “전하는 말에 ‘우리나라 사람들은 불교(佛敎)는 숭상했어도 도교(道敎)는 숭상하지 않았다.’라는 말이 있다. 신라 시대부터 조선(朝鮮)에 이르기까지 몇천 년이 지났으나 득도(得道)하여 신선되어 간 사람이 있음을 듣지 못했다. 그렇다면 전해오는 말이 과연 징험이 되는 말이랴. 그러나 내가 보았던 남궁 선생(南宮先生)으로 말한다면 이상할 수밖에 없다. 선생이 스승으로 여겼던 분은 과연 어떤 사람이고 상(相) 보는 사람에게 알아냈다는 것도 결코 확실히 믿을 만한 것은 못 되며, 말했던 것들도 역시 모두 그렇지만은 않으리라. 요컨대 그림자나 메아리 같은 실체 없는 소리라. 다만 선생의 나이와 용모로 본다면 참으로 득도(得道)할 수 있었던 사람이 아닐 것인지. 어찌하여 80의 나이이고도 그처럼 건강했으랴. 이건 또 도교 숭상하는 일이 실제로 없었다고 결정내릴 수도 없으리라. 아아, 그거야말로 기이하도다. 우리나라가 궁벽한 바다 밖 멀리에 있어 뛰어난 은사(隱士)로 선문자(羨門子)나 안기생(安期生)과 같은 분들이 드물었으나 암석(巖石)의 사이에 그러한 이인(異人)이 있어 여러 천백 년 만에 남궁 선생으로 하여금 만날 수 있게 하였으니 그 누가 ‘좁은 지역이니 그러한 인물이 없다.’라고 말하랴. 도(道)에 통달하면 신선이고 도에 몽매하면 범인이다. 전해진다는 말이 이식(耳食)과 무엇이 다르리오. 선생으로 하여금 빨리 이루려던 욕망이 없게 하여 끝내 단련하던 효과를 거둘 수 있게만 했다면 저들 선문자ㆍ안기생과 어깨를 맞대고 나란히 맞서기에 무슨 어려움이 있었으랴. 다만 그분이 찾아 내지 못하여 다 이루어진 공(功)을 실패하고 말았으니 오호, 애석하도다.”', NULL),
    ('CNRJ02NU00101', '논평_남령전_한국 국립한국문학관_001_최종평_01', '최종평', '남령전', '南靈傳', '한국 국립한국문학관', '花史氏曰: “昔韓慕廬菼, 與南烟及麴生, 爲忘形友. 人問: ‘二者不可兼, 當去何者?’ 韓公沈吟良久曰: ‘皆不可去. 若不獲已, 其去麴生乎!’ 至於烟, 有死不可去. 余於南君亦然, 於是爲立傳以紀. 或曰: ‘其先呂宋人’”', NULL, NULL),
    ('CNSJ01NU00101', '논평_내성지_한국 김종훈_001_종결평_01', '종결평', '내성지', '奈城誌', '한국 김종훈', '嗚呼! 異哉!', '아아! 기이하도다!', NULL),
    ('CNHPDDDPP01NU00101', '논평_남백월이성노힐부득달달박박_한국 규장각한국학연구원_001_종결평_01', '종결평', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '議曰: “娘, 可謂應以婦女身攝化者也. 華嚴經, 摩耶夫人善知識, 寄十一地, 生佛如幻解脫門, 今娘之桷産, 微意在此. 觀其投詞, 哀婉可愛, 宛轉有天仙之趣. 嗚呼! 使娘婆不解隨順衆生語言陁羅尼, 其能若是乎? 其末聯, 宜云: ‘淸風一榻莫予嗔.’ 然不爾云者, 盖不欲同乎流俗語爾.”', NULL, NULL),
    ('CNHPDDDPP01NU00202', '논평_남백월이성노힐부득달달박박_한국 규장각한국학연구원_001_최종평_01', '최종평', '남백월이성노힐부득달달박박', '南白月二聖 努肹夫得 怛怛朴朴', '한국 규장각한국학연구원', '讚曰: “滴翠嵓前剝啄聲, 何人日暮扣雲扃? 南庵且近宜尋去, 莫踏蒼苔汚我庭. 右北庵. 谷暗何歸已暝煙, 南窓有蕈且流連. 夜闌百八深深轉, 只恐成喧惱客眠. 右南庵. 十里松陰一徑迷, 訪僧來試夜招提. 三槽浴罷天將曉, 生下雙兒擲向西. 右聖娘.', NULL, NULL),
    ('CDCMYR02NU00101', '논평_달천몽유록_한국 평해황씨 해월종택_001_종결평_01', '종결평', '달천몽유록', '㺚川夢遊錄', '한국 평해황씨 해월종택', '嗚呼! 異哉!', '아아! 기이하도다!', NULL),
    ('CDGJMYR01NU00101', '논평_대관재몽유록_한국 계명대학교_001_종결평_01', '종결평', '대관재몽유록', '大觀齋夢遊錄', '한국 계명대학교', '噫! 人生於世, 窮達有數, 豈有覺夢兼之者? 咄怪而志夢, 時嘉靖八年季冬上澣也.', '아! 사람이 세상에 살아가면서 궁핍과 영달에 운수가 있으니 어찌 현실과 꿈을 함께 지닐 수 있겠는가? 괴이한 이이라며 혀를 끌끌차며 꿈을 기록하니 때는 가졍 8년 계동 상순이라.', NULL),
    ('CDGJMYR01NU00102', '논평_대관재몽유록_한국 계명대학교_001_최종평_01', '최종평', '대관재몽유록', '大觀齋夢遊錄', '한국 계명대학교', '敬書一絶. “寄生何地不爲虛, 十載南柯一夢餘. 萬事等觀皆可樂, 魚應知我我知魚.”', '삼가 절구 한 수를 쓰다. 기생하는 인생 어느 곳이든 허망하지 않으랴, 십 년 동안의 일도 남가일몽만 남았을 뿐이다. 만사를 평등하게 바라보면 모두 즐거울 수 있으니, 물고기도 나를 알고 나도 물고기를 아네.', NULL),
    ('CDMMSJGIGG01NU00101', '논평_대명명신장곽이공기_한국 고려대학교_001_종결평_01', '종결평', '대명명신장곽이공기', '大明名臣張郭二公記', '한국 고려대학교', '嗚呼! 普天之下, 率土之濱, 能盡其忠孝之道者, 足法於張·郭二相國, 而後可盡賢. 二相在家而孝達于家, 在朝而忠達于朝, 移孝爲忠, 其如斯乎! 富貴不可皆備, 而二公文武兼備, 忠孝具專, 身居王公之位, 以爲萬世之欽仰. 是所可求也, 宜若登天, 然大哉, 張公! 至哉, 郭公! 奮起朔方之布衣, 身摠國政, 今玆幾年, 有乱公平之, 無事公安之. 二公之忠孝, 盡書不記. 而自二公之後, 張氏郭氏盛於長安.', NULL, NULL),
    ('CMGH01NE00301', '논평_만강홍_연인본_한국 장서각_001_종결평_01', '종결평', '만강홍', '滿江紅', '한국 장서각', '嗚呼라 海上行人이 於焉此十年島民이로다 越鳥戀南ᄒᆞ고 胡馬嘶北ᄒᆞ니 人胡不歸', '아! 바다 위의 행인이 어느덧 10년 동안의 섬 주민이 되었구나. 남쪽에서 날아온 새는 남쪽을 그리워하고(戀南), 북쪽 지방의 말은 북쪽을 향해 울부짖으니 사람이 어찌 돌아가지 않겠는가?', NULL),
    ('CMOMYR01NU00101', '논평_만옹몽유록_한국 국립중앙도서관_001_종결평_01', '종결평', '만옹몽유록', '謾翁夢遊錄', '한국 국립중앙도서관', '遂吟曰: "一自飮仙酒, 身輕眼又明. 從知吾夢信, 豈曰構虛成."', '마침내 이렇게 읊조렸다. "한번 신선의 술을 마신 뒤로, 몸이 가벼워지고 눈 또한 밝아지네. 이로부터 내 꿈이 참됨을 알겠으니 어찌 허황되게 얽었다고 하겠는가?"', NULL),
    ('CMYDHR01NU00101', '논평_몽유동해록_한국 국립중앙도서관_001_종결평_01', '종결평', '몽유동해록', '夢遊東海錄', '한국 국립중앙도서관', '嗚呼, 世間得失皆如此夢, 雖有一名之成, 與夢麗者, 何異哉. 況窮達有數, 富貴在天, 余何慽慽於心乎. 都將得失歸之於夢, 而孜孜矻矻, 篤志力學, 以待其時可矣. 夫豈若小丈夫然而悻悻爲哉.', '아아! 세상의 득실은 모두 이 꿈과 같으니 비록 명예를 이룬다고 한들 꿈속의 화려함과 무엇이 다르겠는가? 더구나 궁핍하고 영달하는 것은 운수에 달려 있고 부귀는 하늘에 달려 있는데 내 어찌 마음 속으로 근심한단 말인가? 모두 득실을 꿈으로 돌려버리고 부지런히 매진해 뜻을 독실히 다지고 학문에 힘써 때를 기다리는 것이 좋을 것이다. 어찌 소인배들과 같이 안달복달하겠는가?', NULL),
    ('CMOJ01NU00101', '논평_민옹전_한국 규장각한국학연구원_001_종결평_01', '종결평', '민옹전', '閔翁傳', '한국 규장각한국학연구원', '余誄閔翁曰: “嗚呼閔翁. 可怪可奇, 可驚可愕, 可喜可怒, 而又可憎. 壁上烏, 未化鷹, 翁蓋有志士, 竟老死莫施. 我爲作傳, 嗚呼死未曾.”', NULL, NULL),
    ('CPTPJ01NU00201', '논평_박태보전_한국 국립목포대학교_001_종결평_01', '종결평', '박태보전', '朴泰輔傳', '한국 국립목포대학교', '嗚呼! 自古人臣之抗言殺身何限? 而至於荐酷刑, 遍身焦爛, 而神色不變, 辞氣從容, 守正𥁞節, 始終如一, 如朴應敎者, 求之千百年, 不過數人. 皇明之方孝儒, 我朝之朴彭年, 成三問等六臣而己矣. 噫! 若數子者, 眞可謂烈丈夫. 苟非禀得天地之正氣, 氷玉其心, 鉄石其膓, 照如日星, 凜若雪霜, 蹈昇鑊而不屈, 膏鈇鉞而不悔者, 其何能乃甭? 且以数子論之, 事之難易, 人之優劣, 有難容易言之, 而應校所遭之惨功, 所處之雍容, 尤有所難及者耳. 嗚呼! 斯人也, 豈獨一節一行而已? 觀其急劇應對之際, 操履敦礭, 義理停當, 則可知其得力於道學者, 固非淺尠. 豈但止於殺身成仁而已哉? 同䟽諸人, 皆無臨苟免之意, 而李參判乃欲以身自當,以濟應校之死. 所謂其争也君子, 其亦賢乎哉?', NULL, NULL),
    ('CPTPJ01NU00202', '논평_박태보전_한국 국립목포대학교_001_종결평_02', '종결평', '박태보전', '朴泰輔傳', '한국 국립목포대학교', '詩曰: “一介貞忠朴士元, 精神不逐形骸㓕. 堂堂大義正乾坤, 化作星辰萬古存.”', NULL, NULL),
    ('CPTPJ01NU00401', '논평_박태보전_한국 국립중앙도서관_002_종결평_01', '종결평', '박태보전', '朴泰輔傳', '한국 국립중앙도서관', '嗟呼! 痛哉! 嗟呼! 痛哉! 朴士元判書, 世經之第二子, 世球之養子也. 生于甲午之歲, 娶李相國前室女, 而以乙卯進仕, 中丁巳第壯, 位於朝官顯矣. 門戶赫赫, 聲名藉藉, 而事親竭力, 誠孝無間, 事君致身, 精忠貫日, 古往今來如子者, 惜乎! 閨中殿出宮之時, 犯顏直諫, 竟至於死, 疾風勁草, 歲寒松柏. 嗚呼! 惜哉！', NULL, NULL),
    ('CPUSWCGYR01NU00101', '논평_백운선완춘결연록_한국 박노춘_001_종결평_01', '종결평', '백운선완춘결연록', '白雲仙翫春結緣錄', '한국 박노춘', '吁! 可惜哉! 豈不美哉?', '아! 애석하구나! 어찌 아름답지 않은가?', NULL),
    ('CSHJ02YU01201', '논평_비평숙향전_한국 단국대학교_001_종결평_01', '종결평', '비평숙향전', '批評淑香傳', '한국 단국대학교', '嗚呼! 異哉！', '아아! 기이하도다!', NULL),
    ('CYRWYHG01YU00302', '논평_비평신증요로원기_일본 천리대학교_001_도입평_01', '도입평', '비평신증요로원기', '批評新增要路院記', '일본 천리대학교', '陳談不足, 以消晷, 蔓辭不足, 以遣悶, 却從一場眞境界, 喚做出新奇話說. 〔唱起數句, 括得題目, 甚奇.〕 凡求馬者, 必之伯樂之厩, 那伯樂死, 而良馬有焉, 求玉者, 必之卞和之肆, 卞和去而, 嘉玉存焉. 求人之道, 便一樣子, 語賢於巖廊之上, 論才於簮紳之列, 尙矣. 這個隱草野, 而被布褐者, 貌不揚而優優, 有布政之才,〔一篇肯綮.〕 文不著而彬彬, 有煥獻之譽. 【上一節, 應身短無髥, 下一節應粗識彦文.】 他見如此輩而, 侮笑之者, 眞無目者也. 【封堂先入者, 目育耶.】 眷我錦江, 〔人傑地靈.〕 以西幾十州便是士夫之窟巣, 人才之府庫. 不翅伯樂之厩, 卞和之肆也.〔回龍顧祖法.〕', NULL, NULL),
    ('CYHSSJ01NU00101', '논평_빙호선생전_한국 국립중앙도서관_001_최종평_01', '최종평', '빙호선생전', '氷壺先生傳', '한국 국립중앙도서관', '論曰: “物之遇不遇, 莫非命也, 要之亦時而已矣. 夫以先生之淡泊寒苦, 世之貧人窮士, 猶皆厭而斥之. 易簡, 貴者也, 迺獨爲其所知, 至以徹聞于天子, 得美號以終, 傳之不朽. 是固有命, 亦幸會其時焉耳. 馮唐之鉏鋙, 一言而動萬乘; 蘇子之辯, 書十上而說不行. 是故得時者無賤, 失時者無貴. 嗚呼! 豈獨先生也哉?”', NULL, NULL),
    ('CSJYNJ01NU00101', '논평_산중열녀전_한국 경북대학교_001_도입평_01', '도입평', '산중열녀전', '山中列女傳', '한국 경북대학교', '戊戌春, 予堊居病伏, 隣朋至者, 以古談慰我罪縶涔寂, 須錄之如左.', '무술년 봄 내가 상을 당해 악실(堊室)에 병들어 누워있을 때 이웃의 벗이 찾아와 옛날이야기로 상중이라 적막한 나를 위로해 주었다. 이에 그 내용을 기록하니 다음과 같다.', NULL),
    ('CSJYNJ01NU00102', '논평_산중열녀전_한국 경북대학교_001_최종평_01', '최종평', '산중열녀전', '山中列女傳', '한국 경북대학교', '余聽之曰: “若非烈女之一句, 焉得及此? 噫! 山中岩兮! 有婦廬焉. 朝夕省掃, 其夫泣于泉! 一語貞節, 少年有則. 矧乎其終, 淫婦爲烈, 信其自守, 德加諸人.', '내가 이 이야기를 듣고는 말했다. “열녀의 시 한 구절이 아니었다면 어찌 이럴 수 있었겠는가? 아! 산속의 바위여! 그곳에 부인이 집을 지었구나. 아침저녁으로 살피고 청소하니, 그 남편이 황천에서 감격해 우는구나. 한마디 정절의 말이, 소년이 모범으로 삼았도다. 더구나 마침내, 음탕한 아낙이 열녀가 되었으니 진실로 자신을 지키다가 그 덕이 남들에게 더해졌구나.”', NULL),
    ('CSHJ01NU00101', '논평_삼해지_한국 국립중앙도서관_001_도입평_01', '도입평', '삼해지', '三海誌', '한국 국립중앙도서관', '話說. 天地之間, 海爲最大. 海有東南西北之別, 稱爲四瀆. 四瀆之內, 各有管領之神 : 東海曰:“阿明”, 南海曰:“祝融”, 西海曰:“敖廣”, 北海曰:“禺强”. 又有四龍王, 各主宣化, 東曰:“震靈”, 南曰:“离靈”, 西曰:“兌靈”, 北曰:“坎靈”.', '화설. 천지 사이에 바다가 가장 크다. 바다는 동·남·서·북의 구별이 있으니 이를 사독(四瀆)이라 일컫는다. 사독의 안에는 각각 관장해 다스리는 신이 있다. 동해는 아명(阿明), 남해는 축융(祝融), 서해는 오광(敖廣), 북해는 우강(禺强)이라고 한다. 또 네 명의 용왕이 있어 각각 선화(宣化)를 주관하니 동쪽은 진령(震靈), 남쪽은 이령(离靈), 서쪽은 태령(兌靈), 북쪽은 감령(坎靈)이라 한다.', NULL),
    ('CSSDJGG01NU01501', '논평_상사동전객기_한국 고려대학교_002_종결평_01', '종결평', '상사동전객기', '相思洞餞客記', '한국 고려대학교', '嗚呼! 異哉！', '아아! 기이하도다!', NULL),
    ('CSOS01NU00501', '논평_서옥설_한국 성균관대학교_001_최종평_01', '최종평', '서옥설', '鼠獄說', '한국 성균관대학교', '​太史氏曰: “火不撲則延, 獄不斷則蔓. 向使倉神案其罪而卽磔之, 則其禍必不熾也. 噫! 戾氣所種, 豈獨穴倉之一蟲也哉? 吁! 可畏也.”', NULL, NULL),
    ('CSGSIJ01NU00101', '논평_손곡산인전_한국 규장각한국학연구원_001_종결평_01', '종결평', '손곡산인전', '蓀谷山人傳', '한국 규장각한국학연구원', '噫! 達之詩, 信奇矣哉!', '아! 이달의 시는 참으로 기이하도다!', NULL),
    ('CSHJ02NU00101', '논평_숙향전_한국 경북대학교_001_종결평_01', '종결평', '숙향전', '淑香傳', '한국 경북대학교', '噫呼! 淑德誠孝, 天必祐之, 白日刀圭, 靑天鷄吠, 誠不可誣也哉?', NULL, NULL),
    ('CSHJ02NU00601', '논평_숙향전_한국 고려대학교_003_종결평_01', '종결평', '숙향전', '淑香傳', '한국 고려대학교', '淑德誠孝, 天必祐之, 白日刀圭, 靑天鷄犬, 豈虛語也哉?', NULL, NULL),
    ('CSHJ02NU00701', '논평_숙향전_한국 고석규_001_종결평_01', '종결평', '숙향전', '淑香傳', '한국 고석규', '異哉?', NULL, NULL),
    ('CSHJ02NU00801', '논평_숙향전_한국 국립중앙도서관_001_종결평_01', '종결평', '숙향전', '淑香傳', '한국 국립중앙도서관', '噫! 淑德誠孝, 天必祐之, 白日刀圭, 靑天鷄犬, 豈虛語也哉?', NULL, NULL),
    ('CSHJ02NU01001', '논평_숙향전_한국 국립중앙도서관_003_종결평_01', '종결평', '숙향전', '淑香傳', '한국 국립중앙도서관', '噫呼! 淑德誠孝, 天祐所及, 白日刀圭, 靑天鷄犬, 誠非虛語也哉?', '기이하도다!', NULL),
    ('CSJJJGUG01NE0010101', '논평_신증재자구운기_권1_필사본_한국 영남대학교_도입평_001', '도입평', '신증재자구운기', '新增才子九雲記', '한국 영남대학교', '自古英雄豪傑功名勳業之人, 富貴兼備, 福祿雙全. 有如唐朝之郭汾陽, 朝相暮將, 爲國家之柱石, 又若列國時陶朱公, 積金累貨, 埒公侯之殷富. 重以子孫繞膝, 榮華無侔者, 史冊載錄, 稗說傳稱, 指不勝屈. 難得如今新增九雲記, 萃一時之豪貴, 傳萬世之奇異. 這般好話兒, 寧可因事涉煩瑣, 跡近荒唐, 使之泯滅. 故於燈前月夕, 長夏餘冬, 濡戲墨彙, 爲一編. 奇奇幻幻, 有常有變, 摠要歸之於正. 淫詞穢語, 概所不錄. 試看首尾, 便知梗概.', NULL, NULL),
    ('CSJJJGUG01NE0010901', '논평_신증재자구운기_권9_필사본_한국 영남대학교_종결평_001', '종결평', '신증재자구운기', '新增才子九雲記', '한국 영남대학교', '後人有詩讚歎性眞詩云: “曾因一念結塵緣, 暫假邯鄲千枕邊, 自是道心難久住. 空潭印月在淸天.”', NULL, NULL),
    ('CSJJJGUG01NE0010902', '논평_신증재자구운기_권9_필사본_한국 영남대학교_종결평_002', '종결평', '신증재자구운기', '新增才子九雲記', '한국 영남대학교', '又有詩讚八仙女詩云: “由來竊藥悔嫦娥, 仙袂桐隨渡鵲河. 花雨一番蝴蝶散, 碧雲無限月明多.”', NULL, NULL),
    ('CSJJJGUG01NE0010903', '논평_신증재자구운기_권9_필사본_한국 영남대학교_종결평_003', '종결평', '신증재자구운기', '新增才子九雲記', '한국 영남대학교', '又有一律單單稱六觀大師悟道成佛詩云: “袈裟現相是金仙, 說法蓮花最上巓. 道載河山無量界, 心通天仙有形光. 三生石榻鑑塵性, 一喝禪壇運化權. 從此空門傳鉢在, 月明飛錫向西天.”', NULL, NULL),
    ('CSSJ03NU00101', '논평_심생전_한국 국립한국문학관_001_최종평_01', '최종평', '심생전', '沈生傳', '한국 국립한국문학관', '梅花外史曰: “余十二歲, 游於村塾, 日與同學兒, 喜聽譚故. 一日, 先生語沈生事甚詳, 曰：‘此吾少年時窗伴也. 其山寺哭書時, 吾及見之, 故聞其事, 至今不忘也. ’ 又曰：‘吾非欲汝曹效此風流浪子耳. 人之於事, 苟以必得爲志, 則閨中之女尙可以致, 況文章乎? 況科目乎? 汝輩其時聽之爲新說也.” 後讀情史, 多如此類. 於是追記爲情史補遺,”', '매화외사(梅花外史)가 말한다. “내가 열두 살에 서당에서 공부했을 때 날마다 함께 공부하는 아이들과 옛날이야기 듣기를 좋아했다. 하루는 선생께서 심생(沈生)의 일을 매우 상세하게 말씀해 주시며 말씀하셨다. ‘이 사람은 내가 젊은 시절 동문수학하던 벗이다. 그가 산속 절에서 글을 읽으며 울 때 내가 직접 그를 보았기에 그 일을 들어서 지금까지 잊지 못하는 것이다.’ 또 말씀하셨다. ‘내가 너희들이 이 풍류스러운 사내를 본받게 하려는 것이 아니다. 다만 사람이 어떤 일에 임해 만약 반드시 뜻을 세운다면 규중(閨中)의 여인도 오히려 데려올 수 있는데 더구나 문장(文章) 짓는 일이나 과거 시험은 오죽하겠는가? 너희들은 방금 이를 듣고 ‘신설(新說)’로만 여겼을 것이다.” 훗날 『정사(情史)』를 읽어보니 이와 같은 종류가 많았다. 그러므로 기억을 더듬어 기록해 『정사보유(情史補遺)』로 삼는다.', NULL),
    ('CSJSJ01NU00301', '논평_심진사전_한국 대전시립박물관_001_종결평_01', '종결평', '심진사전', '沈進士傳', '한국 대전시립박물관', '蓋人性壅滯, 則身世困窮矣.', '대개 사람의 성품이 꽉 막히면 신세가 곤궁하기 마련이다.', NULL),
    ('CECSJ01NU00101', '논평_엄처사전_한국 규장각한국학연구원_001_최종평_01', '최종평', '엄처사전', '嚴處士傳', '한국 규장각한국학연구원', '外史氏曰: “處士孝於家廉於鄕, 固當得位, 而以母死不賓于王, 卒窮以終. 其才不少售, 惜哉! 巖穴間有士如此, 名湮沒而不傳者, 非獨處士, 悲夫!”', '처사는 집에서 효도했고 고향에서 청렴했으니 진실로 마땅히 관직을 얻어야 했으나 모친이 세상을 떠나 왕에게 신하로 나아가지 않아 결국 곤궁하게 마쳤다. 그 재능이 조금도 쓰이지 못했으니 안타깝도다! 바위 동굴 사이에 이러한 선비가 있는데도 이름이 인멸되어 전해지지 않는 자가 비단 처사 뿐만이 아니니 슬프도다!', NULL),
    ('CYPJ02NU00101', '논평_연풍전_한국 규장각한국학연구원_001_종결평_01', '종결평', '연풍전', '年豐傳', '한국 규장각한국학연구원', '噫! 余於豐, 非素相識也, 非有恩威可驅使也, 乃一朝卒遇而得之. 抑豐, 賤隷耳, 非知有士君子之行, 又非矯情要譽以取祿仕者也, 而能若此, 其可尙已! 當是時, 奴而棄主、子而後親者滔滔也. 至於官守之臣, 或有偸生鼠竄, 顧戀妻子而忘君背國者, 雖衣冠儼然可畏, 其視此人何如也? 豐時年二十, 爲人謹默而多質.', NULL, NULL),
    ('CORPG01NE00101', '논평_오로봉기_한국 경주최씨 칠계 백불암종중_001_도입평_01', '도입평', '오로봉기', '五老峰記', '한국 경주최씨 칠계 백불암종중', '洛陽天下之中, 山川秀麗, 人物豊盛, 自古以來, 將相王侯, 英雄豪傑, 多出於此, 盖天地精明之氣, 會于中土故也.', '낙양(洛陽)은 천하의 중심으로 산천이 수려하고 인물이 풍성하여 예로부터 왕후장상(王侯將相)과 영웅호걸(英雄豪傑)이 이곳에서 많이 나왔으니 이는 천지의 정명(精明)한 기운이 중토(中土)에 모여있기 때문이다.', NULL),
    ('CORPG01NE00201', '논평_오로봉기_한국 국립중앙도서관_001_도입평_01', '도입평', '오로봉기', '五老峰記', '한국 국립중앙도서관', '洛陽天下之中, 山川秀麗, 人物豊盛, 自古以來, 將相王侯, 英雄豪傑, 多出於此, 盖天地精明之氣, 會于中土故也.', '낙양(洛陽)은 천하의 중심으로 산천이 수려하고 인물이 풍성하여 예로부터 왕후장상(王侯將相)과 영웅호걸(英雄豪傑)이 이곳에서 많이 나왔으니 이는 천지의 정명(精明)한 기운이 중토(中土)에 모여있기 때문이다.', NULL),
    ('COYRJ01NU00101', '논평_오유란전_한국 경북대학교_001_종결평_01', '종결평', '오유란전', '烏有蘭傳', '한국 경북대학교', '仍記其始末, 以爲傳記之資, 使多情者覽之, 則章臺折柳, 佳人之恨無窮, 使有志者聞之, 則茅山成藥, 丈夫之事可戒. 嗟爾! 小子觀此, 愼之哉!', '이에 그 전말을 기록해 전기(傳記)의 자료로 삼으니 정이 많은 자에게 이를 보게 한다면 장대에서 버들을 꺾듯 미인의 무궁한 한을 느낄 것이고 뜻이 있는 자에게 이를 듣게 하면 모산에서 선약을 완성하듯 대장부의 일을 경계할 만할 것이다. 아아, 너희들 후학들은 이를 보고 삼갈지어다!', NULL),
    ('COHGJ01NU00101', '논평_오후강전_한국 이채하 구장_001_중간평_01', '중간평', '오후강전', '吳後姜傳', '한국 이채하 구장', '其後, 松山居士讀此書, 至海甲之誤去鄭尙書家曰:“此不可爲有道者所讀也. 而況桂月之背廉叔, 不足當論, 何者? 以其難死於鄭侍郞, 而易死於安學度也云.” 而又“其構偶人, 而紿廉叔, 甲冑將軍之打破, 是何誕妄也? 凡於外家雜傳, 多有沒理不經之書, 未有若此書之無徵也.”云云.', '훗날 송산 거사(松山居士)가 이 글을 읽고 김해갑이 정 상서 집에 잘못 찾아간 대목에 대해 이렇게 말했다. “이는 도를 지닌 사람이 읽을 게 못 된다. 더군다나 계월이 염숙을 배반한 것도 논할 가치가 못 되니 어째서인가? 정 시랑를 위해 죽는 것은 어렵게 여기고 안학도를 위해 죽는 것은 쉽게 여겼기 때문이다.”라고 했고, 또 “그 나무 인형을 만들어 염숙을 속이고 갑주장군이 그것을 깨부순 대목은 이 어찌 허황된가? 무릇 유가 이외의 잡전(雜傳)에서 대부분 이치에 맞지 않는 불경한 글이 많으나 이 책과 같이 징험할 수 없는 사례는 있지 않다.”라고 말했다.', NULL),
    ('COHGJ01NU00102', '논평_오후강전_한국 이채하 구장_001_종결평_01', '종결평', '오후강전', '吳後姜傳', '한국 이채하 구장', '余讀宋史, 至徽欽之北質, 未嘗不廢書而下泪也. 夫戎狄之爲害, 自周漢以來, 候隙乘便, 輒爲橫逆. 玁狁之來侵, 大戎之入寇, 冒頓之悖慢, 突厥之擾北, 五胡之亂華, 未有能必擊者. 然亦無如二帝之困, 何哉? 弱則畏服, 强則侵叛. 及其强也, 以漢之高祖, 而受困於白登, 及其衰也, 以元成之微, 而單于入朝, 此必然之勢, 已驗之事也. 宋雖起於用兵, 然功成定治之後, 以仁傳家. 仁之弊, 失於弱, 中世, 有欲以自强, 以革其弊. 然當時廟堂之相方鎭之將, 皆非李種張宗之類, 而徒用蔡邕 邕 : 원본에는 童.
INSERT INTO "review" ("id", "name", "work_kor", "work_chi", "target_book", "reviewer", "criticism_type", "paratext_title", "language", "original_text", "translation", "mentioned_work", "notes", "location") VALUES
    ('RGHJ01NU00101', '외평_갈홍전_한국 강릉최씨 천보당_001_01', '갈홍전', '蝎紅傳', '한국 강릉최씨 천보당', '[未詳]', 'Etc', 'N/A', '한문', '與退之毛穎傳相爲表裏. 癸酉所作, 時年二十四', '한유의「모영전」과 서로 표리가 된다. 계유년(1813)에 지은 바 당시 나이는 24세다.', '毛穎傳', NULL, NULL),
    ('RGHJ01NU00201', '외평_갈홍전_한국 창녕조씨 명숙공_001_01', '갈홍전', '蝎紅傳', '한국 창녕조씨 명숙공', '[未詳]', 'Etc', 'N/A', '한문', '與退之毛穎傳相爲表裏', '한유의「모영전」과 서로 표리가 된다', '毛穎傳', NULL, NULL),
    ('RGHJ01NU00202', '외평_갈홍전_한국 창녕조씨 명숙공_001_02', '갈홍전', '蝎紅傳', '한국 창녕조씨 명숙공', '[未詳]', 'Etc', 'N/A', '한문', '右宋王禹備', '이는 송왕우가 갖추고 있다', NULL, NULL, NULL),
    ('RGDR01NU00101', '외평_강도록_미국 버클리대학교_01_01', '강도록', '江都錄', '미국 버클리대학교', '[未詳]', 'Etc', 'N/A', '한문', '此書人多傳看, 而右本畧有相左. 又或補遺, 故因尾之, 以爲賢者參詳焉.', NULL, NULL, NULL, NULL),
    ('RGDR01NU00201', '외평_강도록_일본 동양문고_001_01', '강도록', '江都錄', '일본 동양문고', '[未詳]', 'Etc', 'N/A', '한문', '江都卽江華也', NULL, NULL, NULL, NULL),
    ('RGDR01NU00301', '외평_강도록_한국 고려대학교_001_01', '강도록', '江都錄', '한국 고려대학교', '[未詳]', 'Etc', 'N/A', '한문', '​自丙子十二月, 至丁丑正月日記.', NULL, NULL, NULL, NULL),
    ('RGDR01NU00401', '외평_강도록_한국 국립중앙도서관_001_01', '강도록', '江都錄', '한국 국립중앙도서관', '[未詳]', 'Postscript', '題江都錄後', '한문', '생성필요', NULL, NULL, NULL, NULL),
    ('RGPJDJMD01NU00201', '외평_공부자동자문답_한국 성균관대학교_001_01', '공부자동자문답', '孔夫子童子問答', '한국 성균관대학교', '[未詳]', 'Etc', 'N/A', '한문', '或云黃鐸老人之門人', NULL, NULL, NULL, NULL),
    ('RGHRG01YE00201', '외평_광한루기_한국 고려대학교_001_01', '광한루기', '廣寒樓記', '한국 고려대학교', '운림초객(雲林樵客)', 'Foreword', '廣寒樓記敍', '한문', '생성필요', NULL, '西廂記', NULL, NULL),
    ('RGHRG01YE00202', '외평_광한루기_한국 고려대학교_001_02', '광한루기', '廣寒樓記', '한국 고려대학교', '소엄주인(小广主人)', 'Foreword', '廣寒樓記後敍', '한문', '余讀『西廂記』, 以爲天下後世, 更無如此才子矣, 更無如此佳人矣, 更無如此奇文矣. 近又讀水山『廣寒樓記』, 竊喜天下後世, 所無之奇文, 得之於今日, 而其書之所載之人之事, 又皆天下後世, 所無之佳人才子也. 方與二三君子, 亟加評訂, 圖所以廣其傳未也. … 故『西廂』之辭, 哀而促, 『廣寒樓』之辭, 樂而緩, 此又觀風者之所可辨也. 然則大將旗鼓, 安知不歸於『廣寒樓』, 而爲『西廂』者, 不得不竪降旛矣? 若夫錦心繡口, 千幻萬變, 提古人之性情, 煥時人之耳目, 則水山與聖歎, 雖謂之同, 可也. 雖謂之不同, 亦可也. 難之者, 唯唯而退.', '내가 『서상기(西廂記)』를 읽고 “천하의 후대에 다시는 이러한 재자才子가 없을 것이고 다시는 이러한 가인佳人이 없을 것이며 다시는 이러한 뛰어난 문장이 없을 것이다.”라고 했다. 근래에 또 수산水山의 『광한루기(廣寒樓記)』를 읽고 천하의 후대에 없을 뛰어난 문장을 오늘날 얻었고 그 책에 실린 인물과 사건이 또 모두 천하 후대에 없을 재자가인임을 속으로 기뻐했다. 이제 몇몇 뛰어난 사람들과 서둘러 평점과 교정을 더하여 그 전해지지 못한 부분을 널리 알리길 도모하는 바이다. …중략… 그러므로 『서상기』의 말은 슬프면서 다급하고 『광한루기』의 말은 즐거우면서도 느긋하니 이는 또 풍격을 잘 보는 자만이 분별할 수 있는 점입니다다. 그렇다면 대장의 깃발과 북이 『광한루기』로 돌아가고 『서상기』를 지은 자가 마저 못해 항복기降伏旗를 세우게 되지 않을 줄 어찌 알겠습니까? 만약 저 뛰어난 문재文才로 천만 가지 변화를 통해 옛사람의 성정을 끌고 당시 사람들의 이목을 밝힌다면 즉 수산과 성탄은 비록 같다고 해도 괜찮으며 비록 다르다고 해도 또한 괜찮습니다.” 난색을 짓던 자가 알았다고 수긍하며 물러갔으니 드디어 그 내용을 기록하여 판본에 더한다.', '西廂記', NULL, NULL),
    ('RGHRG01YE00203', '외평_광한루기_한국 고려대학교_001_03', '광한루기', '廣寒樓記', '한국 고려대학교', '운림초객(雲林樵客)', 'Postscript', '廣寒樓記小引', '한문', '余家雲林, 自號樵客. 每見花開葉落, 以知春到秋來. 枕石漱流, 敢曰高蹈. 盟鷗友鹿, 聊寓閑情. 四時岩屋, 或論董仲舒三餘. 一區硯田, 所得白香山六幅. 經史子集, 前人之述頗詳. 仙佛卜醫, 後世之惑滋甚. 至於水滸, 三國, 西遊, 西廂, 已被拘盜. 狐白亦多鐵, 或金黃. 可惜廣寒樓明月, 久染倡優場汗塵. 小技粗效於雕蟲, 高志特著於附驥. 旣勞一身上腕鬼舌妖, 堪作萬人間笑柄語欛.', NULL, '水滸傳;三國志演義;西遊記;西廂記', NULL, NULL),
    ('RGHRG01YE00401', '외평_광한루기_한국 국립중앙도서관_001_01', '광한루기', '廣寒樓記', '한국 국립중앙도서관', '운림초객(雲林樵客)', 'Postscript', '廣寒樓記小引', '한문', '余家雲林, 自號樵客. 每見花開葉落, 以知春到秋來. 枕石漱流, 敢曰高蹈. 盟鷗友鹿, 聊寓閑情. 四時岩屋, 或値董仲舒三餘. 一區硯田, 所得白香山六幅. 經史子集, 前人之述頗詳. 仙佛卜醫, 後世之惑滋甚. 至於水滸, 三國, 西遊, 西廂, 已被拘盜. 狐白亦多鐵, 或金黃. 可惜廣寒樓明月, 久染倡優場汗塵. 小技粗效於雕蟲, 高節特著於附驥. 旣勞一身上腕鬼舌妖, 堪作萬人間笑柄語欛.', NULL, '水滸傳;三國志演義;西遊記;西廂記', NULL, NULL),
    ('RGUM01NE00102', '외평_구운몽_하(下)_일본 국립국회도서관_001_01', '구운몽', '九雲夢', '일본 국립국회도서관', '[未詳]', 'Etc', 'N/A', '한문', '百年如大夢, 萬事總浮雲, 混混将来覺, 身魂已二分', '백 년은 마치 큰 꿈과 같고, 모든 일은 전부 뜬 구름과 같다.
